INSERT INTO verses (goi, conical, edition_id, version, language_subtag, book, chapter, verse, testament, verse_text) VALUES
(1, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 1, 'OT', '태초에 하나님이 하늘과 땅을 창조하셨느니라.'),
(2, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 2, 'OT', '땅이 혼돈하고 공허하며, 어둠이 깊음의 표면 위에 있고, 하나님의 영이 물들의 표면 위에 운행하시니라.'),
(3, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 3, 'OT', '하나님이 이르시되 빛이 있으라 하시니 빛이 있었더라'),
(4, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 4, 'OT', '하나님이 그 빛을 보시니 좋았더라 하나님이 빛과 어두움을 나누시니라'),
(5, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 5, 'OT', '하나님이 빛을 낮이라 부르시고 어두움을 밤이라 부르셨다. 저녁이 되고 아침이 되니 이는 첫째 날이었다.'),
(6, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 6, 'OT', '하나님이 이르시되 물 가운데 궁창이 있어 물과 물 사이에 나뉘게 하라 하시니라'),
(7, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 7, 'OT', '하나님이 궁창을 만드시고 궁창 아래에 있는 물과 궁창 위에 있는 물 사이를 나누시니 그대로 되니라'),
(8, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 8, 'OT', '하나님이 궁창을 하늘이라 부르시니라 저녁이 되고 아침이 되니 이는 둘째 날이니라'),
(9, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 9, 'OT', '하나님이 이르시되 하늘 아래의 물들이 한 곳으로 모이고 뭍이 드러나라 하시매 그대로 되니라'),
(10, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 10, 'OT', '하나님이 마른 땅을 땅이라 부르시고 물의 모임을 바다라 부르셨으며, 하나님이 보시기에 좋았더라.'),
(11, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 11, 'OT', '하나님이 이르시되 땅은 풀과 씨 맺는 채소와 종류대로 씨가 그 속에 있는 열매 맺는 과목을 땅 위에 내라 하시매 그대로 되니라'),
(12, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 12, 'OT', '땅이 풀과 각기 종류대로 씨 맺는 채소와 각기 종류대로 씨 가진 열매 맺는 나무를 내니, 하나님이 보시기에 좋았더라.'),
(13, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 13, 'OT', '저녁이 되고 아침이 되니 이는 셋째 날이니라'),
(14, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 14, 'OT', '하나님이 이르시되 하늘의 궁창에 광명들이 있어 낮과 밤을 나누게 하고 그것들이 징조와 절기와 날들과 해들을 위한 것이 되게 하라'),
(15, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 15, 'OT', '그들이 하늘의 궁창에 광명이 되어 땅을 비추게 하라 하시니 그대로 되니라'),
(16, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 16, 'OT', '하나님이 두 큰 광명을 만드사 큰 광명으로 낮을 주관하게 하시고 작은 광명으로 밤을 주관하게 하시며 또 별들을 만드시고'),
(17, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 17, 'OT', '하나님이 그것들을 하늘의 궁창에 두사 땅 위에 비추게 하셨으며'),
(18, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 18, 'OT', '낮과 밤을 다스리게 하시며 빛과 어둠 사이를 나누게 하셨다. 하나님이 보시기에 좋았더라.'),
(19, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 19, 'OT', '저녁이 되고 아침이 되니 이는 넷째 날이니라'),
(20, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 20, 'OT', '하나님이 이르시되 물들은 생명 있는 생물을 번성하게 하라 새들은 땅 위 하늘의 궁창 앞에서 날으라 하시니라'),
(21, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 21, 'OT', '하나님이 큰 용들과 물에서 번성하여 움직이는 모든 생물을 그 종류대로, 날개 있는 모든 새를 그 종류대로 창조하시니, 하나님이 보시기에 좋았더라.'),
(22, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 22, 'OT', '하나님이 그들을 복 주시며 이르시되, 생육하고 번성하여 바다들의 물에 충만하라, 새들도 땅에서 번성하라 하시니라.'),
(23, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 23, 'OT', '저녁이 되고 아침이 되니 이는 다섯째 날이니라'),
(24, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 24, 'OT', '하나님이 이르시되 땅은 생물을 그 종류대로 내되 가축과 기는 것과 땅의 짐승을 그 종류대로 내라 하시니 그대로 되니라'),
(25, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 25, 'OT', '하나님이 땅의 짐승을 그 종류대로, 가축을 그 종류대로, 땅에 기는 모든 것을 그 종류대로 만드시니, 하나님이 보시기에 좋았더라.'),
(26, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 26, 'OT', '하나님이 이르시되 우리의 형상을 따라 우리의 모양대로 우리가 사람을 만들고 그들로 바다의 고기와 하늘의 새와 가축과 온 땅과 땅에 기는 모든 것을 다스리게 하자 하시니라'),
(27, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 27, 'OT', '하나님이 사람을 자기 형상대로 창조하시되 하나님의 형상대로 그를 창조하셨으며 남자와 여자로 그들을 창조하셨느니라.'),
(28, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 28, 'OT', '하나님이 그들을 복 주시며 그들에게 이르시되 생육하고 번성하여 땅에 충만하라, 땅을 정복하라, 바다의 고기와 하늘의 새와 땅 위에 움직이는 모든 생물을 다스리라 하시니라'),
(29, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 29, 'OT', '하나님이 말씀하시기를, 보라, 내가 온 땅의 표면에 있는 씨 맺는 모든 채소와 그 안에 씨 맺는 열매를 가진 모든 나무를 너희에게 주었노니, 그것이 너희에게 먹을 것이 되리라.'),
(30, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 30, 'OT', '또한 땅의 모든 짐승과 하늘의 모든 새와 땅 위를 기는 모든 것, 곧 그 속에 생명이 있는 모든 것에게 모든 푸른 풀을 먹을 것으로 주노라 하시니 그대로 되니라'),
(31, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 1, 31, 'OT', '하나님이 그가 지으신 모든 것을 보시니, 보라, 그것이 심히 좋았더라. 저녁이 되고 아침이 되니 이는 여섯째 날이니라.'),
(32, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 1, 'OT', '하늘과 땅과 그들의 모든 군대가 다 이루어지니라'),
(33, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 2, 'OT', '하나님이 일곱째 날에 그가 행하신 그의 일을 마치시고, 그가 행하신 그의 모든 일에서 일곱째 날에 안식하시니라.'),
(34, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 3, 'OT', '하나님이 일곱째 날을 복 주시고 그것을 거룩하게 하셨으니 이는 그 날에 그가 창조하시며 만드시던 모든 일을 마치고 안식하셨음이니라'),
(35, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 4, 'OT', '이것이 하늘과 땅의 내력이니라 그것들이 창조되던 때에, 여호와 하나님이 땅과 하늘을 만드신 날에 그러하였더라'),
(36, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 5, 'OT', '들에는 모든 초목이 아직 땅에 있지 아니하였고 밭에는 모든 채소가 아직 나지 아니하였으니, 이는 여호와 하나님이 땅에 비를 내리지 아니하셨고 땅을 경작할 사람도 없었음이라'),
(37, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 6, 'OT', '안개가 땅에서 올라와 온 지면을 적셨더라'),
(38, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 7, 'OT', '여호와 하나님이 흙으로 사람을 지으시고 그의 코에 생명의 숨을 불어넣으시니 사람이 생령이 되니라'),
(39, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 8, 'OT', '여호와 하나님이 동방의 에덴에 동산을 창설하시고 그가 지으신 사람을 거기 두시니라'),
(40, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 9, 'OT', '여호와 하나님이 그 땅에서 보기에 아름답고 먹기에 좋은 모든 나무를 자라게 하셨고, 동산 가운데에는 생명나무와 선악을 알게 하는 나무도 있게 하셨다.'),
(41, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 10, 'OT', '강이 에덴에서 나와 그 동산을 적시고 거기서부터 갈라져 네 근원이 되었더라'),
(42, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 11, 'OT', '첫째의 이름은 비손이요, 그 강은 금이 있는 하윌라 온 땅을 둘러 흐르느니라'),
(43, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 12, 'OT', '그 땅의 금은 좋으며, 거기에는 베델리엄과 호마노 돌이 있느니라.'),
(44, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 13, 'OT', '둘째 강의 이름은 기혼이니, 그것은 구스 온 땅을 두르는 자라.'),
(45, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 14, 'OT', '세째 강의 이름은 힛데겔이니 그것은 앗수르 동쪽으로 흐르는 강이요, 네째 강은 유브라데더라.'),
(46, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 15, 'OT', '여호와 하나님이 그 사람을 데려다가 에덴 동산에 두어 그것을 경작하며 지키게 하셨더라'),
(47, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 16, 'OT', '여호와 하나님이 그 사람에게 명령하여 이르시되 동산의 모든 나무에서 너는 먹되 자유로이 먹을지니라'),
(48, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 17, 'OT', '선악을 알게 하는 나무의 열매는 네가 그것을 먹지 말지니, 네가 그것을 먹는 날에는 반드시 죽으리라.'),
(49, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 18, 'OT', '여호와 하나님이 이르시되 사람이 홀로 있는 것이 좋지 아니하니 내가 그를 위하여 돕는 배필을 만들리라 하시니라'),
(50, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 19, 'OT', '여호와 하나님이 흙에서 들의 모든 짐승과 하늘의 모든 새를 지으시고 아담에게로 이끌어 가서 그가 무엇이라 부르는지 보시니, 아담이 각 생물을 부르는 그것이 곧 그 이름이 되니라.'),
(51, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 20, 'OT', '아담이 모든 가축과 하늘의 새와 들의 모든 짐승에게 이름을 주었으나, 아담에게는 그와 맞는 돕는 자가 찾아지지 아니하였더라.'),
(52, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 21, 'OT', '여호와 하나님이 아담에게 깊은 잠을 내리시니 그가 잠들매, 그가 그의 갈빗대 하나를 취하고 그 자리에 살로 채우니라.'),
(53, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 22, 'OT', '여호와 하나님이 사람에게서 취하신 그 갈빗대로 여자를 만드시고 그를 사람에게로 데려오시니'),
(54, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 23, 'OT', '아담이 말하되, “이제 이는 내 뼈 중의 뼈요, 내 살 중의 살이라. 이것을 여자라 부르리니, 이는 남자에게서 취하여졌음이라.”'),
(55, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 24, 'OT', '그러므로 사람이 그의 아버지와 그의 어머니를 떠나 그의 아내에게 붙을 것이요 그들은 한 몸이 될지니라'),
(56, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 2, 25, 'OT', '그들 둘 곧 아담과 그의 아내가 벌거벗었으나 부끄러워하지 아니하니라'),
(57, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 1, 'OT', '뱀은 여호와 하나님이 지으신 들의 모든 짐승 중에 가장 간교하더라. 그가 여자에게 이르되, "하나님이 정말로 동산의 모든 나무에서 나는 것을 먹지 말라고 말씀하셨느냐?"'),
(58, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 2, 'OT', '여자가 뱀에게 말하되, 동산 나무의 열매를 우리가 먹을 수 있으나'),
(59, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 3, 'OT', '동산 중앙에 있는 나무의 열매는 하나님이 말씀하시기를 너희는 그것을 먹지 말고 그것을 만지지도 말라, 너희가 죽을까 하노라 하셨느니라.'),
(60, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 4, 'OT', '뱀이 여자에게 이르되, 너희가 결코 죽지 아니하리라'),
(61, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 5, 'OT', '하나님이 아시나니 너희가 그것을 먹는 날에는 너희 눈이 밝아지고 너희가 하나님과 같이 되어 선악을 알게 될 줄을.'),
(62, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 6, 'OT', '여자가 그 나무를 보니 먹을 만한 좋은 나무요, 눈에 욕망이 되고, 지혜를 얻게 할 만큼 탐스러운 나무인지라, 그 열매를 따서 먹고, 자기와 함께 있는 자기 남편에게도 주니 그도 먹었더라.'),
(63, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 7, 'OT', '두 사람의 눈이 열리며 그들이 자기가 벗은 줄을 알고 무화과나무 잎을 엮어 자기들을 위해 치마를 만들었더라'),
(64, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 8, 'OT', '그들이 날이 서늘할 때에 동산에 거니시는 여호와 하나님의 음성을 듣고 아담과 그의 아내가 여호와 하나님의 낯을 피하여 동산 나무 사이에 숨으니라'),
(65, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 9, 'OT', '여호와 하나님이 아담을 부르시며 그에게 이르시되 네가 어디 있느냐'),
(66, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 10, 'OT', '그가 이르되 내가 동산에서 당신의 소리를 듣고 내가 벗었으므로 두려워하여 숨었나이다'),
(67, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 11, 'OT', '그가 말하되, 누가 네가 벗었음을 네게 알렸느냐? 내가 너에게 그것을 먹지 말라고 명한 그 나무에서 네가 먹었느냐?'),
(68, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 12, 'OT', '아담이 말하되, 당신이 나와 함께 있게 하신 그 여자가 그 나무에서 내게 주었기에 내가 먹었나이다.'),
(69, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 13, 'OT', '여호와 하나님이 여자에게 이르시되 네가 무슨 짓을 하였느냐 하시니 여자가 이르되 뱀이 나를 속여서 내가 먹었나이다'),
(70, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 14, 'OT', '여호와 하나님이 뱀에게 이르시되 네가 이것을 행하였으니 네가 모든 가축과 들의 모든 짐승보다 더욱 저주를 받아 네 배로 다니고 네 평생에 흙을 먹을지니라'),
(71, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 15, 'OT', '내가 너와 여자 사이에, 또 네 후손과 여자의 후손 사이에 적의를 두리니, 그가 네 머리를 상하게 할 것이요 너는 그의 발꿈치를 상하게 할 것이니라.'),
(72, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 16, 'OT', '여자에게 이르시되 내가 네 고통과 잉태를 크게 더하리니 네가 고통 중에 자녀를 낳을 것이요 네 사모함이 네 남편에게 있으리니 그가 너를 다스리리라'),
(73, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 17, 'OT', '아담에게 이르시되 네가 네 아내의 목소리를 들었고 내가 너에게 명하여 이르기를 그것에서 먹지 말라 한 그 나무에서 먹었으므로 땅이 너로 인하여 저주를 받았나니 네가 평생에 모든 날을 수고하며 그것을 먹으리라'),
(74, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 18, 'OT', '가시와 엉겅퀴를 네게 내리라, 네가 들의 풀을 먹으리라.'),
(75, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 19, 'OT', '네가 얼굴에 땀을 흘려야 빵을 먹으리니, 네가 그 땅으로 돌아갈 때까지이니, 이는 네가 그에게서 취해졌음이라. 너는 흙이니, 흙으로 돌아가리라.'),
(76, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 20, 'OT', '아담이 그의 아내의 이름을 하와라 불렀으니, 이는 그가 모든 살아 있는 자의 어미가 되었음이라.'),
(77, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 21, 'OT', '여호와 하나님이 아담과 그의 아내를 위하여 가죽 옷을 지어 그들에게 입히셨더라'),
(78, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 22, 'OT', '여호와 하나님이 이르시되, 보라, 사람이 우리 중 하나 같이 되어 선과 악을 알게 되었도다. 이제 그가 그의 손을 내밀어 생명나무에서도 따서 먹고 영원히 살까 하노라.'),
(79, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 23, 'OT', '여호와 하나님이 그를 에덴 동산에서 내보내어, 그가 거기서 취함을 입은 땅을 갈게 하셨더라.'),
(80, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 3, 24, 'OT', '그가 그 사람을 쫓아내시고 에덴 동산 동쪽에 그룹들과 사방으로 돌이키는 불타는 칼을 두어 생명나무의 길을 지키게 하니라'),
(81, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 1, 'OT', '아담이 그의 아내 하와를 알았더니 그녀가 잉태하여 가인을 낳고 이르되, "내가 여호와로 말미암아 한 남자를 얻었다" 하니라.'),
(82, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 2, 'OT', '그녀가 또 그의 아우 아벨을 낳았는데, 아벨은 양 치는 자였고, 가인은 땅을 경작하는 자였더라.'),
(83, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 3, 'OT', '세월이 끝난 후에 가인이 땅의 열매로 여호와께 제물을 드렸더라'),
(84, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 4, 'OT', '아벨도 자기 양 떼의 첫 새끼들과 그 기름으로 가져왔더니, 여호와께서 아벨과 그의 제물을 돌아보셨으나'),
(85, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 5, 'OT', '가인과 그의 제물에게는 돌아보지 아니하셨다. 그러므로 가인이 매우 노하여 그의 얼굴이 떨어졌다.'),
(86, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 6, 'OT', '여호와께서 가인에게 이르시되 네가 어찌하여 분노하였으며 어찌하여 네 얼굴이 떨어졌느냐'),
(87, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 7, 'OT', '네가 선을 행하면 어찌 낯을 들지 못하겠느냐? 선을 행하지 아니하면 죄가 문에 엎드려 있느니라. 그의 소원이 네게 있으나 너는 그를 다스릴지니라.'),
(88, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 8, 'OT', '가인이 그의 아우 아벨에게 말하니라 그들이 들에 있을 때에 가인이 그의 아우 아벨을 치려고 일어나 그를 죽이니라'),
(89, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 9, 'OT', '여호와께서 가인에게 이르시되 네 아우 아벨이 어디 있느냐 그가 이르되 내가 알지 못하나이다 내가 내 아우를 지키는 자니이까'),
(90, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 10, 'OT', '그가 이르되 네가 무엇을 하였느냐 네 아우의 피의 소리가 땅에서부터 내게 부르짖느니라'),
(91, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 11, 'OT', '이제 너는 땅에서 저주를 받았나니, 그 땅이 네 손에서 네 아우의 피를 받으려고 그 입을 벌렸느니라.'),
(92, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 12, 'OT', '네가 땅을 경작할지라도 땅이 다시는 그 힘을 네게 주지 아니할 것이요, 너는 땅에서 떠도는 자와 유리하는 자가 되리라'),
(93, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 13, 'OT', '가인이 여호와께 말하되, 내 죄악이 용서받기에는 너무 크나이다.'),
(94, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 14, 'OT', '보라, 주께서 오늘 이 땅의 얼굴에서 나를 쫓아내셨고, 주의 얼굴에서 내가 숨게 되었으며, 내가 땅에서 도망하며 유리하는 자가 되리니, 나를 만나는 모든 자가 나를 죽이리이다.'),
(95, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 15, 'OT', '여호와께서 그에게 이르시되 그러므로 가인을 죽이는 자는 누구든지 일곱 배로 보복을 받으리라 하시고 여호와께서 가인에게 표를 주사 그를 만나는 모든 자가 그를 치지 못하게 하시니라'),
(96, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 16, 'OT', '가인이 여호와 앞에서 나가서 에덴 동쪽 놋 땅에 거주하니라.'),
(97, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 17, 'OT', '가인이 그의 아내와 동침하매 그가 임신하여 에녹을 낳았고, 그가 성을 건축하며 그 성의 이름을 그의 아들의 이름을 따라 에녹이라 불렀더라.'),
(98, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 18, 'OT', '에녹에게 이랏이 태어났고, 이랏은 므후야엘을 낳았고, 므후야엘은 므드사엘을 낳았고, 므드사엘은 라멕을 낳았더라.'),
(99, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 19, 'OT', '라멕이 두 아내를 취하였으니, 하나의 이름은 아다요, 둘째의 이름은 실라였더라.'),
(100, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 20, 'OT', '아다가 야발을 낳았으니, 그는 장막에 거하며 가축을 기르는 자의 조상이 되었더라.'),
(101, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 21, 'OT', '그의 형제의 이름은 유발이니, 그는 수금과 퉁소를 잡는 모든 자의 아버지가 되었더라.'),
(102, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 22, 'OT', '씰라도 그가 두발가인을 낳았으니 그는 놋쇠와 쇠로 모든 연장을 만드는 자요 두발가인의 누이는 나아마였더라'),
(103, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 23, 'OT', '라멕이 자기 아내들에게 말하였다. “아다와 씰라여, 내 목소리를 들으라. 라멕의 아내들이여, 내 말에 귀를 기울이라. 내가 내 상처로 말미암아 한 사람을 죽였고, 내가 내 타박상으로 말미암아 한 소년을 죽였도다.'),
(104, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 24, 'OT', '가인을 위하여는 일곱 배로 갚으리니, 라멕을 위하여는 일흔일곱 배로 갚으리라.'),
(105, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 25, 'OT', '아담이 다시 그의 아내를 알았고 그녀가 아들을 낳아 그의 이름을 셋이라 불렀으니 이는 하나님이 내게 가인이 죽인 아벨 대신에 다른 씨를 주셨음이라'),
(106, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 4, 26, 'OT', '셋에게도 아들이 태어났고, 그가 그의 이름을 에노스라 불렀으며, 그 때에 사람들이 비로소 여호와의 이름을 부르기 시작하였더라.'),
(107, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 1, 'OT', '이것이 아담의 족보의 책이니라. 하나님이 사람을 창조하신 날에, 하나님의 형상대로 그를 지으셨느니라.'),
(108, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 2, 'OT', '그들을 남자와 여자로 창조하셨고, 그들에게 복을 주시며, 그들이 창조되던 날에 그들의 이름을 아담이라 부르셨더라.'),
(109, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 3, 'OT', '아담이 삼십 년과 백 년을 살았고 자기 모양과 형상대로 아들을 낳아 그의 이름을 셋이라 불렀더라'),
(110, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 4, 'OT', '아담이 셋을 낳은 후의 날들은 팔백 년이었으며, 그가 아들들과 딸들을 낳았더라.'),
(111, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 5, 'OT', '아담이 산 모든 날은 구백삼십 년이었으며 그가 죽었더라.'),
(112, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 6, 'OT', '셋은 백오 년을 살고 에노스를 낳았으며'),
(113, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 7, 'OT', '셋은 에노스를 낳은 후에 팔백칠 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(114, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 8, 'OT', '셋의 모든 날이 구백십이 년이었고 그가 죽었더라.'),
(115, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 9, 'OT', '에노스는 구십 년을 살았고, 게난을 낳았더라.'),
(116, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 10, 'OT', '에노스가 게난을 낳은 후에 팔백십오 년을 살며 아들들과 딸들을 낳았더라'),
(117, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 11, 'OT', '에노스의 모든 날은 구백오 년이었으며 그가 죽었더라.'),
(118, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 12, 'OT', '게난은 칠십 년을 살았고, 마할랄렐을 낳았더라.'),
(119, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 13, 'OT', '케난이 마할랄렐을 낳은 후에 팔백사십 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(120, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 14, 'OT', '케난의 모든 날이 구백십 년이었으며 그가 죽었더라.'),
(121, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 15, 'OT', '마할랄렐은 육십오 년을 살았고, 야렛을 낳았으며'),
(122, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 16, 'OT', '므할랄렐이 야렛을 낳은 후에 팔백삼십 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(123, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 17, 'OT', '므할랄렐의 모든 날이 팔백구십오 년이었으며 그가 죽었더라.'),
(124, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 18, 'OT', '야렛은 백육십이 년을 살았고, 에녹을 낳았으며'),
(125, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 19, 'OT', '야렛이 에녹을 낳은 후에 팔백 년을 살며 아들들과 딸들을 낳았더라.'),
(126, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 20, 'OT', '야렛의 모든 날이 구백육십이 년이었으며 그가 죽었더라.'),
(127, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 21, 'OT', '에녹은 육십오 년을 살았고, 므두셀라를 낳았더라.'),
(128, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 22, 'OT', '에녹이 므두셀라를 낳은 후 삼백 년 동안 하나님과 동행하며 아들들과 딸들을 낳았더라'),
(129, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 23, 'OT', '에녹의 모든 날은 삼백육십오 년이었더라'),
(130, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 24, 'OT', '에녹이 하나님과 동행하였더니 그가 있지 아니하였으니 이는 하나님이 그를 데려가셨음이니라'),
(131, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 25, 'OT', '므두셀라는 팔십칠 년과 백 년을 살았고, 라멕을 낳았으며'),
(132, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 26, 'OT', '므두셀라는 라멕을 낳은 후에 칠백팔십이 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(133, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 27, 'OT', '므두셀라의 모든 날이 구백육십구 년이었으며 그가 죽었더라.'),
(134, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 28, 'OT', '라멕은 백팔십이 년을 살고 아들을 낳았으며'),
(135, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 29, 'OT', '그가 그의 이름을 노아라 하여 이르되, “이 아이가 여호와께서 저주하신 땅으로 인한 우리의 수고와 우리 손의 고통에서 우리를 위로하리라” 하였더라.'),
(136, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 30, 'OT', '라멕이 노아를 낳은 후에 오백구십오 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(137, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 31, 'OT', '레멕의 모든 날은 칠백칠십칠 년이었고 그가 죽었더라.'),
(138, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 5, 32, 'OT', '노아가 오백 세가 되었을 때에, 노아가 셈과 함과 야벳을 낳았더라.'),
(139, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 1, 'OT', '사람들이 땅 위에 번성하기 시작할 때에 그들에게서 딸들이 태어났더라.'),
(140, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 2, 'OT', '하나님의 아들들이 사람의 딸들이 아름다운 것을 보고 그들이 모든 택한 자들 중에서 아내들을 취하였더라'),
(141, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 3, 'OT', '여호와께서 말씀하시기를, 내 영이 사람 속에 영원히 머물지 아니하리니, 이는 그도 육체임이라. 그의 날들은 백이십 년이 되리라 하셨다.'),
(142, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 4, 'OT', '그 때에 땅에 네피림이 있었고, 그 후에도 하나님의 아들들이 사람의 딸들에게 들어와 그들에게서 자식을 낳았으니, 그들은 옛날부터 이름난 사람들인 용사들이었더라.'),
(143, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 5, 'OT', '여호와께서 보시니 땅에서 사람의 악함이 크고 그의 마음의 생각의 모든 계획이 오직 온종일 악할 뿐이었더라'),
(144, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 6, 'OT', '여호와께서 땅에 사람을 지으셨음을 후회하시고 마음에 근심하셨더라'),
(145, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 7, 'OT', '여호와께서 이르시되 내가 창조한 사람을 지면에서 쓸어버리되 사람으로부터 가축과 기는 것과 하늘의 새까지 그리하리니 이는 내가 그것들을 지었음을 후회함이니라 하시니라'),
(146, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 8, 'OT', '노아는 여호와의 눈에 은혜를 찾았더라'),
(147, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 9, 'OT', '이것이 노아의 족보이니라 노아는 의롭고 흠 없는 사람이었으며 그의 당대에 그러하였고 노아는 하나님과 동행하였더라'),
(148, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 10, 'OT', '노아가 세 아들을 낳았으니 셈과 함과 야벳이더라.'),
(149, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 11, 'OT', '땅이 하나님 앞에서 부패하였고, 땅에 폭력이 가득하였다.'),
(150, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 12, 'OT', '하나님이 땅을 보시니, 보라, 그것이 부패하였으니, 이는 모든 육체가 땅에서 자기 길을 부패시켰음이라.'),
(151, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 13, 'OT', '하나님이 노아에게 말씀하시되 모든 육체의 끝이 내 앞에 이르렀나니 이는 그들 때문에 땅에 폭력이 가득함이라 보라 내가 그들을 땅과 함께 멸하리라'),
(152, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 14, 'OT', '너는 잣나무로 네게 방주를 만들되, 그 방주에 간들을 만들고, 그것을 안과 밖에 역청으로 칠하라.'),
(153, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 15, 'OT', '네가 그것을 지을 모양은 이러하니, 방주의 길이는 삼백 규빗, 너비는 오십 규빗, 높이는 삼십 규빗이니라.'),
(154, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 16, 'OT', '방주에 창을 내되 위에서부터 한 규빗에 미치게 하고 방주의 문은 그 옆에 두되 아래층, 둘째 층, 셋째 층으로 만들지니라.'),
(155, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 17, 'OT', '나와, 내가 홍수 곧 물을 땅 위에 내리리니 하늘 아래에서 생명의 기식이 있는 모든 육체를 멸절시키려 함이라 땅에 있는 모든 것이 죽으리라'),
(156, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 18, 'OT', '그러나 나는 너와 내 언약을 세우리니, 너는 네 아들들과 네 아내와 네 며느리들과 함께 그 방주로 들어갈지니라.'),
(157, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 19, 'OT', '모든 육체를 가진 모든 생물 중에서 너는 각 종류에서 둘씩 방주로 데려와 너와 함께 살게 하라, 수컷과 암컷이 되리라.'),
(158, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 20, 'OT', '새가 그 종류대로, 가축이 그 종류대로, 땅에 기는 모든 것이 그 종류대로, 각기 둘씩 네게로 나아오리니 그 생명을 보존하게 하려 함이라'),
(159, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 21, 'OT', '너는 먹을 수 있는 모든 먹을 것을 네게로 취하여 네게 모으라 그것이 너와 그들에게 먹을 것이 되리라'),
(160, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 6, 22, 'OT', '노아가 그와 같이 하였으니, 곧 하나님이 그에게 명령하신 모든 대로 그가 행하였더라.'),
(161, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 1, 'OT', '여호와께서 노아에게 이르시되, 너와 네 온 집은 방주로 들어가라, 이는 내가 이 세대에 네가 내 앞에서 의롭다는 것을 보았음이니라.'),
(162, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 2, 'OT', '모든 정결한 짐승 중에서 너는 암수 일곱씩 취하고, 정결하지 아니한 짐승 중에서는 암수 둘씩 취할지니라.'),
(163, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 3, 'OT', '또한 하늘의 새들도 일곱씩, 수컷과 암컷을 취하여 온 땅의 지면에 씨를 살아 있게 하려 함이니라'),
(164, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 4, 'OT', '이제 칠 일이 지나면 내가 사십 주야를 땅에 비를 내리리니, 내가 지은 모든 생물을 지면에서 쓸어 버리리라.'),
(165, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 5, 'OT', '노아가 여호와께서 자기에게 명령하신 모든 대로 행하였더라.'),
(166, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 6, 'OT', '노아가 육백 세였고, 홍수가 땅에 물이 되었더라.'),
(167, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 7, 'OT', '노아가 그의 아들들과 그의 아내와 그의 아들들의 아내들과 함께 그와 더불어 방주로 들어갔으니, 홍수의 물들로 말미암아서였더라.'),
(168, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 8, 'OT', '정결한 짐승과 정결하지 않은 짐승과 새와 땅에 기는 모든 것에서'),
(169, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 9, 'OT', '하나님이 노아에게 명령하신 대로, 둘씩 둘씩, 수컷과 암컷이 노아에게 나아와 방주로 들어갔더라.'),
(170, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 10, 'OT', '칠 일 후에 홍수의 물들이 땅 위에 있게 되었더라.'),
(171, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 11, 'OT', '노아의 생애 육백 년째 되는 해, 둘째 달, 그 달 십칠 일에 그 날에 큰 깊음의 모든 샘들이 터지며 하늘의 창들이 열렸더라.'),
(172, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 12, 'OT', '비가 땅 위에 사십 일과 사십 밤 동안 내렸더라'),
(173, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 13, 'OT', '바로 그 날에 노아와 그의 아들들인 셈과 함과 야벳, 그리고 노아의 아내와 그의 아들들의 세 아내가 그들과 함께 방주로 들어갔더라.'),
(174, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 14, 'OT', '그들과 모든 들짐승이 그 종류대로, 모든 가축이 그 종류대로, 땅에 기는 모든 기는 것이 그 종류대로, 모든 새가 그 종류대로, 모든 날개 있는 새가 그 종류대로'),
(175, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 15, 'OT', '그들이 생명의 기운이 있는 모든 육체 가운데서 둘씩 노아에게 나아와 방주로 들어갔더라'),
(176, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 16, 'OT', '모든 육체의 암수들이 들어갔는데, 하나님이 그에게 명령하신 대로 들어갔고, 여호와께서 그를 닫아 넣으셨다.'),
(177, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 17, 'OT', '홍수가 땅 위에 사십 일 동안 있었고, 물이 많아져 방주를 떠올렸으며, 방주가 땅 위로 높이 들렸더라.'),
(178, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 18, 'OT', '물이 땅 위에 크게 넘치고 매우 많아졌으며, 방주가 물 위에서 다녔더라.'),
(179, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 19, 'OT', '물이 땅 위에 심히 심히 창일하였고 온 하늘 아래에 있는 모든 높은 산들이 덮였더라'),
(180, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 20, 'OT', '물이 위로 십오 규빗이나 넘쳐 산들을 덮었더라.'),
(181, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 21, 'OT', '땅 위에 기는 모든 육체가 죽었으니 곧 새와 가축과 들짐승과 땅 위에 기는 모든 벌레와 모든 사람이라'),
(182, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 22, 'OT', '코에 생명의 기운의 숨이 있는 모든 것, 곧 육지에 있는 모든 것이 죽었더라'),
(183, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 23, 'OT', '땅 위에 있던 모든 생물을 쓸어버리셨으니 사람부터 짐승까지, 기는 것과 하늘의 새까지라 그들이 땅에서 쓸어버림을 당하였고 오직 노아와 그와 함께 방주에 있던 자들만 남았더라'),
(184, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 7, 24, 'OT', '물이 땅 위에 더욱 창일하여 백오십 일을 지속하였더라'),
(185, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 1, 'OT', '하나님이 노아와 그와 함께 방주에 있는 모든 생물과 모든 가축을 기억하시고, 하나님이 땅 위에 바람을 지나가게 하시매 물이 줄어들었더라.'),
(186, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 2, 'OT', '깊음의 샘들과 하늘의 창들이 막히고, 하늘에서 비가 그쳤더라.'),
(187, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 3, 'OT', '물이 땅 위에서 계속 물러가고 돌아왔으며, 백오십 일이 끝날 무렵에 물이 줄어들었더라.'),
(188, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 4, 'OT', '방주가 일곱째 달, 그 달 십칠일에 아라랏 산들 위에 머물렀더라.'),
(189, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 5, 'OT', '물이 계속 줄어들어 열째 달까지 이르렀고, 열째 달 첫째 날에 산들의 봉우리들이 보였더라.'),
(190, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 6, 'OT', '사십 일이 끝난 때에 노아가 자기가 만든 방주의 창문을 열었더라.'),
(191, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 7, 'OT', '그가 까마귀를 내보내매, 까마귀가 나가서 다시 오기를 땅 위에서 물이 마를 때까지 하였더라.'),
(192, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 8, 'OT', '그가 그 비둘기를 자기에게서 내보내어 물이 땅의 표면에서 줄었는지를 보려 하였더라'),
(193, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 9, 'OT', '비둘기가 발바닥을 둘 곳을 찾지 못하고 그에게로, 방주로 돌아왔으니 이는 물이 온 땅의 표면에 있었음이라 그가 손을 내밀어 그를 잡아 방주 속 자기에게로 데려왔더라'),
(194, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 10, 'OT', '또 칠 일을 기다려 다시 비둘기를 방주에서 내보내니라'),
(195, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 11, 'OT', '저녁 때에 비둘기가 그에게로 돌아왔는데, 보라, 그 입에 찢긴 감람나무 잎사귀가 있었더라. 노아가 물이 땅에서 줄어든 줄을 알았더라.'),
(196, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 12, 'OT', '또 칠 일을 더 기다려 비둘기를 내보냈더니 그가 다시는 그에게로 돌아오지 아니하였더라'),
(197, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 13, 'OT', '육백 일년 정월 곧 그 달 일일에 땅에서 물이 마르니라. 노아가 방주의 덮개를 벗기고 보니, 보라, 땅의 표면이 마르니라.'),
(198, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 14, 'OT', '둘째 달 스물일곱째 날에 땅이 말랐더라.'),
(199, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 15, 'OT', '하나님이 노아에게 말씀하여 이르시되'),
(200, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 16, 'OT', '방주에서 나오라, 너와 네 아내와 네 아들들과 네 자부들이 너와 함께.'),
(201, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 17, 'OT', '너와 함께 있는 모든 육체의 모든 생물, 곧 새와 가축과 땅에 기는 모든 기는 것을 너와 함께 이끌어 내라 그것들이 땅에서 번성하고 땅에서 생육하고 많아지리라'),
(202, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 18, 'OT', '노아가 그의 아들들과 그의 아내와 그의 아들들의 아내들과 함께 나왔더라.'),
(203, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 19, 'OT', '모든 짐승과 모든 기는 것과 모든 새와 땅 위에 기는 모든 것이 그 종류대로 방주에서 나왔더라'),
(204, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 20, 'OT', '노아가 여호와를 위하여 단을 쌓고 모든 정결한 짐승 중에서와 모든 정결한 새 중에서 취하여 단에 번제를 드렸더라'),
(205, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 21, 'OT', '여호와께서 그 향기로운 냄새를 맡으시고 여호와께서 그 마음에 이르시되 내가 다시는 사람으로 인하여 땅을 저주하지 아니하리니 이는 사람의 마음의 생각이 어려서부터 악함이라 내가 행한 것 같이 다시는 모든 생물을 치지 아니하리라'),
(206, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 8, 22, 'OT', '땅이 있는 모든 날 동안에는 씨 뿌림과 거둠과 추위와 더위와 여름과 겨울과 낮과 밤이 쉬지 아니하리라'),
(207, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 1, 'OT', '하나님이 노아와 그의 아들들에게 복을 주시며 그들에게 이르시되 생육하고 번성하여 땅에 충만하라'),
(208, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 2, 'OT', '너희에 대한 두려움과 너희에 대한 공포가 땅의 모든 짐승과 하늘의 모든 새와 땅에서 기는 모든 것과 바다의 모든 물고기 위에 있으리라 그것들이 너희 손에 넘겨졌느니라'),
(209, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 3, 'OT', '살아 있는 모든 움직이는 것은 너희에게 먹을 것이 될지라 푸른 채소 같이 내가 그것을 다 너희에게 주노라'),
(210, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 4, 'OT', '다만 고기를 그 생명 되는 피째 먹지 말지니라'),
(211, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 5, 'OT', '내가 반드시 너희 생명의 피를 찾으리니 모든 짐승의 손에서 그것을 찾을 것이며, 사람의 손에서, 각 사람이 그의 형제의 손에서, 내가 사람의 생명을 찾으리라.'),
(212, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 6, 'OT', '사람의 피를 흘리는 자는 사람으로 말미암아 그 피가 흘려지리니 이는 하나님이 자기 형상대로 사람을 지으셨음이라'),
(213, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 7, 'OT', '너희는 생육하고 번성하며 땅에서 번성하여 그 가운데서 번성하라.'),
(214, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 8, 'OT', '하나님이 노아와 그와 함께 한 아들들에게 말씀하여 이르시되'),
(215, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 9, 'OT', '내가, 보라, 내가 너희와 너희 후손과 내 언약을 세우노라.'),
(216, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 10, 'OT', '또한 너희와 함께 한 모든 살아 있는 생물, 곧 새와 가축과 땅의 모든 짐승, 너희와 함께 한 그것들에게 내가 내 언약을 세우리니, 방주에서 나온 모든 것, 곧 땅의 모든 짐승에게니라.'),
(217, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 11, 'OT', '내가 너희와 내 언약을 세우리니, 다시는 모든 육체가 홍수의 물로 끊어지지 아니할 것이요, 땅을 멸할 홍수가 다시 있지 아니하리라.'),
(218, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 12, 'OT', '하나님이 말씀하시기를, 이것이 내가 나와 너희 사이에, 그리고 너희와 함께 하는 모든 살아 있는 생물 사이에 영원한 대대에 걸쳐 세우는 언약의 표징이라.'),
(219, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 13, 'OT', '내가 내 활을 구름 속에 두었나니 그것이 나와 땅 사이의 언약의 표징이 될 것이라'),
(220, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 14, 'OT', '내가 구름을 땅 위에 두를 때에 무지개가 구름 속에 나타나리라'),
(221, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 15, 'OT', '내가 나와 너희 사이에, 그리고 모든 육체 가운데 있는 모든 살아 있는 생명과의 사이에 세운 내 언약을 기억하리니, 다시는 물이 모든 육체를 멸하는 홍수가 되지 아니할지라.'),
(222, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 16, 'OT', '무지개가 구름 가운데 있으리니 내가 그것을 보고 땅 위의 모든 육체를 가진 모든 살아 있는 생물과 하나님 사이의 영원한 언약을 기억하리라'),
(223, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 17, 'OT', '하나님이 노아에게 이르시되, 이것이 내가 나와 땅 위에 있는 모든 육체 사이에 세운 언약의 표적이니라.'),
(224, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 18, 'OT', '방주에서 나온 노아의 아들들은 셈과 함과 야벳이었고, 함은 가나안의 아버지였다.'),
(225, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 19, 'OT', '노아의 이 세 아들이 이러하며, 이들로부터 온 땅이 퍼지니라.'),
(226, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 20, 'OT', '노아가 땅의 사람이 되어 포도원을 심었더라.'),
(227, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 21, 'OT', '그가 포도주를 마시고 취하여 자기 장막 안에서 벌거벗었더라'),
(228, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 22, 'OT', '가나안의 아버지 함이 그의 아버지의 하체를 보고 밖으로 나가서 그의 두 형제에게 알렸더라'),
(229, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 23, 'OT', '셈과 야벳이 그 옷을 취하여 둘 다 자기들의 어깨에 두고 뒷걸음쳐 가서 그들의 아버지의 하체를 덮었으며 그들의 얼굴은 뒤로 향하였고 그들의 아버지의 하체를 보지 아니하였더라'),
(230, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 24, 'OT', '노아가 술에서 깨어나, 그의 작은 아들이 자기에게 행한 일을 알았더라.'),
(231, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 25, 'OT', '그가 말하되, 가나안은 저주를 받으리니, 그가 그의 형제들에게 종들의 종이 되리라.'),
(232, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 26, 'OT', '그가 이르되, 셈의 하나님 여호와를 찬송하리로다. 가나안은 그들의 종이 되리라.'),
(233, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 27, 'OT', '하나님이 야벳을 창대하게 하시고 그가 셈의 장막에 거하게 하시며 가나안은 그들의 종이 되게 하시기를 원하노라'),
(234, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 28, 'OT', '홍수 후에 노아가 삼백오십 년을 살았더라.'),
(235, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 9, 29, 'OT', '노아의 모든 날은 구백오십 년이었고 그가 죽었더라.'),
(236, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 1, 'OT', '노아의 아들들 곧 셈과 함과 야벳의 족보는 이러하니라 홍수 후에 그들에게 아들들이 태어났더라'),
(237, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 2, 'OT', '야벳의 아들들은 고멜과 마곡과 마대와 야완과 두발과 메섹과 디라스며'),
(238, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 3, 'OT', '고멜의 아들들은 아스그나스와 리밧과 도갈마더라'),
(239, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 4, 'OT', '야완의 아들들은 엘리사와 다시스와 깃딤과 도다님이더라'),
(240, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 5, 'OT', '이들로부터 여러 민족의 섬들이 그들의 땅에서 나뉘었으니, 각 사람이 자기 언어대로, 그들의 가족들과 그들의 민족들에 따라 나뉘었더라.'),
(241, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 6, 'OT', '함의 아들들은 구스와 미스라임과 붓과 가나안이더라'),
(242, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 7, 'OT', '구스의 아들들은 스바와 하윌라와 삽다와 라아마와 삽드가요, 라아마의 아들들은 스바와 드단이더라.'),
(243, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 8, 'OT', '구스가 니므롯을 낳았으니, 그가 세상에서 용사가 되기 시작하였더라.'),
(244, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 9, 'OT', '그는 여호와 앞에서 용감한 사냥꾼이었으므로, 이르기를 니므롯이 여호와 앞에서 용감한 사냥꾼이었다 하느니라.'),
(245, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 10, 'OT', '그의 왕국의 시작은 바벨과 에렉과 악갓과 갈레였으며, 그 땅은 시날 땅이었더라.'),
(246, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 11, 'OT', '그 땅에서 앗수르가 나왔고, 그가 니느웨와 르호보딜과 갈라를 건축하였으며,'),
(247, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 12, 'OT', '레센은 니느웨와 갈라 사이에 있으니, 그것이 큰 성이었더라.'),
(248, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 13, 'OT', '미스라임은 루딤과 아나밈과 르하빔과 납두힘을 낳았더라'),
(249, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 14, 'OT', '바드루심과 가슬루힘과 갑도림을 낳았으니, 블레셋 사람들이 그들에게서 나왔더라.'),
(250, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 15, 'OT', '가나안은 그의 장자 시돈과 헷을 낳았더라'),
(251, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 16, 'OT', '여부스 족속과 아모리 족속과 기르가스 족속을'),
(252, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 17, 'OT', '히위 족속과 알가 족속과 신 족속을'),
(253, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 18, 'OT', '아르왓 족속과 스말 족속과 하맛 족속을 낳았으며, 그 후에 가나안 족속들의 가문들이 흩어졌더라.'),
(254, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 19, 'OT', '가나안 족속의 경계는 시돈에서부터 그랄로 들어가 가사까지요, 소돔과 고모라와 아드마와 스보임으로 들어가 라사까지였더라.'),
(255, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 20, 'OT', '이들은 함의 자손들이라 그들의 족속들과 그들의 방언들대로, 그들의 땅들과 그들의 나라들에서였더라.'),
(256, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 21, 'OT', '셈에게도 아들이 태어났으니 그는 에벨 모든 자손의 조상이요, 형인 야벳의 형제라.'),
(257, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 22, 'OT', '셈의 아들들은 엘람과 앗수르와 아르박삿과 룻과 아람이더라'),
(258, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 23, 'OT', '아람의 아들들은 우스와 훌과 게델과 마스며'),
(259, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 24, 'OT', '아르박삿은 셀라를 낳고, 셀라는 에벨을 낳았으며'),
(260, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 25, 'OT', '에벨에게 두 아들이 태어났는데, 하나의 이름은 벨렉이라 하였으니 이는 그의 시대에 땅이 나뉘었음이요, 그의 형제의 이름은 욕단이었더라.'),
(261, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 26, 'OT', '욕단은 알모닷과 셀렙과 하살마웹과 예라를 낳았더라'),
(262, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 27, 'OT', '하도람과 우살과 디글라와'),
(263, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 28, 'OT', '오발과 아비마엘과 스바를'),
(264, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 29, 'OT', '오빌과 하윌라와 요밥이니 이 모든 자는 욕단의 아들들이라'),
(265, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 30, 'OT', '그들의 거주지는 메사에서부터 스발로 가는 길의 동쪽 산이었더라.'),
(266, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 31, 'OT', '이들은 셈의 아들들이라 그들의 족속대로, 그들의 방언대로, 그들의 땅에서, 그들의 민족들대로였더라.'),
(267, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 10, 32, 'OT', '이들은 노아 아들들의 족속들이요 그들의 세대와 민족들대로라 이들에게서 홍수 후에 땅에서 민족들이 나뉘었더라'),
(268, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 1, 'OT', '온 땅이 한 언어와 한 말을 가졌더라'),
(269, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 2, 'OT', '그들이 동쪽에서 이동할 때에 시날 땅에서 평지를 만나 거기 거주하였더라.'),
(270, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 3, 'OT', '서로 말하되, “자, 벽돌을 만들어 불에 철저히 굽자” 하고 그들에게 벽돌이 돌을 대신하였고, 역청이 그들에게 진흙을 대신하였더라.'),
(271, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 4, 'OT', '그들이 말하되 “자, 우리가 성읍과 망대를 세워 그 꼭대기를 하늘에 닿게 하고 우리를 위하여 이름을 내어 온 땅의 표면에 흩어짐을 면하자” 하였더라'),
(272, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 5, 'OT', '여호와께서 사람의 아들들이 지은 그 성읍과 그 망대를 보시려고 내려오셨더라'),
(273, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 6, 'OT', '여호와께서 말씀하시되, 보라, 이 백성은 한 족속이요 그들 모두에게 한 언어가 있도다. 이것이 그들이 행하기 시작한 바이니, 이제는 그들이 행하려고 꾀하는 모든 것을 그들에게서 막을 수 없으리라.'),
(274, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 7, 'OT', '우리가 내려가서 거기서 그들의 언어를 혼잡하게 하여, 그들이 각자 서로의 말을 알아듣지 못하게 하자.'),
(275, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 8, 'OT', '여호와께서 그들을 그 곳에서 온 땅의 표면에 흩으셨고 그들이 그 성읍을 건축하기를 그쳤더라'),
(276, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 9, 'OT', '그러므로 그 이름을 바벨이라 불렀으니 이는 여호와께서 거기서 온 땅의 언어를 혼잡하게 하셨음이라 여호와께서 거기서 그들을 온 지면에 흩으셨더라'),
(277, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 10, 'OT', '이들은 셈의 족보라 셈이 백 세에 홍수 후 이 년에 아르박삿을 낳았으며'),
(278, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 11, 'OT', '셈은 아르박삿을 낳은 후에 오백 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(279, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 12, 'OT', '아르박삿은 삼십오 년을 살고 셀라를 낳았으며'),
(280, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 13, 'OT', '아르박삿은 셀라를 낳은 후에 사백삼 년을 살며 아들들과 딸들을 낳았더라.'),
(281, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 14, 'OT', '셀라는 삼십 세에 에벨을 낳았으며'),
(282, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 15, 'OT', '셀라는 에벨을 낳은 후에 사백삼 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(283, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 16, 'OT', '에벨은 삼십사 년을 살았고, 벨렉을 낳았으며,'),
(284, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 17, 'OT', '에벨은 벨렉을 낳은 후에 사백삼십 년을 살았으며, 아들들과 딸들을 낳았더라.'),
(285, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 18, 'OT', '벨렉은 삼십 년을 살았고, 르우를 낳았으며,'),
(286, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 19, 'OT', '벨렉은 르우를 낳은 후에 이백구 년을 살며 아들들과 딸들을 낳았더라.'),
(287, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 20, 'OT', '르우는 삼십이 년을 살았고 스룩을 낳았으며'),
(288, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 21, 'OT', '르우가 스룩을 낳은 후에 이백 칠 년을 살며 아들들과 딸들을 낳았더라.'),
(289, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 22, 'OT', '스룩은 삼십 년을 살았고 나홀을 낳았으며'),
(290, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 23, 'OT', '스룩이 나홀을 낳은 후에 이백 년을 살며 아들들과 딸들을 낳았더라.'),
(291, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 24, 'OT', '나홀은 이십구 세에 살았고, 데라를 낳았더라.'),
(292, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 25, 'OT', '나홀은 데라를 낳은 후에 백십구 년을 살며 아들들과 딸들을 낳았더라.'),
(293, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 26, 'OT', '데라는 칠십 년을 살았고, 아브람과 나홀과 하란을 낳았더라.'),
(294, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 27, 'OT', '데라의 족보는 이러하니라 데라가 아브람과 나홀과 하란을 낳았고 하란이 롯을 낳았더라'),
(295, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 28, 'OT', '하란이 그의 아버지 데라보다 먼저 그의 본토 갈대아 우르에서 죽었더라.'),
(296, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 29, 'OT', '아브람과 나홀이 그들을 위하여 아내들을 취하였으니 아브람의 아내의 이름은 사래요 나홀의 아내의 이름은 밀가라 하란의 딸이요 하란은 밀가의 아버지이며 이스가의 아버지더라'),
(297, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 30, 'OT', '사래는 잉태하지 못하여 자식이 없었더라.'),
(298, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 31, 'OT', '데라가 그 아들 아브람과 하란의 아들 그 손자 롯과 그 자부 아브람의 아내 사래를 데리고 갈대아 우르에서 떠나 가나안 땅으로 가고자 하여 하란에 이르러 거기 거하였더라'),
(299, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 11, 32, 'OT', '데라의 날들은 이백 오 년이었고, 데라는 하란에서 죽었더라.'),
(300, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 1, 'OT', '여호와께서 아브람에게 이르시되 너는 네 땅과 네 친족과 네 아버지의 집을 떠나 내가 네게 보여 줄 땅으로 가라'),
(301, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 2, 'OT', '내가 너로 큰 민족을 이루고 네게 복을 주며 네 이름을 창대하게 하리니 너는 복이 될지라'),
(302, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 3, 'OT', '너를 축복하는 자들을 내가 축복하리니 너를 저주하는 자는 내가 저주하리라 땅의 모든 족속이 너로 말미암아 복을 받으리라'),
(303, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 4, 'OT', '아브람이 여호와께서 그에게 말씀하신 대로 갔고 롯도 그와 함께 갔으며, 아브람이 하란을 떠날 때에 나이가 칠십오 세였더라.'),
(304, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 5, 'OT', '아브람이 그의 아내 사래와 그의 조카 롯과 그들이 모은 모든 소유와 하란에서 얻은 사람들을 데리고 가나안 땅으로 가려고 떠나서, 그들이 가나안 땅에 이르렀더라.'),
(305, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 6, 'OT', '아브람이 그 땅을 지나 세겜 곳, 모레 상수리나무까지 이르렀고, 그 때에 가나안 사람이 그 땅에 있었더라.'),
(306, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 7, 'OT', '여호와께서 아브람에게 나타나 이르시되 내가 이 땅을 네 자손에게 주리라 하시니 그가 자기에게 나타나신 여호와를 위하여 거기서 제단을 쌓았더라'),
(307, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 8, 'OT', '그가 거기서 벧엘 동쪽 산으로 옮겨 장막을 쳤는데, 벧엘은 서쪽에 있고 아이는 동쪽에 있었으며, 그가 거기서 여호와를 위하여 제단을 쌓고 여호와의 이름을 불렀더라.'),
(308, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 9, 'OT', '아브람이 계속 떠나 남방으로 옮겨 갔더라'),
(309, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 10, 'OT', '그 땅에 기근이 있었고, 아브람이 그곳에 우거하려고 애굽으로 내려갔으니, 이는 그 땅에 기근이 심하였음이라.'),
(310, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 11, 'OT', '그가 애굽에 들어가려고 가까이 이르렀을 때에, 그가 자기 아내 사래에게 말하되, "보라, 내가 알거니와 너는 보기에 아리따운 여인이라."'),
(311, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 12, 'OT', '애굽 사람들이 너를 볼 때에 그들이 말하기를 이것이 그의 아내라 하고 나를 죽이고 너는 살리리라'),
(312, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 13, 'OT', '너는 나의 누이라 하라, 내가 너로 말미암아 잘 되고 내 목숨이 너로 말미암아 살게 하려 함이라.'),
(313, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 14, 'OT', '아브람이 애굽에 이르렀을 때에 애굽 사람들이 그 여인을 보니 그가 심히 아름다웠더라.'),
(314, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 15, 'OT', '바로의 고관들이 그녀를 보고 바로 앞에서 그녀를 칭찬하니, 그 여인이 바로의 집으로 취하여졌더라.'),
(315, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 16, 'OT', '아브람에게 그녀로 인하여 잘 대접하셨고, 그에게 양과 소와 나귀들과 종들과 여종들과 암나귀들과 낙타들이 있게 되었더라.'),
(316, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 17, 'OT', '여호와께서 아브람의 아내 사래의 일로 말미암아 바로와 그의 집에 큰 재앙들을 내리셨더라.'),
(317, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 18, 'OT', '바로가 아브람을 불러 이르되 네가 내게 행한 이 일이 무엇이냐 어찌하여 그가 네 아내인 것을 내게 알리지 아니하였느냐'),
(318, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 19, 'OT', '어찌하여 네가 그를 내 누이라 말하여 내가 그를 아내로 취하게 하였느냐? 이제 보라 네 아내가 여기 있으니 데려가라.'),
(319, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 12, 20, 'OT', '바로가 그에 대해 사람들에게 명령하매 그들이 그와 그의 아내와 그의 모든 소유를 보내었더라'),
(320, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 1, 'OT', '아브람이 애굽에서 올라가되 그와 그의 아내와 그의 모든 소유와 그와 함께한 롯도 네게브로 갔더라'),
(321, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 2, 'OT', '아브람은 가축과 은과 금에 있어서 매우 부유하였다.'),
(322, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 3, 'OT', '그가 그의 여정대로 남방에서부터 벧엘까지 갔으며, 처음에 그의 장막이 있었던 곳, 곧 벧엘과 아이 사이에 이르렀더라.'),
(323, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 4, 'OT', '처음에 그가 거기서 제단을 만든 곳으로, 아브람이 거기서 여호와의 이름을 불렀더라.'),
(324, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 5, 'OT', '또한 아브람과 함께 가는 롯에게도 양 떼와 소 떼와 장막들이 있었다.'),
(325, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 6, 'OT', '그 땅이 그들이 함께 거주함을 감당하지 못하였으니 이는 그들의 소유가 많아서 그들이 함께 거주할 수 없었음이라'),
(326, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 7, 'OT', '아브람의 가축을 치는 목자들과 롯의 가축을 치는 목자들 사이에 다툼이 있었고, 그 때에 가나안 사람과 브리스 사람이 그 땅에 거주하고 있었더라.'),
(327, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 8, 'OT', '아브람이 롯에게 이르되, 원하건대 나와 너 사이에, 또 내 목자들과 네 목자들 사이에 다툼이 없게 하라, 우리는 형제들이니라.'),
(328, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 9, 'OT', '온 땅이 네 앞에 있지 아니하냐? 내게서 청하노니 나를 떠나라. 네가 왼쪽을 취하면 나는 오른쪽으로 가고, 네가 오른쪽을 취하면 나는 왼쪽으로 가리라.'),
(329, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 10, 'OT', '롯이 눈을 들어 요단 온 평지를 보니, 그 온 땅이 물이 넉넉하였으니, 여호와께서 소돔과 고모라를 멸하시기 전이었고, 여호와의 동산 같고 애굽 땅과 같아서 소알까지 이르렀더라.'),
(330, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 11, 'OT', '롯이 요단 온 들을 택하고 동으로 옮겼으며, 그들이 서로 떠났더라.'),
(331, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 12, 'OT', '아브람은 가나안 땅에 거하였고, 롯은 평지의 성읍들에 거하였으며, 그 장막을 세워 소돔까지 이르렀더라.'),
(332, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 13, 'OT', '소돔 사람들은 악하며 여호와 앞에 심히 죄인들이었더라'),
(333, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 14, 'OT', '여호와께서 아브람에게 이르시되, 롯이 그에게서 갈라선 후에, 너는 눈을 들어 네가 있는 곳에서 북쪽과 남쪽과 동쪽과 서쪽을 바라보라.'),
(334, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 15, 'OT', '네가 보는 모든 땅을 내가 너와 네 자손에게 영원히 주리라'),
(335, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 16, 'OT', '내가 네 자손을 땅의 티끌 같게 하리니, 사람이 땅의 티끌을 셀 수 있다면 네 자손도 셀 수 있으리라.'),
(336, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 17, 'OT', '일어나 그 땅을 그 길이와 그 너비로 두루 다녀 보라, 내가 그것을 네게 주리라.'),
(337, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 13, 18, 'OT', '아브람이 장막을 옮겨 헤브론에 있는 마므레의 상수리나무들 사이에 이르러 거주하며, 거기서 여호와께 제단을 쌓았더라.'),
(338, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 1, 'OT', '그 때에 시날 왕 아므라벨과 엘라살 왕 아리옥과 엘람 왕 그돌라오멜과 고임 왕 디달의 시대에 일어난 일이라'),
(339, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 2, 'OT', '소돔 왕 베라와 고모라 왕 비르사와 아드마 왕 시납과 스보임 왕 세메벨과 벨라 곧 소알 왕과 싸웠더라'),
(340, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 3, 'OT', '이 모든 자들이 싯딤 골짜기, 곧 염해에 함께 모였더라.'),
(341, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 4, 'OT', '십이 년 동안 그들이 그돌라오멜을 섬겼고, 십삼 년째에 그들이 반역하였더라.'),
(342, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 5, 'OT', '제 십사 년에 그돌라오멜과 그와 함께한 왕들이 와서 아스드롯 가르나임에서 르바 족속을, 함에서 수스 족속을, 사웨 기랴다임에서 엠 족속을 쳤더라.'),
(343, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 6, 'OT', '호리 족속을 그들의 산 세일에서, 광야 곁에 있는 엘바란까지 이르렀더라.'),
(344, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 7, 'OT', '그들이 돌아와 엔미스밧 곧 가데스에 이르러 아말렉 족속의 모든 들판을 쳤고 또한 하사손다말에 사는 아모리 족속도 쳤더라'),
(345, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 8, 'OT', '소돔 왕과 고모라 왕과 아드마 왕과 스보임 왕과 벨라 곧 소알 왕이 나와서 싯딤 골짜기에서 그들과 전쟁을 벌였더라.'),
(346, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 9, 'OT', '곧 엘람 왕 그돌라오멜과, 고임 왕 디달과, 시날 왕 아므라벨과, 엘라살 왕 아리옥, 네 왕이 다섯 왕과 함께 하였더라.'),
(347, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 10, 'OT', '싯딤 골짜기에는 역청 구덩이들이 많았고, 소돔 왕과 고모라 왕이 도망하여 거기 빠졌으며, 남은 자들은 산으로 도망하였더라.'),
(348, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 11, 'OT', '그들이 소돔과 고모라의 모든 재물과 모든 양식을 빼앗아 갔더라'),
(349, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 12, 'OT', '그들이 아브람의 형제의 아들 롯과 그의 소유를 붙잡아 갔는데, 그가 소돔에 거주하고 있었더라.'),
(350, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 13, 'OT', '도망한 자가 와서 히브리 사람 아브람에게 고하니, 그가 아모리 사람 마므레의 상수리나무들 곁에 거주하고 있었는데, 마므레는 에스골의 형제요 아넬의 형제였으며, 그들은 아브람과 동맹한 자들이었더라.'),
(351, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 14, 'OT', '아브람이 그의 형제가 사로잡혔음을 듣고, 자기 집에서 태어난 훈련된 자 삼백 십 팔 명을 거느리고 단까지 쫓아가니라.'),
(352, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 15, 'OT', '그가 밤에 자기와 그의 종들이 그들을 나누어 치고, 다메섹 왼편에 있는 호바까지 그들을 쫓았더라.'),
(353, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 16, 'OT', '그가 모든 재물을 되돌렸고, 또한 그의 형제 롯과 그의 재물도 되돌렸으며, 또 그 여자들과 백성도 되돌렸더라.'),
(354, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 17, 'OT', '소돔 왕이 그를 맞으러 나왔으니, 그가 그돌라오멜과 그와 함께 한 왕들을 쳐부수고 돌아온 후에, 사웨 골짜기 곧 왕의 골짜기로 나왔더라.'),
(355, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 18, 'OT', '살렘 왕 멜기세덱이 떡과 포도주를 내왔으니 그는 지극히 높으신 하나님의 제사장이었더라'),
(356, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 19, 'OT', '그가 아브람을 축복하며 이르되, 지극히 높으신 하나님, 하늘과 땅의 소유주이신 여호와께서 아브람에게 복을 주시기를 원하노라.'),
(357, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 20, 'OT', '지극히 높으신 하나님이여, 찬송을 받으소서, 그가 네 대적들을 네 손에 붙이셨도다. 그가 모든 것에서 십분의 일을 그에게 주었더라.'),
(358, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 21, 'OT', '소돔 왕이 아브람에게 말하되, "사람들은 내게 주고, 재물은 네가 취하라."'),
(359, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 22, 'OT', '아브람이 소돔 왕에게 이르되, 내가 하늘과 땅의 소유주이신 지극히 높으신 하나님 여호와께 내 손을 들어 맹세하였노라'),
(360, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 23, 'OT', '실 한 가닥이나 신발 끈 하나라도 내가 네게 속한 모든 것에서 취하지 아니하리니, 이는 네가 말하기를 내가 아브람을 부하게 하였다 할까 함이라'),
(361, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 14, 24, 'OT', '오직 소년들이 먹은 것과 나와 함께 간 사람들, 곧 아넬과 에스골과 마므레의 몫만 제외하라. 그들이 그들의 몫을 가질 것이다.'),
(362, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 1, 'OT', '이 일들 후에 여호와의 말씀이 환상 중에 아브람에게 임하여 이르시되, 아브람아 두려워 말라, 나는 너의 방패요, 너의 지극히 큰 상급이니라'),
(363, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 2, 'OT', '아브람이 말하되 주 여호와여 무엇을 내게 주시려나이까 나는 자식 없이 가고 있사오며 내 집의 청지기는 다메섹 엘리에셀이니이다'),
(364, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 3, 'OT', '아브람이 이르되, 보소서, 주께서 내게 씨를 주지 아니하셨으니, 보소서, 내 집에서 난 자가 나를 상속하리이다.'),
(365, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 4, 'OT', '보라, 여호와의 말씀이 그에게 임하여 이르시되, 이 사람은 네 상속자가 아니요, 네 몸에서 나올 자가 네 상속자가 되리라 하셨더라.'),
(366, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 5, 'OT', '그를 이끌고 밖으로 나가서 이르시되 하늘을 바라보고 별들을 셀 수 있거든 세어 보라 또 그에게 이르시되 네 자손이 이와 같으리라'),
(367, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 6, 'OT', '그가 여호와를 믿으니 여호와께서 그것을 그에게 의로 여기셨더라'),
(368, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 7, 'OT', '그가 그에게 말씀하시기를, 나는 너를 갈대아 우르에서 이끌어 내어 이 땅을 네게 주어 차지하게 하는 여호와라.'),
(369, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 8, 'OT', '그가 말하되, 주 여호와여, 내가 그것을 상속받을 줄을 무엇으로 알리이까?'),
(370, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 9, 'OT', '그가 그에게 이르되, 나를 위하여 삼 년 된 암소와 삼 년 된 암염소와 삼 년 된 수양과 산비둘기와 새끼 비둘기를 취하라.'),
(371, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 10, 'OT', '그가 그 모든 것을 자기에게 가져다가 그것들을 중간에서 쪼개고 각 조각을 그 짝을 향하여 마주 놓았으며, 그 새는 쪼개지 아니하였더라.'),
(372, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 11, 'OT', '솔개가 그 사체 위에 내리매, 아브람이 그것들을 쫓아냈더라.'),
(373, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 12, 'OT', '해가 지려 할 때에 깊은 잠이 아브람에게 내렸고, 보라, 큰 어둠의 두려움이 그에게 내리더라.'),
(374, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 13, 'OT', '그가 아브람에게 이르되, 너는 반드시 알라, 네 자손이 그들의 것이 아닌 땅에서 나그네가 될 것이며, 그들을 섬길 것이고, 그들이 사백 년 동안 그들을 괴롭게 하리라.'),
(375, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 14, 'OT', '그들이 섬길 그 민족도 내가 심판하리니 그 후에 그들이 큰 재물을 가지고 나오리라'),
(376, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 15, 'OT', '너는 평안히 네 조상들에게로 갈 것이며, 좋은 늙음으로 장사될 것이다.'),
(377, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 16, 'OT', '사 대 만에 그들이 이리로 돌아오리니 이는 아모리 족속의 죄악이 아직 가득 차지 아니함이니라'),
(378, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 17, 'OT', '해가 지고 어둠이 내렸을 때, 보라 연기 나는 화덕과 불붙은 횃불이 그 조각들 사이로 지나가더라.'),
(379, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 18, 'OT', '그 날에 여호와께서 아브람과 언약을 세워 이르시되, 내가 이 땅을 애굽 강에서부터 그 큰 강 유브라데 강까지 네 자손에게 주었노라.'),
(380, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 19, 'OT', '켄 족속과 그니스 족속과 갓몬 족속을'),
(381, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 20, 'OT', '헷 족속과 브리스 족속과 르바 족속을'),
(382, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 15, 21, 'OT', '아모리 족속과 가나안 족속과 기르가스 족속과 여부스 족속을'),
(383, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 1, 'OT', '아브람의 아내 사래는 그에게 자식을 낳지 못하였고, 그에게 애굽 여종이 하나 있었는데 그 이름은 하갈이었다.'),
(384, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 2, 'OT', '사래가 아브람에게 이르되, 보소서, 여호와께서 나를 출산하지 못하게 하셨으니 원하건대 내 여종에게 들어가소서, 혹시 내가 그로 말미암아 자녀를 얻을까 하노라 하매, 아브람이 사래의 목소리를 들으니라.'),
(385, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 3, 'OT', '아브람의 아내 사래가 그 여종 애굽 사람 하갈을 데려다가, 아브람이 가나안 땅에 거한 지 십 년이 끝난 때에, 그녀를 자기 남편 아브람에게 아내로 주었더라.'),
(386, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 4, 'OT', '그가 하갈에게 들어갔더니 그가 잉태하였고, 그가 잉태한 것을 보고 그의 여주인이 그의 눈에 멸시를 받게 되었더라.'),
(387, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 5, 'OT', '사래가 아브람에게 이르되, 나의 해받음이 네게 있도다. 내가 나의 여종을 네 품에 주었거늘 그가 잉태함을 보고 내가 그 눈에 멸시를 받았도다. 여호와께서 나와 너 사이에 판단하시기를 원하노라.'),
(388, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 6, 'OT', '아브람이 사래에게 이르되, 보라 네 여종이 네 손에 있으니 네 눈에 좋은 대로 그에게 행하라 하매, 사래가 그를 학대하니 그가 그 앞에서 도망하였더라.'),
(389, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 7, 'OT', '여호와의 사자가 광야의 물 샘 위, 곧 술 길에 있는 샘 위에서 그를 만났더라.'),
(390, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 8, 'OT', '그가 말하되, “하갈아, 사래의 여종아, 네가 어디서 왔으며 어디로 가느냐?” 그가 말하되, “내가 나의 여주인 사래의 낯을 피하여 도망하나이다.”'),
(391, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 9, 'OT', '여호와의 사자가 그녀에게 이르되, 네 여주인에게로 돌아가서 그녀의 손 아래에서 복종하라.'),
(392, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 10, 'OT', '여호와의 사자가 그녀에게 이르되, 내가 네 자손을 크게 번성하게 하리니, 그 수가 많아 셀 수 없으리라.'),
(393, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 11, 'OT', '여호와의 사자가 그녀에게 이르되, 보라 네가 잉태하여 아들을 낳을 것이요, 너는 그의 이름을 이스마엘이라 부를지니, 이는 여호와께서 네 고통을 들으셨음이니라.'),
(394, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 12, 'OT', '그는 사람 중에 들나귀 같이 되리니 그의 손이 모든 사람을 대적하고 모든 사람의 손이 그를 대적하리라 그가 모든 형제 앞에 거하리라'),
(395, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 13, 'OT', '그녀가 자기에게 말씀하신 여호와의 이름을 불러 이르되, 당신은 나를 보시는 하나님이시니이다 하였으니, 이는 그녀가 말하기를, 내가 여기서 나를 보시는 이를 본 뒤에 살아 있도다 하였음이라.'),
(396, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 14, 'OT', '그러므로 그가 그 샘을 브엘라해로이라 불렀으니, 보라, 그것이 가데스와 베렛 사이에 있도다.'),
(397, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 15, 'OT', '하갈이 아브람에게 아들을 낳으매, 아브람이 하갈이 낳은 그의 아들의 이름을 이스마엘이라 하였더라.'),
(398, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 16, 16, 'OT', '아브람이 팔십육 세였을 때에 하갈이 아브람에게 이스마엘을 낳았더라'),
(399, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 1, 'OT', '아브람이 아흔아홉 살이 되었을 때에 여호와께서 아브람에게 나타나서 그에게 이르시되 나는 전능한 하나님이라 내 앞에서 행하고 완전하라'),
(400, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 2, 'OT', '내가 내 언약을 나와 너 사이에 세우고 너를 심히 많이 번성하게 하리라.'),
(401, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 3, 'OT', '아브람이 그의 얼굴에 엎드리니, 하나님이 그와 말씀하여 이르시되'),
(402, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 4, 'OT', '내가 보라, 내 언약이 너와 함께 있나니, 네가 많은 민족들의 아버지가 될지라.'),
(403, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 5, 'OT', '네 이름을 다시는 아브람이라 부르지 아니할 것이요, 네 이름이 아브라함이 될 것이니, 이는 내가 너를 많은 민족의 아버지로 세웠음이니라.'),
(404, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 6, 'OT', '내가 너를 심히 매우 번성하게 하리니, 내가 너를 민족들이 되게 하리라. 왕들이 네게서 나오리라.'),
(405, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 7, 'OT', '내가 내 언약을 나와 너 사이에, 그리고 네 후손과 그들의 대대 사이에 세워 영원한 언약을 삼고, 너와 네 후손의 하나님이 되리라.'),
(406, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 8, 'OT', '내가 너와 네 후손에게 네가 거주하는 땅, 곧 가나안 온 땅을 영원한 소유로 주리니, 내가 그들의 하나님이 되리라.'),
(407, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 9, 'OT', '하나님이 아브라함에게 이르시되, 너는 내 언약을 지키라, 너와 네 후손이 대대로 지키라.'),
(408, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 10, 'OT', '이것이 나와 너희와 네 후손 사이에 너희가 지킬 내 언약이니, 너희 중 모든 남자는 할례를 받을지니라.'),
(409, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 11, 'OT', '너희는 너희 포피의 살을 할례하라 그것이 나와 너희 사이에 언약의 표징이 되리라'),
(410, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 12, 'OT', '너희 중에 팔 일 된 자마다 할례를 받을지니 너희 대대에 모든 남자가 집에서 난 자나 돈으로 산 어떤 이방 사람의 아들이든지 네 씨가 아닌 자라도 할례를 받을 것이라'),
(411, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 13, 'OT', '네 집에서 태어난 자와 네 돈으로 산 자는 반드시 할례를 받아야 하리니, 내 언약이 너희 살에 있어 영원한 언약이 되리라.'),
(412, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 14, 'OT', '할례받지 아니한 남자 곧 자기 포피의 살을 베지 아니한 자, 그 영혼은 그의 백성 가운데서 끊어지리니 그가 내 언약을 어겼음이니라.'),
(413, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 15, 'OT', '하나님이 아브라함에게 이르시되 네 아내 사래는 그 이름을 사래라 부르지 말라 그 이름이 사라가 될 것임이니라'),
(414, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 16, 'OT', '내가 그녀를 축복하고 또한 그녀로 말미암아 네게 아들을 주리라 내가 그녀를 축복하리니 그녀가 민족들을 낳으리라 민족들의 왕들이 그녀에게서 나오리라'),
(415, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 17, 'OT', '아브라함이 그의 얼굴에 엎드려 웃으며 그의 마음에 이르되, 백 세 된 사람이 아이를 낳겠느냐, 그리고 사라가 구십 세의 딸이 되어 낳겠느냐 하니라'),
(416, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 18, 'OT', '아브라함이 하나님께 말하되, 이스마엘이나 주 앞에 살기를 원하나이다.'),
(417, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 19, 'OT', '하나님이 말씀하시되, 참으로 네 아내 사라가 네게 아들을 낳을 것이며, 너는 그의 이름을 이삭이라 부를지니라. 내가 그와 내 언약을 세우리니, 그의 후손에게 영원한 언약이 되리라.'),
(418, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 20, 'OT', '이스마엘에 관하여는 내가 네 말을 들었나니, 보라 내가 그에게 복을 주고 그를 번성하게 하며 그를 심히 많게 하리라. 그가 열두 방백을 낳을 것이요, 내가 그를 큰 민족이 되게 하리라.'),
(419, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 21, 'OT', '내가 내 언약을 이삭과 세우리니, 곧 사라가 이 정한 때에 다음 해에 네게 낳을 자니라.'),
(420, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 22, 'OT', '그가 그와 말하기를 마치니, 하나님이 아브라함 위에서 올라가셨더라.'),
(421, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 23, 'OT', '아브라함이 그의 아들 이스마엘과 그의 집에서 태어난 모든 자와 그의 돈으로 산 모든 자, 곧 아브라함의 집 사람들 중 모든 남자를 데려다가 그들의 포피의 살을 할례하였으니, 바로 그 날에 하나님이 그에게 말씀하신 대로였더라.'),
(422, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 24, 'OT', '아브라함이 그 포피의 살을 할례받을 때에 구십구 세였더라.'),
(423, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 25, 'OT', '그의 아들 이스마엘은 자기 포경의 살을 할례받을 때에 열세 살이었더라.'),
(424, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 26, 'OT', '바로 그 날에 아브라함과 그의 아들 이스마엘이 할례를 받았더라.'),
(425, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 17, 27, 'OT', '그의 집의 모든 남자, 집에서 태어난 자와 이방 사람에게서 돈으로 산 자가 그와 함께 할례를 받았더라.'),
(426, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 1, 'OT', '여호와께서 마므레의 상수리나무들 사이에서 그에게 나타나셨는데, 그가 날이 뜨거울 때에 장막 문에 앉아 있었더라.'),
(427, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 2, 'OT', '그가 눈을 들어 보니, 보라, 세 사람이 그 앞에 서 있는지라, 그가 보고 장막 문에서 그들을 맞으러 달려가서 땅에 엎드려 절하니라.'),
(428, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 3, 'OT', '주께서 이르시되, 내 주여, 만일 내가 주의 눈앞에서 은혜를 입었사오면 원하건대 주의 종을 떠나 지나가지 마옵소서.'),
(429, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 4, 'OT', '물을 조금 가져오게 하소서, 당신들의 발을 씻고 나무 아래에서 쉬소서.'),
(430, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 5, 'OT', '내가 떡 한 조각을 가져오리니 당신들의 마음을 위로한 후에 지나가소서, 이는 당신들이 종에게 이르렀음이니이다. 그들이 이르되, 네가 말한 대로 그리하라.'),
(431, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 6, 'OT', '아브라함이 급히 장막으로 사라에게 들어가 이르되, 속히 고운 가루 세 스아를 가져다가 반죽하여 과자를 만들라 하니라'),
(432, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 7, 'OT', '아브라함이 소 떼에게로 달려가서 부드럽고 좋은 송아지를 취하여 그 하인에게 주니 그가 그것을 급히 준비하니라'),
(433, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 8, 'OT', '아브라함이 버터와 우유와 그가 준비한 송아지를 가져다가 그들 앞에 놓고, 그가 나무 아래 그들 곁에 서 있으매 그들이 먹으니라.'),
(434, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 9, 'OT', '그들이 그에게 말하되 네 아내 사라가 어디 있느냐 하니 그가 이르되 보라 장막에 있나이다'),
(435, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 10, 'OT', '그가 말하되, 내가 정녕 생명의 때에 네게로 돌아오리니, 보라 네 아내 사라에게 아들이 있으리라 하니, 사라가 그 뒤에 있는 장막 문에서 듣고 있더라.'),
(436, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 11, 'OT', '아브라함과 사라는 나이가 많아 늙었고, 사라에게는 여인들의 관례가 끊어졌더라.'),
(437, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 12, 'OT', '사라가 속으로 웃으며 이르되, 내가 늙었으니 내게 낙이 있으랴, 내 주인도 늙었도다.'),
(438, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 13, 'OT', '여호와께서 아브라함에게 이르시되, 사라가 어찌하여 웃으며 말하기를, 내가 늙었는데 참으로 내가 낳으리요 하느냐'),
(439, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 14, 'OT', '여호와께 능하지 못한 일이 있겠느냐? 정한 때에 내가 네게로 돌아오리니, 생명의 때에 사라에게 아들이 있으리라.'),
(440, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 15, 'OT', '사라가 두려워서 부인하며 이르되 내가 웃지 아니하였나이다 하니 그가 이르되 아니라 네가 웃었느니라'),
(441, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 16, 'OT', '그 사람들이 거기서 일어나 소돔 쪽을 바라보았고, 아브라함은 그들을 전송하려고 그들과 함께 가더라.'),
(442, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 17, 'OT', '여호와께서 말씀하시되, 내가 행하는 것을 아브라함에게 숨기겠느냐?'),
(443, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 18, 'OT', '아브라함은 반드시 크고 강한 민족이 될 것이며, 땅의 모든 민족들이 그로 말미암아 복을 받을 것이다.'),
(444, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 19, 'OT', '내가 그를 아노니 이는 그가 그의 아들들과 그의 집을 자기 뒤에 명하여 여호와의 길을 지켜 의와 공의를 행하게 하려 함이며, 이는 여호와께서 아브라함에 대하여 말씀하신 것을 그에게 이루려 하심이니라.'),
(445, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 20, 'OT', '여호와께서 이르시되, 소돔과 고모라의 부르짖음이 크고 그들의 죄가 심히 무겁도다.'),
(446, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 21, 'OT', '내가 이제 내려가서 그 부르짖음이 내게 이른 대로 그들이 과연 다 행하였는지 보고, 그렇지 아니하면 내가 알리라.'),
(447, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 22, 'OT', '그 사람들이 거기서 떠나 소돔으로 향하여 가고 아브라함은 여호와 앞에 그대로 섰더니'),
(448, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 23, 'OT', '아브라함이 가까이 나아가 이르되, 주께서 의인을 악인과 함께 멸하시려나이까?'),
(449, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 24, 'OT', '혹시 그 성 중에 의인 오십 명이 있을지라도 주께서 그 곳을 멸하시고 그 성 안에 있는 그 오십 의인을 위하여 용서하지 아니하시리이까?'),
(450, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 25, 'OT', '주께서 이같이 행하사 의인을 악인과 함께 죽이심은 결코 주께서 하실 수 없는 일이오며, 의인이 악인과 같이 됨도 결코 주께서 하실 수 없는 일이니이다. 온 땅을 심판하시는 이가 공의를 행하지 아니하시겠나이까?'),
(451, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 26, 'OT', '여호와께서 이르시되, 내가 소돔 성 중에서 의인 오십을 찾으면 그들을 위하여 온 곳을 용서하리라.'),
(452, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 27, 'OT', '아브라함이 응답하여 이르되, 보소서, 내가 주께 말씀드리기를 감히 시작하였사오니, 나는 티끌과 재에 불과하나이다.'),
(453, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 28, 'OT', '혹시 오십 의인 중에 다섯이 부족할지라도, 그 다섯으로 인하여 온 성을 멸하시겠나이까? 그가 이르되, 내가 거기서 사십오 인을 찾으면 멸하지 아니하리라.'),
(454, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 29, 'OT', '그가 또 다시 그에게 말하여 이르되 혹시 거기서 사십 명이 찾아지리이다 하니 그가 이르되 내가 사십 명으로 인하여 행하지 아니하리라'),
(455, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 30, 'OT', '아브라함이 이르되, 원하옵나니 내 주여 노하지 마옵시고 내가 말씀드리게 하옵소서. 혹시 거기서 삼십 명을 찾으시면 어찌 하시겠나이까? 그가 이르되, 내가 거기서 삼십 명을 찾으면 행하지 아니하리라.'),
(456, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 31, 'OT', '그가 이르되, 보소서, 내가 감히 내 주께 말씀드리나이다. 혹시 거기서 이십 명을 찾으시면 어찌 하시려나이까? 그가 이르되, 내가 그 이십 명으로 인하여 멸하지 아니하리라.'),
(457, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 32, 'OT', '아브라함이 이르되, 오 주여 노하지 마옵소서 내가 이번만 더 말씀하리이다 혹시 거기서 열 명을 찾으시면 어찌 하시려나이까 하니 여호와께서 이르시되 내가 그 열 명을 위하여도 멸하지 아니하리라'),
(458, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 18, 33, 'OT', '여호와께서 아브라함에게 말씀하기를 마치시고 떠나가시니, 아브라함도 자기 곳으로 돌아갔더라.'),
(459, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 1, 'OT', '날이 저물 때에 그 두 천사가 소돔에 이르렀고, 롯은 소돔 성문에 앉아 있더니, 롯이 그들을 보고 일어나 맞이하러 가서 얼굴을 땅에 대고 절하니라.'),
(460, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 2, 'OT', '그가 말하되 "보소서, 내 주여, 청하건대 종의 집으로 돌이켜 들어와 밤을 지내고 발을 씻고 아침에 일찍 일어나 너희 길로 가소서" 하니, 그들이 말하되 "아니라, 우리가 거리에서 밤을 지내리라" 하더라.'),
(461, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 3, 'OT', '그가 그들을 크게 권하매 그들이 그에게로 돌이켜 그의 집으로 들어오니라 그가 그들을 위하여 잔치를 베풀고 무교병을 구웠더니 그들이 먹으니라'),
(462, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 4, 'OT', '그들이 눕기 전에, 그 성 사람들 곧 소돔 사람들이 그 집을 둘러쌌으니, 젊은이로부터 늙은이까지, 모든 백성이 사방에서 모였더라.'),
(463, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 5, 'OT', '그들이 롯을 불러 그에게 이르되, 밤에 네게 온 사람들이 어디 있느냐? 그들을 우리에게로 이끌어내라, 우리가 그들을 알리라.'),
(464, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 6, 'OT', '롯이 그들에게 문 밖으로 나가서, 그 뒤로 문을 닫았다.'),
(465, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 7, 'OT', '이르되 청하노니 내 형제들아 악을 행하지 말지어다'),
(466, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 8, 'OT', '보라 내게 남자를 알지 못하는 두 딸이 있노니 청하건대 내가 그들을 너희에게로 이끌어내리라 너희 눈에 좋은 대로 그들에게 행하고 오직 이 사람들에게는 아무 일도 하지 말라 그들이 내 지붕의 그늘 아래로 들어왔음이니라'),
(467, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 9, 'OT', '그들이 말하되 “물러나라” 하고 또 말하되 “이 자가 들어와서 우거하면서 판관이 되려 하는도다 이제 우리가 그들보다 너를 더 해하리라” 하며 그 사람 롯에게 심히 강박하고 가까이 나아와 그 문을 깨뜨리려 하더라'),
(468, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 10, 'OT', '그 사람들이 손을 내밀어 롯을 자기들에게 집으로 끌어들이고 문을 닫으니라'),
(469, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 11, 'OT', '그 집 문에 있던 사람들을 작은 자로부터 큰 자까지 눈이 어둡게 하였더니 그들이 문을 찾느라고 곤비하였더라'),
(470, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 12, 'OT', '그 사람들이 롯에게 이르되, 이 외에 네게 여기 있는 자가 누구냐, 사위와 네 아들들과 네 딸들과 성중에 네게 있는 모든 자를 그 곳에서 데리고 나가라'),
(471, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 13, 'OT', '우리가 이 곳을 멸하려 하느니, 이는 그들의 부르짖음이 여호와 앞에 크게 되었음이라. 여호와께서 우리를 보내어 그것을 멸하게 하셨느니라.'),
(472, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 14, 'OT', '롯이 나가서 그 딸들을 취한 사위들에게 말하여 이르되, 너희는 일어나 이 곳에서 나가라, 여호와께서 이 성을 멸하실 것임이라 하였더니, 그가 농담하는 것 같이 그의 사위들의 눈에 보였더라.'),
(473, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 15, 'OT', '새벽이 밝아오자 천사들이 롯을 재촉하여 이르되 일어나 네 아내와 여기 있는 네 두 딸을 데리고 가라 이 성의 죄악 가운데서 함께 멸망하지 않도록 하라 하니라'),
(474, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 16, 'OT', '그가 지체하매 그 사람들이 여호와께서 그에게 인자를 더하심으로 그의 손과 그의 아내의 손과 그의 두 딸의 손을 붙잡아 그를 이끌어 내어 성 밖에 두니라'),
(475, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 17, 'OT', '그들이 그들을 밖으로 이끌어 낸 후에 그가 이르되, 네 생명을 위하여 도망하라, 네 뒤를 돌아보지 말고 온 평지에 머무르지 말며 산으로 도망하라, 너희가 소멸되지 않도록 하라.'),
(476, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 18, 'OT', '롯이 그들에게 이르되, 내 주여, 청하건대 그리 마옵소서.'),
(477, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 19, 'OT', '보소서, 주의 종이 주의 눈앞에서 은혜를 얻었고, 주께서 내 생명을 살리시려고 내게 베푸신 주의 인자를 크게 하셨나이다. 그러나 나는 그 산으로 도피할 수 없나이다. 혹시 재앙이 나를 덮쳐 내가 죽을까 두렵나이다.'),
(478, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 20, 'OT', '보라, 이 성은 도망하기에 가깝고 그것은 작은 것이니이다. 내가 거기로 도망하게 하소서, 그것은 작은 것이 아니니이까? 그러면 내 생명이 살겠나이다.'),
(479, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 21, 'OT', '그가 그에게 이르되, 보라 내가 이 일에도 네 얼굴을 들어 주었노니, 네가 말한 그 성을 내가 뒤엎지 아니하리라.'),
(480, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 22, 'OT', '그리로 급히 도망하라 네가 거기 이르기까지는 내가 아무 일도 행할 수 없노라 하셨으므로 그 성의 이름을 소알이라 불렀더라'),
(481, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 23, 'OT', '해가 땅 위에 떠올랐고, 롯은 소알에 들어갔더라.'),
(482, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 24, 'OT', '여호와께서 소돔과 고모라 위에 하늘에서 여호와에게로부터 유황과 불을 비같이 내리셨더라'),
(483, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 25, 'OT', '그가 그 성들과 온 평지와 그 성들의 모든 주민과 땅의 식물을 뒤엎으셨더라'),
(484, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 26, 'OT', '그의 아내가 그 뒤에서 돌아보았더니 소금 기둥이 되었더라.'),
(485, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 27, 'OT', '아브라함이 아침에 일찍 일어나 여호와 앞에 섰던 그 곳으로 갔더라'),
(486, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 28, 'OT', '그가 소돔과 고모라의 얼굴을 향하여 내려다보고, 그 온 평지 땅의 얼굴을 향하여 보니, 보라, 땅의 연기가 용광로의 연기같이 올라가고 있었다.'),
(487, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 29, 'OT', '하나님이 들의 성들을 멸하실 때에 하나님이 아브라함을 기억하사 그 뒤집으심 중에서 롯을 보내셨으니 곧 롯이 거주하던 성들을 뒤집으실 때였더라'),
(488, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 30, 'OT', '롯이 소알에서 올라가 산에 거하였고 그의 두 딸이 그와 함께 하였으니 이는 그가 소알에 거하기를 두려워함이라 그와 그의 두 딸이 굴에 거하였더라'),
(489, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 31, 'OT', '맏딸이 작은 딸에게 이르되, 우리 아버지는 늙으셨고, 이 땅에는 온 땅의 관례대로 우리에게 들어올 사람이 없도다.'),
(490, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 32, 'OT', '우리 아버지에게 포도주를 마시게 하고 그와 함께 눕자, 우리가 아버지로부터 자손을 보존하자.'),
(491, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 33, 'OT', '그 밤에 그들이 그들의 아버지에게 포도주를 마시게 하였고, 맏딸이 들어가서 그녀의 아버지와 함께 누웠으나, 그가 그녀가 누운 것과 일어난 것을 알지 못하였더라.'),
(492, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 34, 'OT', '이튿날에 맏딸이 작은 딸에게 이르되, 보라, 내가 어젯밤에 우리 아버지와 동침하였으니, 오늘 밤에도 우리가 그에게 포도주를 마시게 하고, 네가 들어가 그와 함께 누워, 우리가 우리 아버지로 말미암아 씨를 보존하자 하니라.'),
(493, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 35, 'OT', '그 밤에도 그들이 또 그들의 아버지에게 포도주를 마시게 하였고, 작은 딸이 일어나 그와 함께 누웠으나, 그가 그녀가 눕는 것과 일어나는 것을 알지 못하였더라.'),
(494, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 36, 'OT', '그리하여 롯의 두 딸이 그들의 아비로 말미암아 임신하였더라'),
(495, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 37, 'OT', '맏딸이 아들을 낳아 그의 이름을 모압이라 불렀으니, 그가 오늘날까지 모압의 조상이니라.'),
(496, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 19, 38, 'OT', '작은 딸도 또한 아들을 낳아 그의 이름을 벤암미라 하였으니, 그는 오늘날까지 암몬 자손의 조상이니라.'),
(497, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 1, 'OT', '아브라함이 거기서 남방 땅으로 떠나 가데스와 술 사이에 거주하며 그랄에 우거하였더라'),
(498, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 2, 'OT', '아브라함이 그의 아내 사라에 대하여 말하기를 “그는 내 누이”라 하였고, 그랄 왕 아비멜렉이 보내어 사라를 취하였더라.'),
(499, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 3, 'OT', '그 밤에 하나님이 아비멜렉에게 꿈에 나타나서 그에게 이르시되, 네가 취한 그 여인 때문에 네가 죽게 되었나니, 그녀는 남편이 있는 여자이기 때문이라.'),
(500, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 4, 'OT', '아비멜렉이 그녀에게 가까이 가지 아니하였더라. 그가 말하되, 주여, 주께서 의로운 민족도 죽이시겠나이까?'),
(501, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 5, 'OT', '그가 내게 말하기를 그는 내 누이라 하지 아니하였나이까? 그녀도 또한 그가 내 형제라 말하였사오니, 내가 온전한 마음과 깨끗한 손으로 이 일을 행하였나이다.'),
(502, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 6, 'OT', '하나님이 꿈에 그에게 이르시되, 참으로 나도 네가 네 마음의 정직함으로 이 일을 행한 줄을 알았노라. 나도 너를 막아 내게 범죄하지 않게 하였고, 그러므로 내가 그녀를 네가 만지지 못하게 하였노라.'),
(503, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 7, 'OT', '이제 그 사람의 아내를 돌려보내라 그가 선지자이니 그가 너를 위하여 기도하리니 네가 살리라 만일 네가 돌려보내지 아니하면 너와 네게 속한 모든 자가 반드시 죽을 줄 알지니라'),
(504, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 8, 'OT', '아비멜렉이 아침에 일찍 일어나 그의 모든 신복을 불러 이 모든 말을 그들의 귀에 전하니 그 사람들이 심히 두려워하더라'),
(505, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 9, 'OT', '아비멜렉이 아브라함을 불러 그에게 이르되, 네가 우리에게 무슨 일을 행하였느냐? 내가 네게 무슨 죄를 범하였기에 네가 나와 내 나라에 큰 죄를 가져왔느냐? 행해서는 안 될 일들을 네가 내게 행하였도다.'),
(506, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 10, 'OT', '아비멜렉이 아브라함에게 이르되, 네가 무엇을 보았기에 이 일을 행하였느냐?'),
(507, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 11, 'OT', '아브라함이 말하되, 내가 생각하기를 이곳에는 하나님을 두려워함이 정녕 없으니 그들이 내 아내로 인하여 나를 죽이리라 하였노라'),
(508, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 12, 'OT', '그러나 참으로 그는 내 아버지의 딸인 내 누이이지만, 내 어머니의 딸은 아니며, 그가 내 아내가 되었느니라.'),
(509, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 13, 'OT', '하나님이 나를 내 아버지 집에서 떠나 방황하게 하셨을 때에 내가 그녀에게 말하기를, “이것이 네가 내게 베풀 은혜니, 우리가 가는 모든 곳에서 나를 네 형제라 말하라” 하였노라.'),
(510, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 14, 'OT', '아비멜렉이 양과 소와 종들과 여종들을 취하여 아브라함에게 주고 그의 아내 사라를 그에게 돌려보내니라'),
(511, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 15, 'OT', '아비멜렉이 이르되, 보라 내 땅이 네 앞에 있으니 네 눈에 좋은 대로 거하라 하니라'),
(512, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 16, 'OT', '사라에게 이르되, 보라 내가 네 형제에게 은 천 개를 주었나니, 보라 그것이 너와 함께 있는 모든 자에게 네 눈을 가리는 것이 되리라, 그리고 모든 것이 바로잡혔느니라.'),
(513, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 17, 'OT', '아브라함이 하나님께 기도하매 하나님이 아비멜렉과 그의 아내와 그의 여종들을 치료하셨고 그들이 낳았더라'),
(514, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 20, 18, 'OT', '여호와께서 아비멜렉의 집의 모든 태를 완전히 닫으셨으니, 이는 아브라함의 아내 사라의 일로 인함이었더라.'),
(515, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 1, 'OT', '여호와께서 말씀하신 대로 사라를 돌보셨고, 여호와께서 이르신 대로 사라에게 행하셨더라.'),
(516, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 2, 'OT', '사라가 잉태하여 늙은 아브라함에게 아들을 낳았으니, 하나님이 그에게 말씀하신 그 정한 때에 이르러서였더라.'),
(517, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 3, 'OT', '아브라함이 그에게 태어난 그의 아들, 곧 사라가 그에게 낳은 아들의 이름을 이삭이라 불렀다.'),
(518, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 4, 'OT', '아브라함이 그의 아들 이삭을 난 지 팔 일 만에 할례를 행하였으니, 하나님이 그에게 명령하신 대로였더라.'),
(519, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 5, 'OT', '아브라함이 그의 아들 이삭을 낳을 때에 백 세였더라'),
(520, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 6, 'OT', '사라가 말하되, 하나님이 나를 위해 웃음을 만드셨으니, 듣는 모든 자가 나를 위해 웃으리라.'),
(521, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 7, 'OT', '그녀가 말하되, 누가 아브라함에게 말하였으리요, 사라가 아들들을 젖 먹이리라고? 내가 그의 늙음에 아들을 낳았도다.'),
(522, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 8, 'OT', '아이가 자라서 젖을 떼매 아브라함이 이삭이 젖을 떼는 날에 큰 잔치를 베풀었더라'),
(523, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 9, 'OT', '사라가 애굽 여인 하갈이 아브라함에게 낳은 아들이 희롱하는 것을 보았더라.'),
(524, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 10, 'OT', '그가 아브라함에게 말하되, 이 여종과 그 아들을 쫓아내라. 이 여종의 아들이 내 아들 이삭과 함께 유업을 얻지 못할 것임이라.'),
(525, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 11, 'OT', '아브라함의 눈에 그 일이 그의 아들 때문에 매우 근심스러웠더라'),
(526, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 12, 'OT', '하나님이 아브라함에게 이르시되, 그 아이와 네 여종 때문에 네 눈에 근심하지 말게 하라. 사라가 네게 말한 모든 것을 그녀의 목소리에 들으라. 이삭 안에서 네 씨가 불릴 것임이니라.'),
(527, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 13, 'OT', '또한 여종의 아들도 내가 한 민족으로 세우리니 이는 그가 네 씨이기 때문이라'),
(528, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 14, 'OT', '아브라함이 아침에 일찍 일어나 떡과 물 한 가죽부대를 취하여 하갈의 어깨에 메워 주고 그 아이를 그에게 주어 보내매 그가 떠나 브엘세바 들에서 방황하니라'),
(529, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 15, 'OT', '물이 가죽부대에서 다하였고, 그녀가 아이를 떨기나무 하나 아래에 던져 두었다.'),
(530, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 16, 'OT', '그녀가 가서 활 한 바탕 거리쯤 되는 곳에 마주 앉았으니 이는 그가 말하기를 “내가 아이가 죽는 것을 보지 못하리라” 하였음이라. 그녀가 맞은편에 앉아 목소리를 높여 울었더라.'),
(531, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 17, 'OT', '하나님이 그 아이의 소리를 들으셨고, 하나님의 사자가 하늘에서부터 하갈을 불러 그녀에게 이르되, 하갈아, 네게 무슨 일이 있느냐? 두려워하지 말라. 이는 하나님이 그가 거기 있는 아이의 소리를 들으셨음이라.'),
(532, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 18, 'OT', '일어나서 아이를 들어 올려 네 손으로 그를 붙잡으라, 내가 그를 큰 민족으로 만들 것임이라.'),
(533, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 19, 'OT', '하나님이 그녀의 눈을 밝히시매 그녀가 물 샘을 보았고, 가서 가죽부대에 물을 채워 그 아이에게 마시게 하였더라.'),
(534, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 20, 'OT', '하나님이 그 아이와 함께 계셨고 그가 자라며 광야에 거주하였으며 활을 쏘는 자가 되었더라.'),
(535, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 21, 'OT', '그가 바란 광야에 거주하였고, 그의 어머니가 그를 위하여 애굽 땅에서 아내를 데려왔더라.'),
(536, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 22, 'OT', '그 때에 아비멜렉과 그의 군대 장관 비골이 아브라함에게 말하여 이르되, 네가 행하는 모든 일에 하나님이 너와 함께 계시도다.'),
(537, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 23, 'OT', '그러므로 이제 너는 나와 내 아들과 내 손자에게 거짓되이 행하지 않기를 여기서 하나님을 가리켜 내게 맹세하라 내가 네게 행한 인애대로 너도 나와 네가 머문 이 땅에 행할 것이니라'),
(538, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 24, 'OT', '아브라함이 이르되, 내가 맹세하리라.'),
(539, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 25, 'OT', '아브라함이 아비멜렉을 책망하였으니 이는 아비멜렉의 종들이 그 물 우물을 빼앗았음이었더라'),
(540, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 26, 'OT', '아비멜렉이 말하되, "누가 이 일을 행하였는지 내가 알지 못하노라. 너도 내게 알리지 아니하였고, 나도 오늘 외에는 듣지 못하였노라."'),
(541, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 27, 'OT', '아브라함이 양과 소를 취하여 아비멜렉에게 주었고, 그들 둘이 언약을 세웠더라.'),
(542, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 28, 'OT', '아브라함이 그 양 떼의 암양 새끼 일곱을 따로 세웠더라'),
(543, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 29, 'OT', '아비멜렉이 아브라함에게 이르되, 네가 따로 세운 이 일곱 암양 새끼들은 무엇이냐?'),
(544, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 30, 'OT', '그가 말하기를, “네가 내 손에서 이 일곱 암양 새끼를 받으라, 그것이 내게 증거가 되게 하려 함이니, 내가 이 우물을 팠기 때문이라.”'),
(545, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 31, 'OT', '그러므로 그가 그 곳을 브엘세바라 불렀으니 이는 두 사람이 거기서 맹세하였음이라'),
(546, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 32, 'OT', '그들이 브엘세바에서 언약을 세우니라 아비멜렉과 그의 군대 장관 비골이 일어나 블레셋 족속의 땅으로 돌아갔더라'),
(547, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 33, 'OT', '아브라함이 브엘세바에 에셀나무를 심고 거기서 영원하신 하나님 여호와의 이름을 불렀더라'),
(548, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 21, 34, 'OT', '아브라함이 블레셋 족속의 땅에서 여러 날을 거주하였더라'),
(549, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 1, 'OT', '이 일들 후에 하나님이 아브라함을 시험하시고 그에게 이르시되 아브라함아 하시니 그가 이르되 내가 여기 있나이다'),
(550, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 2, 'OT', '하나님이 이르시되 네 아들, 네가 사랑하는 네 독자 이삭을 데리고 모리아 땅으로 가서 내가 네게 말할 한 산 거기서 그를 번제로 드리라'),
(551, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 3, 'OT', '아브라함이 아침에 일찍 일어나 자기 나귀에 안장을 지우고 두 청년을 데리고 자기 아들 이삭과 함께 번제에 쓸 나무를 쪼개어 일어나서 하나님이 그에게 말씀하신 곳으로 갔더라.'),
(552, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 4, 'OT', '제 삼일에 아브라함이 눈을 들어 그 곳을 멀리서 바라보았더라'),
(553, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 5, 'OT', '아브라함이 그의 종들에게 이르되, 너희는 나귀와 함께 여기 머물라, 나와 아이는 저기까지 가서 경배하고 너희에게로 돌아오리라.'),
(554, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 6, 'OT', '아브라함이 번제 나무를 취하여 그 아들 이삭에게 지우고, 자기는 손에 불과 칼을 들고, 두 사람이 함께 갔더라.'),
(555, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 7, 'OT', '이삭이 그의 아버지 아브라함에게 말하여 이르되, 내 아버지여 하니 그가 이르되, 내 아들아 내가 여기 있노라. 그가 이르되, 보소서 불과 나무는 있거니와 번제할 어린 양은 어디 있나이까?'),
(556, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 8, 'OT', '아브라함이 이르되, 내 아들아, 하나님이 자신을 위하여 번제할 어린 양을 준비하시리라 하고, 두 사람이 함께 나아가니라.'),
(557, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 9, 'OT', '그들이 하나님이 그에게 말씀하신 그 곳에 이르렀고, 아브라함이 거기서 제단을 쌓고 나무를 벌여 놓고, 그의 아들 이삭을 결박하여 제단 위 나무 위에 그를 두었더라.'),
(558, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 10, 'OT', '아브라함이 그의 손을 내밀어 그 칼을 잡아 그의 아들을 죽이려 하였더라'),
(559, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 11, 'OT', '여호와의 사자가 하늘에서부터 그를 불러 이르되 아브라함아, 아브라함아 하니 그가 이르되 내가 여기 있나이다 하니라'),
(560, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 12, 'OT', '그가 말하되, 네 손을 그 아이에게 대지 말고 그에게 아무 일도 하지 말라. 이제 내가 네가 하나님을 경외하는 줄을 알았노니, 네가 네 아들, 네 독자를 내게 아끼지 아니하였도다.'),
(561, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 13, 'OT', '아브라함이 눈을 들어 보니, 보라, 한 숫양이 뒤에 있는데 뿔이 덤불에 걸려 있었더라. 아브라함이 가서 그 숫양을 취하여 그의 아들 대신에 번제물로 드렸더라.'),
(562, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 14, 'OT', '아브라함이 그 곳의 이름을 여호와 이레라 불렀으니, 오늘까지 사람들이 이르기를 여호와의 산에서 나타나시리라 하느니라.'),
(563, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 15, 'OT', '여호와의 사자가 하늘에서부터 두 번째로 아브라함에게 부르셨다.'),
(564, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 16, 'OT', '내가 나를 가리켜 맹세하노니 여호와의 말씀이니라 네가 이 일을 행하고 네 아들 네 독자를 아끼지 아니하였으므로'),
(565, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 17, 'OT', '내가 반드시 너를 복되게 하리니, 네 씨를 하늘의 별들과 같이, 바닷가의 모래와 같이 크게 번성하게 하리라. 네 씨가 그 원수들의 성문을 차지하리라.'),
(566, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 18, 'OT', '네 씨로 말미암아 땅의 모든 민족들이 복을 받으리니, 이는 네가 내 목소리를 청종하였음이니라.'),
(567, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 19, 'OT', '아브라함이 그의 청년들에게로 돌아가니 그들이 일어나 함께 브엘세바로 갔고 아브라함이 브엘세바에 거하였더라'),
(568, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 20, 'OT', '이 일들 후에 아브라함에게 알려져 이르되, 보라 밀가가 그녀도 네 형제 나홀에게 아들들을 낳았도다.'),
(569, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 21, 'OT', '맏아들 우스와 그의 형제 부스와 아람의 아버지 그므엘을 낳았더라'),
(570, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 22, 'OT', '그리고 케셋과 하조와 필다스와 이들랍과 브두엘을'),
(571, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 23, 'OT', '브두엘은 리브가를 낳았고, 이 여덟 사람은 아브라함의 형제 나홀에게 밀가가 낳은 자들이더라.'),
(572, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 22, 24, 'OT', '그의 첩의 이름은 르우마인데, 그녀도 데바와 가함과 다하스와 마아가를 낳았더라.'),
(573, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 1, 'OT', '사라의 생애는 백 년과 이십 년과 칠 년이었으니, 이것이 사라의 생애의 햇수였더라.'),
(574, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 2, 'OT', '사라가 가나안 땅 기럇아르바 곧 헤브론에서 죽으매 아브라함이 사라를 위하여 슬퍼하며 그녀를 위하여 울려고 왔더라.'),
(575, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 3, 'OT', '아브라함이 그 죽은 자의 앞에서 일어나서 헷 족속에게 말하여 이르되'),
(576, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 4, 'OT', '나는 당신들 가운데 나그네요 거주자이니, 당신들 가운데서 내게 매장할 땅을 주어 소유를 삼게 하소서, 내가 내 죽은 자를 내 앞에서 장사하게 하소서.'),
(577, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 5, 'OT', '헷 자손들이 아브라함에게 대답하여 그에게 이르되'),
(578, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 6, 'OT', '내 주여, 우리를 들으소서 당신은 우리 중에 하나님의 방백이시니 우리 묘실 중에서 가장 좋은 것을 택하여 당신의 죽은 자를 장사하소서 우리 중에 누구든지 당신의 죽은 자를 장사하지 못하게 자기 묘실을 당신에게 금하지 아니하리이다'),
(579, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 7, 'OT', '아브라함이 일어나 그 땅의 백성 곧 헷 자손에게 몸을 굽혔더라'),
(580, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 8, 'OT', '그가 그들에게 말하여 이르되, 만일 너희 마음에 내 죽은 자를 내 앞에서 장사하는 것이 있거든 내 말을 듣고 나를 위하여 소할의 아들 에브론에게 구하라'),
(581, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 9, 'OT', '그가 그 밭 끝에 있는 막벨라 굴을 내게 주게 하되, 그가 가진 그것을, 충분한 은으로 내게 주어 당신들 가운데서 내게 매장지 소유가 되게 하기를 원하노라.'),
(582, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 10, 'OT', '에브론이 헷 족속 중에 앉아 있었더니, 헷 사람 에브론이 그 성읍의 성문에 들어온 모든 자의 귀에 아브라함에게 대답하여 이르되,'),
(583, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 11, 'OT', '아니요, 내 주여, 내 말을 들으소서. 그 밭을 내가 당신께 드리고, 그 안에 있는 굴도 내가 당신께 드리나이다. 내 백성의 아들들 앞에서 내가 그것을 당신께 드리오니, 당신의 죽은 자를 장사하소서.'),
(584, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 12, 'OT', '아브라함이 그 땅의 백성 앞에 엎드려 절하니라'),
(585, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 13, 'OT', '그가 그 땅 백성이 듣는 가운데 에브론에게 말하여 이르되, 만일 당신이 원하거든 청하건대 내 말을 들으소서. 내가 그 밭값을 당신에게 주리니 당신은 내게서 받으소서. 내가 나의 죽은 자를 거기 장사하겠나이다.'),
(586, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 14, 'OT', '에브론이 아브라함에게 대답하여 그에게 이르되'),
(587, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 15, 'OT', '내 주여, 내게 들으소서. 땅은 은 사백 세겔이니 나와 당신 사이에 그것이 무엇이겠나이까? 당신의 죽은 자를 장사하소서.'),
(588, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 16, 'OT', '아브라함이 에브론의 말을 들었고, 아브라함이 에브론에게 헷 족속의 아들들이 듣는 가운데 그가 말한 은, 곧 상인에게 통용되는 은 사백 세겔을 달아 주었더라.'),
(589, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 17, 'OT', '에브론의 밭, 곧 마므레 앞 막벨라에 있는 그 밭과 그 안에 있는 굴과 그 밭 안에 있는 모든 나무, 그 사방 경계 안에 있는 모든 것이 확정되었더라.'),
(590, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 18, 'OT', '아브라함에게 소유로, 헷 자손들의 목전에서, 그의 성문에 들어오는 모든 자들 앞에서.'),
(591, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 19, 'OT', '그 후에 아브라함이 그의 아내 사라를 가나안 땅에 있는 마므레 앞 막벨라 밭의 굴에 장사하였으니, 그것은 곧 헤브론이더라.'),
(592, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 23, 20, 'OT', '그 밭과 그 안에 있는 굴이 헷 족속에게서 아브라함의 매장지 소유로 확정되었더라.'),
(593, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 1, 'OT', '아브라함이 나이가 많아 늙었고, 여호와께서 아브라함에게 모든 것에 복을 주셨더라.'),
(594, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 2, 'OT', '아브라함이 자기 집의 늙은 종, 곧 자기의 모든 소유를 다스리는 자에게 이르되, 청하건대 네 손을 내 허벅지 아래에 두라'),
(595, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 3, 'OT', '내가 너를 하늘의 하나님, 땅의 하나님이신 여호와로 맹세하게 하리니, 너는 내가 그 가운데 거주하는 가나안 족속의 딸들 중에서 내 아들을 위하여 아내를 취하지 말지니라.'),
(596, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 4, 'OT', '너는 내 땅과 내 족속에게로 갈지니라. 그리고 내 아들 이삭을 위하여 아내를 취할지니라.'),
(597, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 5, 'OT', '종이 그에게 이르되, 혹시 그 여자가 나를 따라 이 땅으로 오기를 원하지 아니하면 내가 주인의 아들을 주인이 나온 땅으로 반드시 데리고 돌아가야 하리이까?'),
(598, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 6, 'OT', '아브라함이 그에게 이르되, 삼가 네가 내 아들을 그리로 데리고 돌아가지 말지니라'),
(599, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 7, 'OT', '하늘의 하나님 여호와께서 나를 내 아버지의 집과 내 본토에서 취하셨고, 내게 말씀하시며 내게 맹세하여 이르시기를 내가 이 땅을 네 씨에게 주리라 하셨으니, 그가 그의 사자를 네 앞에 보내리라. 네가 거기서 내 아들을 위하여 아내를 취할지니라.'),
(600, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 8, 'OT', '만일 그 여자가 너를 따라가고자 하지 아니하면, 너는 나의 이 맹세에서 면제될 것이니라. 오직 내 아들을 그리로 데리고 돌아가지 말지니라.'),
(601, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 9, 'OT', '종이 그의 손을 그의 주인 아브라함의 넓적다리 아래에 두고 그 일에 대하여 그에게 맹세하니라'),
(602, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 10, 'OT', '종이 그 주인의 약대 중에서 열 필을 취하고 떠났는데, 그의 주인의 모든 좋은 것이 그의 손에 있었더라. 그가 일어나 아람 나하라임, 곧 나홀의 성으로 갔더라.'),
(603, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 11, 'OT', '그가 약대들을 성 밖 물 우물 곁에 꿇렸으니 저녁 때, 여인들이 물을 길으러 나오는 때였더라.'),
(604, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 12, 'OT', '그가 말하되 여호와여, 내 주 아브라함의 하나님이여, 원하건대 오늘 내 앞에 좋은 만남을 주시고 내 주 아브라함에게 인애를 베푸소서.'),
(605, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 13, 'OT', '보라, 내가 물 샘 곁에 서 있나니, 성읍 사람들의 딸들이 물을 길으러 나오리라.'),
(606, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 14, 'OT', '그 일이 있게 하소서, 내가 그 소녀에게 말하기를 청하건대 네 물 항아리를 기울여 내가 마시게 하라 하리니 그가 말하기를 마시라 내가 당신의 낙타들에게도 마시게 하리라 하면, 그가 주께서 주의 종 이삭을 위하여 정하신 자라, 이로써 내가 주께서 내 주인에게 은혜를 베푸셨음을 알겠나이다.'),
(607, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 15, 'OT', '그가 말을 마치기 전에, 보라, 리브가가 나왔으니, 그녀는 아브라함의 형제 나홀의 아내 밀가의 아들 브두엘에게서 태어난 자요, 그녀의 물 항아리를 어깨에 메고 있었더라.'),
(608, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 16, 'OT', '그 소녀는 보기에 심히 아름답고 처녀라 남자가 그녀를 알지 못하였더라 그녀가 우물로 내려가서 자기 물 항아리를 채우고 올라왔더라'),
(609, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 17, 'OT', '종이 그녀에게로 달려가서 말하되 “청하건대 네 물 항아리에서 물을 조금 내게 마시게 하라”'),
(610, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 18, 'OT', '그녀가 말하되, “내 주여, 마시소서” 하고 급히 물 항아리를 손에 내려 그에게 마시게 하니라'),
(611, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 19, 'OT', '그가 마시기를 마치게 하니 그가 말하기를 “당신의 낙타들을 위하여도 내가 물을 길으리니 그들이 마시기를 마칠 때까지 하리이다” 하니라'),
(612, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 20, 'OT', '그녀가 급히 물 항아리를 구유에 쏟아 붓고 다시 길으려고 우물로 달려가서 그의 모든 낙타들을 위하여 물을 길었더라.'),
(613, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 21, 'OT', '그 사람이 그녀를 바라보며 잠잠히 여호와께서 그의 길을 형통하게 하셨는지 아닌지를 알려고 하더라.'),
(614, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 22, 'OT', '약대들이 마시기를 다하였을 때에 그 사람이 반 세겔 무게의 금 고리 하나와 그녀의 손목에 두 팔찌를 취하니 그 무게가 금 열 세겔이었더라'),
(615, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 23, 'OT', '그가 말하되 "네가 누구의 딸이냐? 청컨대 내게 말하라. 네 아버지의 집에 우리가 묵을 만한 곳이 있느냐?"'),
(616, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 24, 'OT', '그 여자가 그에게 말하되, 나는 밀가가 나홀에게 낳은 브두엘의 딸이니이다.'),
(617, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 25, 'OT', '그녀가 그에게 말하되, 우리에게 짚과 사료가 많으며, 유숙할 곳도 있나이다'),
(618, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 26, 'OT', '그 사람이 머리를 숙여 여호와께 경배하니라'),
(619, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 27, 'OT', '그가 말하되, “내 주인 아브라함의 하나님 여호와를 찬송하리로다. 그가 내 주인에게 그의 인자와 진실을 버리지 아니하셨으며, 여호와께서 나를 길에서 인도하사 내 주인의 형제들의 집에 이르게 하셨도다.”'),
(620, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 28, 'OT', '그 소녀가 달려가서 이 일들을 그 어머니의 집에 알렸더라'),
(621, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 29, 'OT', '리브가에게 오라비가 있었는데 그의 이름은 라반이었고, 라반이 그 사람에게로 밖으로, 우물로 달려갔다.'),
(622, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 30, 'OT', '그가 그 누이의 손에 있는 코걸이와 팔찌를 보고, 또 그 누이 리브가가 “그 사람이 내게 이같이 말하였다” 하는 말을 들었을 때, 그 사람에게로 나아갔더니, 보라, 그가 우물가의 낙타들 곁에 서 있었더라.'),
(623, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 31, 'OT', '그가 말하되, 여호와께 복을 받은 자여, 들어오소서. 어찌하여 밖에 서 있나이까? 내가 집을 정리하고 약대들을 위한 자리도 마련하였나이다.'),
(624, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 32, 'OT', '그 사람이 집으로 들어와서 낙타들의 짐을 풀고 낙타들에게 짚과 꼴을 주고, 자기 발과 그와 함께 한 사람들의 발을 씻을 물을 주니라.'),
(625, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 33, 'OT', '그 앞에 먹을 것이 놓였으나 그가 이르되 내가 내 말을 전하기 전에는 먹지 아니하겠나이다 하니 그가 이르되 말하라'),
(626, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 34, 'OT', '그가 말하되, 나는 아브라함의 종이니이다.'),
(627, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 35, 'OT', '여호와께서 나의 주인을 크게 복 주셨고 그가 창대하게 되었으며 그에게 양 떼와 소 떼와 은과 금과 남종들과 여종들과 낙타들과 나귀들을 주셨느니라'),
(628, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 36, 'OT', '나의 주인의 아내 사라가 그녀의 노년에 나의 주인에게 아들을 낳았고, 그가 그에게 그의 모든 소유를 주었습니다.'),
(629, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 37, 'OT', '내 주인이 나를 맹세하게 하여 이르되, 내가 그 땅에 거주하는 가나안 족속의 딸들 중에서 내 아들을 위하여 아내를 취하지 말라 하였느니라'),
(630, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 38, 'OT', '만일 네가 내 아버지의 집과 내 족속에게로 가지 아니하면, 내 아들을 위하여 아내를 취하지 아니하리라.'),
(631, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 39, 'OT', '내가 내 주인에게 말하기를, 혹시 그 여자가 나를 따라오지 아니할까 하였나이다.'),
(632, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 40, 'OT', '그가 내게 이르되, 내가 그 앞에서 걸어온 여호와께서 그의 사자를 너와 함께 보내어 네 길을 형통하게 하시리니, 너는 내 족속과 내 아버지의 집에서 내 아들을 위하여 아내를 취할지니라.'),
(633, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 41, 'OT', '그때에 네가 내 맹세에서 벗어나리니, 네가 내 친족에게 갈 때에 그들이 네게 주지 아니하면 네가 내 맹세에서 벗어나리라.'),
(634, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 42, 'OT', '내가 오늘 우물에 이르러 말하기를, 나의 주인 아브라함의 하나님 여호와여, 만일 주께서 나의 가는 길을 형통하게 하실진대'),
(635, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 43, 'OT', '보라, 내가 물 샘 곁에 서 있으리니, 처녀가 물을 길으러 나올 때에 내가 그녀에게 말하기를, 원하건대 네 물 항아리에서 물을 조금 내게 마시게 하라 하리라.'),
(636, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 44, 'OT', '그녀가 내게 말하기를 ‘너도 마시라, 내가 네 낙타들을 위해서도 길어 주리라’ 하면, 그 여자는 여호와께서 내 주인의 아들을 위하여 정하신 자니라.'),
(637, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 45, 'OT', '내가 마음속으로 말하기를 마치기 전에, 보라 리브가가 물 항아리를 어깨에 메고 나오며 우물로 내려가 길었는데, 내가 그녀에게 이르기를 청하노니 내게 마시게 하라 하였노라'),
(638, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 46, 'OT', '그녀가 급히 물 항아리를 어깨에서 내려놓으며 말하되, 마시라, 내가 당신의 낙타들에게도 마시게 하리라 하기에 내가 마셨고, 그녀가 또 낙타들에게도 마시게 하였더라.'),
(639, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 47, 'OT', '내가 그녀에게 물어 이르되, 네가 누구의 딸이냐 하였더니 그녀가 이르되, 밀가가 나홀에게 낳은 브두엘의 딸이라 하기에 내가 코고리를 그녀의 코에 두고 팔찌들을 그녀의 손에 두었노라'),
(640, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 48, 'OT', '내가 머리를 숙여 여호와께 경배하고 내 주인 아브라함의 하나님 여호와를 찬송하였나니 그가 나를 진리의 길로 인도하사 내 주인의 형제의 딸을 그 아들을 위하여 취하게 하셨음이니라'),
(641, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 49, 'OT', '이제 너희가 나의 주인에게 인자와 진실을 행하려거든 내게 말하라. 그렇지 않을지라도 내게 말하라. 그러면 내가 오른쪽이나 왼쪽으로 향하리라.'),
(642, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 50, 'OT', '라반과 브두엘이 대답하여 이르되, 이 일이 여호와께로부터 나왔으니 우리가 네게 좋다거나 나쁘다 말할 수 없노라.'),
(643, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 51, 'OT', '보라, 리브가가 네 앞에 있으니 그를 데리고 가라, 그리하여 그가 네 주인의 아들의 아내가 되게 하라, 여호와께서 말씀하신 대로.'),
(644, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 52, 'OT', '아브라함의 종이 그들의 말을 듣고 여호와께 땅에 엎드려 절하니라'),
(645, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 53, 'OT', '종이 은패물과 금패물과 의복을 꺼내어 리브가에게 주고, 그 오라비와 어미에게도 보물을 주니라'),
(646, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 54, 'OT', '그들이 먹고 마시되 그와 그와 함께 한 사람들이 유숙하고 아침에 일어나서 그가 이르되 나를 보내어 내 주인에게로 가게 하소서'),
(647, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 55, 'OT', '그녀의 오라비와 그 어미가 말하되, 소녀가 우리와 함께 며칠을, 혹은 열흘을 머물게 하라, 그 후에 그녀가 가리라.'),
(648, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 56, 'OT', '그가 그들에게 이르되, “나를 지체시키지 마소서. 여호와께서 내 길을 형통하게 하셨으니, 나를 보내어 내 주인에게로 가게 하소서.”'),
(649, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 57, 'OT', '그들이 말하기를 “우리가 그 소녀를 부르고 그 입에서 물어보자” 하니라'),
(650, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 58, 'OT', '그들이 리브가를 불러 그에게 말하되, “네가 이 사람과 함께 가겠느냐?” 하니 그가 말하되, “가겠나이다.”'),
(651, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 59, 'OT', '그들이 그들의 누이 리브가와 그녀의 유모와 아브라함의 종과 그의 사람들을 보내니라'),
(652, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 60, 'OT', '그들이 리브가를 축복하며 그녀에게 말하되, “우리 누이여, 너는 천만의 어미가 되라. 네 자손이 그를 미워하는 자들의 성문을 차지하리라.”'),
(653, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 61, 'OT', '리브가가 일어나 그녀의 여종들과 함께 약대를 타고 그 사람을 따라갔으며, 그 종이 리브가를 데리고 갔더라.'),
(654, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 62, 'OT', '이삭이 브엘 라해로이에서 오는 길에서 왔는데, 그가 네겝 땅에 거주하고 있었더라.'),
(655, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 63, 'OT', '이삭이 저녁 때에 들에 나가 묵상하려 하다가 눈을 들어 보니, 보라, 약대들이 오고 있었다.'),
(656, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 64, 'OT', '리브가가 눈을 들어 이삭을 보고 약대에서 내리니라'),
(657, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 65, 'OT', '그녀가 종에게 말하되, “우리를 만나러 들에서 걸어오는 이 사람이 누구입니까?” 하니 종이 말하되, “그는 내 주인입니다.” 하매 그녀가 너울을 가져다가 스스로 가리웠더라.'),
(658, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 66, 'OT', '종이 이삭에게 자기가 행한 모든 일을 다 말하니라.'),
(659, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 24, 67, 'OT', '이삭이 그를 그의 어머니 사라의 장막으로 데리고 들어가서 리브가를 취하여 그가 그의 아내가 되게 하였고 그를 사랑하였으며 이삭이 그의 어머니 후에 위로를 얻었더라'),
(660, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 1, 'OT', '아브라함이 다시 아내를 취하였는데 그 이름은 그두라였더라'),
(661, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 2, 'OT', '그가 그에게 시므란과 욕산과 므단과 미디안과 이스박과 수아를 낳았더라'),
(662, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 3, 'OT', '욕산이 스바와 드단을 낳았고, 드단의 아들들은 앗수림과 르두심과 르움밈이었더라.'),
(663, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 4, 'OT', '미디안의 아들들은 에바와 에벨과 하녹과 아비다와 엘다아요, 이 모든 자들은 그두라의 자손이었더라.'),
(664, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 5, 'OT', '아브라함이 이삭에게 자기의 모든 소유를 주었더라'),
(665, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 6, 'OT', '아브라함이 첩들의 아들들에게도 선물을 주고, 자기 아들 이삭을 떠나 그가 아직 살아 있는 동안에 동방, 곧 동쪽 땅으로 보냈더라.'),
(666, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 7, 'OT', '아브라함이 산 생애의 연수는 백칠십오 년이었더라.'),
(667, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 8, 'OT', '아브라함이 숨을 거두며 죽었으니 좋은 늙은 나이에, 늙고 만족하여 죽었으며 그의 백성에게로 돌아갔더라.'),
(668, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 9, 'OT', '그의 아들 이삭과 이스마엘이 그를 막벨라 굴에 장사하였으니, 이는 마므레 앞에 있는 헷 족속 소할의 아들 에브론의 밭에 있던 곳이라.'),
(669, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 10, 'OT', '아브라함이 헷 족속의 아들들에게서 산 밭, 거기에 아브라함과 그의 아내 사라가 장사되었더라.'),
(670, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 11, 'OT', '아브라함이 죽은 후에 하나님이 그의 아들 이삭에게 복을 주셨고, 이삭은 브엘 라해로이 곁에 거하였더라.'),
(671, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 12, 'OT', '이스마엘의 족보는 이러하니라. 아브라함의 아들이며, 사라의 여종 애굽인 하갈이 아브라함에게 낳은 자니라.'),
(672, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 13, 'OT', '이스마엘의 아들들의 이름은 그들의 이름대로 그들의 세대에 따라 이러하니, 이스마엘의 장자는 느바욧이요, 게달과 앗브엘과 밉삼이요,'),
(673, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 14, 'OT', '미스마와 두마와 맛사와'),
(674, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 15, 'OT', '하닷과 데마와 여둘과 나비스와 게드마'),
(675, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 16, 'OT', '이들은 이스마엘의 아들들이며, 이들은 그들의 이름들이니, 그들의 마을들과 그들의 성들에 따라, 그들의 민족들에 따른 열두 지도자들이라.'),
(676, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 17, 'OT', '이스마엘의 생애의 햇수는 백삼십칠 년이었으며, 그가 숨을 거두어 죽어 자기 백성에게로 돌아갔더라.'),
(677, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 18, 'OT', '그들이 하윌라에서부터 앗수르로 가는 길에 있는 애굽 앞 술까지 거주하였으며, 그의 모든 형제들 앞에서 죽었더라.'),
(678, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 19, 'OT', '이삭의 족보는 이러하니라 아브라함의 아들 이삭이라 아브라함이 이삭을 낳았더라'),
(679, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 20, 'OT', '이삭이 사십 세에 리브가를 아내로 취하였으니, 그녀는 밧단 아람의 아람 사람 브두엘의 딸이요, 아람 사람 라반의 누이였더라.'),
(680, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 21, 'OT', '이삭이 그의 아내를 위하여 여호와께 간구하였으니 이는 그가 잉태하지 못함이었더라. 여호와께서 그에게 응답하셨고 그의 아내 리브가가 잉태하였더라.'),
(681, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 22, 'OT', '아이들이 그의 태 속에서 서로 부딪치더라. 그가 이르되, 만일 그렇다면 어찌하여 내가 이러하리요 하고, 여호와께 묻으러 갔더라.'),
(682, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 23, 'OT', '여호와께서 그녀에게 이르시되 두 민족이 네 태 중에 있구나 두 백성이 네 복 중에서 갈라지리라 한 백성이 다른 백성보다 강하겠고 큰 자가 어린 자를 섬기리라'),
(683, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 24, 'OT', '그녀가 해산할 날이 차매, 보라 그 태에 쌍둥이가 있었더라.'),
(684, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 25, 'OT', '먼저 나온 자는 붉고 온몸이 털옷 같았으며, 그들이 그의 이름을 에서라 불렀더라.'),
(685, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 26, 'OT', '그 후에 그의 아우가 나오는데 그의 손이 에서의 발꿈치를 잡았으므로 그 이름을 야곱이라 불렀고, 이삭이 그들을 낳을 때에 육십 세였더라.'),
(686, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 27, 'OT', '그 아이들이 자라매 에서는 사냥을 잘 아는 사람, 곧 들의 사람이 되었고, 야곱은 온전한 사람으로 장막에 거하니라.'),
(687, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 28, 'OT', '이삭은 에서를 사랑하였으니 이는 그 입에 사냥한 것이 있었기 때문이며, 리브가는 야곱을 사랑하였더라.'),
(688, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 29, 'OT', '야곱이 죽을 쑤었더니 에서가 들에서부터 왔는데 그가 피곤하였더라'),
(689, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 30, 'OT', '에서가 야곱에게 이르되, 청하노니 그 붉은 것, 그 붉은 것을 내게 먹게 하라, 내가 피곤함이니라. 그러므로 그의 이름을 에돔이라 불렀더라.'),
(690, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 31, 'OT', '야곱이 이르되, 오늘 네 장자권을 내게 팔라.'),
(691, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 32, 'OT', '에서가 말하되, 보라 내가 죽게 되었으니 이 장자의 명분이 내게 무엇이 유익하리요'),
(692, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 33, 'OT', '야곱이 이르되, 오늘 내게 맹세하라 하매 그가 그에게 맹세하고, 그가 그의 장자권을 야곱에게 팔았더라.'),
(693, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 25, 34, 'OT', '야곱이 에서에게 빵과 팥죽을 주었고, 그가 먹고 마시고 일어나서 갔으며, 에서가 장자의 명분을 멸시하였더라.'),
(694, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 1, 'OT', '그 땅에 흉년이 들었는데, 아브라함 때에 있었던 첫 흉년 외에 또 흉년이 들었더라. 이삭이 블레셋 왕 아비멜렉에게로 그랄에 갔더라.'),
(695, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 2, 'OT', '여호와께서 그에게 나타나 이르시되 애굽으로 내려가지 말고 내가 네게 말하는 땅에 거하라'),
(696, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 3, 'OT', '이 땅에 거하라, 내가 너와 함께 있어 너를 축복하리니, 이는 내가 이 모든 땅을 너와 네 자손에게 주고, 네 아버지 아브라함에게 맹세한 그 맹세를 내가 이루리라.'),
(697, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 4, 'OT', '내가 네 자손을 하늘의 별들처럼 많게 하겠고, 네 자손에게 이 모든 땅들을 주겠다. 네 자손으로 말미암아 땅의 모든 민족들이 복을 받을 것이다.'),
(698, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 5, 'OT', '이는 아브라함이 내 음성을 순종하고 내 직분과 내 계명과 내 율례와 내 법도를 지켰음이라.'),
(699, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 6, 'OT', '이삭이 그랄에 거하였더라.'),
(700, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 7, 'OT', '그 곳 사람들이 그의 아내에 대해 물으매 그가 말하기를 그녀는 나의 누이라 하였으니, 이는 그가 리브가로 인하여 그 곳 사람들이 자기를 죽일까 두려워하여 그녀가 나의 아내라 말하기를 무서워함이었더라, 그녀가 보기에 아름다웠음이라.'),
(701, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 8, 'OT', '그가 거기서 오래 머물렀더니 블레셋 왕 아비멜렉이 창으로 내다보며 보니, 보라, 이삭이 그의 아내 리브가를 희롱하고 있었더라.'),
(702, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 9, 'OT', '아비멜렉이 이삭을 불러 이르되, “참으로 그녀는 네 아내인데, 어찌하여 네가 ‘그녀는 내 누이’라고 말하였느냐?” 하니, 이삭이 그에게 이르되, “내가 말하기를, ‘그녀로 인하여 내가 죽을까 두려워하였다’ 하였음이니라.”'),
(703, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 10, 'OT', '아비멜렉이 이르되, 네가 우리에게 행한 이 일이 무엇이냐? 백성 중 하나가 네 아내와 동침할 뻔하였으니, 네가 우리에게 죄를 입혔도다.'),
(704, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 11, 'OT', '아비멜렉이 모든 백성에게 명령하여 이르되, 이 사람이나 그의 아내를 만지는 자는 반드시 죽임을 당하리라 하였더라.'),
(705, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 12, 'OT', '이삭이 그 땅에서 씨를 뿌렸더니 그 해에 백 배를 얻었고 여호와께서 그에게 복을 주셨더라.'),
(706, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 13, 'OT', '그 사람이 창대해지고, 점점 더 커져 마침내 심히 창대하게 되었더라.'),
(707, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 14, 'OT', '그에게 양 떼와 소 떼가 생기고 종들이 심히 많았더라. 블레셋 사람들이 그를 시기하였더라.'),
(708, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 15, 'OT', '그의 아버지 아브라함 때에 그의 아버지의 종들이 판 모든 우물들을 블레셋 사람들이 막고 흙으로 채웠더라.'),
(709, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 16, 'OT', '아비멜렉이 이삭에게 말하였다. “우리를 떠나가라. 네가 우리보다 매우 강성해졌기 때문이다.”'),
(710, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 17, 'OT', '이삭이 그곳을 떠나 그랄 골짜기에 진을 치고 거기 거주하였더라'),
(711, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 18, 'OT', '이삭이 돌아와서 그 아비 아브라함 때에 팠던 우물들을 다시 팠으니 이는 아브라함이 죽은 후에 블레셋 사람들이 그것들을 메웠음이라 그가 그 우물들의 이름을 그 아비가 부르던 이름으로 불렀더라'),
(712, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 19, 'OT', '이삭의 종들이 골짜기에서 팠더니 거기서 생수가 솟는 우물을 찾았더라'),
(713, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 20, 'OT', '그랄의 목자들이 이삭의 목자들과 다투며 말하기를 “그 물은 우리의 것이라” 하였고, 그가 그 우물의 이름을 에섹이라 불렀으니 이는 그들이 그와 다투었기 때문이었더라.'),
(714, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 21, 'OT', '그들이 또 다른 우물을 팠더니 그들이 그것에 대해서도 다투었고, 그가 그 이름을 싯나라 하였더라.'),
(715, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 22, 'OT', '그가 거기서 옮겨 다른 우물을 팠는데 그들이 그것에 대하여 다투지 아니하였으므로 그가 그 이름을 르호봇이라 불렀고, 말하기를 “이제 여호와께서 우리를 위하여 넓히셨으니 우리가 이 땅에서 번성하리라” 하였더라.'),
(716, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 23, 'OT', '그가 거기서부터 브엘세바로 올라갔더라'),
(717, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 24, 'OT', '그 밤에 여호와께서 그에게 나타나 이르시되 나는 네 아버지 아브라함의 하나님이니 두려워하지 말라 내가 너와 함께 있어 네게 복을 주고 내 종 아브라함을 위하여 네 자손을 번성하게 하리라 하셨더라'),
(718, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 25, 'OT', '그가 거기서 제단을 쌓고 여호와의 이름을 불렀으며 거기서 자기 장막을 쳤고 이삭의 종들이 거기서 우물을 팠더라.'),
(719, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 26, 'OT', '아비멜렉이 그랄에서부터 그에게로 갔고, 그의 친구 아훗삿과 그의 군대 장관 비골도 함께 갔더라.'),
(720, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 27, 'OT', '이삭이 그들에게 이르되, 너희가 나를 미워하여 나를 너희에게서 쫓아보냈거늘 어찌하여 내게 왔느냐?'),
(721, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 28, 'OT', '그들이 말하되, “여호와께서 당신과 함께 계심을 우리가 분명히 보았나이다. 그러므로 우리가 말하기를, 이제 우리 사이 곧 우리와 당신 사이에 맹세를 두고 당신과 언약을 맺자 하였나이다.”'),
(722, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 29, 'OT', '네가 우리에게 해를 끼치지 않기를 원하노니, 이는 우리가 너를 건드리지 아니하였고, 오직 선한 일만 네게 행하며 너를 평안히 보내었음이라. 이제 너는 여호와께 복을 받은 자니라.'),
(723, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 30, 'OT', '그가 그들을 위하여 잔치를 베풀었더니 그들이 먹고 마셨더라'),
(724, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 31, 'OT', '그들이 아침에 일찍 일어나 서로 맹세하였고, 이삭이 그들을 보내매 그들이 평안히 그에게서 떠나갔더라.'),
(725, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 32, 'OT', '그 날에 이삭의 종들이 와서 그들이 판 우물에 대하여 그에게 알리며 그에게 이르되 우리가 물을 얻었나이다 하였더라'),
(726, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 33, 'OT', '그가 그것을 세바라 불렀으므로 그 성읍의 이름이 오늘까지 브엘세바이니라'),
(727, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 34, 'OT', '에서가 사십 세에 헷 사람 브에리의 딸 유딧과 헷 사람 엘론의 딸 바스맛을 아내로 취하였더라'),
(728, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 26, 35, 'OT', '그들이 이삭과 리브가에게 마음의 근심이 되었더라'),
(729, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 1, 'OT', '이삭이 늙어 그의 눈이 흐려져 보지 못하게 되었을 때, 그가 그의 큰 아들 에서를 불러 그에게 이르되, 내 아들아, 하니 그가 그에게 이르되, 내가 여기 있나이다, 하였더라.'),
(730, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 2, 'OT', '그가 이르되, 보라, 이제 내가 늙었으니 내가 죽을 날을 알지 못하노라.'),
(731, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 3, 'OT', '이제 네 기구, 곧 네 전통과 네 활을 가지고 들로 나가서 나를 위하여 사냥감을 잡으라.'),
(732, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 4, 'OT', '네가 내가 사랑한 별미를 만들어 내게로 가져오라, 내가 먹고, 내가 죽기 전에 내 마음이 너를 축복하게 하려 함이라.'),
(733, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 5, 'OT', '리브가가 이삭이 그의 아들 에서에게 말하는 것을 들었더라. 에서가 사냥감을 잡아 가져오려고 들로 나가니라.'),
(734, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 6, 'OT', '리브가가 그 아들 야곱에게 말하여 이르되, 보라, 내가 네 아버지가 네 형 에서에게 말씀하시는 것을 들었노라, 이르시기를'),
(735, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 7, 'OT', '나를 위하여 사냥한 것을 가져다가 별미를 만들어 내가 먹게 하여, 내가 죽기 전에 여호와 앞에서 너를 축복하게 하라.'),
(736, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 8, 'OT', '그러므로 내 아들아, 내가 네게 명하는 대로 내 목소리를 들으라.'),
(737, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 9, 'OT', '이제 양 떼에게로 가서 거기서 내게 염소 새끼 두 마리, 좋은 것을 가져오라. 내가 그것으로 네 아버지를 위하여 그가 사랑하시는 별미를 만들리라.'),
(738, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 10, 'OT', '네가 그것을 네 아버지에게 가져가면 그가 먹을 것이요, 그가 죽기 전에 네게 축복하게 하려 함이니라.'),
(739, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 11, 'OT', '야곱이 그의 어머니 리브가에게 이르되, 보라, 내 형 에서는 털이 많은 사람이요, 나는 매끈한 사람이라.'),
(740, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 12, 'OT', '혹시 아버지께서 나를 만지실지라, 내가 그의 눈에 속이는 자가 되어, 내게 저주를 가져오게 되고 복을 받지 못할까 두렵나이다.'),
(741, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 13, 'OT', '그의 어머니가 그에게 이르되, 내 아들아, 네 저주는 내게로 돌리라. 오직 내 목소리를 듣고 가서 내게 가져오라.'),
(742, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 14, 'OT', '그가 가서 취하여 그의 어머니에게로 가져왔더니 그의 어머니가 그의 아버지가 사랑하는 별미를 만들었더라'),
(743, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 15, 'OT', '리브가가 집에 있는 그녀의 맏아들 에서의 아름다운 옷들을 가져다가 그녀의 작은 아들 야곱에게 입혔더라.'),
(744, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 16, 'OT', '그리고 그가 염소 새끼들의 가죽을 그의 손들과 그의 목의 매끈한 부분에 입혔더라.'),
(745, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 17, 'OT', '그녀가 만든 별미와 빵을 자기 아들 야곱의 손에 주었더라.'),
(746, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 18, 'OT', '그가 아버지에게 나아가서 이르되 아버지여 하니 그가 이르되 내가 여기 있노라 내 아들아 네가 누구냐'),
(747, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 19, 'OT', '야곱이 그의 아버지에게 말하되, 나는 아버지의 맏아들 에서니이다. 아버지께서 내게 말씀하신 대로 내가 행하였사오니, 청하건대 일어나 앉아서 내 사냥한 것을 잡수시고, 아버지의 영혼이 내게 축복하시기를 원하나이다.'),
(748, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 20, 'OT', '이삭이 그의 아들에게 이르되, 내 아들아, 네가 어찌 이같이 속히 찾았느냐? 그가 이르되, 아버지의 하나님 여호와께서 그것을 내 앞에 이르게 하셨나이다.'),
(749, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 21, 'OT', '이삭이 야곱에게 이르되, 내 아들아, 가까이 오라, 내가 너를 만져 보리라, 네가 과연 내 아들 에서인지 아닌지.'),
(750, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 22, 'OT', '야곱이 그의 아버지 이삭에게 가까이 나아가니 그가 그를 만지며 이르되, 음성은 야곱의 음성이나 손은 에서의 손이로다.'),
(751, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 23, 'OT', '그가 그를 알아보지 못하였으니 이는 그의 손이 그의 형 에서의 손과 같이 털이 있었음이라 그가 그를 축복하였더라'),
(752, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 24, 'OT', '그가 말하되, 네가 참으로 내 아들 에서냐? 그가 말하되, 나니라.'),
(753, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 25, 'OT', '그가 말하기를 “내게 가까이 가져오라. 내가 내 아들의 사냥한 고기를 먹고, 내 영혼이 너를 축복하게 하라.” 하니, 그가 그에게 가져가매 그가 먹고, 그가 그에게 포도주를 가져오매 그가 마셨다.'),
(754, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 26, 'OT', '그의 아버지 이삭이 그에게 말하되, 내 아들아, 가까이 와서 내게 입맞추라.'),
(755, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 27, 'OT', '그가 가까이 가서 그에게 입을 맞추고 그의 옷의 향기를 맡으며 그를 축복하고 말하였다. "보라, 내 아들의 향기는 여호와께서 복 주신 밭의 향기로다."'),
(756, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 28, 'OT', '하나님이 하늘의 이슬과 땅의 기름진 것으로 네게 주시고 곡식과 포도주의 풍성함을 주시기를 원하노라'),
(757, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 29, 'OT', '만민이 너를 섬기고 열국이 네게 경배하리니 네가 형제들의 주가 되고 네 어미의 아들들이 네게 경배하리라 너를 저주하는 자는 저주를 받고 너를 축복하는 자는 복을 받으리라'),
(758, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 30, 'OT', '이삭이 야곱에게 축복하기를 마치매 야곱이 그의 아버지 이삭의 앞에서 거의 나갔을 때에, 그의 형 에서가 사냥에서 돌아왔더라.'),
(759, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 31, 'OT', '그도 별미를 만들어 아버지에게 가져왔고 아버지에게 말하되 아버지여 일어나서 아들의 사냥한 것을 잡수소서 아버지의 영혼이 나를 축복하시도록 하였더라.'),
(760, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 32, 'OT', '그의 아버지 이삭이 그에게 말하되, “너는 누구냐?” 그가 말하되, “나는 아버지의 아들, 아버지의 맏아들 에서입니다.”'),
(761, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 33, 'OT', '이삭이 심히 크게 떨며 이르되 누구냐, 그런즉 사냥한 고기를 내게 가져온 자가 누구냐, 네가 오기 전에 내가 그 모든 것을 먹고 그를 축복하였으니 그가 또한 복을 받을 것이라.'),
(762, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 34, 'OT', '에서가 그의 아버지의 말을 듣고 심히 크고 쓰라린 부르짖음으로 부르짖으며 그의 아버지에게 이르되, 내 아버지여, 나도 또한 축복하소서.'),
(763, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 35, 'OT', '그가 말하기를, “네 형이 간교함으로 와서 네 복을 빼앗았느니라.”'),
(764, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 36, 'OT', '에서가 이르되, 그가 야곱이라 불림이 합당하지 아니하니이까? 그가 나를 두 번 속였나이다. 그가 나의 장자권을 빼앗았고, 보소서, 이제는 나의 복을 빼앗았나이다. 또 이르되, 아버지께서 나를 위하여 복을 남기지 아니하셨나이까?'),
(765, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 37, 'OT', '이삭이 에서에게 대답하여 이르되, 보라, 내가 그를 너의 주인으로 삼았고 그의 모든 형제를 내가 그에게 종으로 주었으며 곡식과 포도주로 그를 붙들었노라. 그런즉 내 아들아, 내가 이제 네게 무엇을 할 수 있으랴?'),
(766, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 38, 'OT', '에서가 그의 아버지에게 말하되, “내 아버지여, 아버지에게 축복이 오직 하나뿐이니이까? 내 아버지여, 나도 축복하소서, 나도 그리 하소서.” 하고 에서가 소리를 높여 울었더라.'),
(767, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 39, 'OT', '그의 아버지 이삭이 그에게 대답하여 이르되, 보라, 네 거처는 땅의 기름진 곳에서 되고 위로부터 하늘의 이슬에서 되리라.'),
(768, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 40, 'OT', '네가 칼을 믿고 살겠고 네 형제를 섬길 것이며, 네가 자유로울 때에 그의 멍에를 네 목에서 꺾어 벗을 것이라.'),
(769, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 41, 'OT', '에서가 야곱을 미워하니 이는 그의 아버지가 그에게 축복한 그 축복 때문이었더라. 에서가 마음속으로 이르되, 아버지를 위한 애곡의 날들이 가까웠으니 내가 내 형제 야곱을 죽이리라 하였더라.'),
(770, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 42, 'OT', '리브가에게 그녀의 큰 아들 에서의 말들이 전해지매, 그녀가 보내어 그녀의 작은 아들 야곱을 불러 그에게 이르되, 보라, 네 형 에서가 너를 죽이려고 스스로 위로하고 있느니라.'),
(771, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 43, 'OT', '그러므로 내 아들아, 내 목소리를 들으라. 일어나 하란에 있는 내 형제 라반에게로 도피하라.'),
(772, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 44, 'OT', '네 형의 진노가 풀릴 때까지 그와 함께 며칠 동안 머물라'),
(773, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 45, 'OT', '네 형의 진노가 네게서 풀리고 그가 네가 그에게 행한 것을 잊을 때까지 기다리라. 그리하면 내가 보내어 너를 거기서 데려오리라. 어찌 하루에 너희 둘을 잃으리요?'),
(774, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 27, 46, 'OT', '리브가가 이삭에게 말하되, 내가 헷 사람의 딸들 때문에 내 생명을 싫어하나니, 만일 야곱이 이 땅의 딸들 중에서 이와 같은 헷 사람의 딸들로 아내를 취하면, 내게 생명이 무엇이 있겠느냐'),
(775, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 1, 'OT', '이삭이 야곱을 불러 그를 축복하고 그에게 명령하여 그에게 이르되, 너는 가나안의 딸들 중에서 아내를 취하지 말지니라.'),
(776, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 2, 'OT', '일어나 밧단아람으로 가서 네 어머니의 아버지 브두엘의 집에 이르러, 거기서 네 어머니의 형제 라반의 딸들 중에서 아내를 취하라.'),
(777, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 3, 'OT', '전능하신 하나님이 너를 축복하시고 너를 생육하게 하시며 번성하게 하시리니 네가 민족들의 무리가 되리라'),
(778, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 4, 'OT', '네게 아브라함의 복을 주시고, 너와 함께 있는 네 자손에게 주사, 네가 나그네 된 땅, 곧 하나님이 아브라함에게 주신 땅을 네가 차지하게 하시기를 원하노라.'),
(779, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 5, 'OT', '이에 이삭이 야곱을 보내니 그가 밧단아람으로 가서 아람 사람 브두엘의 아들이요 야곱과 에서의 어미 리브가의 오라비인 라반에게 이르렀더라'),
(780, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 6, 'OT', '에서가 보니 이삭이 야곱을 축복하고 그를 밧단아람으로 보내어 거기서 그를 위하여 아내를 취하게 하였으며, 그를 축복할 때에 그에게 명령하여 이르기를, 너는 가나안의 딸들 중에서 아내를 취하지 말라 하였고'),
(781, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 7, 'OT', '야곱이 그의 아버지와 그의 어머니의 말을 들었고, 밧단아람으로 갔더라.'),
(782, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 8, 'OT', '에서가 보니 가나안 사람의 딸들이 그의 아버지 이삭의 눈에 좋지 않음을 알았더라'),
(783, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 9, 'OT', '에서가 이스마엘에게로 가서, 아브라함의 아들 이스마엘의 딸이요 느바욧의 누이인 마할랏을 그의 아내로, 그의 아내들 위에 더하여 취하였더라.'),
(784, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 10, 'OT', '야곱이 브엘세바에서 나와 하란으로 갔더라'),
(785, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 11, 'OT', '그가 그 곳에 이르러 거기서 유숙하였으니 이는 해가 졌음이라 그가 그 곳의 돌들을 취하여 자기 머리 베개로 삼고 그 곳에 누웠더라'),
(786, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 12, 'OT', '그가 꿈을 꾸었는데, 보라, 사닥다리가 땅 위에 세워져 있고 그 꼭대기가 하늘에 닿았으며, 보라, 하나님의 천사들이 그 위에서 오르락내리락하고 있었다.'),
(787, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 13, 'OT', '보라 여호와께서 그 위에 서서 말씀하시되 나는 여호와니 네 아버지 아브라함의 하나님이요 이삭의 하나님이라 네가 누운 땅을 내가 너와 네 자손에게 주리라'),
(788, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 14, 'OT', '네 자손이 땅의 티끌 같이 되고 네가 서쪽과 동쪽과 북쪽과 남쪽으로 퍼지리라 땅의 모든 족속이 너와 네 자손으로 말미암아 복을 받으리라'),
(789, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 15, 'OT', '보라 내가 너와 함께 있어 네가 어디로 가든지 너를 지키고 너를 이 땅으로 돌아오게 하리니 내가 네게 말한 것을 이루기까지는 너를 떠나지 아니하리라'),
(790, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 16, 'OT', '야곱이 그의 잠에서 깨어 이르되, 진실로 여호와께서 이 곳에 계시거늘 내가 알지 못하였도다.'),
(791, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 17, 'OT', '그가 두려워하여 이르되, 이 곳이 어찌 그리 두려운가! 이는 다른 것이 아니라 하나님의 집이요, 이는 하늘의 문이로다 하니라'),
(792, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 18, 'OT', '야곱이 아침에 일찍 일어나 자기 머리 밑에 두었던 돌을 가져다가 기둥으로 세우고 그 꼭대기에 기름을 부으니라'),
(793, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 19, 'OT', '그가 그 곳의 이름을 벧엘이라 불렀더라 그러나 그 성의 처음 이름은 루스였더라'),
(794, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 20, 'OT', '야곱이 서원하여 말하되, 하나님이 나와 함께 계시고 내가 가는 이 길에서 나를 지키시며 내게 먹을 빵과 입을 옷을 주시면'),
(795, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 21, 'OT', '내가 평안히 아버지의 집으로 돌아가게 하시면 여호와께서 나의 하나님이 되실 것이요'),
(796, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 28, 22, 'OT', '내가 기둥으로 세운 이 돌은 하나님의 집이 될 것이요, 내게 주신 모든 것에서 내가 반드시 십일조를 드리겠나이다.'),
(797, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 1, 'OT', '야곱이 그의 발을 들고 동방 사람들의 땅으로 갔더라.'),
(798, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 2, 'OT', '그가 보니 들에 우물이 있는데, 보라 그 곁에 양 떼 세 무리가 누워 있으니, 이는 그 우물에서 양 떼에게 물을 먹였기 때문이라. 그 우물 아구에는 큰 돌이 덮여 있더라.'),
(799, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 3, 'OT', '모든 떼가 그리로 모이면 그들이 우물 아구에서 돌을 굴려 내고 양에게 물을 먹인 후에 그 돌을 도로 우물 아구 그 자리에 놓더라'),
(800, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 4, 'OT', '야곱이 그들에게 이르되, "내 형제들아, 너희는 어디서 왔느냐?" 그들이 이르되, "우리는 하란에서 왔노라."'),
(801, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 5, 'OT', '그가 그들에게 이르되, 너희가 나홀의 아들 라반을 아느냐? 그들이 이르되, 우리가 아노라.'),
(802, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 6, 'OT', '그가 그들에게 이르되 그에게 평안이 있느냐? 그들이 이르되 평안하니라, 보라 그의 딸 라헬이 양들과 함께 오고 있느니라.'),
(803, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 7, 'OT', '그가 이르되, 보라 아직 해가 높으니 가축을 모을 때가 아니니라. 양에게 물을 먹이고 가서 뜯기라.'),
(804, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 8, 'OT', '그들이 말하되 우리가 할 수 없나니 모든 떼가 모이고 그들이 우물 아구에서 돌을 옮긴 후에야 우리가 양에게 물을 먹이리라 하니라'),
(805, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 9, 'OT', '그가 아직 그들과 말하는 중에 라헬이 그 아비의 양과 함께 왔으니 그가 양을 치는 자였음이라'),
(806, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 10, 'OT', '야곱이 그의 어머니의 형제 라반의 딸 라헬과 그의 어머니의 형제 라반의 양들을 볼 때에, 야곱이 가까이 나아가서 우물 입구에서 돌을 굴려 내고 그의 어머니의 형제 라반의 양떼에게 물을 먹였더라.'),
(807, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 11, 'OT', '야곱이 라헬에게 입맞추고 소리를 높여 울었더라'),
(808, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 12, 'OT', '야곱이 라헬에게 말하기를 그가 그의 아버지의 형제요 리브가의 아들이라고 하였더니, 그녀가 달려가서 그녀의 아버지에게 말하니라.'),
(809, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 13, 'OT', '라반이 그의 누이의 아들 야곱의 소식을 듣고 그를 맞으러 달려가서 그를 안고 입맞추며 그를 자기 집으로 데려왔고, 야곱이 이 모든 일을 라반에게 이야기하니라.'),
(810, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 14, 'OT', '라반이 그에게 말하되 “너는 참으로 내 뼈요 내 살이로다” 하였고, 그가 그와 함께 한 달을 거하니라.'),
(811, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 15, 'OT', '라반이 야곱에게 이르되 네가 비록 내 형제라도 어찌 공으로 나를 섬기겠느냐? 내게 고하라 네 품삯이 무엇이냐?'),
(812, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 16, 'OT', '라반에게 두 딸이 있었는데, 큰 딸의 이름은 레아요 작은 딸의 이름은 라헬이었더라.'),
(813, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 17, 'OT', '레아의 눈은 약하고 라헬은 아름다운 용모와 아리따운 모습이었더라'),
(814, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 18, 'OT', '야곱이 라헬을 사랑하였더라. 그가 말하되, “내가 당신의 작은 딸 라헬을 위하여 당신에게 칠 년을 섬기리이다.”'),
(815, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 19, 'OT', '라반이 이르되, 그를 네게 주는 것이 다른 사람에게 주는 것보다 나으니, 나와 함께 있으라.'),
(816, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 20, 'OT', '야곱이 라헬을 위하여 칠 년을 섬겼더니 그를 사랑하는 까닭에 그 눈에는 며칠 같이 보였더라'),
(817, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 21, 'OT', '야곱이 라반에게 이르되, 내 아내를 내게 주소서, 내 날들이 찼으니 내가 그에게 들어가리이다.'),
(818, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 22, 'OT', '라반이 그 곳의 모든 사람들을 모아 잔치를 베풀었더라.'),
(819, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 23, 'OT', '저녁에 그가 그의 딸 레아를 데려다가 그에게로 이끌었고, 그가 그녀에게로 들어갔더라.'),
(820, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 24, 'OT', '라반이 그의 여종 실바를 그의 딸 레아에게 시녀로 주었더라'),
(821, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 25, 'OT', '아침에 보니, 보라, 그녀는 레아였다. 그가 라반에게 말하되, “네가 내게 행한 이 일이 무엇이냐? 내가 라헬을 위하여 너와 함께 섬기지 아니하였느냐? 그런데 어찌하여 네가 나를 속였느냐?”'),
(822, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 26, 'OT', '라반이 말하되, 우리 지방에서는 이같이 하지 아니하나니, 첫째를 앞서서 어린 이를 주는 일은 하지 아니하느니라.'),
(823, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 27, 'OT', '이를 위하여 칠 일을 채우라 우리가 그도 네게 주리니 네가 또 다른 칠 년을 나와 함께 봉사할지니라'),
(824, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 28, 'OT', '야곱이 그대로 행하여 그 칠 일을 채우니, 그가 그에게 그의 딸 라헬을 아내로 주었더라.'),
(825, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 29, 'OT', '라반이 그의 딸 라헬에게 그의 여종 빌하를 주어 그녀의 시녀가 되게 하였더라.'),
(826, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 30, 'OT', '그가 또한 라헬에게로 들어갔고, 그가 레아보다 라헬을 더 사랑하였으며, 그와 함께 다시 칠 년을 더 섬겼더라.'),
(827, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 31, 'OT', '여호와께서 레아가 미움을 받는 것을 보시고 그녀의 태를 여셨으나 라헬은 임신하지 못하는 자였더라'),
(828, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 32, 'OT', '레아가 잉태하여 아들을 낳고 그의 이름을 르우벤이라 불렀으니 이는 그가 말하기를 여호와께서 나의 괴로움을 보셨으니 이제는 내 남편이 나를 사랑하리라 하였음이더라'),
(829, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 33, 'OT', '그녀가 다시 잉태하여 아들을 낳고 말하기를 “여호와께서 내가 미움을 받음을 들으셨으므로 내게 이 아들도 주셨다” 하고 그 이름을 시므온이라 불렀더라.'),
(830, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 34, 'OT', '그녀가 또 잉태하여 아들을 낳고 말하되, 이제 이번에는 내 남편이 내게 연합하리니, 내가 그에게 세 아들을 낳았음이라. 그러므로 그 이름을 레위라 불렀더라.'),
(831, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 29, 35, 'OT', '그녀가 또 다시 임신하여 아들을 낳고 말하기를 “이제는 내가 여호와를 찬송하리라” 하였으므로 그 이름을 유다라 불렀으며, 그녀는 출산을 멈추었더라.'),
(832, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 1, 'OT', '라헬이 자기가 야곱에게 아들을 낳지 못함을 보고, 라헬이 그 자매를 시기하여 야곱에게 이르되, "내게 아들들을 주소서, 그렇지 않으면 내가 죽겠나이다."'),
(833, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 2, 'OT', '야곱이 라헬에게 노를 발하여 이르되, 네게 태의 열매를 금하신 이는 하나님이시니 내가 하나님을 대신하겠느냐?'),
(834, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 3, 'OT', '그녀가 말하되, 보라 나의 여종 빌하에게 들어가라, 그가 내 무릎 위에 낳으리니, 그러면 나도 그로 말미암아 세워지리라.'),
(835, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 4, 'OT', '그가 그의 여종 빌하를 그에게 아내로 주었고, 야곱이 그에게로 들어갔더라.'),
(836, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 5, 'OT', '빌하가 잉태하여 야곱에게 아들을 낳았더라.'),
(837, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 6, 'OT', '라헬이 말하되 하나님이 나를 판단하셨고 또한 내 목소리를 들으셨으며 내게 아들을 주셨도다 그러므로 그가 그의 이름을 단이라 불렀더라'),
(838, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 7, 'OT', '라헬의 시녀 빌하가 다시 잉태하여 야곱에게 둘째 아들을 낳았더라'),
(839, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 8, 'OT', '라헬이 말하되, “내가 하나님의 씨름들로 내 자매와 씨름하여 이겼도다” 하고 그 이름을 납달리라 불렀더라.'),
(840, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 9, 'OT', '레아가 생산이 멈춘 것을 보고 그녀의 여종 실바를 데려다가 야곱에게 아내로 주었더라.'),
(841, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 10, 'OT', '레아의 여종 실바가 야곱에게 아들을 낳으니라.'),
(842, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 11, 'OT', '레아가 말하기를 “군대가 오는도다” 하고 그의 이름을 갓이라 불렀더라.'),
(843, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 12, 'OT', '레아의 여종 실바가 야곱에게 둘째 아들을 낳으니라'),
(844, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 13, 'OT', '레아가 이르되, 나는 복되도다, 딸들이 나를 복되다 하리로다, 하고 그 이름을 아셀이라 하였더라.'),
(845, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 14, 'OT', '맥추 때에 르우벤이 나가서 들에서 합환채를 얻어 그의 어머니 레아에게 가져왔더라. 그러자 라헬이 레아에게 말하되 청하노니 네 아들의 합환채를 내게 주라 하니라.'),
(846, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 15, 'OT', '레아가 그녀에게 이르되, “네가 내 남편을 취한 것이 작은 일이냐? 네가 내 아들의 합환채도 취하려 하느냐?” 라헬이 이르되, “그러므로 그가 오늘 밤에 네 아들의 합환채를 대신하여 너와 함께 누우리라.”'),
(847, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 16, 'OT', '저물 때에 야곱이 들에서 돌아오매 레아가 나와서 그를 맞이하며 이르되 내게로 들어오라 내가 내 아들의 합환채로 당신을 샀노라 하니 그 밤에 그가 그녀와 동침하였더라'),
(848, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 17, 'OT', '하나님이 레아의 소리를 들으셨고, 그가 잉태하여 야곱에게 다섯째 아들을 낳았더라.'),
(849, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 18, 'OT', '레아가 말하되, 하나님이 내게 내 삯을 주셨으니 이는 내가 내 여종을 내 남편에게 주었음이라 하고 그 이름을 잇사갈이라 불렀더라'),
(850, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 19, 'OT', '레아가 다시 잉태하여 야곱에게 여섯째 아들을 낳았더라'),
(851, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 20, 'OT', '레아가 말하되, 하나님이 내게 좋은 선물을 주셨도다. 이제는 내 남편이 나와 함께 거하리니, 이는 내가 그에게 여섯 아들을 낳았음이라. 그가 그의 이름을 스불론이라 불렀더라.'),
(852, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 21, 'OT', '그 후에 그가 딸을 낳고 그 이름을 디나라 하였더라'),
(853, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 22, 'OT', '하나님이 라헬을 기억하셨고, 하나님이 그녀의 소리를 들으셨으며, 그녀의 태를 여셨더라.'),
(854, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 23, 'OT', '그녀가 잉태하여 아들을 낳고 말하되, 하나님이 나의 수치를 거두셨다 하였더라.'),
(855, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 24, 'OT', '그녀가 그의 이름을 요셉이라 부르며 말하되, 여호와께서 내게 또 다른 아들을 더하시리로다 하였더라.'),
(856, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 25, 'OT', '라헬이 요셉을 낳았을 때에 야곱이 라반에게 이르되 나를 보내어 내 곳과 내 땅으로 가게 하소서'),
(857, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 26, 'OT', '내 아내들과 내 자식들을 내게 주어 내가 가게 하소서 내가 당신을 섬긴 것은 그들을 위한 것이니이다 당신은 내가 당신을 섬긴 내 수고를 아시나이다'),
(858, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 27, 'OT', '라반이 그에게 이르되, "청하건대 내가 네 눈에 은혜를 얻었으면, 내가 점쳐 보니 여호와께서 너로 말미암아 나를 복 주셨도다."'),
(859, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 28, 'OT', '그가 이르되, 네 품삯을 내게 정하라, 내가 그것을 주리라.'),
(860, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 29, 'OT', '너는 내가 어떻게 당신을 섬겼는지, 그리고 당신의 짐승이 나와 함께 있었는지를 아시나이다'),
(861, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 30, 'OT', '내가 오기 전에 외삼촌에게 있던 것이 적었으나 이제는 번성하여 많아졌고, 여호와께서 내 발걸음을 따라 외삼촌에게 복을 주셨나이다. 이제 내가 언제 내 집도 세우리이까?'),
(862, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 31, 'OT', '그가 말하되, 내가 무엇을 네게 주랴? 야곱이 말하되, 당신이 내게 아무것도 주지 마소서. 만일 당신이 나를 위하여 이 일을 행하시면, 내가 돌아와 당신의 양 떼를 먹이고 지키리이다.'),
(863, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 32, 'OT', '내가 오늘 당신의 모든 양 떼 가운데로 지나가며, 거기서 모든 점 있는 것과 얼룩진 양과 어린 양 가운데 모든 검은 양, 그리고 염소 가운데 얼룩진 것과 점 있는 것을 제거하리니, 그것이 나의 삯이 되리라.'),
(864, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 33, 'OT', '내 의로움이 내게 대답하리니, 내일 당신이 내 품삯을 보러 내 앞에 올 때에, 염소들 가운데서 점 없고 아롱진 것이 없고 양들 가운데서 검은 것이 없는 모든 것은, 그것은 내게 도둑맞은 것이리이다.'),
(865, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 34, 'OT', '라반이 이르되 보라, 네 말대로 되기를 원하노라'),
(866, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 35, 'OT', '그 날에 그가 점 있는 염소와 아롱진 염소와 모든 점 있는 암염소와 아롱진 암염소와 그 중에 흰 빛이 있는 모든 것과 양 가운데서 모든 검은 것을 떼어 내어 그의 아들들의 손에 맡겼더라'),
(867, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 36, 'OT', '그는 자기와 야곱 사이에 사흘 길을 두었고, 야곱은 라반의 남은 양 떼를 치고 있었더라.'),
(868, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 37, 'OT', '야곱이 자기에게 버드나무와 살구나무와 밤나무의 푸른 가지를 취하고, 그 가지들의 흰 껍질을 벗겨 흰 무늬를 내되, 가지에 있는 흰 부분이 드러나게 하였더라.'),
(869, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 38, 'OT', '그가 벗긴 나뭇가지들을 양 떼가 마시러 올 때 물 구유의 개천들에 세워 양 떼 앞에 두었으니, 그들이 마시러 올 때에 번식하게 하려 함이었더라.'),
(870, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 39, 'OT', '양 떼가 그 막대기들을 향하여 새끼를 배어서, 양 떼가 줄무늬 있는 것과 점 있는 것과 얼룩무늬 있는 것을 낳았더라.'),
(871, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 40, 'OT', '야곱이 어린 양들을 구별하고 그 양 떼의 얼굴을 줄무늬 있는 것과 라반의 양 떼 중 모든 검은 갈색 있는 것을 향하게 하였으며, 자기 양 떼를 따로 두고 라반의 양 떼와는 섞지 아니하였더라.'),
(872, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 41, 'OT', '그 때에 양 떼 중에 강한 것이 새끼를 밸 때마다 야곱이 그 물 구유 앞 양 떼의 눈 앞에 가지를 두어 그것들이 가지 사이에서 새끼를 배게 하였더라'),
(873, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 42, 'OT', '그러나 양 떼가 약할 때에는 넣지 아니하니, 약한 것은 라반의 것이 되고 강한 것은 야곱의 것이 되었더라.'),
(874, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 30, 43, 'OT', '그 사람이 매우 심히 창성하여 양 떼와 여종과 남종과 낙타와 나귀가 많았더라'),
(875, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 1, 'OT', '야곱이 라반의 아들들의 말을 들으니 그들이 이르되, 야곱이 우리 아버지의 모든 것을 빼앗았고 우리 아버지의 것으로 이 모든 영광을 얻었다 하더라'),
(876, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 2, 'OT', '야곱이 라반의 얼굴을 보니, 보라, 그가 전날과 그제날처럼 자기와 함께하지 아니하였더라.'),
(877, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 3, 'OT', '여호와께서 야곱에게 이르시되 네 조상들의 땅과 네 족속에게로 돌아가라 내가 너와 함께 있으리라'),
(878, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 4, 'OT', '야곱이 보내어 라헬과 레아를 자기 양 떼 있는 들로 불렀더라'),
(879, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 5, 'OT', '그가 그들에게 말하되, 내가 그대들의 아버지의 얼굴을 보니 그가 내게 대하여 전과 같지 아니하도다. 그러나 내 아버지의 하나님이 나와 함께 계셨느니라.'),
(880, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 6, 'OT', '너희도 알거니와 내가 모든 힘을 다하여 너희 아버지를 섬겼느니라.'),
(881, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 7, 'OT', '너희 아버지가 나를 속였고 내 품삯을 열 번이나 바꾸었으나 하나님이 그가 나를 해치지 못하게 하셨느니라'),
(882, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 8, 'OT', '그가 이르기를 점 있는 것이 네 삯이 되리라 하면 모든 양 떼가 점 있는 것을 낳고, 또 그가 이르기를 얼룩무늬 있는 것이 네 삯이 되리라 하면 모든 양 떼가 얼룩무늬 있는 것을 낳았더라.'),
(883, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 9, 'OT', '하나님이 당신들 아버지의 가축을 빼앗아 내게 주셨느니라'),
(884, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 10, 'OT', '그 때에 양 떼가 새끼를 밸 때에 내가 꿈에 눈을 들어 보니, 보라, 양 떼 위에 오르는 숫염소들은 줄무늬 있는 것, 점 있는 것, 아롱진 것들이었더라.'),
(885, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 11, 'OT', '꿈에 하나님의 사자가 내게 말씀하시기를 야곱아 하시기에 내가 대답하기를 여기 있나이다 하였노라'),
(886, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 12, 'OT', '그가 이르되, 네 눈을 들어 보라, 양 떼 위에 오르는 모든 숫양들이 줄무늬 있는 것, 점 있는 것, 아롱진 것들이니, 이는 내가 라반이 네게 행하는 모든 것을 보았음이라.'),
(887, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 13, 'OT', '나는 벧엘의 하나님이라, 네가 거기서 기둥에 기름을 부었고 거기서 내게 서원하였느니라. 이제 일어나 이 땅에서 나가 네 고향 땅으로 돌아가라.'),
(888, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 14, 'OT', '라헬과 레아가 대답하여 그에게 말하되, 우리가 우리 아버지 집에서 아직 무슨 몫이나 유산이 있으리요'),
(889, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 15, 'OT', '우리를 그가 외인으로 여기지 아니하느냐 이는 그가 우리를 팔았고 우리의 돈을 또한 온전히 먹어버렸음이라'),
(890, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 16, 'OT', '하나님이 우리 아버지에게서 빼앗으신 모든 재물은 우리와 우리 자녀의 것이니, 이제 하나님이 당신에게 말씀하신 모든 것을 행하라.'),
(891, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 17, 'OT', '야곱이 일어나서 그의 아들들과 그의 아내들을 약대들에게 태웠더라'),
(892, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 18, 'OT', '그가 모든 가축과 그가 얻은 모든 소유물, 곧 그가 밧단아람에서 얻은 가축을 이끌고 가나안 땅에 있는 그의 아버지 이삭에게로 가려 하였더라'),
(893, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 19, 'OT', '라반이 그의 양 떼를 깎으러 갔고, 라헬은 그녀의 아버지의 드라빔을 도둑질하였더라.'),
(894, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 20, 'OT', '야곱이 아람 사람 라반의 마음을 훔쳤으니 이는 그가 도망함을 그에게 알리지 아니하였음이라'),
(895, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 21, 'OT', '그가 그 모든 소유와 함께 도망하여 일어나 강을 건너 길르앗 산으로 그의 얼굴을 향하게 하였더라'),
(896, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 22, 'OT', '라반에게 사흘째 되는 날에 야곱이 도망하였다는 것이 알려졌더라.'),
(897, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 23, 'OT', '그가 그의 형제들을 데리고 그를 따라 칠 일 길을 쫓아가서 길르앗 산에서 그를 따라잡았다.'),
(898, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 24, 'OT', '밤에 하나님이 아람 사람 라반에게 꿈에 나타나서 그에게 이르시되, 너는 삼가 야곱에게 선한 말에서 악한 말까지 말하지 말라 하셨더라'),
(899, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 25, 'OT', '라반이 야곱을 따라잡았고, 야곱은 산에 자기 장막을 쳤으며, 라반은 그의 형제들과 함께 길르앗 산에 장막을 쳤더라.'),
(900, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 26, 'OT', '라반이 야곱에게 이르되 네가 무엇을 행하였기에 내 마음을 도적질하고 내 딸들을 칼에 사로잡힌 자 같이 끌고 갔느냐'),
(901, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 27, 'OT', '어찌하여 네가 숨어서 도망하고 나를 속였느냐? 네가 내게 알리지 아니하였으니 내가 기쁨과 노래와 북과 수금으로 너를 보내었을 것을!'),
(902, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 28, 'OT', '네가 나로 내 아들들과 딸들에게 입맞추지 못하게 하였으니, 이제 네가 어리석게 행하였도다.'),
(903, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 29, 'OT', '내 손에 너희를 해할 능력이 있으나 너희 아버지의 하나님이 어제 밤에 내게 말씀하여 이르시기를 너는 삼가 야곱에게 좋은 말이든 나쁜 말이든 말하지 말라 하셨느니라'),
(904, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 30, 'OT', '이제 네가 네 아버지의 집을 사모하여 반드시 갔거니와, 어찌하여 내 신들을 도적질하였느냐?'),
(905, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 31, 'OT', '야곱이 라반에게 대답하여 이르되, 내가 두려워하였기 때문이니, 내가 말하기를 당신이 당신의 딸들을 내게서 빼앗을까 하였음이니이다.'),
(906, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 32, 'OT', '네가 네 신들을 찾는 자는 살지 못할 것이요, 우리 형제들 앞에서 네게 있는 것이 무엇인지 가려서 네 것으로 가지라 하였으나, 야곱은 라헬이 그것들을 도적질한 줄을 알지 못하였더라.'),
(907, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 33, 'OT', '라반이 야곱의 장막에 들어가고 레아의 장막에 들어가고 두 여종의 장막에 들어갔으나 찾지 못하였고, 레아의 장막에서 나와 라헬의 장막에 들어갔더라.'),
(908, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 34, 'OT', '라헬이 그 드라빔을 가져다가 낙타 안장에 넣고 그 위에 앉았더라. 라반이 그 장막 전체를 더듬어 찾았으나 찾지 못하니라.'),
(909, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 35, 'OT', '그녀가 아버지에게 말하되, "내 주여, 주의 눈에 노하지 마소서, 내가 주 앞에 일어설 수 없음은 여인의 길이 내게 있음이니이다." 하매 그가 찾았으나 그 드라빔을 찾지 못하니라.'),
(910, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 36, 'OT', '야곱이 노하여 라반과 다투며, 야곱이 라반에게 대답하여 이르되, 나의 허물이 무엇이며 나의 죄가 무엇이기에 네가 나를 맹렬히 쫓았느냐?'),
(911, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 37, 'OT', '네가 내 모든 물건을 뒤져 보았으니 네 집의 모든 물건 중에서 무엇을 찾았느냐? 그것을 내 형제들과 네 형제들 앞에 두라 그들이 우리 둘 사이에 판단하게 하리라'),
(912, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 38, 'OT', '내가 이 이십 년 동안 너와 함께 있었으나 네 암양들과 암염소들이 낙태하지 아니하였고 네 양 떼의 수양들은 내가 먹지 아니하였느니라'),
(913, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 39, 'OT', '물려 찢긴 것은 내가 당신에게 가져오지 아니하고 내가 그것을 보충하였으며, 그것을 내 손에서 요구하셨나이다. 낮에 도둑맞은 것이나 밤에 도둑맞은 것이나 내가 물어 내었나이다.'),
(914, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 40, 'OT', '내가 낮에는 더위가 나를 삼켰고 밤에는 서리가 내게 임하였으며, 내 눈에서 잠이 떠나갔나이다.'),
(915, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 41, 'OT', '내가 이십 년을 당신의 집에 있었사오며 당신의 두 딸을 위하여 십사 년을, 당신의 양 떼를 위하여 육 년을 당신을 섬겼사오나 당신은 내 품삯을 열 번이나 바꾸셨나이다'),
(916, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 42, 'OT', '내 아버지의 하나님, 아브라함의 하나님, 이삭이 경외하는 이가 나와 함께 계시지 아니하셨더면, 당신이 이제 나를 빈손으로 보냈을 것이니이다. 하나님이 나의 고난과 내 손의 수고를 보셨고, 어젯밤에 책망하셨나이다.'),
(917, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 43, 'OT', '라반이 야곱에게 대답하여 이르되, 딸들은 내 딸들이요, 아들들은 내 아들들이요, 양 떼는 내 양 떼요, 네가 보는 모든 것은 내 것이니, 내가 오늘 내 딸들이나 그들이 낳은 자식들에게 무엇을 할 수 있겠느냐?'),
(918, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 44, 'OT', '이제 오라, 나와 네가 언약을 맺자, 그것이 나와 너 사이에 증거가 되리라.'),
(919, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 45, 'OT', '야곱이 돌을 가져 그것을 기둥으로 세우니라'),
(920, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 46, 'OT', '야곱이 그의 형제들에게 말하되 돌들을 모으라 하니 그들이 돌들을 가져다가 무더기를 만들고 그 무더기 위에서 거기서 먹으니라'),
(921, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 47, 'OT', '라반은 그것을 여갈사하두다라 불렀고, 야곱은 그것을 갈르엣이라 불렀더라.'),
(922, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 48, 'OT', '라반이 이르되, 이 무더기가 오늘 나와 너 사이에 증거가 된다 하였으므로 그 이름을 갈르엣이라 불렀더라'),
(923, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 49, 'OT', '또한 미스바라 하였으니, 이는 여호와께서 나와 너 사이를 감찰하시기를 원함이라, 우리가 서로 떠나 있을 때에 하였음이라.'),
(924, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 50, 'OT', '네가 내 딸들을 학대하거나 내 딸들 외에 다른 아내들을 취하면 우리와 함께 있는 사람이 없을지라도 보라, 하나님이 나와 너 사이에 증인이 되시느니라.'),
(925, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 51, 'OT', '라반이 야곱에게 이르되, 보라 이 무더기를, 또 보라 내가 너와 나 사이에 세운 이 기둥을.'),
(926, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 52, 'OT', '이 무더기가 증거가 되고 이 기둥이 증거가 되나니 내가 이 무더기를 넘어 네게로 가지 아니할 것이요, 너도 이 무더기와 이 기둥을 넘어 내게로 와서 해하지 아니할 것이라'),
(927, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 53, 'OT', '아브라함의 하나님과 나홀의 하나님이 우리 사이에 판단하시기를 원하노라 하매, 그들의 아버지의 하나님이시라. 야곱이 그의 아버지 이삭의 경외하는 이를 가리켜 맹세하니라.'),
(928, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 54, 'OT', '야곱이 산에서 제사를 드리고 그의 형제들을 불러 떡을 먹게 하니 그들이 떡을 먹고 산에서 밤을 지냈더라.'),
(929, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 31, 55, 'OT', '라반이 아침에 일찍 일어나 그의 아들들과 딸들에게 입맞추고 그들을 축복한 후, 라반이 떠나 자기 곳으로 돌아갔더라.'),
(930, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 1, 'OT', '야곱이 그의 길로 가더니, 하나님의 사자들이 그를 만나니라.'),
(931, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 2, 'OT', '야곱이 그들을 보고 말하기를 “이것은 하나님의 진영이다” 하고 그 곳의 이름을 마하나임이라 불렀더라.'),
(932, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 3, 'OT', '야곱이 자기 앞서 사자들을 그의 형 에서에게 세일 땅, 에돔 들로 보내니라'),
(933, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 4, 'OT', '그들에게 명령하여 이르되, 너희는 이같이 내 주 에서에게 말하라, 주의 종 야곱이 이같이 말하기를, 내가 라반과 함께 머물렀고 지금까지 지체하였나이다.'),
(934, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 5, 'OT', '내게 소와 나귀와 양 떼와 종과 여종이 있으며, 내가 내 주께 알리려고 사람을 보내어 주의 눈앞에서 은혜를 얻고자 하나이다.'),
(935, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 6, 'OT', '사자들이 야곱에게 돌아와 말하여 이르되, 우리가 당신의 형 에서에게 이르렀나이다. 그가 또한 사백 명의 사람들과 함께 당신을 만나러 오고 있나이다.'),
(936, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 7, 'OT', '야곱이 심히 두렵고 답답하여 자기와 함께 한 백성과 양 떼와 소 떼와 낙타들을 두 진영으로 나누니라'),
(937, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 8, 'OT', '에서가 한 진영에 이르러 그것을 치면, 남은 진영은 피하게 되리라'),
(938, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 9, 'OT', '야곱이 말하되, 내 아버지 아브라함의 하나님이시요 내 아버지 이삭의 하나님이신 여호와여, 주께서 내게 말씀하시기를 네 땅과 네 친족에게로 돌아가라, 내가 너와 함께 선을 행하리라 하셨나이다'),
(939, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 10, 'OT', '나는 주께서 주의 종에게 베푸신 모든 은총과 모든 진리를 조금이라도 감당할 수 없사오니 내가 내 지팡이만 가지고 이 요단을 건넜더니 지금은 두 떼나 이루었나이다'),
(940, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 11, 'OT', '나를 청하노니 내 형의 손에서, 에서의 손에서 나를 건져내소서. 내가 그를 두려워함은 그가 와서 나를 치고 어머니를 자식들과 함께 칠까 함이니이다.'),
(941, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 12, 'OT', '네가 말하기를 내가 반드시 너에게 은혜를 베풀리라 하였고, 네 씨를 바다의 모래와 같이 많게 하리니, 그것은 그 수가 많아서 셀 수 없으리라 하였느니라.'),
(942, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 13, 'OT', '그 날 밤에 거기서 유숙하고 그의 손에 있는 것 중에서 형 에서를 위하여 예물을 취하니라'),
(943, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 14, 'OT', '암염소가 이백이요, 수염소가 이십이요, 암양이 이백이요, 수양이 이십이요,'),
(944, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 15, 'OT', '젖 나는 약대 삼십과 그 새끼들, 암소 사십과 수소 열, 암나귀 이십과 새끼 나귀 열이라.'),
(945, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 16, 'OT', '그것을 각각 떼로 나누어 그의 종들의 손에 맡기고 그 종들에게 이르되 너희는 나보다 앞서 건너가서 떼와 떼 사이에 간격을 두라 하니라'),
(946, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 17, 'OT', '그가 앞선 자에게 명령하여 이르되, 내 형 에서가 너를 만나 네게 묻기를, 네가 누구의 사람이며 어디로 가느냐, 네 앞에 있는 이들은 누구의 것이냐 하거든'),
(947, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 18, 'OT', '당신은 당신의 종 야곱에게 말하기를, 이것은 내 주 에서에게 보내는 예물이며, 보라, 그도 우리 뒤에 있나이다 하라.'),
(948, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 19, 'OT', '또한 둘째와 셋째와 양 떼를 따라가는 모든 자에게 명령하여 이르되 너희가 에서를 만나거든 이와 같이 그에게 말할지니라'),
(949, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 20, 'OT', '또 너희는 말하기를, 보라, 주의 종 야곱이 우리 뒤에 있다 하라 하였으니, 이는 그가 말하기를 내가 내 앞에 보내는 예물로 그의 얼굴을 달래리라, 그 후에 내가 그의 얼굴을 보리니 혹시 그가 나의 얼굴을 들어 주리라 하였음이라.'),
(950, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 21, 'OT', '그 예물은 그의 앞서 행하고 그는 그 밤에 진영에서 유숙하니라'),
(951, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 22, 'OT', '그 밤에 그가 일어나 두 아내와 두 여종과 열한 아들을 데리고 얍복 나루를 건넜더라.'),
(952, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 23, 'OT', '그들을 데려다가 그 시내를 건네주고 그가 가진 것도 건네주었더라'),
(953, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 24, 'OT', '야곱이 홀로 남았더니, 어떤 사람이 그와 함께 새벽이 오를 때까지 씨름하였더라.'),
(954, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 25, 'OT', '그가 자기에게 이기지 못함을 보고 야곱의 넓적다리 관절을 치매 야곱의 넓적다리 관절이 그와 씨름할 때에 어긋났더라'),
(955, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 26, 'OT', '그가 말하되 “날이 새려 하니 나를 보내라” 하니, 그가 말하되 “네가 나를 축복하지 아니하면 보내지 아니하리라” 하니라.'),
(956, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 27, 'OT', '그가 그에게 이르되 네 이름이 무엇이냐 하니 그가 이르되 야곱이니이다'),
(957, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 28, 'OT', '그가 이르되, 네 이름이 다시는 야곱이라 불리지 아니하고 이스라엘이라 불리리니, 이는 네가 하나님과 사람들과 더불어 싸워 이겼음이니라.'),
(958, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 29, 'OT', '야곱이 물어 이르되 청하노니 당신의 이름을 알려 주소서 하니 그가 이르되 어찌하여 내 이름을 묻느냐 하고 거기서 그를 축복하니라'),
(959, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 30, 'OT', '야곱이 그 곳의 이름을 브니엘이라 불렀으니 이는 내가 하나님을 얼굴과 얼굴로 보았으나 내 생명이 보전되었음이라.'),
(960, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 31, 'OT', '그가 브니엘을 지날 때에 해가 그에게 떠올랐고, 그는 자기 넓적다리로 인하여 절뚝거렸더라.'),
(961, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 32, 32, 'OT', '그러므로 이스라엘 자손들은 오늘날까지 넓적다리 위에 있는 힘줄, 곧 환도뼈의 힘줄을 먹지 아니하나니 이는 그가 야곱의 넓적다리 힘줄을 만졌음이라.'),
(962, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 1, 'OT', '야곱이 눈을 들어 보니, 보라, 에서가 오고 있었고 그와 함께 사백 명의 사람들이 있었으며, 그가 아이들을 레아와 라헬과 두 여종에게 나누었다.'),
(963, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 2, 'OT', '여종들과 그들의 자녀들을 첫 번째로 두고, 레아와 그녀의 자녀들을 그 다음에 두고, 라헬과 요셉을 마지막에 두었다.'),
(964, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 3, 'OT', '그는 그들 앞에서 지나가며 몸을 일곱 번 땅에 굽혀 그 형에게 가까이 이르렀더라'),
(965, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 4, 'OT', '에서가 달려와 그를 맞이하여 그를 안고 그의 목에 엎드려 입맞추고 그들이 울었더라.'),
(966, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 5, 'OT', '에서가 눈을 들어 여인들과 아이들을 보고 이르되, 이들은 누구니이까? 그가 이르되, 하나님이 주의 종에게 은혜로 주신 아이들이니이다.'),
(967, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 6, 'OT', '여종들이 그 자식들과 함께 나아와 절하니라'),
(968, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 7, 'OT', '레아도 그 자식들과 함께 나아와 절하고, 그 후에 요셉과 라헬이 나아와 절하니라.'),
(969, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 8, 'OT', '에서가 이르되 내가 만난 이 모든 떼가 네게 무슨 까닭이냐 하니 그가 이르되 내 주의 목전에서 은혜를 얻으려 함이니이다'),
(970, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 9, 'OT', '에서가 말하되, 내게 많은 것이 있나니, 내 형제여, 네게 있는 것은 네게 두라.'),
(971, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 10, 'OT', '야곱이 말하되, 청하건대 내가 당신의 눈에 은혜를 얻었사오면 내 손에서 이 예물을 받으소서, 이는 내가 당신의 얼굴을 보되 하나님의 얼굴을 보는 것 같이 보았사오며 당신이 나를 기쁘게 받으셨음이니이다.'),
(972, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 11, 'OT', '청컨대 내가 네게 가져온 예물을 받으소서, 이는 하나님이 내게 은혜를 베푸셨고 내게 모든 것이 있음이니이다. 그가 그에게 강권하매 그가 받으니라.'),
(973, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 12, 'OT', '에서가 이르되, 우리가 떠나가자, 내가 네 앞으로 가리라.'),
(974, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 13, 'OT', '그가 그에게 이르되, 내 주께서 아시거니와 아이들은 연약하고 양떼와 소떼가 나를 따라 새끼를 데리고 있나이다. 만일 그것들을 하루만 과히 몰면 모든 양떼가 죽으리이다.'),
(975, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 14, 'OT', '내 주여 청하건대 주의 종보다 앞서 가소서 나는 내 앞에 있는 짐승과 아이들의 걸음에 맞추어 천천히 인도하여 세일로 가서 내 주께 나아가리이다'),
(976, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 15, 'OT', '에서가 말하되, 내가 청하노니 나와 함께 있는 백성 중에서 얼마를 네게 머물리라 하니, 그가 말하되, 어찌하여 그리하리이까, 내가 내 주의 눈앞에서 은혜를 얻기를 원하나이다.'),
(977, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 16, 'OT', '그 날에 에서는 세일로 그의 길로 돌아갔더라.'),
(978, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 17, 'OT', '야곱이 숙곳으로 여행하여 자기에게 집을 짓고 그의 가축을 위하여 초막들을 지었으므로 그 곳의 이름을 숙곳이라 불렀더라'),
(979, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 18, 'OT', '야곱이 평안히 세겜 성에 이르렀으니, 그 성은 가나안 땅에 있으며, 그가 밧단아람에서 올 때에 성 앞에 장막을 쳤더라.'),
(980, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 19, 'OT', '그가 자기 장막을 친 밭의 한 부분을 세겜의 아버지 하몰의 아들들의 손에서 백 개의 크시타로 샀더라.'),
(981, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 33, 20, 'OT', '그가 거기서 제단을 쌓고 그것을 이스라엘의 하나님 엘이라 불렀더라.'),
(982, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 1, 'OT', '레아가 야곱에게 낳은 딸 디나가 그 땅의 딸들을 보러 나갔더라.'),
(983, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 2, 'OT', '히위 사람 하몰의 아들 그 땅의 추장 세겜이 그를 보고 그를 붙잡아 그와 동침하며 그를 욕되게 하니라'),
(984, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 3, 'OT', '그의 마음이 야곱의 딸 디나에게 깊이 붙었고, 그가 그 소녀를 사랑하여 그 소녀의 마음에 말로 위로하였더라.'),
(985, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 4, 'OT', '세겜이 그의 아버지 하몰에게 말하여 이르되, 이 소녀를 내 아내로 얻어 주소서 하였더라'),
(986, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 5, 'OT', '야곱이 그의 딸 디나를 그가 더럽혔음을 들었으나 그의 아들들이 들에서 그들의 가축과 함께 있었으므로 야곱이 그들이 올 때까지 잠잠하였더라'),
(987, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 6, 'OT', '하몰이 세겜의 아비라 야곱에게 말하러 나아갔더라'),
(988, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 7, 'OT', '야곱의 아들들이 그 소식을 듣고 들에서 돌아왔고, 그 사람들이 근심하며 그들에게 매우 화가 났으니, 이는 그가 야곱의 딸과 동침함으로 이스라엘 가운데 어리석은 일을 행하였음이라, 그런 일은 행해져서는 안 될 것이었더라.'),
(989, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 8, 'OT', '하몰이 그들과 말하여 이르되, 내 아들 세겜의 마음이 너희 딸을 사모하니 청하노니 그를 그에게 아내로 주라'),
(990, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 9, 'OT', '너희는 우리와 혼인 관계를 맺어, 너희 딸들을 우리에게 주고, 우리 딸들을 너희가 취하라.'),
(991, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 10, 'OT', '너희는 우리와 함께 거주하라, 땅이 너희 앞에 있으니, 거기 앉아 장사하며 그 땅에서 기업을 얻으라.'),
(992, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 11, 'OT', '세겜이 그녀의 아버지와 그녀의 형제들에게 말하되, "내가 너희 눈에 은혜를 얻으리니, 너희가 내게 말하는 것을 내가 주리라."'),
(993, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 12, 'OT', '내게 혼인 예물과 선물을 크게 많이 청구하라 내가 너희가 내게 말한 대로 주리라 오직 이 소녀만 내게 주어 아내가 되게 하라'),
(994, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 13, 'OT', '야곱의 아들들이 세겜과 그의 아비 하몰에게 속임으로 대답하여 말하되, 그가 그들의 누이 디나를 더럽혔음이라.'),
(995, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 14, 'OT', '그들이 그들에게 말하되 우리가 이 일을 행할 수 없나니 곧 할례 없는 사람에게 우리 누이를 주는 것은 우리에게 수욕이 됨이라'),
(996, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 15, 'OT', '오직 이것으로 우리가 너희에게 허락하리니 너희가 우리 같이 되어 너희 중 모든 남자가 할례를 받으면'),
(997, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 16, 'OT', '우리가 우리 딸들을 너희에게 주고 너희 딸들을 우리가 취하며 우리가 너희와 함께 거하여 한 백성이 되리라'),
(998, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 17, 'OT', '만일 너희가 우리 말을 듣지 아니하고 할례를 받지 아니하면, 우리가 우리 딸을 데리고 가리라.'),
(999, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 18, 'OT', '그들의 말이 하몰의 눈에, 그리고 하몰의 아들 세겜의 눈에 좋게 보였더라.'),
(1000, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 19, 'OT', '그 소년은 그 일을 행하기를 지체하지 아니하였으니 이는 그가 야곱의 딸을 기뻐함이며 그는 그의 아버지 집의 모든 사람보다 더 존귀하였더라.'),
(1001, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 20, 'OT', '하몰과 그의 아들 세겜이 그들의 성읍 문에 이르러 그들의 성읍 사람들에게 말하여 이르되'),
(1002, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 21, 'OT', '이 사람들은 우리와 화평하니 그들이 이 땅에 거주하며 그 땅에서 장사하게 하자, 보라 그 땅이 그들 앞에 넓으니 우리가 그들의 딸들을 아내로 취하고 우리 딸들을 그들에게 주자.'),
(1003, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 22, 'OT', '오직 이것으로 그 사람들이 우리와 함께 거하여 한 백성이 되기를 허락하리니 우리 중에 모든 남자가 그들이 할례를 받음 같이 할례를 받아야 하리라'),
(1004, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 23, 'OT', '그들의 가축과 소유물과 그들의 모든 짐승이 우리의 것이 아니겠느냐? 다만 우리가 그들에게 동의하자, 그러면 그들이 우리와 함께 거하리라.'),
(1005, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 24, 'OT', '그의 성문으로 나가는 모든 자가 하몰과 그의 아들 세겜의 말을 들었고, 그의 성문으로 나가는 모든 남자가 할례를 받았다.'),
(1006, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 25, 'OT', '제삼일에 그들이 고통할 때에 야곱의 두 아들, 디나의 형제 시므온과 레위가 각기 칼을 들고, 그 성읍을 안전하게 여기고 있는 틈을 타서 들어가 모든 남자를 죽였더라.'),
(1007, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 26, 'OT', '그들이 칼날로 하몰과 그의 아들 세겜을 죽이고, 디나를 세겜의 집에서 데려가 나갔더라.'),
(1008, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 27, 'OT', '야곱의 아들들이 죽임을 당한 자들에게 이르러 그 성읍을 노략하였으니 이는 그들이 그들의 누이를 더럽혔음이라.'),
(1009, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 28, 'OT', '그들의 양 떼와 그들의 소 떼와 그들의 나귀들과 그 성에 있는 것과 들에 있는 것을 그들이 가져갔더라'),
(1010, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 29, 'OT', '그들의 모든 재물과 그들의 모든 어린아이들과 그들의 아내들을 사로잡아 노략하였으며 집 안에 있는 모든 것을 다 탈취하였더라'),
(1011, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 30, 'OT', '야곱이 시므온과 레위에게 이르되 너희가 나를 괴롭게 하여 이 땅의 거주민 곧 가나안 족속과 브리스 족속에게 나를 악취나게 하였도다 나는 수가 적은즉 그들이 내게 모여 나를 치고 나를 죽이리니 나와 내 집이 멸망하리라'),
(1012, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 34, 31, 'OT', '그들이 말하되, “그가 우리 누이를 창녀처럼 대우하겠느냐?”'),
(1013, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 1, 'OT', '하나님이 야곱에게 이르시되 일어나 벧엘로 올라가서 거기 거주하며 네가 네 형 에서의 낯을 피하여 도망하던 때에 네게 나타난 하나님께 거기서 제단을 쌓으라 하시니라'),
(1014, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 2, 'OT', '야곱이 자기 집과 자기와 함께 한 모든 자에게 이르되, 너희 중에 있는 이방 신들을 제거하고, 자신을 정결하게 하며, 너희 옷을 바꾸라.'),
(1015, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 3, 'OT', '우리가 일어나 벧엘로 올라가자, 내가 거기서 나의 환난 날에 내게 응답하시고 내가 걸어간 길에서 나와 함께 하신 하나님께 제단을 쌓으리라.'),
(1016, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 4, 'OT', '그들이 자기 손에 있는 모든 이방 신들과 자기 귀에 있는 귀고리들을 야곱에게 주었고, 야곱은 그것들을 세겜 곁에 있는 상수리나무 아래에 묻었더라.'),
(1017, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 5, 'OT', '그들이 떠났는데, 그들의 사면에 있는 성읍들 위에 하나님의 두려움이 임하였고, 그들이 야곱의 아들들을 추격하지 아니하였더라.'),
(1018, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 6, 'OT', '야곱이 가나안 땅에 있는 루스 곧 벧엘에 이르렀으니 그와 그와 함께한 모든 백성이더라'),
(1019, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 7, 'OT', '그가 거기서 제단을 쌓고 그 곳을 엘벧엘이라 불렀으니 이는 그가 형의 낯을 피하여 도망할 때에 하나님이 그에게 거기서 나타나셨음이더라'),
(1020, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 8, 'OT', '리브가의 유모 드보라가 죽으매 그를 벧엘 아래 상수리나무 밑에 장사하였고 그 이름을 알론바굿이라 불렀더라'),
(1021, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 9, 'OT', '야곱이 밧단아람에서 돌아올 때에 하나님이 다시 야곱에게 나타나 그에게 복을 주셨더라'),
(1022, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 10, 'OT', '하나님이 그에게 이르시되 네 이름이 야곱이로되 네 이름을 다시는 야곱이라 부르지 아니할 것이요 이스라엘이 네 이름이 되리라 하시고 그가 그의 이름을 이스라엘이라 부르니라'),
(1023, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 11, 'OT', '하나님이 그에게 이르시되 나는 전능한 하나님이라 생육하고 번성하라 한 민족과 민족들의 무리가 네게서 나며 왕들이 네 허리에서 나오리라'),
(1024, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 12, 'OT', '내가 아브라함과 이삭에게 준 땅을 네게 주리라, 네 뒤를 잇는 네 자손에게도 그 땅을 주리라.'),
(1025, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 13, 'OT', '하나님이 그와 말씀하신 그 곳에서 그를 떠나 올라가시니라.'),
(1026, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 14, 'OT', '야곱이 그와 말씀하신 곳에 돌 기둥을 세우고, 그 위에 전제를 붓고, 그 위에 기름을 부었더라.'),
(1027, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 15, 'OT', '야곱이 하나님께서 자기와 말씀하신 그 곳의 이름을 벧엘이라 불렀더라.'),
(1028, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 16, 'OT', '그들이 벧엘에서 떠났는데 에브랏에 이르기까지 얼마쯤 땅이 남았을 때에 라헬이 해산하게 되어 산고가 심하였더라'),
(1029, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 17, 'OT', '그녀가 해산할 때 진통이 심하였더니 산파가 그녀에게 이르되 두려워하지 말라 이번에도 네게 아들이 있느니라 하매'),
(1030, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 18, 'OT', '그의 혼이 떠나려 할 때에 그가 죽었으므로 그가 그의 이름을 베노니라 불렀으나 그의 아버지가 그를 베냐민이라 불렀더라'),
(1031, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 19, 'OT', '라헬이 죽어서 에브랏 곧 베들레헴 길에 장사되었더라.'),
(1032, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 20, 'OT', '야곱이 그녀의 무덤 위에 기둥을 세웠으니 그것이 라헬의 무덤 기둥이라 오늘까지 이르느니라.'),
(1033, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 21, 'OT', '이스라엘이 떠나서 에델 망대 너머에 장막을 쳤더라'),
(1034, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 22, 'OT', '이스라엘이 그 땅에 거주할 때에 르우벤이 가서 그의 아버지의 첩 빌하와 동침하였고 이스라엘이 그것을 들었더라. 야곱의 아들들은 열둘이었더라.'),
(1035, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 23, 'OT', '레아의 아들들은 야곱의 장자 르우벤과 시므온과 레위와 유다와 잇사갈과 스불론이더라'),
(1036, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 24, 'OT', '라헬의 아들들은 요셉과 베냐민이더라.'),
(1037, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 25, 'OT', '라헬의 여종 빌하의 아들들은 단과 납달리였더라.'),
(1038, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 26, 'OT', '레아의 여종 실바의 아들들은 갓과 아셀이며, 이들은 야곱이 밧단아람에서 그에게 태어난 아들들이다.'),
(1039, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 27, 'OT', '야곱이 그 아비 이삭에게 마므레, 곧 아르바 성읍으로 갔으니, 그것은 헤브론이며, 아브라함과 이삭이 거기서 거류하던 곳이더라.'),
(1040, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 28, 'OT', '이삭의 날들이 백 년과 팔십 년이었더라.'),
(1041, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 35, 29, 'OT', '이삭이 숨을 거두고 죽어 자기 백성에게로 돌아가니, 늙고 나이가 차서였으며, 그의 아들들 에서와 야곱이 그를 장사하였더라.'),
(1042, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 1, 'OT', '에서 곧 에돔의 족보는 이러하니라'),
(1043, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 2, 'OT', '에서가 가나안 여인들 중에서 아내들을 취하였으니, 헷 사람 엘론의 딸 아다와, 히위 사람 시브온의 딸 아나의 딸 오홀리바마라.'),
(1044, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 3, 'OT', '또한 느바욧의 누이인 이스마엘의 딸 바스맛을 취하였더라'),
(1045, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 4, 'OT', '아다는 에서에게 엘리바스를 낳았고, 바스맛은 르우엘을 낳았더라.'),
(1046, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 5, 'OT', '오홀리바마는 여우스와 얄람과 고라를 낳았으니, 이들은 에서의 아들들로서 가나안 땅에서 그에게 태어난 자들이라.'),
(1047, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 6, 'OT', '에서가 그의 아내들과 그의 아들들과 그의 딸들과 그의 집의 모든 사람들과 그의 가축과 그의 모든 짐승과 그가 가나안 땅에서 얻은 모든 소유를 취하고, 그의 형제 야곱의 얼굴을 피하여 다른 땅으로 갔더라.'),
(1048, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 7, 'OT', '그들의 재산이 많아 함께 거할 수 없었으며, 그들이 머물던 땅이 그들의 가축 때문에 그들을 감당할 수 없었더라.'),
(1049, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 8, 'OT', '에서가 세일 산에 거주하였으니, 에서는 곧 에돔이라.'),
(1050, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 9, 'OT', '에서 곧 에돔 족속의 조상의 족보는 이러하니 그가 세일 산에 거하였더라'),
(1051, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 10, 'OT', '에서의 아들들의 이름은 이러하니, 에서의 아내 아다의 아들 엘리바스와 에서의 아내 바스맛의 아들 르우엘이라.'),
(1052, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 11, 'OT', '엘리바스의 아들들은 데만과 오말과 스보와 가담과 그나스였더라'),
(1053, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 12, 'OT', '딤나는 에서의 아들 엘리바스의 첩이었으며, 그가 엘리바스에게 아말렉을 낳았으니, 이들은 에서의 아내 아다의 아들들이더라.'),
(1054, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 13, 'OT', '르우엘의 아들들은 나핫과 세라와 삼마와 미사니, 이들은 에서의 아내 바스맛의 아들들이었더라.'),
(1055, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 14, 'OT', '이들은 에서의 아내인 시브온의 딸 아나의 딸 오홀리바마의 아들들이니, 그가 에서에게 여우스와 얄람과 고라를 낳았더라.'),
(1056, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 15, 'OT', '에서의 아들들의 족장들은 이러하니라 에서의 장자 엘리바스의 아들들 중에 데만 족장, 오말 족장, 스보 족장, 그나스 족장이요'),
(1057, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 16, 'OT', '고라 족장, 가담 족장, 아말렉 족장이니 이들은 에돔 땅에 있는 엘리바스의 족장들이요 이들은 아다의 아들들이라'),
(1058, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 17, 'OT', '에서의 아들 르우엘의 아들들은 이러하니 나핫 족장, 세라 족장, 삼마 족장, 미사 족장이라 이들은 에돔 땅에 있는 르우엘의 족장들이요 이들은 에서의 아내 바스맛의 아들들이니라'),
(1059, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 18, 'OT', '에서의 아내 오홀리바마의 아들들은 이러하니, 여우스 족장, 얄람 족장, 고라 족장이라. 이들은 아나의 딸이요 에서의 아내인 오홀리바마의 족장들이라.'),
(1060, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 19, 'OT', '에서의 아들들은 이러하니 곧 그들의 족장들, 그는 에돔이라.'),
(1061, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 20, 'OT', '이들은 그 땅에 거주하던 호리 족속 세일의 아들들로서, 로단과 소발과 시브온과 아나이니라.'),
(1062, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 21, 'OT', '디손과 에셀과 디산이니, 이들은 에돔 땅에 있는 세일의 아들들인 호리 족속의 족장들이다.'),
(1063, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 22, 'OT', '로단의 아들들은 호리와 헤맘이었고, 로단의 누이는 딤나였다.'),
(1064, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 23, 'OT', '소발의 아들들은 알완과 마나핫과 에발과 스보와 오남이었더라.'),
(1065, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 24, 'OT', '시브온의 아들들은 아야와 아나요, 이 아나는 그 아비 시브온의 나귀를 먹일 때에 광야에서 하이밈을 발견한 아나였더라.'),
(1066, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 25, 'OT', '아나의 아들들은 디손과 아나의 딸 오홀리바마였더라'),
(1067, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 26, 'OT', '디손의 아들들은 헴단과 에스반과 이드란과 그란이더라'),
(1068, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 27, 'OT', '에셀의 아들들은 이러하니 빌한과 사아완과 아간이더라'),
(1069, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 28, 'OT', '디산의 아들들은 웃스와 아란이라'),
(1070, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 29, 'OT', '이들은 호리 족속의 족장들이니, 로단 족장, 소발 족장, 시브온 족장, 아나 족장이요,'),
(1071, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 30, 'OT', '족장 디손, 족장 에셀, 족장 디산이라 이들은 세일 땅에서 그 족장들에 따라 호리 족속의 족장들이니라'),
(1072, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 31, 'OT', '에돔 땅에서 다스린 왕들은 이러하니, 이스라엘 자손을 다스리는 왕이 있기 전이었더라.'),
(1073, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 32, 'OT', '브올의 아들 벨라가 에돔에서 왕이 되었고, 그의 성읍의 이름은 딘하바였더라.'),
(1074, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 33, 'OT', '벨라가 죽으매, 그를 대신하여 보스라 사람 세라의 아들 요밥이 왕이 되니라.'),
(1075, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 34, 'OT', '요밥이 죽으니, 데만 족속의 땅의 후삼이 그를 대신하여 왕이 되었더라.'),
(1076, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 35, 'OT', '후삼이 죽으매 브닷의 아들 하닷이 그를 대신하여 왕이 되었는데, 그가 모압 들에서 미디안을 쳤더라. 그의 성읍의 이름은 아윗이었더라.'),
(1077, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 36, 'OT', '하닷이 죽으매, 마스레가의 삼라가 그를 대신하여 왕이 되니라.'),
(1078, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 37, 'OT', '삼라가 죽고, 그를 대신하여 강가의 르호봇 출신 사울이 왕이 되니라.'),
(1079, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 38, 'OT', '사울이 죽고, 악볼의 아들 바알하난이 그를 대신하여 왕이 되니라.'),
(1080, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 39, 'OT', '악볼의 아들 바알하난이 죽으매, 하달이 그를 대신하여 왕이 되니, 그의 성읍의 이름은 바우며, 그의 아내의 이름은 므헤다벨이니, 마트렛의 딸이요, 메사합의 딸이더라.'),
(1081, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 40, 'OT', '에서의 족장들의 이름은 그들의 가족들과 그들의 거처들과 그들의 이름들대로 이러하니 딤나 족장, 알와 족장, 여뎃 족장'),
(1082, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 41, 'OT', '오홀리바마 족장, 엘라 족장, 비논 족장'),
(1083, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 42, 'OT', '그나스 족장, 데만 족장, 밉살 족장'),
(1084, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 36, 43, 'OT', '막디엘 족장, 이람 족장이라 이들은 그들의 거주지와 그들의 땅의 소유에 따른 에돔의 족장들이며 그는 에서요 에돔의 조상이더라'),
(1085, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 1, 'OT', '야곱이 그의 아버지가 나그네 되었던 땅, 곧 가나안 땅에 거주하였더라.'),
(1086, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 2, 'OT', '이것이 야곱의 족보이니라. 요셉이 십칠 세 소년으로서 그의 형제들과 함께 양을 치고 있었는데, 그 소년이 그의 아버지의 아내들인 빌하의 아들들과 실바의 아들들과 함께 있었더라. 요셉이 그들의 악한 소문을 그들의 아버지에게 가져왔더라.'),
(1087, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 3, 'OT', '이스라엘이 요셉을 그의 모든 아들들보다 더 사랑하였으니 이는 그가 그에게 노년의 아들이었음이라 그가 그를 위하여 채색 옷을 지었더라'),
(1088, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 4, 'OT', '그의 형들이 그들의 아버지가 그를 그의 모든 형들보다 사랑함을 보고 그를 미워하여 그와 화평하게 말할 수 없었더라'),
(1089, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 5, 'OT', '요셉이 꿈을 꾸고 그의 형들에게 말하니 그들이 그를 더욱 미워하게 되었더라'),
(1090, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 6, 'OT', '그가 그들에게 이르되, 청하건대 내가 꾼 이 꿈을 들으라.'),
(1091, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 7, 'OT', '보라, 우리가 밭 가운데에서 곡식 단들을 묶고 있었는데, 보라, 내 단이 일어섰고 또한 똑바로 섰으며, 보라, 당신들의 단들이 둘러서서 내 단에게 절하더이다.'),
(1092, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 8, 'OT', '그의 형들이 그에게 말하되, “네가 참으로 우리를 다스릴 왕이 되겠느냐? 네가 참으로 우리를 지배하겠느냐?” 하고 그들이 그의 꿈들과 그의 말들로 인하여 그를 더욱 미워하였더라.'),
(1093, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 9, 'OT', '그가 또 다른 꿈을 꾸고 그 형들에게 그것을 말하며 이르되, 보라, 내가 또 꿈을 꾸었는데, 보라, 해와 달과 열한 별이 내게 절하더라.'),
(1094, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 10, 'OT', '그가 아버지와 형제들에게 말하니, 그의 아버지가 그를 꾸짖으며 그에게 이르되, "네가 꾼 이 꿈이 무엇이냐, 나와 네 어머니와 네 형제들이 참으로 가서 땅에 엎드려 네게 절하겠느냐?"'),
(1095, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 11, 'OT', '그의 형들이 그를 시기하였으나 그의 아버지는 그 말을 마음에 두었더라.'),
(1096, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 12, 'OT', '그의 형들이 세겜에서 그들의 아버지의 양 떼를 먹이러 갔더라.'),
(1097, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 13, 'OT', '이스라엘이 요셉에게 이르되, 네 형들이 세겜에서 양을 치고 있지 아니하냐? 오라, 내가 너를 그들에게로 보내리라. 그가 그에게 이르되, 내가 여기 있나이다.'),
(1098, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 14, 'OT', '그가 그에게 이르되, "청하노니 가서 네 형들의 안부와 양 떼의 안부를 살피고 내게 말을 가져오라" 하고, 그를 헤브론 골짜기에서 보내매, 그가 세겜으로 갔더라.'),
(1099, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 15, 'OT', '어떤 사람이 그를 만났는데, 보라 그가 들에서 방황하고 있었다. 그 사람이 그에게 물어 이르되, 네가 무엇을 찾느냐?'),
(1100, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 16, 'OT', '그가 말하되 내가 내 형들을 찾고 있나이다 청하건대 그들이 양을 치는 곳을 내게 알려 주소서'),
(1101, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 17, 'OT', '그 사람이 말하되 그들이 여기서 떠났느니라 내가 그들의 말을 들으니 도단으로 가자 하더라 하니 요셉이 그의 형들 뒤를 따라가서 도단에서 그들을 만나니라'),
(1102, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 18, 'OT', '그들이 그를 멀리서 보고, 그가 그들에게 가까이 오기 전에 그를 죽이려고 음모를 꾸몄다.'),
(1103, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 19, 'OT', '그들이 서로 말하되, 보라, 이 꿈꾸는 자가 오는도다.'),
(1104, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 20, 'OT', '이제 오라, 우리가 그를 죽여 한 구덩이에 던지고 말하기를 악한 짐승이 그를 먹었다 하자, 우리가 그의 꿈들이 어떻게 될지 보리라.'),
(1105, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 21, 'OT', '르우벤이 듣고 그를 그들의 손에서 구원하여 이르되 우리가 그 생명을 치지 말자'),
(1106, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 22, 'OT', '르우벤이 그들에게 이르되, 피를 흘리지 말라. 그를 광야에 있는 이 구덩이에 던지고, 그에게 손을 대지 말라 하니, 이는 그가 그를 그들의 손에서 구원하여 그의 아버지에게로 돌려보내려 함이었더라.'),
(1107, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 23, 'OT', '요셉이 그의 형들에게 이르렀을 때에, 그들이 요셉의 옷 곧 그 위에 있던 채색 옷을 벗겼더라.'),
(1108, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 24, 'OT', '그들이 그를 붙잡아 구덩이에 던졌는데, 그 구덩이는 비어 있어 그 속에 물이 없었더라.'),
(1109, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 25, 'OT', '그들이 앉아 떡을 먹다가 눈을 들어 보니, 보라, 이스마엘 사람들의 대상이 길르앗에서 오고 있었고, 그들의 낙타들이 향품과 유향과 몰약을 싣고 애굽으로 내려가고 있었다.'),
(1110, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 26, 'OT', '유다가 그의 형제들에게 말하되, 우리가 우리 형제를 죽이고 그의 피를 덮은들 무슨 이익이 있으랴?'),
(1111, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 27, 'OT', '오라, 우리가 그를 이스마엘인에게 팔자, 그리고 우리 손이 그에게 미치지 말게 하자, 그는 우리의 형제요 우리의 살이니라. 그의 형제들이 들었더라.'),
(1112, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 28, 'OT', '그때에 미디안 상인들이 지나가더라 그들이 요셉을 구덩이에서 끌어올려 이스마엘 사람들에게 은 이십에 팔고 그들이 요셉을 애굽으로 데려가니라'),
(1113, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 29, 'OT', '르우벤이 구덩이로 돌아와 보니, 보라, 요셉이 구덩이에 없으므로 그의 옷을 찢으니라.'),
(1114, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 30, 'OT', '그가 형제들에게로 돌아와서 말하되, “아이가 없도다. 나는 내가 어디로 가랴?”'),
(1115, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 31, 'OT', '그들이 요셉의 옷을 취하고 염소 새끼를 죽여 그 옷을 피에 적셨더라'),
(1116, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 32, 'OT', '그들이 그 화려한 옷을 보내어 그들의 아버지에게로 가져와서 말하되, “우리가 이것을 찾았으니, 아버지의 아들의 옷인지 아닌지 이제 알아보소서.” 하였더라.'),
(1117, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 33, 'OT', '아비가 그것을 알아보고 이르되 내 아들의 옷이라 악한 짐승이 그를 먹었도다 요셉이 정녕 찢겼도다'),
(1118, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 34, 'OT', '야곱이 자기 옷을 찢고 굵은 베로 허리를 묶고 그의 아들을 위하여 여러 날 동안 애통하였더라.'),
(1119, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 35, 'OT', '그의 모든 아들들과 모든 딸들이 그를 위로하러 일어났으나 그가 위로받기를 거절하고 말하기를 “내가 슬퍼하며 스올에 내려 내 아들에게로 가리라” 하였고 그의 아버지가 그를 위하여 울었더라'),
(1120, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 37, 36, 'OT', '미디안 사람들이 그를 애굽으로 팔아 바로의 내시요 시위대장인 보디발에게 이르렀더라'),
(1121, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 1, 'OT', '그 때에 유다가 그의 형제들에게서 내려가 아둘람 사람 히라라는 이름의 사람에게로 향하니라'),
(1122, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 2, 'OT', '유다가 거기서 가나안 사람의 딸을 보았는데 그 이름은 수아였으며, 그가 그녀를 데려가 그녀에게 들어갔더라.'),
(1123, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 3, 'OT', '그가 잉태하여 아들을 낳으매 그가 그의 이름을 에르라 하니라'),
(1124, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 4, 'OT', '그가 다시 잉태하여 아들을 낳고 그 이름을 오난이라 하였더라'),
(1125, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 5, 'OT', '그가 또 다시 아들을 낳고 그의 이름을 셀라라 하였으며, 그가 그를 낳을 때에 그가 크십에 있었더라.'),
(1126, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 6, 'OT', '유다는 그의 장자 엘을 위하여 아내를 취하였으니 그 이름은 다말이었더라'),
(1127, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 7, 'OT', '유다의 장자 엘이 여호와의 눈에 악하였으므로 여호와께서 그를 죽이셨더라.'),
(1128, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 8, 'OT', '유다가 오난에게 이르되, 네 형의 아내에게 들어가서 그녀에게 시동생의 의무를 행하고 네 형을 위하여 씨를 세우라.'),
(1129, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 9, 'OT', '오난이 그 씨가 자기에게 있지 않을 줄 알았고, 그가 형의 아내에게 들어갔을 때에 형에게 씨를 주지 아니하려고 땅에 흘려버렸더라.'),
(1130, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 10, 'OT', '그가 행한 일이 여호와의 눈에 악하였으므로 여호와께서 그도 죽이셨더라.'),
(1131, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 11, 'OT', '유다가 그의 며느리 다말에게 이르되, 네 아버지의 집에서 과부로 지내되 내 아들 셀라가 장성할 때까지 기다리라 하였으니, 이는 그가 말하기를 그도 그의 형들처럼 죽을까 두려워함이었더라. 다말이 가서 그 아버지의 집에 거하니라.'),
(1132, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 12, 'OT', '세월이 지나서 유다의 아내 수아의 딸이 죽으니라. 유다가 위로를 받고 그의 친구 아둘람 사람 히라와 함께 자기 양 떼를 깎는 자들에게 딤나로 올라가니라.'),
(1133, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 13, 'OT', '다말에게 전갈이 이르되, 보라 네 시아버지가 자기 양을 깎으려고 딤나로 올라간다 하였더라.'),
(1134, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 14, 'OT', '그녀가 과부의 옷을 벗고 너울로 얼굴을 가리고 몸을 휩싼 후, 딤나 길 곁에 있는 에나임 어귀에 앉았으니, 이는 셀라가 장성함을 보았으나 그녀가 그의 아내로 주어지지 않았기 때문이었더라.'),
(1135, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 15, 'OT', '유다가 그녀를 보고 그를 창녀로 여겼으니, 이는 그녀가 얼굴을 가렸기 때문이었다.'),
(1136, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 16, 'OT', '그가 길가에서 그녀에게로 향하여 이르되 청하노니 내가 네게 들어가게 하라 하니 이는 그가 그녀가 자기 며느리인 줄 알지 못하였음이라 그녀가 이르되 당신이 내게 들어오려면 무엇을 내게 주겠느냐 하니'),
(1137, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 17, 'OT', '그가 말하기를, 내가 양 떼에서 염소 새끼를 보내리라. 그녀가 말하기를, 당신이 그것을 보낼 때까지 담보물을 주겠느냐?'),
(1138, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 18, 'OT', '그가 말하되 “내가 네게 무엇을 담보로 주랴?” 그녀가 말하되 “당신의 도장과 그 끈과 당신의 손에 있는 지팡이로 하라.” 그가 그것을 그녀에게 주고 그녀에게 들어갔더니 그녀가 그로 말미암아 잉태하였더라.'),
(1139, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 19, 'OT', '그가 일어나 떠나가서 그 너울을 벗고 과부의 옷을 입으니라'),
(1140, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 20, 'OT', '유다가 그 친구 아둘람 사람의 손으로 염소 새끼를 보내어 그 여인의 손에서 저당물을 받으려 하였으나 그가 그 여인을 찾지 못하였더라.'),
(1141, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 21, 'OT', '그가 그 곳 사람들에게 물어 이르되, 길 곁에 있는 에나임의 창녀가 어디 있느냐 하니, 그들이 이르되, 이 곳에는 창녀가 없었느니라.'),
(1142, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 22, 'OT', '그가 유다에게로 돌아와 말하기를 “내가 그녀를 찾지 못하였고, 그 곳 사람들도 말하기를 ‘이 곳에는 창녀가 없었다’ 하더라” 하였더라'),
(1143, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 23, 'OT', '유다가 말하되, 그가 그것을 가지게 하라, 우리가 수치를 당할까 두렵노라. 보라, 내가 이 염소 새끼를 보냈으나 너는 그를 찾지 못하였느니라.'),
(1144, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 24, 'OT', '약 석 달 후에 유다에게 알려지기를 “네 며느리 다말이 행음하였고, 보라 그가 행음함으로 임신하였느니라” 하니, 유다가 말하되 “그를 끌어내어 불사르라” 하였더라.'),
(1145, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 25, 'OT', '그 여인이 끌려 나갈 때에 그녀가 시아버지에게 사람을 보내어 이르되, 이 물건들의 주인으로 말미암아 내가 임신하였나이다, 또 이르되, 청하건대 이 도장과 끈과 지팡이가 누구의 것인지 분별하소서, 하였더라.'),
(1146, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 26, 'OT', '유다가 그것을 알아보고 말하기를 “그가 나보다 의롭도다. 이는 내가 그를 내 아들 셀라에게 주지 아니하였음이라” 하고 다시는 그를 알지 아니하였더라.'),
(1147, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 27, 'OT', '그녀가 해산할 때가 되었는데, 보라 그녀의 태에 쌍둥이가 있었더라.'),
(1148, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 28, 'OT', '그녀가 해산할 때에 손을 내밀었더니 산파가 그 손에 홍색 실을 매어 이르되, 이가 먼저 나온 자라 하였더라'),
(1149, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 29, 'OT', '그가 손을 거두었을 때에 그의 형제가 나왔고 그가 말하기를 “네가 어찌하여 터지고 나왔느냐, 이 터짐이 네게 있으리라” 하였으므로 그의 이름을 베레스라 불렀더라.'),
(1150, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 38, 30, 'OT', '그 후에 그의 형제가 나왔는데 그의 손에 붉은 실이 있었고, 그의 이름을 세라라 불렀더라.'),
(1151, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 1, 'OT', '요셉이 애굽으로 내려갔고, 바로의 내시요 시위대장인 애굽 사람 보디발이 그를 그리로 데려간 이스마엘 사람들의 손에서 그를 샀더라.'),
(1152, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 2, 'OT', '여호와께서 요셉과 함께 하셨고, 그는 형통한 사람이 되었으며, 그의 주인인 애굽 사람의 집에 있었다.'),
(1153, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 3, 'OT', '그의 주인이 여호와께서 그와 함께하심을 보았고, 그가 하는 모든 일을 여호와께서 그의 손에서 형통하게 하심을 보았더라.'),
(1154, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 4, 'OT', '요셉이 그의 눈에 은혜를 얻어 그를 섬기니 그가 그를 자기 집의 관리자로 삼고 그가 가진 모든 것을 그의 손에 맡겼더라'),
(1155, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 5, 'OT', '그가 그를 자기 집과 그 모든 소유물을 주관하게 한 때부터 여호와께서 요셉으로 말미암아 그 애굽 사람의 집에 복을 내리셨고, 여호와의 복이 그의 집과 밭에 있는 모든 소유에 있었더라.'),
(1156, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 6, 'OT', '그가 가진 모든 것을 요셉의 손에 맡겼고, 그가 먹는 빵 외에는 그와 함께 아는 것이 없었더라. 요셉은 용모가 아름답고 얼굴이 잘생겼더라.'),
(1157, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 7, 'OT', '이 일들 후에 그의 주인의 아내가 요셉에게 눈을 들어 이르되, 나와 함께 누우라 하니라'),
(1158, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 8, 'OT', '그가 거절하며 자기 주인의 아내에게 이르되, 보소서, 내 주인은 집에 있는 내게 있는 것을 알지 못하며, 그가 가진 모든 것을 내 손에 맡겼나이다'),
(1159, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 9, 'OT', '이 집에는 나보다 큰 이가 없으며 그가 내게 아무것도 숨기지 아니하였고 오직 너뿐이니 이는 네가 그의 아내임이라 그런즉 내가 어찌 이 큰 악을 행하여 하나님께 죄를 짓겠느냐?'),
(1160, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 10, 'OT', '그녀가 날마다 요셉에게 말하였으나 요셉이 그녀의 말을 듣지 아니하여 그녀 곁에 눕지도 아니하고 그녀와 함께 있지도 아니하니라'),
(1161, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 11, 'OT', '그 때에 요셉이 그 집에 들어가 그의 일을 하려 하였는데, 그 집 사람들 중에는 아무도 그 집에 있지 아니하였더라.'),
(1162, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 12, 'OT', '그 여인이 그의 옷을 붙잡아 이르되 나와 동침하자 하매 그가 자기 옷을 그녀의 손에 버리고 도망하여 밖으로 나가니라'),
(1163, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 13, 'OT', '그가 그가 그 옷을 자기 손에 버려두고 도망하여 밖으로 나간 것을 보았더라'),
(1164, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 14, 'OT', '그녀가 자기 집 사람들을 불러 그들에게 말하여 이르되, 보라, 그가 히브리 사람을 우리에게 데려와 우리를 희롱하게 하도다. 그가 나에게 와서 나와 동침하려 하므로 내가 큰 소리로 불렀노라.'),
(1165, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 15, 'OT', '그가 내가 소리를 높여 부르는 것을 듣고, 자기 옷을 내게 버려두고 도망하여 밖으로 나갔느니라.'),
(1166, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 16, 'OT', '그의 옷을 자기 곁에 두고 그의 주인이 집에 올 때까지 두었더라'),
(1167, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 17, 'OT', '그녀가 그에게 이 말들로 말하여 이르되, 당신이 우리에게 데려온 히브리 종이 나를 희롱하려고 내게로 들어왔나이다.'),
(1168, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 18, 'OT', '내가 소리를 높여 부르짖을 때에 그가 자기 옷을 내 곁에 버려두고 밖으로 도망하여 나갔나이다.'),
(1169, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 19, 'OT', '그의 주인이 자기 아내가 자기에게 말하여 이르기를, 당신의 종이 내게 이같이 행하였다 하는 그 말을 듣고, 그의 진노가 타올랐더라.'),
(1170, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 20, 'OT', '요셉의 주인이 그를 붙잡아 옥에 넣으니, 그곳은 왕의 죄수들이 갇혀 있는 곳이었더라. 그가 거기 옥에 있었더라.'),
(1171, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 21, 'OT', '여호와께서 요셉과 함께 하셨고 그에게 은혜를 베푸사 옥중 관리인의 눈에 그를 은혜롭게 하셨더라'),
(1172, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 22, 'OT', '전옥이 옥중에 있는 모든 죄수들을 요셉의 손에 맡기고, 그들이 그곳에서 하는 모든 일을 그가 행하였더라.'),
(1173, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 39, 23, 'OT', '전옥의 우두머리는 그의 손에 있는 모든 것을 살피지 아니하였으니 이는 여호와께서 그와 함께 하셨음이라 그가 행하는 모든 것을 여호와께서 형통하게 하셨더라'),
(1174, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 1, 'OT', '이 일들 후에 애굽 왕의 술 맡은 자와 떡 굽는 자가 그들의 주인 애굽 왕에게 범죄하였더라.'),
(1175, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 2, 'OT', '바로가 그의 두 관원장, 곧 술 맡은 관원장과 떡 굽는 관원장에게 노하니라'),
(1176, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 3, 'OT', '그들을 시위대장의 집 안에 있는 옥에 가두었으니, 곧 요셉이 갇혀 있던 그 곳이더라.'),
(1177, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 4, 'OT', '시위대장이 요셉을 그들과 함께 있게 하여 그를 섬기게 하였고, 그들이 감옥에 있던 날이 며칠이었다.'),
(1178, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 5, 'OT', '애굽 왕의 술 맡은 자와 떡 굽는 자, 곧 옥에 갇혀 있던 그 두 사람이 한 밤에 각각 꿈을 꾸었는데, 각 사람의 꿈은 그 해몽이 각기 달랐더라.'),
(1179, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 6, 'OT', '아침에 요셉이 그들에게 들어가서 그들을 보니, 보라 그들이 근심하고 있더라.'),
(1180, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 7, 'OT', '그가 자기 주인의 집에 자기와 함께 갇혀 있는 바로의 내시들에게 물어 이르되, 어찌하여 오늘 너희 얼굴에 근심이 있느냐?'),
(1181, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 8, 'OT', '그들이 그에게 말하되, “우리가 꿈을 꾸었으나 그것을 해석할 자가 없나이다.” 요셉이 그들에게 말하되, “해석은 하나님께 있지 아니하나이까? 청하건대 내게 고하소서.”'),
(1182, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 9, 'OT', '술 맡은 관원장이 그 꿈을 요셉에게 말하며 그에게 이르되, 내 꿈에 보라, 내 앞에 포도나무가 있더라'),
(1183, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 10, 'OT', '그 포도나무에 세 가지가 있었는데, 그것이 싹이 나서 꽃이 피고 그 송이들이 익어 포도가 되었더라'),
(1184, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 11, 'OT', '내 손에 바로의 잔이 있었고, 내가 포도들을 취하여 바로의 잔에 그것들을 짜서, 그 잔을 바로의 손바닥에 드렸노라.'),
(1185, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 12, 'OT', '요셉이 그에게 이르되 이것이 그 해석이니 세 가지 덩굴 가지는 사흘이라'),
(1186, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 13, 'OT', '아직 사흘이 지나기 전에 바로가 네 머리를 들고 너를 네 자리에 회복시키리니 네가 이전에 그의 술 맡은 자였을 때의 관례대로 바로의 잔을 그의 손에 건네주게 될 것이다.'),
(1187, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 14, 'OT', '오직 당신이 형통할 때에 나를 기억하고 내게 은혜를 베풀어 주소서, 그리고 나를 바로에게 알리고 이 집에서 나를 건져내소서.'),
(1188, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 15, 'OT', '나는 히브리 땅에서 도둑맞아 끌려왔사오며, 또한 여기서도 아무것도 행하지 아니하였사온데 그들이 나를 옥에 가두었나이다.'),
(1189, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 16, 'OT', '떡 굽는 관원장이 그 해석이 좋은 것을 보고 요셉에게 이르되, 나도 내 꿈에 보니, 보라, 흰 떡 세 광주리가 내 머리 위에 있더이다.'),
(1190, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 17, 'OT', '맨 위 광주리에는 바로를 위한 온갖 구운 음식이 있었는데, 새들이 내 머리 위 광주리에서 그것들을 먹었습니다.'),
(1191, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 18, 'OT', '요셉이 대답하여 이르되, 이것이 그 해석이니, 세 광주리는 사흘이니라.'),
(1192, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 19, 'OT', '아직 사흘이 지나기 전에 바로가 네 머리를 네게서 들어 올려 나무에 매달리게 할 것이며, 새들이 네 살을 네게서 먹으리라.'),
(1193, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 20, 'OT', '제삼일에 바로의 생일이 되어 그가 모든 신하를 위하여 잔치를 베풀었고, 그가 술 맡은 관원장의 머리와 떡 굽는 관원장의 머리를 그의 신하들 가운데서 들게 하였더라.'),
(1194, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 21, 'OT', '술 맡은 관원장을 그의 직무에 복귀시키고, 그가 잔을 바로의 손에 주었더라.'),
(1195, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 22, 'OT', '그러나 떡 굽는 관원장은 매달렸으니, 요셉이 그들에게 해석한 대로 되었더라.'),
(1196, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 40, 23, 'OT', '술 맡은 관원장이 요셉을 기억하지 아니하고 그를 잊었더라'),
(1197, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 1, 'OT', '이년이 끝난 후에 바로가 꿈을 꾸었는데, 보라, 그가 나일 강가에 서 있었더라.'),
(1198, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 2, 'OT', '보라, 강에서 아름다운 모습에 살진 일곱 암소가 올라와 갈대밭에서 뜯어먹더라'),
(1199, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 3, 'OT', '그 후에 또 모습이 흉하고 살이 파리한 다른 일곱 암소가 강에서 올라와 그 암소들 곁 강가에 섰더라'),
(1200, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 4, 'OT', '흉악하고 파리한 모습의 소들이 그 아름답고 살진 일곱 소를 먹었더라. 바로가 깨어났더라.'),
(1201, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 5, 'OT', '그가 다시 잠들어 두 번째 꿈을 꾸었는데, 보라, 한 줄기에 무성하고 좋은 일곱 이삭이 올라오더라'),
(1202, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 6, 'OT', '보라, 그 후에 동풍에 마르고 가는 일곱 이삭이 나오더라'),
(1203, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 7, 'OT', '야위고 가는 일곱 이삭이 무성하고 충실한 일곱 이삭을 삼켰더라. 바로가 깨어 보니 그것은 꿈이었더라.'),
(1204, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 8, 'OT', '아침에 그의 영이 번민하여 보내어 애굽의 모든 술객과 그 모든 지혜 있는 자들을 불렀고, 바로가 그들에게 그의 꿈을 말하였으나 그것을 바로에게 해석할 자가 없었더라.'),
(1205, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 9, 'OT', '술 맡은 관원장이 바로에게 말하여 이르되, 내가 오늘 나의 허물을 기억하나이다'),
(1206, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 10, 'OT', '바로가 그의 신하들에게 노하여 나를 시위대장의 집에 있는 감옥에 가두었는데, 나와 떡 굽는 관원장을 가두었더라.'),
(1207, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 11, 'OT', '나와 그가 하룻밤에 꿈을 꾸었는데, 우리 각자는 자기 꿈의 해석대로 꿈을 꾸었습니다.'),
(1208, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 12, 'OT', '그 곳에 우리와 함께 히브리 소년 하나가 있었는데, 그는 시위대장의 종이었습니다. 우리가 그에게 말하매 그가 우리의 꿈을 풀되, 각 사람이 꿈대로 해석하였습니다.'),
(1209, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 13, 'OT', '그가 우리에게 해석한 대로 그렇게 되었나이다. 나는 내 직분으로 회복되었고 그는 매달렸나이다.'),
(1210, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 14, 'OT', '바로가 사람을 보내어 요셉을 부르매 그들이 그를 급히 구덩이에서 끌어내니 그가 수염을 깎고 옷을 갈아입고 바로에게로 들어가니라'),
(1211, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 15, 'OT', '바로가 요셉에게 말하되, 내가 꿈을 꾸었으나 그것을 해석할 자가 없도다. 내가 너에 대하여 들으니, 네가 꿈을 들으면 그것을 해석할 수 있다 하더라.'),
(1212, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 16, 'OT', '요셉이 바로에게 대답하여 이르되, 내게는 그것이 없나이다. 하나님이 바로에게 평안한 대답을 주시리이다.'),
(1213, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 17, 'OT', '바로가 요셉에게 말하되, 내 꿈에 보라, 내가 나일 강가에 서 있었노라.'),
(1214, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 18, 'OT', '보라, 살이 찌고 아름다운 일곱 암소가 강에서 올라와 갈대밭에서 뜯어 먹고 있더라.'),
(1215, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 19, 'OT', '그런데 보라, 그들 뒤에 또 다른 일곱 암소가 올라오는데, 심히 흉악하고 파리하며 살이 빠진 것들이라. 내가 애굽 온 땅에서 그처럼 흉악한 것은 보지 못하였느니라.'),
(1216, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 20, 'OT', '파리하고 흉악한 소들이 처음의 일곱 살진 소들을 먹었더라'),
(1217, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 21, 'OT', '그들이 그것들을 삼켰으나 그것들을 삼켰는지 알 수 없었고 그들의 모양이 처음과 같이 흉악하였더라 내가 곧 깨어났느니라'),
(1218, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 22, 'OT', '내가 꿈에 보니, 보라, 한 줄기에 가득하고 좋은 일곱 이삭이 올라오더라.'),
(1219, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 23, 'OT', '보라, 동풍에 마르고 얇고 쇠약한 일곱 이삭이 그들 뒤에 자라났더라'),
(1220, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 24, 'OT', '가느다란 이삭들이 좋은 일곱 이삭을 삼켰고, 내가 그 술객들에게 말하였으나 그것을 내게 알려 줄 자가 없었느니라.'),
(1221, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 25, 'OT', '요셉이 바로에게 말하되, 바로의 꿈은 하나이니, 하나님이 행하시는 것을 바로에게 알리셨나이다.'),
(1222, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 26, 'OT', '일곱 좋은 암소는 일곱 해요, 일곱 좋은 이삭도 일곱 해니, 그 꿈은 하나이니라.'),
(1223, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 27, 'OT', '그 후에 올라온 야위고 흉악한 일곱 암소는 칠 년이요, 동풍에 말라 속이 빈 일곱 이삭도 일곱 해 흉년이니라'),
(1224, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 28, 'OT', '이것이 내가 바로에게 말한 그 말이니, 하나님이 행하시는 것을 바로에게 보이신 것이니라.'),
(1225, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 29, 'OT', '보라, 애굽 온 땅에 큰 풍년의 일곱 해가 오리라.'),
(1226, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 30, 'OT', '그 후에 일곱 해의 흉년이 그들을 뒤따라 일어나리니, 애굽 땅의 모든 풍년이 잊혀지고, 그 흉년이 그 땅을 소멸하리라.'),
(1227, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 31, 'OT', '그 후에 오는 흉년이 매우 심하므로 그 땅에서 이전의 풍년을 기억하지 못하리이다.'),
(1228, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 32, 'OT', '꿈이 바로에게 두 번 겹쳐진 것은 이 일이 하나님께로부터 정해졌음이며, 하나님이 그것을 속히 행하실 것임이니라.'),
(1229, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 33, 'OT', '이제 바로는 명철하고 지혜 있는 사람을 찾아서 애굽 땅 위에 세우게 하소서.'),
(1230, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 34, 'OT', '바로가 이같이 행하여 그 땅 위에 관리들을 임명하고, 일곱 풍년의 해에 애굽 땅의 오분의 일을 거두게 하소서.'),
(1231, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 35, 'OT', '그들이 장차 올 좋은 해들의 모든 양식을 거두고, 그 곡식을 바로의 손 아래에 쌓아 두며, 성읍들에 양식을 지키게 하라.'),
(1232, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 36, 'OT', '그 음식은 애굽 땅에 있을 일곱 해 흉년을 위하여 그 땅의 저장물이 될 것이요, 그 땅이 흉년으로 멸망하지 아니하리라.'),
(1233, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 37, 'OT', '바로의 눈과 그의 모든 신하들의 눈에 그 일이 좋게 보였더라.'),
(1234, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 38, 'OT', '바로가 그의 신하들에게 이르되, 이와 같은 사람, 곧 하나님의 영이 그 안에 있는 사람을 우리가 어찌 찾을 수 있으랴?'),
(1235, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 39, 'OT', '바로가 요셉에게 이르되, 하나님이 네게 이 모든 것을 알게 하셨은즉 너와 같이 명철하고 지혜 있는 자가 없도다'),
(1236, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 40, 'OT', '너는 내 집 위에 있게 될 것이요, 네 입으로 말미암아 내 모든 백성이 복종하리니, 다만 보좌에 있어서만 내가 너보다 크리라.'),
(1237, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 41, 'OT', '바로가 요셉에게 이르되, 보라, 내가 너를 애굽 온 땅 위에 세웠노라.'),
(1238, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 42, 'OT', '바로가 그의 손에서 인장 반지를 빼어 요셉의 손에 끼우고, 그에게 세마포 옷을 입히며, 금사슬을 그의 목에 두르니라.'),
(1239, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 43, 'OT', '그가 그를 자기에게 있는 둘째 수레에 태우고, 그들 앞에서 “엎드리라” 하고 외치게 하였으며, 그를 온 애굽 땅 위에 세웠더라.'),
(1240, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 44, 'OT', '바로가 요셉에게 이르되, 내가 바로라, 네가 없이는 애굽 온 땅에서 아무도 자기 손과 발을 들지 못하리라.'),
(1241, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 45, 'OT', '바로가 요셉의 이름을 사브낫바네아라 부르고, 또 온 제사장 보디베라의 딸 아스낫을 그에게 주어 아내를 삼게 하였으며, 요셉이 애굽 땅 위로 나아가니라.'),
(1242, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 46, 'OT', '요셉이 애굽 왕 바로 앞에 설 때에 삼십 세였으며, 요셉이 바로 앞에서 나가 애굽 온 땅을 두루 다녔더라.'),
(1243, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 47, 'OT', '일곱 해의 풍년 동안에 땅이 소출을 한 움큼씩 내었더라'),
(1244, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 48, 'OT', '그가 애굽 땅에 있던 그 칠 년의 모든 양식을 모아 각 성에 양식을 쌓아 두되, 각 성 주위에 있는 밭의 양식을 그 성 안에 두었더라'),
(1245, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 49, 'OT', '요셉이 곡식을 바다의 모래같이 심히 많이 쌓았으니, 그 수가 없어 세기를 그쳤더라.'),
(1246, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 50, 'OT', '흉년이 이르기 전에 요셉에게 두 아들이 태어났으니, 곧 온의 제사장 보디베라의 딸 아스낫이 그에게 낳은 자들이더라.'),
(1247, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 51, 'OT', '요셉이 그 장자의 이름을 므낫세라 하였으니 이는 하나님이 나의 모든 수고와 내 아버지의 온 집을 잊게 하셨음이라'),
(1248, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 52, 'OT', '둘째의 이름은 에브라임이라 불렀으니, 이는 하나님이 나를 내 고난의 땅에서 번성하게 하셨음이로다.'),
(1249, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 53, 'OT', '애굽 땅에 있던 일곱 해의 풍년이 끝났더라'),
(1250, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 54, 'OT', '칠 년의 흉년이 오기 시작하니 요셉이 말한 대로라 모든 땅에 기근이 있었으나 애굽 온 땅에는 양식이 있었더라'),
(1251, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 55, 'OT', '애굽 온 땅이 주리매 백성이 바로에게 부르짖어 양식을 구하니 바로가 모든 애굽 사람에게 이르되 요셉에게 가서 그가 너희에게 말하는 대로 행하라 하였더라'),
(1252, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 56, 'OT', '그 땅의 온 지면에 기근이 있었고, 요셉이 그들 가운데 있는 모든 곳간을 열어 애굽 사람들에게 팔았더니, 애굽 땅에 기근이 심해졌더라.'),
(1253, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 41, 57, 'OT', '온 땅의 모든 사람들이 곡식을 사려고 애굽으로 와서 요셉에게 이르렀으니, 이는 기근이 온 땅에 심하였음이었더라.'),
(1254, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 1, 'OT', '야곱이 애굽에 곡식이 있음을 보고 아들들에게 이르되 너희가 어찌하여 서로 바라보고만 있느냐'),
(1255, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 2, 'OT', '그가 이르되, 보라, 내가 들었으니 애굽에 곡식이 있다 하니 너희는 그리로 내려가서 거기서 우리를 위하여 사오라, 그리하면 우리가 살고 죽지 아니하리라.'),
(1256, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 3, 'OT', '요셉의 형들 열 명이 애굽에서 곡식을 사려고 내려갔더라.'),
(1257, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 4, 'OT', '야곱이 요셉의 형제 베냐민을 그의 형들과 함께 보내지 아니하였으니 이는 그가 말하기를 재난이 그에게 미칠까 두려워함이었더라'),
(1258, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 5, 'OT', '이스라엘의 아들들이 양식을 사러 온 자들 가운데 섞여 들어왔으니, 이는 가나안 땅에 기근이 있었기 때문이었더라.'),
(1259, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 6, 'OT', '요셉은 그 땅을 다스리는 자요 그 땅의 모든 백성에게 곡식을 파는 자라 요셉의 형들이 와서 그에게 얼굴을 땅에 대고 절하니라'),
(1260, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 7, 'OT', '요셉이 그의 형들을 보고 그들을 알아보았으나, 그들에게 모르는 체하고 그들에게 엄한 말로 말하며 그들에게 이르되 "너희가 어디서 왔느냐?" 하니 그들이 이르되 "곡식을 사려고 가나안 땅에서 왔나이다" 하였더라.'),
(1261, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 8, 'OT', '요셉이 그의 형들을 알아보았으나 그들은 그를 알지 못하더라.'),
(1262, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 9, 'OT', '요셉이 그들에게 꾼 꿈들을 기억하고 그들에게 말하되, 너희는 정탐꾼들이라, 이 땅의 벌거벗음을 보려고 왔느니라.'),
(1263, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 10, 'OT', '그들이 그에게 말하되, “아니요, 내 주여, 당신의 종들은 곡식을 사러 왔나이다.”'),
(1264, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 11, 'OT', '우리는 다 한 사람의 아들들이니 우리는 진실한 자들이요 당신의 종들은 정탐꾼이 아니니이다'),
(1265, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 12, 'OT', '그가 그들에게 말하되, “아니라, 너희는 이 땅의 벌거벗음을 보러 왔느니라.”'),
(1266, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 13, 'OT', '그들이 말하되, 당신의 종들인 우리는 열두 형제로서 가나안 땅에서 한 사람의 아들들이니이다. 보소서, 막내는 오늘 우리 아버지와 함께 있고, 하나는 없어졌나이다.'),
(1267, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 14, 'OT', '요셉이 그들에게 이르되, "내가 너희에게 말하여 이르기를 너희는 정탐꾼들이라 한 것이 이것이니라."'),
(1268, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 15, 'OT', '너희는 이같이 시험을 받으리라 바로의 생명으로 맹세하노니 너희 작은 아우가 여기 오지 아니하면 너희가 결코 여기서 나가지 못하리라'),
(1269, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 16, 'OT', '너희 중에서 한 사람을 보내어 너희 형제를 데려오게 하고, 너희는 갇혀 있으라. 그리하여 너희 말이 시험을 받아 너희에게 진실이 있는지 알게 하리라. 만일 그렇지 아니하면, 바로의 생명으로 맹세하노니 너희는 정탐꾼이니라.'),
(1270, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 17, 'OT', '그들을 다 함께 삼 일 동안 가두었더라'),
(1271, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 18, 'OT', '사흘째 되는 날에 요셉이 그들에게 이르되, 너희는 이렇게 하여 살지니, 나는 하나님을 두려워하노라.'),
(1272, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 19, 'OT', '너희가 진실한 자들이면 너희 형제 중 한 사람이 너희 감옥에 갇히게 하고, 너희는 가서 너희 집들의 기근을 위한 곡식을 가져오라.'),
(1273, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 20, 'OT', '너희 작은 아우를 내게로 데려오라 그리하면 너희 말이 믿음직하게 되고 너희가 죽지 아니하리라 하매 그들이 그대로 행하니라'),
(1274, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 21, 'OT', '그들이 서로 말하되, 우리가 참으로 우리 형제에 대하여 죄가 있도다. 우리가 그가 우리에게 간청할 때에 그의 영혼의 괴로움을 보았으나 듣지 아니하였으니, 그러므로 이 괴로움이 우리에게 임하였도다.'),
(1275, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 22, 'OT', '르우벤이 그들에게 대답하여 이르되, 내가 너희에게 말하여 이르기를, 그 아이에게 죄를 짓지 말라고 하지 아니하였느냐? 그러나 너희가 듣지 아니하였도다. 또한 보라, 그의 피가 찾아지리라.'),
(1276, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 23, 'OT', '그들은 요셉이 듣는 줄을 알지 못하였으니 이는 그들 사이에 통역자가 있었기 때문이었더라'),
(1277, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 24, 'OT', '그가 그들에게서 돌아서서 울고, 다시 그들에게 돌아와 그들과 말하며, 그들 가운데서 시므온을 데려다가 그들의 눈앞에서 그를 결박하니라.'),
(1278, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 25, 'OT', '요셉이 명하여 그들의 그릇에 곡식을 채우게 하고 각 사람의 돈을 그의 자루에 도로 넣게 하며 그들에게 길 양식을 주게 하였더니 그대로 그들에게 행하였더라'),
(1279, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 26, 'OT', '그들이 그들의 곡식을 나귀들에게 싣고 그 곳에서 떠났더라'),
(1280, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 27, 'OT', '한 사람이 여관에서 자기 나귀에게 사료를 주려고 자기 자루를 열었는데, 자기 돈을 보니, 보라, 그것이 그의 자루 아귀에 있더라.'),
(1281, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 28, 'OT', '그가 그의 형제들에게 말하되 “내 돈이 돌아왔고, 보라, 내 자루 속에도 있도다” 하니 그들의 마음이 나갔고 그들이 서로에게 떨며 말하되 “하나님이 우리에게 행하신 이것이 무엇이냐” 하였더라'),
(1282, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 29, 'OT', '그들이 가나안 땅에 있는 그들의 아버지 야곱에게 이르렀고, 그들에게 일어난 모든 일을 그에게 말하여 이르되'),
(1283, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 30, 'OT', '그 땅의 주인이신 그 사람이 우리에게 엄하게 말하고 우리를 그 땅을 정탐하는 자로 여겼습니다.'),
(1284, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 31, 'OT', '우리가 그에게 말하기를 우리는 진실한 자들이요, 우리는 정탐꾼이 아니었나이다'),
(1285, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 32, 'OT', '우리는 열두 형제로 아버지의 아들들이요, 하나는 없고, 막내는 오늘 우리 아버지와 함께 가나안 땅에 있나이다.'),
(1286, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 33, 'OT', '그 땅의 주인인 그 사람이 우리에게 이르되, 내가 이것으로 너희가 진실한 자임을 알리니, 너희 형제 중 하나를 내게 남겨 두고, 너희 집들의 주림을 위한 양식을 가지고 가라.'),
(1287, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 34, 'OT', '너희 작은 아우를 내게로 데려오라 그리하면 너희가 정탐꾼이 아니요 진실한 자임을 내가 알리라 내가 너희 아우를 너희에게 주리니 너희가 그 땅에서 무역하리라'),
(1288, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 35, 'OT', '그들이 자루를 비울 때에, 보라, 각 사람의 돈 뭉치가 그의 자루 속에 있었더라. 그들과 그들의 아버지가 그들의 돈 뭉치들을 보고 두려워하였더라.'),
(1289, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 36, 'OT', '그들의 아버지 야곱이 그들에게 이르되 너희가 나를 자식들을 잃게 하였도다 요셉도 없고 시므온도 없거늘 너희가 베냐민을 데려가려 하니 이 모든 일이 나를 해롭게 하는도다'),
(1290, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 37, 'OT', '르우벤이 그의 아버지에게 말하여 이르되, 내가 그를 당신께로 데려오지 아니하거든 나의 두 아들을 죽이소서. 그를 내 손에 맡기소서. 내가 그를 당신께로 데리고 돌아오리이다.'),
(1291, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 42, 38, 'OT', '야곱이 말하되, “내 아들이 너희와 함께 내려가지 못하리니, 이는 그의 형이 죽었고 그가 홀로 남았음이라. 만일 너희가 가는 길에서 재난이 그에게 닥치면, 너희가 나의 백발을 슬픔으로 스올에 내려가게 하리라.”'),
(1292, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 1, 'OT', '그 땅에 기근이 심하였더라'),
(1293, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 2, 'OT', '그들이 애굽에서 가져온 곡식을 다 먹었을 때에, 그들의 아버지가 그들에게 이르되, "돌아가서 우리를 위하여 조금 양식을 사라."'),
(1294, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 3, 'OT', '유다가 그에게 말하여 이르되, 그 사람이 우리에게 엄히 증언하여 이르기를, 너희 아우가 너희와 함께 하지 아니하면 너희가 내 얼굴을 보지 못하리라 하였나이다'),
(1295, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 4, 'OT', '만일 당신이 우리 형제를 우리와 함께 보내시면, 우리가 내려가서 당신을 위해 양식을 사겠나이다.'),
(1296, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 5, 'OT', '만일 당신이 그를 보내지 않으시면 우리는 내려가지 아니하리니, 이는 그 사람이 우리에게 말하기를 너희 형제가 너희와 함께하지 아니하면 너희가 내 얼굴을 보지 못하리라 하였음이니이다.'),
(1297, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 6, 'OT', '이스라엘이 말하되, 너희가 어찌하여 그 사람에게 너희에게 아직 형제가 있다고 말하여 나를 해롭게 하였느냐?'),
(1298, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 7, 'OT', '그들이 말하되, “그 사람이 우리와 우리의 친족에 대하여 엄격히 물으며 말하기를 ‘너희 아버지가 아직 살아 있느냐? 너희에게 형제가 있느냐?’ 하기에 우리가 그 말대로 그에게 알렸나니, 그가 ‘너희 형제를 데리고 내려오라’ 할 줄을 우리가 어찌 알았겠느냐?”'),
(1299, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 8, 'OT', '유다가 그의 아버지 이스라엘에게 말하되, 그 아이를 나와 함께 보내소서, 우리가 일어나 가리이다, 그러면 우리가 살고 죽지 아니하리이다, 우리와 당신과 우리 어린 것들도 다 살리이다.'),
(1300, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 9, 'OT', '내가 그를 담보하리니, 내 손에서 그를 찾으소서. 만일 내가 그를 당신께 데려다가 당신 앞에 세우지 아니하면, 내가 당신께 항상 죄를 지리이다.'),
(1301, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 10, 'OT', '우리가 지체하지 아니하였더면 벌써 두 번 갔다 왔으리이다'),
(1302, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 11, 'OT', '그들의 아버지 이스라엘이 그들에게 이르되, 만일 그렇다면 이제 이렇게 하라. 너희는 이 땅의 아름다운 소산을 너희 그릇에 담아 그 사람에게 예물로 내려가라. 유향 조금과 꿀 조금과 향품과 몰약과 비자와 아몬드이니라.'),
(1303, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 12, 'OT', '너희 손에 갑절의 돈을 가지고, 너희 자루 아귀에 돌려진 그 돈도 너희 손에 도로 가져가라. 혹 그것이 실수였을까 하노라.'),
(1304, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 13, 'OT', '너희 형제도 데리고 일어나 그 사람에게로 돌아가라'),
(1305, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 14, 'OT', '전능하신 하나님이 그 사람 앞에서 너희에게 긍휼을 베푸사 너희 다른 형제와 베냐민을 너희에게 돌려보내게 하시기를 원하노라 내가 자식을 잃게 되면 잃으리로다'),
(1306, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 15, 'OT', '그 사람들이 그 예물을 취하고 갑절 돈을 그들의 손에 가지고 베냐민을 데리고 일어나 애굽으로 내려가 요셉 앞에 섰더라'),
(1307, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 16, 'OT', '요셉이 그들과 함께 베냐민을 보고 자기 집을 관리하는 자에게 이르되, 이 사람들을 집으로 데려오고 짐승을 잡아 준비하라, 이 사람들이 정오에 나와 함께 먹을 것이니라.'),
(1308, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 17, 'OT', '그 사람이 요셉이 말한 대로 행하여, 그 사람이 그 사람들을 요셉의 집으로 데려왔더라.'),
(1309, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 18, 'OT', '그 사람들이 요셉의 집으로 인도되매 두려워하여 이르되 전일에 우리 자루에 돌아있던 돈 때문에 우리가 끌려 들어옴이로다 이는 그가 우리를 공격하여 덮치고 우리를 종으로 삼고 우리의 나귀를 빼앗으려 함이로다'),
(1310, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 19, 'OT', '그들이 요셉의 집을 맡은 그 사람에게 가까이 나아가 그 집 문에서 그에게 말하니라'),
(1311, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 20, 'OT', '오라버니여, 우리가 처음에 정말로 양식을 사려고 내려왔나이다.'),
(1312, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 21, 'OT', '우리가 여관에 이르러 자루를 풀어보니, 보라 각 사람의 돈이 그 자루 아구에 있되 우리 돈이 본수대로 있었으므로 우리가 그것을 도로 손에 가지고 왔나이다.'),
(1313, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 22, 'OT', '우리가 양식을 사려고 다른 돈도 손에 가지고 내려왔나이다. 누가 우리 돈을 우리 자루에 넣었는지 우리가 알지 못하나이다.'),
(1314, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 23, 'OT', '그가 말하되 “너희에게 평강이 있으라, 두려워하지 말라. 너희 하나님과 너희 아버지의 하나님이 너희 자루에 보물을 주셨느니라. 너희 돈은 내게로 왔느니라.” 하고 그들에게 시므온을 데리고 나왔더라.'),
(1315, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 24, 'OT', '그 사람이 그 사람들을 요셉의 집으로 데려가고 물을 주어 그들의 발을 씻게 하며 그들의 나귀들에게 먹이를 주었더라.'),
(1316, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 25, 'OT', '그들이 요셉이 정오에 오기까지 예물을 준비하였으니, 이는 그들이 거기서 떡을 먹을 줄 들었음이라.'),
(1317, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 26, 'OT', '요셉이 집으로 오매 그들이 손에 가진 예물을 그에게 집으로 가져왔고 그에게 땅에 엎드려 절하니라'),
(1318, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 27, 'OT', '그가 그들에게 안부를 묻고 이르되, 너희가 말한 너희 아버지 그 노인이 평안하냐? 그가 아직 살아 있느냐?'),
(1319, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 28, 'OT', '그들이 말하되, “주의 종 우리 아버지께서 평안하시고 아직 살아 계십니다” 하고, 머리 숙여 경배하더라.'),
(1320, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 29, 'OT', '그가 눈을 들어 그의 어머니의 아들인 그의 동생 베냐민을 보고 말하였다. “이것이 너희가 내게 말한 너희의 작은 동생이냐?” 그리고 말하였다. “하나님이 네게 은혜를 베푸시기를 원하노라, 내 아들아.”'),
(1321, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 30, 'OT', '요셉이 급히 서둘렀으니 이는 그의 마음이 그의 형제를 향해 뜨거워졌음이라 그가 울려고 찾아 안방으로 들어가서 거기서 울었더라'),
(1322, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 31, 'OT', '그가 얼굴을 씻고 나와서 자신을 억제하며 이르되, 음식을 차리라 하니라.'),
(1323, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 32, 'OT', '그들이 그를 위하여 따로 차리고 그들을 위하여 따로 차리며 그와 함께 먹는 애굽 사람들에게도 따로 차렸으니, 이는 애굽 사람들이 히브리 사람들과 함께 빵을 먹을 수 없었기 때문이라, 그것이 애굽 사람들에게 가증한 일이었음이라.'),
(1324, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 33, 'OT', '그들이 그의 앞에 앉되, 장자는 그의 장자됨대로, 작은 자는 그의 작음대로 앉았더라. 그 사람들이 서로 이상히 여기며 놀라더라.'),
(1325, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 43, 34, 'OT', '그가 자기 앞에서 그들에게 음식을 나누어 주되 베냐민의 몫은 그들 모두의 몫보다 다섯 배나 많았고, 그들이 그와 함께 마시며 즐거워하였더라.'),
(1326, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 1, 'OT', '그가 자기 집 청지기에게 명령하여 이르되, 사람들의 자루에 그들이 실을 수 있을 만큼 양식을 채우고 각 사람의 돈을 그의 자루 아귀에 넣으라.'),
(1327, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 2, 'OT', '또한 내 잔, 곧 은잔을 가장 어린 자의 자루 아귀에 넣고 그의 곡식 값 돈도 넣으라 하매 그가 요셉이 말한 대로 행하였더라'),
(1328, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 3, 'OT', '아침이 밝았을 때, 그 사람들과 그들의 나귀들이 보내졌더라.'),
(1329, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 4, 'OT', '그들이 성에서 나가 아직 멀리 가지 아니하였을 때에 요셉이 자기 집을 맡은 자에게 이르되 일어나 그 사람들의 뒤를 따라가서 그들을 미칠 때에 그들에게 말하기를 어찌하여 너희가 선을 악으로 갚았느냐'),
(1330, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 5, 'OT', '이것은 내 주인이 마시는 잔이 아니며, 그가 그것으로 점을 치는 것이 아니냐? 너희가 행한 일이 악하도다.'),
(1331, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 6, 'OT', '그가 그들을 따라잡아 그들에게 이 말들을 전하니라.'),
(1332, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 7, 'OT', '그들이 그에게 말하되, “내 주여, 어찌하여 이런 말씀을 하시나이까? 당신의 종들이 이런 일을 행하는 것은 결코 있을 수 없나이다.”'),
(1333, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 8, 'OT', '보라, 우리가 가나안 땅에서 우리 자루 아귀에서 찾은 돈을 당신에게로 도로 가져왔거늘, 어찌 우리가 당신 주인의 집에서 은이나 금을 도둑질하겠나이까?'),
(1334, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 9, 'OT', '당신의 종들 중 누구에게서 그것이 발견되든지 그는 죽을 것이요, 우리도 우리 주의 종이 되리이다.'),
(1335, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 10, 'OT', '그가 말하되, 이제 너희 말대로 그렇게 하리라. 그와 함께 있는 자가 발견되면 그는 내 종이 될 것이요, 너희는 무죄하리라.'),
(1336, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 11, 'OT', '그들이 급히 각각 자기 자루를 땅에 내려 놓고 각각 자기 자루를 열었다.'),
(1337, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 12, 'OT', '그가 큰 자에게서부터 수색하기 시작하여 작은 자에게서 마치매, 잔이 베냐민의 자루에서 발견되었더라.'),
(1338, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 13, 'OT', '그들이 옷을 찢고 각자 자기 나귀에 짐을 싣고 성으로 돌아오니라'),
(1339, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 14, 'OT', '유다와 그의 형제들이 요셉의 집에 이르렀는데 그가 아직 거기 있었고 그들이 그의 앞 땅에 엎드렸더라'),
(1340, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 15, 'OT', '요셉이 그들에게 이르되, 너희가 행한 이 일이 무엇이냐? 나와 같은 사람이 점을 칠 줄을 너희가 알지 못하느냐?'),
(1341, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 16, 'OT', '유다가 말하되, “내 주께 무엇이라 말하리이까? 무엇이라 말하며 어떻게 우리가 의롭다 함을 얻으리이까? 하나님이 주의 종들의 죄악을 찾아내셨나이다. 보소서, 우리와 그 잔이 그의 손에서 발견된 자도 다 내 주의 종이 되겠나이다.”'),
(1342, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 17, 'OT', '그가 말하되, 내가 결코 그런 일을 하지 아니하리라. 그 잔이 그의 손에서 발견된 사람, 그가 내 종이 될 것이요, 너희는 평안히 너희 아버지께로 올라갈지니라.'),
(1343, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 18, 'OT', '유다가 그에게 가까이 나아가 말하되, 내 주여, 청하건대 주의 종이 주의 귀에 한 말씀을 말하게 하소서, 주의 종에게 주의 진노가 타오르지 않게 하소서, 주는 바로와 같으심이니이다.'),
(1344, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 19, 'OT', '내 주께서 그의 종들에게 물어 이르시되 너희에게 아버지가 있느냐, 형제가 있느냐 하셨나이다'),
(1345, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 20, 'OT', '우리가 내 주께 말하기를 우리에게 아버지가 있으니 늙은 이요, 또 그의 노년의 아들, 어린 자가 있는데 그의 형은 죽었고 그는 그의 어머니에게 홀로 남았으므로 그의 아버지가 그를 사랑하나이다 하였나이다'),
(1346, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 21, 'OT', '당신이 당신의 종들에게 말하기를, 그를 내게로 데리고 내려오라, 내가 그를 눈여겨보게 하려 함이라 하였나이다.'),
(1347, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 22, 'OT', '우리가 내 주께 말씀드리기를, 그 아이는 그의 아버지를 떠날 수 없나이다. 만일 그가 그의 아버지를 떠나면, 그의 아버지가 죽을 것이기 때문이니이다.'),
(1348, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 23, 'OT', '당신이 당신의 종들에게 말하기를 너희 작은 아우가 너희와 함께 내려오지 아니하면 너희가 다시 내 얼굴을 보지 못하리라 하였나이다'),
(1349, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 24, 'OT', '우리가 주의 종 우리 아버지에게로 올라갔을 때에, 우리가 내 주의 말씀을 그에게 전하였나이다.'),
(1350, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 25, 'OT', '우리 아버지가 말씀하시기를, 돌아가서 우리를 위해 조금 먹을 것을 사 오라 하셨습니다.'),
(1351, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 26, 'OT', '우리가 말하기를 우리는 내려갈 수 없다 하였나이다 만일 우리의 작은 아우가 우리와 함께 있으면 우리가 내려가겠나이다 이는 우리의 작은 아우가 우리와 함께 있지 아니하면 그 사람의 얼굴을 볼 수 없음이니이다'),
(1352, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 27, 'OT', '당신의 종 내 아버지가 우리에게 말하기를, 너희가 알거니와 내 아내가 내게 두 아들을 낳았도다'),
(1353, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 28, 'OT', '하나가 내게서 나갔고 내가 말하기를 정녕 찢겨 죽었다 하였으며 내가 지금까지 그를 보지 못하였나이다'),
(1354, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 29, 'OT', '너희가 이 또한 내 앞에서 데려가려 하면 재앙이 그에게 닥칠 것이요, 너희가 나의 백발을 슬픔으로 스올에 내려가게 하리라.'),
(1355, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 30, 'OT', '그러므로 이제 내가 주의 종 내 아버지에게 갈 때에 그 소년이 우리와 함께 있지 아니하니 그의 생명이 그 소년의 생명에 결박되어 있나이다'),
(1356, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 31, 'OT', '그가 그 아이가 없음을 보고 죽을 것이니, 주의 종들의 아버지인 당신의 종의 백발을 슬픔 가운데 스올로 내려가게 하리이다.'),
(1357, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 32, 'OT', '주의 종이 내 아버지에게 그 아이를 담보하였나이다, 말하기를 내가 그를 당신께로 데려오지 아니하면 내가 내 아버지께 모든 날에 죄를 지으리이다 하였나이다'),
(1358, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 33, 'OT', '그러므로 이제 청하건대 주의 종이 아이를 대신하여 머물러 주의 종이 되게 하시고, 아이는 그의 형제들과 함께 올라가게 하소서.'),
(1359, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 44, 34, 'OT', '내가 어찌 내 아버지께로 올라가리이까, 그 소년이 나와 함께 있지 아니하니, 내가 아버지에게 닥칠 재앙을 볼까 두렵나이다.'),
(1360, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 1, 'OT', '요셉이 그 곁에 선 모든 사람들 앞에서 스스로를 억제할 수 없어 외쳐 이르되, 모든 사람을 내게서 나가게 하라 하였고, 요셉이 그의 형제들에게 자신을 알릴 때에 그와 함께 한 사람이 아무도 없었더라.'),
(1361, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 2, 'OT', '그가 소리를 높여 울었고, 애굽 사람들이 들었으며, 바로의 집도 들었더라.'),
(1362, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 3, 'OT', '요셉이 그의 형들에게 이르되 나는 요셉이라 내 아버지가 아직 살아 있느냐 하니 그의 형들이 그 앞에서 놀라서 그에게 대답할 수 없었더라'),
(1363, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 4, 'OT', '요셉이 그의 형들에게 이르되 내게로 가까이 오라 하니 그들이 가까이 가니라 그가 이르되 나는 너희가 애굽에 판 너희 형제 요셉이니라'),
(1364, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 5, 'OT', '그러므로 이제 너희는 근심하지 말며 너희 눈에 화가 나지 않게 하라, 이는 너희가 나를 이곳에 팔았음이라, 하나님이 생명을 보존하시려고 나를 너희보다 앞서 보내셨음이니라.'),
(1365, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 6, 'OT', '이 땅 가운데 흉년이 이년 동안 있었으나 아직 오년은 밭 갈지도 못하고 추수하지도 못할지라'),
(1366, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 7, 'OT', '하나님이 나를 당신들 앞에 보내사 당신들을 위해 땅에서 남은 자를 두시고 큰 구원으로 당신들의 생명을 보존하게 하셨나니'),
(1367, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 8, 'OT', '그러므로 나를 이리로 보낸 자는 너희가 아니요 하나님이시라 그가 나를 바로에게 아버지로, 그의 온 집의 주인으로, 애굽 온 땅의 통치자로 세우셨느니라'),
(1368, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 9, 'OT', '너희는 속히 내 아버지께로 올라가서 그에게 말하라 네 아들 요셉이 이렇게 말하노니 하나님이 나를 온 애굽의 주로 세우셨느니라 내게로 내려오되 지체하지 말지어다'),
(1369, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 10, 'OT', '네가 고센 땅에 거주하며 내게 가까이 있으리라, 너와 네 아들들과 네 손자들과 네 양 떼와 네 소 떼와 네 모든 소유가.'),
(1370, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 11, 'OT', '내가 거기서 너를 부양하리니 이는 아직 다섯 해의 기근이 있음이라 너와 네 집과 네 모든 소유가 궁핍에 이르지 아니하도록 하려 함이니라'),
(1371, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 12, 'OT', '보라, 너희 눈과 내 아우 베냐민의 눈이 보는 바, 너희에게 말하는 이는 내 입이니라.'),
(1372, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 13, 'OT', '너희는 내가 애굽에서 얻은 모든 영광과 너희가 본 모든 것을 내 아버지께 고하고, 속히 내 아버지를 이리로 모시고 내려오라.'),
(1373, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 14, 'OT', '그가 그의 형제 베냐민의 목에 엎드려 울었고, 베냐민도 그의 목에 엎드려 울었더라.'),
(1374, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 15, 'OT', '그가 모든 형제들에게 입을 맞추고 그들 위에서 울었으며, 그 후에 그의 형제들이 그와 말하였더라.'),
(1375, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 16, 'OT', '그 소문이 바로의 궁에 들려 이르되 요셉의 형들이 왔다 하매 바로의 눈과 그의 신하들의 눈에 좋게 보였더라'),
(1376, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 17, 'OT', '바로가 요셉에게 말하되, 네 형들에게 말하라, 너희는 이렇게 하라, 너희 짐승들에게 짐을 싣고 가서 가나안 땅으로 들어가라.'),
(1377, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 18, 'OT', '너희 아버지와 너희 집들을 데리고 내게로 오라. 내가 너희에게 애굽 땅의 좋은 것을 주리니, 너희는 그 땅의 기름진 것을 먹으리라.'),
(1378, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 19, 'OT', '너는 명령을 받았으니 이것을 행하라 너희는 애굽 땅에서 수레를 가져다가 너희 어린 자녀들과 아내들을 위하여 그것을 취하고 너희 아버지를 싣고 오라'),
(1379, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 20, 'OT', '너희의 눈으로 너희의 기구를 아끼지 말라 이는 애굽 온 땅의 좋은 것이 너희 것이기 때문이라'),
(1380, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 21, 'OT', '이스라엘 자손들이 그대로 하였고, 요셉이 바로의 명령대로 그들에게 수레들을 주고 길 양식을 그들에게 주었더라.'),
(1381, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 22, 'OT', '그들 모두에게 각 사람에게 갈아입을 옷들을 주었고, 베냐민에게는 은 삼백과 옷 다섯 벌을 주었다.'),
(1382, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 23, 'OT', '그의 아버지에게도 이와 같이 보내되 애굽의 좋은 물건을 실은 수나귀 열 필과, 그의 아버지에게 길에서 쓸 곡식과 떡과 양식을 실은 암나귀 열 필을 보냈더라'),
(1383, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 24, 'OT', '그가 그의 형들을 보내니 그들이 떠났고 그가 그들에게 이르되, 너희는 길에서 다투지 말라 하였더라'),
(1384, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 25, 'OT', '그들이 애굽에서 올라와 가나안 땅으로 들어가 그들의 아비 야곱에게 이르렀더라'),
(1385, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 26, 'OT', '그들이 그에게 말하여 이르되, 요셉이 아직 살아 있고 그가 애굽 온 땅을 다스리는 자가 되었나이다 하니, 그의 마음이 기절하였으니 이는 그가 그들을 믿지 아니함이었더라.'),
(1386, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 27, 'OT', '그들이 요셉이 그들에게 말한 모든 말을 그에게 전하니, 그가 요셉이 자기를 태우려고 보낸 수레들을 보고, 그들의 아버지 야곱의 영이 소생하였더라.'),
(1387, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 45, 28, 'OT', '이스라엘이 말하되, “내 아들 요셉이 아직 살아 있음이 족하도다. 내가 죽기 전에 가서 그를 보리라.”'),
(1388, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 1, 'OT', '이스라엘이 그의 모든 소유와 함께 떠나 브엘세바에 이르러, 그의 아버지 이삭의 하나님께 희생제사를 드렸더라.'),
(1389, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 2, 'OT', '하나님이 밤의 환상 중에 이스라엘에게 말씀하시며 이르시되 야곱아, 야곱아 하시니 그가 이르되 내가 여기 있나이다 하니라'),
(1390, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 3, 'OT', '그가 말씀하셨다. 나는 네 아버지의 하나님, 곧 하나님이라. 애굽으로 내려가기를 두려워하지 말라. 내가 거기서 너를 큰 민족이 되게 하리라.'),
(1391, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 4, 'OT', '내가 너와 함께 애굽으로 내려가겠고, 내가 또한 반드시 너를 올리리라. 그리고 요셉이 그의 손을 네 눈 위에 얹으리라.'),
(1392, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 5, 'OT', '야곱이 브엘세바에서 일어났고, 이스라엘의 아들들이 그들의 아버지 야곱과 그들의 어린 자녀들과 그들의 아내들을 바로가 그를 태우려고 보낸 수레들에 실었더라.'),
(1393, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 6, 'OT', '그들이 가나안 땅에서 얻은 가축과 재물을 취하고 애굽으로 들어갔으니, 야곱과 그의 모든 자손이 그와 함께 하였더라.'),
(1394, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 7, 'OT', '그의 아들들과 그의 손자들이 그와 함께, 그의 딸들과 그의 손녀들과 그의 모든 자손을 그가 데리고 애굽으로 갔더라'),
(1395, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 8, 'OT', '애굽으로 들어간 이스라엘 자손들의 이름은 이러하니, 야곱과 그의 아들들, 곧 야곱의 맏아들 르우벤이라.'),
(1396, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 9, 'OT', '르우벤의 아들들은 하녹과 발루와 헤스론과 갈미더라'),
(1397, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 10, 'OT', '시므온의 아들들은 여무엘과 야민과 오핫과 야긴과 소할과 가나안 여인의 아들 사울이더라'),
(1398, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 11, 'OT', '레위의 아들들은 게르손과 크핫과 므라리였더라.'),
(1399, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 12, 'OT', '유다의 아들들은 에르와 오난과 셀라와 베레스와 세라였으며, 에르와 오난은 가나안 땅에서 죽었고, 베레스의 아들들은 헤스론과 하물이었다.'),
(1400, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 13, 'OT', '잇사갈의 아들들은 돌라와 부와와 욥과 시므론이더라.'),
(1401, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 14, 'OT', '스불론의 아들들은 세렛과 엘론과 야흘르엘이더라'),
(1402, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 15, 'OT', '이들은 레아가 밧단아람에서 야곱에게 낳은 아들들이며, 그의 딸 디나도 함께하니, 그의 아들들과 딸들의 모든 영혼이 삼십삼 명이었더라.'),
(1403, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 16, 'OT', '갓의 아들들은 시뵨과 학기와 수니와 에스본과 에리와 아로디와 아렐리였더라'),
(1404, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 17, 'OT', '아셀의 아들들은 임나와 이스와와 이스위와 브리아와 그들의 누이 세라요, 브리아의 아들들은 헤벨과 말기엘이었더라.'),
(1405, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 18, 'OT', '이들은 라반이 그의 딸 레아에게 준 실바의 아들들이라 그가 이들을 야곱에게 낳았으니 열여섯 영혼이었더라'),
(1406, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 19, 'OT', '야곱의 아내 라헬의 아들들, 요셉과 베냐민이라.'),
(1407, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 20, 'OT', '요셉이 애굽 땅에서 아스낫에게서 낳은 자, 곧 온 제사장 보디베라의 딸이 그에게 낳은 므낫세와 에브라임이더라'),
(1408, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 21, 'OT', '베냐민의 아들들은 벨라와 베겔과 아스벨, 게라와 나아만, 에히와 로스, 뭅빔과 훔빔과 아릇이었더라.'),
(1409, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 22, 'OT', '이들은 라헬이 야곱에게 낳은 아들들이니, 모든 영혼이 열넷이었더라.'),
(1410, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 23, 'OT', '단의 아들들은 후심이더라.'),
(1411, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 24, 'OT', '납달리의 아들들은 야흐츠엘과 구니와 예첼과 실렘이었더라.'),
(1412, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 25, 'OT', '이들은 라반이 그의 딸 라헬에게 준 빌하의 아들들이며, 그녀가 이들을 야곱에게 낳았으니 모든 영혼이 일곱이었더라.'),
(1413, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 26, 'OT', '야곱과 함께 애굽으로 들어온 모든 영혼, 곧 그의 허리에서 나온 자들은 야곱의 아들들의 아내들을 제외하고 모두 육십육 명이었더라.'),
(1414, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 27, 'OT', '애굽에서 요셉에게 태어난 아들들이 두 명이었으니, 야곱의 집으로 애굽에 들어온 모든 사람이 칠십 명이었더라.'),
(1415, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 28, 'OT', '야곱이 유다를 요셉에게 앞서 보내어 자기 앞길을 고센으로 인도하게 하였더니 그들이 고센 땅에 이르렀더라'),
(1416, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 29, 'OT', '요셉이 자기 병거를 갖추고 고센으로 올라가서 그의 아버지 이스라엘을 맞이하니, 그가 그에게 나타나 그 목에 떨어져 그 목에 붙잡고 오래 울었더라.'),
(1417, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 30, 'OT', '이스라엘이 요셉에게 이르되 내가 네 얼굴을 보았고 네가 아직 살아 있으니 이제 죽어도 되겠다'),
(1418, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 31, 'OT', '요셉이 그의 형들과 그의 아버지의 집에게 말하되, 내가 올라가서 바로에게 알리고 그에게 말하리라, 가나안 땅에 있던 내 형들과 내 아버지의 집이 내게로 왔나이다.'),
(1419, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 32, 'OT', '그 사람들은 목자들이요, 그들은 가축을 기르는 사람들이었으며, 그들의 양 떼와 소 떼와 그들이 가진 모든 것을 가지고 왔느니라.'),
(1420, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 33, 'OT', '바로가 너희를 부르며 “너희의 직업이 무엇이냐?” 하고 말할 때에,'),
(1421, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 46, 34, 'OT', '당신들은 말하기를, 주의 종들은 어렸을 때부터 지금까지 가축을 치는 사람들이었나이다, 우리도 우리 조상들도 그러하오며, 당신들이 고센 땅에 거주하게 하시려 함이니이다, 이는 애굽 사람이 모든 양 치는 자를 가증히 여김이니이다.'),
(1422, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 1, 'OT', '요셉이 바로에게 가서 고하여 이르되, 내 아버지와 내 형제들과 그들의 양 떼와 소 떼와 그들의 모든 소유가 가나안 땅에서 왔고, 보라, 그들이 고센 땅에 있나이다 하니라.'),
(1423, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 2, 'OT', '또 그 형들 중에서 다섯 사람을 데려다가 바로 앞에 세우니라'),
(1424, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 3, 'OT', '바로가 그의 형들에게 말하되, 너희의 생업이 무엇이냐? 그들이 바로에게 말하되, 당신의 종들은 양 떼를 치는 목자이온데 우리와 우리 조상들도 그러하니이다.'),
(1425, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 4, 'OT', '그들이 바로에게 말하였다: “우리가 이 땅에 나그네로 살려고 왔사오니, 이는 당신의 종들의 양 떼에게 먹을 풀이 없기 때문입니다. 가나안 땅에 기근이 심하기 때문입니다. 이제 원하옵나니 당신의 종들이 고센 땅에 거하게 하소서.”'),
(1426, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 5, 'OT', '바로가 요셉에게 말하여 이르되, 네 아버지와 네 형제들이 네게 왔느니라'),
(1427, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 6, 'OT', '애굽 땅이 네 앞에 있나니 그 땅의 가장 좋은 곳에 네 아버지와 네 형제들을 거하게 하되 고센 땅에서 그들이 거하게 하라 만일 그들 중에 능력 있는 사람이 있음을 네가 알거든 그들을 내 가축을 다스리는 자로 삼으라'),
(1428, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 7, 'OT', '요셉이 그의 아버지 야곱을 데려다가 바로 앞에 세우니, 야곱이 바로에게 축복하니라.'),
(1429, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 8, 'OT', '바로가 야곱에게 이르되, 네 생애의 날들이 얼마냐'),
(1430, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 9, 'OT', '야곱이 바로에게 말하되, “내 나그네 생활의 연수가 백삼십 년이니이다. 내 생애의 연수는 짧고 괴로웠으며, 내 조상들이 나그네로 살던 시대의 연수에는 미치지 못하나이다.”'),
(1431, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 10, 'OT', '야곱이 바로를 축복하고 바로 앞에서 나아가니라'),
(1432, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 11, 'OT', '요셉이 그의 아버지와 그의 형제들을 거주하게 하고 그들에게 애굽 땅에서 소유를 주되 그 땅의 가장 좋은 곳, 라암세스 땅에서 그들에게 주었으니, 바로가 명령한 대로였더라.'),
(1433, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 12, 'OT', '요셉이 그의 아버지와 그의 형제들과 그의 아버지의 온 집을 그들의 식구 수대로 양식으로 부양하였더라'),
(1434, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 13, 'OT', '온 땅에 양식이 없었으니 이는 기근이 매우 심하였음이라 애굽 땅과 가나안 땅이 기근으로 말미암아 쇠약하였더라'),
(1435, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 14, 'OT', '요셉이 애굽 땅과 가나안 땅에서 발견된 모든 돈을 그들이 사는 곡식 값을 위해 거두었고, 요셉이 그 돈을 바로의 집으로 가져왔더라.'),
(1436, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 15, 'OT', '애굽 땅과 가나안 땅에서 돈이 다 떨어지매 모든 애굽 사람들이 요셉에게 와서 이르되 우리에게 양식을 주소서 어찌하여 당신 앞에서 우리가 죽으리이까 돈이 다하였나이다'),
(1437, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 16, 'OT', '요셉이 이르되 너희의 가축을 내라 돈이 떨어졌으니 내가 너희의 가축과 바꾸어 주리라'),
(1438, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 17, 'OT', '그들이 그들의 가축을 요셉에게로 끌어왔고, 요셉이 그들에게 말들과 양 떼와 소 떼와 나귀들을 대가로 빵을 주었으며, 그 해에 그들의 모든 가축과 바꾸어 빵으로 그들을 먹였더라.'),
(1439, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 18, 'OT', '그 해가 끝나고 둘째 해에 그들이 그에게 와서 말하되 우리가 내 주에게 숨기지 아니하나이다 돈이 다하였고 가축 떼가 내 주에게로 갔사오니 내 주 앞에 남은 것이 없고 오직 우리의 몸과 우리의 땅뿐이니이다'),
(1440, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 19, 'OT', '어찌하여 우리가 우리 땅과 함께 주의 목전에서 죽으리이까? 우리와 우리 땅을 양식으로 사소서. 우리가 우리 땅과 함께 바로의 종이 되리니, 종자를 주소서. 우리가 살고 죽지 아니하며 땅이 황폐하지 아니하리이다.'),
(1441, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 20, 'OT', '요셉이 애굽의 모든 땅을 바로에게 사들였으니 이는 애굽 사람들이 각자 자기 밭을 팔았음이라 흉년이 그들을 심히 눌렀음이라 그리하여 그 땅이 바로의 소유가 되었더라'),
(1442, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 21, 'OT', '그 백성을 애굽 경계의 한쪽 끝에서 다른 쪽 끝까지 성읍들로 옮겼더라'),
(1443, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 22, 'OT', '다만 제사장들의 땅은 사지 아니하였으니 이는 제사장들이 바로에게서 정한 몫을 받았고 바로가 그들에게 준 그 몫을 먹었음이라 그러므로 그들이 자기 땅을 팔지 아니하였더라'),
(1444, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 23, 'OT', '요셉이 백성에게 이르되, 보라, 내가 오늘 너희와 너희 땅을 바로를 위하여 샀노라. 보라, 너희를 위하여 종자가 여기 있으니, 너희는 그 땅에 뿌릴지니라.'),
(1445, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 24, 'OT', '그 소출 중에서 오분의 일을 바로에게 바치고, 사분은 너희 것이 되리니 그것으로 밭의 씨와 너희의 양식과 너희 집에 있는 자들의 양식과 너희 어린 아이들의 양식을 삼을지니라.'),
(1446, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 25, 'OT', '그들이 말하되, 당신이 우리를 살리셨나이다. 우리가 내 주의 눈앞에서 은혜를 얻고 바로의 종이 되겠나이다.'),
(1447, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 26, 'OT', '요셉이 그것을 애굽 땅에서 바로에게 오분의 일을 바치는 법으로 오늘까지 세웠으나, 다만 제사장들의 땅만은 바로의 소유가 되지 아니하였더라.'),
(1448, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 27, 'OT', '이스라엘이 애굽 땅, 고센 땅에 거주하였으며 그들이 그 땅에서 소유를 얻고 생육하며 매우 번성하였더라.'),
(1449, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 28, 'OT', '야곱이 애굽 땅에서 십칠 년을 살았고, 야곱의 생애의 날들은 백사십칠 년이었더라.'),
(1450, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 29, 'OT', '이스라엘의 죽을 날이 가까우매 그가 그의 아들 요셉을 불러 그에게 이르되, 이제 내가 네 눈앞에서 은혜를 얻었거든 청하노니 네 손을 내 허벅지 아래에 두고 나에게 인애와 진실함을 행하며 청하노니 나를 애굽에 장사하지 말지어다.'),
(1451, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 30, 'OT', '내가 내 조상들과 함께 눕겠고 너는 나를 애굽에서 메어다가 그들의 묘지에 장사할지니라. 그가 이르되 내가 네 말대로 행하리라 하니라.'),
(1452, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 47, 31, 'OT', '그가 말하기를 “내게 맹세하라” 하니 그가 그에게 맹세하더라. 이스라엘이 침상 머리에서 경배하니라.'),
(1453, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 1, 'OT', '이 일 후에 요셉에게 말하기를, 보라 네 아버지가 병들었다 하였고, 그가 그의 두 아들 므낫세와 에브라임을 데리고 그와 함께 갔더라.'),
(1454, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 2, 'OT', '야곱에게 알리며 이르되 보라 네 아들 요셉이 네게 오고 있다 하매 이스라엘이 힘을 내어 침상에 앉으니라'),
(1455, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 3, 'OT', '야곱이 요셉에게 이르되, 전능하신 하나님이 가나안 땅 루스에서 내게 나타나 나를 축복하셨느니라.'),
(1456, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 4, 'OT', '내게 이르시되, 보라, 내가 너를 생육하게 하고 번성하게 하며, 너를 많은 백성의 무리로 만들고, 이 땅을 네 뒤를 잇는 네 자손에게 영원한 기업으로 주리라.'),
(1457, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 5, 'OT', '이제 네가 애굽 땅에서 내가 네게로 애굽에 이르기 전에 네게서 낳은 두 아들 에브라임과 므낫세는 내 것이라 르우벤과 시므온처럼 그들이 내 것이 되리라'),
(1458, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 6, 'OT', '네가 그들 이후에 낳은 자손은 네 것이 되리니 그들은 그들의 형들의 이름으로 그들의 기업에서 불릴 것이다.'),
(1459, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 7, 'OT', '내가 밧단에서 올 때에 라헬이 가나안 땅에서 길 중에 내 곁에서 죽었는데, 에브랏에 이르기까지 얼마 남지 않은 땅이었고, 내가 그를 거기 에브랏 길에 장사하였으니, 그것이 곧 베들레헴이니라.'),
(1460, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 8, 'OT', '이스라엘이 요셉의 아들들을 보고 이르되, 이들은 누구냐 하니'),
(1461, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 9, 'OT', '요셉이 그의 아버지에게 말하되, 이들은 하나님이 이 곳에서 내게 주신 내 아들들이니이다. 그가 말하되, 그들을 내게로 데려오라, 내가 그들에게 축복하리라.'),
(1462, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 10, 'OT', '이스라엘의 눈이 늙음으로 말미암아 무거워져서 볼 수 없었더라 그가 그들을 그에게로 가까이 데려오니 그가 그들에게 입맞추고 그들을 안았더라'),
(1463, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 11, 'OT', '이스라엘이 요셉에게 이르되, 내가 네 얼굴을 보리라고는 생각하지 못하였더니, 보라, 하나님이 내게 네 자손까지도 보이셨도다.'),
(1464, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 12, 'OT', '요셉이 그들을 그의 무릎 사이에서 데리고 나와, 그의 얼굴을 땅에 대고 절하니라.'),
(1465, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 13, 'OT', '요셉이 그 두 사람을 데리되 에브라임을 그의 오른손으로 이스라엘의 왼편을 향하게 하고 므낫세를 그의 왼손으로 이스라엘의 오른편을 향하게 하여 그에게로 가까이 이끌었더라'),
(1466, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 14, 'OT', '이스라엘이 오른손을 내밀어 에브라임의 머리에 얹었는데 그는 작은 자였고, 왼손은 므낫세의 머리에 얹었으니, 그가 그의 손들을 지혜롭게 인도하였음이라, 므낫세는 장자였음이라.'),
(1467, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 15, 'OT', '그가 요셉을 축복하며 말하되, 내 조상 아브라함과 이삭이 그 앞에서 행한 하나님, 나를 내가 태어난 때부터 이 날까지 기르신 하나님이여,'),
(1468, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 16, 'OT', '나를 모든 악에서 구속하신 그 사자가 이 아이들에게 복을 주시고, 그들 가운데 내 이름과 내 조상 아브라함과 이삭의 이름이 불리게 하시며, 그들이 땅 가운데서 많은 무리로 번성하게 하시기를 원하나이다.'),
(1469, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 17, 'OT', '요셉이 그의 아버지가 오른손을 에브라임의 머리 위에 얹은 것을 보고 그것이 그의 눈에 좋지 않게 보였으며, 그가 아버지의 손을 붙잡아 에브라임의 머리 위에서 므낫세의 머리 위로 옮기려 하였다.'),
(1470, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 18, 'OT', '요셉이 그의 아버지에게 말하되, 아버지여, 그렇지 아니하니이다. 이는 이가 장자이오니, 아버지의 오른손을 그의 머리 위에 얹으소서.'),
(1471, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 19, 'OT', '아비가 거절하며 이르되 내가 아노라 내 아들아 내가 아노라 그도 한 백성이 되고 그도 크게 되리라 그러나 그의 작은 아우가 그보다 크게 되고 그의 자손이 여러 민족의 충만함을 이루리라 하니라'),
(1472, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 20, 'OT', '그 날에 그가 그들을 축복하여 이르되, 이스라엘이 너로 말미암아 축복하여 이르기를, 하나님이 너를 에브라임과 므낫세 같이 되게 하시리라 하리라 하고, 에브라임을 므낫세보다 앞에 두었더라.'),
(1473, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 21, 'OT', '이스라엘이 요셉에게 이르되, 보라 내가 죽으려니와 하나님이 너희와 함께 계시리니 그가 너희를 너희 조상들의 땅으로 돌아가게 하시리라.'),
(1474, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 48, 22, 'OT', '내가 네게 네 형제들보다 한 몫을 주었나니 이는 내가 내 칼과 내 활로 아모리 사람의 손에서 빼앗은 것이니라'),
(1475, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 1, 'OT', '야곱이 그의 아들들을 불러 이르되, 너희는 모이라, 내가 너희에게 마지막 날들에 너희에게 닥칠 일을 알려 주리라.'),
(1476, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 2, 'OT', '너희는 모여서 들으라, 야곱의 아들들아, 너희 아비 이스라엘에게 귀를 기울이라.'),
(1477, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 3, 'OT', '르우벤아, 너는 내 맏아들이요, 내 힘이요, 내 기력의 시작이라, 존귀의 뛰어남이요, 권능의 뛰어남이로다.'),
(1478, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 4, 'OT', '물의 끓음 같았은즉 너는 탁월하지 못하리니 이는 네가 네 아버지의 침상에 올랐음이라 그 때에 네가 내 자리를 더럽혔도다 그가 올라갔도다'),
(1479, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 5, 'OT', '시므온과 레위는 형제요, 그들의 거처는 폭력의 도구로다.'),
(1480, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 6, 'OT', '내 혼아, 그들의 비밀 모임에 들어가지 말지어다 내 영광아, 그들의 집회에 참여하지 말지어다 그들이 분노로 사람을 죽였고 그들의 뜻대로 소의 발목 힘줄을 끊었음이로다'),
(1481, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 7, 'OT', '그들의 분노는 맹렬하니 저주를 받을 것이요, 그들의 진노는 잔인하니 저주를 받을 것이라. 내가 그들을 야곱 가운데서 나누며 이스라엘 가운데서 흩으리라.'),
(1482, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 8, 'OT', '유다야, 너는 네 형제들이 너를 찬송하리라, 네 손이 네 원수들의 목덜미에 있으리라, 네 아버지의 아들들이 네 앞에 경배하리라.'),
(1483, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 9, 'OT', '유다는 사자 새끼로다 내 아들아, 네가 움킨 것을 찢고 올라갔도다 그가 엎드리고 웅크림이 수사자 같고 암사자 같으니 누가 그를 일으키랴'),
(1484, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 10, 'OT', '유다에게서 홀이 떠나지 아니하며 그의 발 사이에서 통치자의 지팡이가 떠나지 아니하리니 실로가 올 때까지라 그에게 모든 백성이 복종하리로다'),
(1485, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 11, 'OT', '그의 나귀 새끼를 포도나무에 매며 그의 암나귀를 좋은 포도나무에 매리로다 그가 그의 옷을 포도주에 빨며 그의 옷을 포도의 피에 빨리로다'),
(1486, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 12, 'OT', '그의 눈은 포도주로 인하여 붉고, 그의 이는 우유로 인하여 희도다.'),
(1487, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 13, 'OT', '스불론은 바닷가에 거하리니 그가 배들의 해변에 있으리라 그의 경계는 시돈에 이르리라'),
(1488, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 14, 'OT', '잇사갈은 양의 우리 사이에 꿇어 앉은 건장한 나귀로다'),
(1489, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 15, 'OT', '그가 쉼이 좋음을 보고 그 땅이 아름다움을 보며 그의 어깨를 굽혀 짐을 지고 강제 노역의 종이 되었도다.'),
(1490, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 16, 'OT', '단이 그 백성을 심판하리니 이스라엘의 한 지파 같이 되리라'),
(1491, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 17, 'OT', '단은 길의 뱀이요, 첩경의 독사로다. 말의 발꿈치를 물어서 그 탄 자가 뒤로 떨어지게 하리로다.'),
(1492, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 18, 'OT', '여호와여, 내가 주의 구원을 기다렸나이다.'),
(1493, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 19, 'OT', '갓은 군대가 그를 치리로다 그러나 그가 그 뒤를 추격하리로다'),
(1494, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 20, 'OT', '아셀에게서 나는 그의 떡은 기름지며 그가 왕의 진수를 주리라'),
(1495, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 21, 'OT', '납달리는 놓인 암사슴이라 아름다운 말을 주는도다'),
(1496, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 22, 'OT', '요셉은 무성한 가지, 샘 곁의 무성한 가지라, 딸들이 성벽 위로 걸어가도다'),
(1497, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 23, 'OT', '활쏘는 자들이 그를 심히 괴롭게 하였고, 그를 쏘며, 그를 미워하였도다.'),
(1498, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 24, 'OT', '그의 활이 견고하게 머물렀고, 그의 손의 팔들이 힘 있게 되었도다, 야곱의 능하신 이의 손으로 말미암아, 그로부터 이스라엘의 반석인 목자가 나시도다.'),
(1499, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 25, 'OT', '네 아버지의 하나님께로 말미암아 그가 너를 도우시리라, 전능하신 이께로 말미암아 그가 너를 복 주시리니 위로 하늘의 복과 아래로 깔린 깊음의 복과 유방과 태의 복이로다'),
(1500, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 26, 'OT', '네 아버지의 축복이 내 조상들의 축복보다 더하여 영원한 산들의 소원까지 이르렀나니 그것들이 요셉의 머리와 그의 형제들 중 구별된 자의 정수리에 있으리라'),
(1501, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 27, 'OT', '베냐민은 약탈하는 이리라, 아침에는 먹이를 먹고 저녁에는 탈취물을 나누리라.'),
(1502, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 28, 'OT', '이 모든 것은 이스라엘의 열두 지파라 그들의 아버지가 그들에게 말하고 그들을 축복하였으되 각 사람이 그의 축복대로 그들을 축복하였더라'),
(1503, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 29, 'OT', '그가 그들에게 명령하여 그들에게 이르되, 내가 내 백성에게로 모임을 당하리니 나를 내 조상들에게, 곧 헷 사람 에브론의 밭에 있는 굴에 장사하라.'),
(1504, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 30, 'OT', '막벨라 밭에 있는 굴이니, 그 굴은 마므레 앞, 가나안 땅에 있으며, 아브라함이 헷 사람 에브론에게서 그 밭을 매장지로 삼아 산 것이더라.'),
(1505, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 31, 'OT', '거기서 그들이 아브라함과 그의 아내 사라를 장사하였고, 거기서 그들이 이삭과 그의 아내 리브가를 장사하였으며, 거기서 내가 레아를 장사하였노라.'),
(1506, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 32, 'OT', '밭과 그 안에 있는 굴은 헷 자손에게서 산 것이니라'),
(1507, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 49, 33, 'OT', '야곱이 그의 아들들에게 명령하기를 마치고 그의 발을 침상에 거두고 기운이 진하여 그의 백성에게로 돌아갔더라'),
(1508, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 1, 'OT', '요셉이 그의 아버지의 얼굴에 엎드려 그 위에서 울며 그에게 입맞추니라'),
(1509, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 2, 'OT', '요셉이 그의 신하 의사들에게 명하여 그의 아버지를 향료로 방부 처리하게 하매, 의사들이 이스라엘을 방부 처리하였더라.'),
(1510, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 3, 'OT', '그를 위하여 사십 일이 차니 이는 향료를 넣는 날이 이와 같이 차기 때문이라 애굽 사람들이 그를 위하여 칠십 일을 곡하였더라'),
(1511, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 4, 'OT', '그의 애곡하는 날들이 지나매 요셉이 바로의 집에 말하여 이르되, 내가 너희 눈에 은혜를 입었으면 청하노니 바로의 귀에 말하여 이르기를'),
(1512, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 5, 'OT', '아버지께서 나를 맹세하게 하여 이르시되, 보라 내가 죽으리니, 내가 가나안 땅에서 나를 위하여 판 내 무덤에 네가 나를 장사하라 하셨나이다. 이제 내가 올라가서 내 아버지를 장사하고 돌아오겠나이다.'),
(1513, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 6, 'OT', '바로가 말하되, 올라가서 네 아버지를 장사하라 그가 네게 맹세시킨 대로 하라.'),
(1514, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 7, 'OT', '요셉이 자기 아버지를 장사하러 올라가니, 바로의 모든 신하들 곧 그의 집의 장로들과 애굽 땅의 모든 장로들이 그와 함께 올라갔더라.'),
(1515, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 8, 'OT', '요셉의 온 집과 그의 형제들과 그의 아버지의 집은 다만 그들의 어린 아이들과 양 떼와 소 떼만 고센 땅에 남겼더라'),
(1516, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 9, 'OT', '병거와 기병도 그와 함께 올라갔고, 그 진영이 심히 컸더라.'),
(1517, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 10, 'OT', '그들이 요단 건너편 아닷 타작마당에 이르러 거기서 심히 크고 무거운 애곡으로 슬퍼하였으며 그가 그의 아버지를 위하여 칠 일 동안 애곡을 행하였더라'),
(1518, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 11, 'OT', '그 땅의 거주민인 가나안 사람들이 아탓 타작마당의 애곡을 보고 말하기를 “이것은 애굽 사람들에게 무거운 애곡이라” 하였으므로, 그 이름을 아벨 미스라임이라 불렀으니, 이는 요단 건너편에 있더라.'),
(1519, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 12, 'OT', '그의 아들들이 그에게 명령한 대로 그에게 행하였더라.'),
(1520, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 13, 'OT', '그의 아들들이 그를 가나안 땅으로 메어다가 마므레 앞 막벨라 밭의 굴에 장사하였으니, 이는 아브라함이 헷 사람 에브론에게서 그 밭을 매장지로 삼아 산 곳이더라.'),
(1521, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 14, 'OT', '요셉이 그의 형제들과 그와 함께 그의 아버지를 장사하러 올라간 모든 자들과 함께 애굽으로 돌아갔으니, 그가 그의 아버지를 장사한 후였더라.'),
(1522, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 15, 'OT', '요셉의 형제들이 그들의 아버지가 죽었음을 보고 말하되, “요셉이 혹시 우리를 미워하여 우리가 그에게 행한 모든 악을 반드시 갚지나 아니할까?” 하였더라.'),
(1523, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 16, 'OT', '그들이 요셉에게 말을 전하여 이르되, 당신의 아버지가 죽기 전에 명하여 이르시기를'),
(1524, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 17, 'OT', '너희는 이같이 요셉에게 말하라: 청하노니 이제 네 형들의 허물과 그들의 죄를 용서하라, 그들이 네게 악을 행하였음이니라. 이제 청하노니 네 아버지의 하나님의 종들의 허물을 용서하소서. 그들이 그에게 말할 때에 요셉이 울었더라.'),
(1525, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 18, 'OT', '그의 형들도 가서 그의 앞에 엎드려 말하되, 보소서, 우리는 당신의 종들이니이다.'),
(1526, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 19, 'OT', '요셉이 그들에게 이르되 두려워하지 말라 내가 하나님을 대신하겠느냐'),
(1527, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 20, 'OT', '너희는 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 많은 백성을 살리려 하심이니라'),
(1528, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 21, 'OT', '그러므로 이제 두려워하지 마십시오. 내가 당신들과 당신들의 어린 자녀들을 먹이리라. 그가 그들을 위로하고 그들의 마음에 말하였더라.'),
(1529, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 22, 'OT', '요셉이 애굽에 거하였으니 그와 그의 아버지의 집이요, 요셉이 백 십 년을 살았더라.'),
(1530, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 23, 'OT', '요셉이 에브라임의 삼대 자손을 보았고, 므낫세의 아들 마길의 아들들도 요셉의 무릎에서 태어났더라.'),
(1531, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 24, 'OT', '요셉이 그의 형제들에게 이르되, 나는 죽으나 하나님이 반드시 너희를 돌보시고 너희를 이 땅에서 인도하여 내사 아브라함과 이삭과 야곱에게 맹세하신 그 땅으로 데려가시리라.'),
(1532, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 25, 'OT', '요셉이 이스라엘 자손에게 맹세하게 하여 이르되, 하나님이 반드시 너희를 돌보시리니 너희는 내 뼈를 이곳에서 가지고 올라가야 하리라 하였더라'),
(1533, 1, 'GOI_Ko', 'GOI_Ko', 'ko', 'GEN', 50, 26, 'OT', '요셉이 백십 세에 죽으매 그들이 그를 향으로 처리하고 애굽에서 관에 넣었더라'),
(1534, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 1, 'OT', '이스라엘 아들들의 이름은 이러하니 애굽에 들어온 자들 곧 야곱과 함께 각 사람과 그의 집이 들어왔더라'),
(1535, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 2, 'OT', '르우벤, 시므온, 레위와 유다'),
(1536, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 3, 'OT', '잇사갈과 스불론과 베냐민'),
(1537, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 4, 'OT', '단과 납달리와 갓과 아셀'),
(1538, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 5, 'OT', '야곱의 넓적다리에서 나온 모든 영혼이 칠십 영혼이었고, 요셉은 애굽에 있었더라.'),
(1539, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 6, 'OT', '요셉이 죽었고 그의 모든 형제와 그 모든 세대도 죽었더라.'),
(1540, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 7, 'OT', '이스라엘의 아들들은 생육하고 번성하며 많아지고 심히 강대해졌으며, 땅이 그들로 가득하게 되었더라.'),
(1541, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 8, 'OT', '새 왕이 애굽 위에 일어났는데, 그가 요셉을 알지 못하더라.'),
(1542, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 9, 'OT', '그가 자기 백성에게 이르되, 보라, 이스라엘 자손의 백성이 우리보다 많고 강하도다.'),
(1543, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 10, 'OT', '자, 우리가 그들에게 지혜롭게 행하자, 그들이 많아지지 않도록, 전쟁이 일어날 때에 그들도 우리 원수들에게 합류하여 우리와 싸우고 이 땅에서 올라갈까 두렵도다.'),
(1544, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 11, 'OT', '그들이 그 위에 공물의 통치자들을 세워 그들의 짐으로 그를 괴롭게 하였고, 그가 파라오를 위하여 국고 성읍들, 곧 비톰과 라암세스를 건축하였더라.'),
(1545, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 12, 'OT', '그들이 그를 학대할수록 그는 더욱 번성하고 창성하였으며, 그들이 이스라엘 자손의 얼굴 때문에 근심하게 되었더라.'),
(1546, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 13, 'OT', '애굽 사람들이 이스라엘 자손을 혹독함으로 섬기게 하였더라'),
(1547, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 14, 'OT', '그들이 진흙과 벽돌과 들판의 모든 일로 혹독한 노역으로 그들의 살아있는 삶을 괴롭게 하였으며, 그들이 그들에게 시킨 모든 일이 혹독함으로 행해졌더라.'),
(1548, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 15, 'OT', '애굽 왕이 히브리 산파들에게 말하되, 그 중 한 사람의 이름은 십브라요, 둘째의 이름은 푸아였더라.'),
(1549, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 16, 'OT', '그가 말하기를, 너희가 히브리인 여인들을 해산하게 할 때에, 그 바퀴 위에서 보거든, 만일 그가 아들이면 그를 죽이고, 만일 그가 딸이면 그녀는 살게 두라.'),
(1550, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 17, 'OT', '산파들이 하나님을 두려워하여 애굽 왕이 그들에게 말한 대로 행하지 아니하고 아이들을 살렸더라'),
(1551, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 18, 'OT', '애굽 왕이 산파들을 불러 그들에게 이르되, 너희가 어찌하여 이 일을 행하여 아이들을 살렸느냐?'),
(1552, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 19, 'OT', '산파들이 파라오에게 말하되, 히브리 여인들은 애굽 사람 여자들과 같지 아니하니, 그들은 건장하여 산파가 그들에게 이르기 전에 이미 해산하였나이다.'),
(1553, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 20, 'OT', '하나님이 산파들에게 은혜를 베푸셨고 백성이 번성하며 심히 강대해졌더라'),
(1554, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 21, 'OT', '산파들이 하나님을 두려워하였으므로 그가 그들에게 집들을 지어 주셨더라.'),
(1555, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 1, 22, 'OT', '파라오가 그의 모든 백성에게 명령하여 이르되, 태어난 모든 아들은 나일강에 던지고 모든 딸은 살리라 하였더라'),
(1556, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 1, 'OT', '레위 집에서 한 사람이 가서 레위의 딸을 취하였더라'),
(1557, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 2, 'OT', '그 여자가 잉태하여 아들을 낳고, 그가 좋은 것을 보고 그를 석 달 동안 숨겼더라.'),
(1558, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 3, 'OT', '그러나 그를 더 이상 숨길 수 없게 되매, 그를 위하여 골풀 방주를 가져다가 역청과 역청으로 그것에 칠하고, 그 아이를 그 안에 두며, 나일강 입술 갈대 사이에 두니라.'),
(1559, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 4, 'OT', '그의 자매가 멀리 서서 그에게 어떻게 될지를 알려 하였더라'),
(1560, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 5, 'OT', '바로의 딸이 나일강에서 목욕하러 내려오니 그녀의 처녀들이 나일강의 손길을 따라 걷고 있었으며, 그녀가 갈대 중간에 있는 방주를 보고 그녀의 여종을 보내어 그것을 가져오게 하였다.'),
(1561, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 6, 'OT', '그녀가 열어 그 아이를 보니, 보라, 소년이 우는지라 그녀가 그를 불쌍히 여겨 말하되 "이는 히브리인들의 아이 중 하나로다"'),
(1562, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 7, 'OT', '그의 누이가 파라오의 딸에게 말하되, 내가 가서 히브리인 여인들 중에서 젖먹이 여자를 불러다가 당신을 위하여 그 아이를 젖 먹이게 하리이까?'),
(1563, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 8, 'OT', '바로의 딸이 그녀에게 이르되 가라 하니, 그 처녀가 가서 아이의 어머니를 불렀더라.'),
(1564, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 9, 'OT', '바로의 딸이 그녀에게 이르되, 이 아이를 데려가서 나를 위하여 젖을 먹이라, 내가 네 삯을 주리라. 그 여자가 아이를 데려다가 젖을 먹이니라.'),
(1565, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 10, 'OT', '아이가 자라매 그를 파라오의 딸에게로 데려가니 그가 그녀에게 아들이 되니라 그가 그의 이름을 모세라 하여 이르되 내가 그를 물에서 건져내었음이라 하였더라'),
(1566, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 11, 'OT', '그 때에 모세가 장성하여 그의 형제들에게 나가서 그들의 짐을 보았고, 한 애굽 사람이 그의 형제들 중 한 히브리 사람을 치는 것을 보았더라.'),
(1567, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 12, 'OT', '그가 이리저리 돌아보고 사람이 없음을 보고 그 애굽 사람을 쳐죽여 모래에 그를 감추니라'),
(1568, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 13, 'OT', '둘째 날에 그가 나가니, 보라 두 히브리 사람이 싸우고 있었고, 그가 그 악한 자에게 말하되, 어찌하여 네 친구를 치느냐 하니라.'),
(1569, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 14, 'OT', '그가 말하되 누가 너를 우리의 통치자와 재판관으로 세웠느냐? 네가 애굽 사람을 죽인 것 같이 나도 죽이려느냐? 모세가 두려워하여 말하되 참으로 이 말씀이 알려졌도다'),
(1570, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 15, 'OT', '파라오가 이 말씀을 듣고 모세를 죽이려고 찾았으나, 모세가 파라오의 얼굴을 피하여 미디안 땅에 거주하며 우물 곁에 앉았더라.'),
(1571, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 16, 'OT', '미디안 제사장에게 일곱 딸이 있었는데, 그들이 와서 물을 길어 구유에 채우고 그들의 아버지의 양떼에게 물을 먹이려 하였더라.'),
(1572, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 17, 'OT', '목자들이 와서 그들을 쫓아냈으나, 모세가 일어나 그들을 도와 그들의 양떼에게 물을 먹였더라.'),
(1573, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 18, 'OT', '그들이 그들의 아버지 르우엘에게 이르렀더니 그가 말하되, 너희가 오늘 어찌하여 이같이 속히 왔느냐?'),
(1574, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 19, 'OT', '한 애굽 사람이 우리를 목자들의 손에서 건져내고 또한 우리를 위하여 물을 길어 올려 양떼에게 먹였나이다'),
(1575, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 20, 'OT', '그가 그의 딸들에게 말하되, 그가 어디 있느냐? 어찌하여 너희가 그 사람을 버려 두고 왔느냐? 그를 불러 빵을 먹게 하라.'),
(1576, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 21, 'OT', '모세가 그 사람과 함께 거하기를 기뻐하였고, 그가 그의 딸 십보라를 모세에게 주었더라.'),
(1577, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 22, 'OT', '그가 아들을 낳으매 그가 그의 이름을 게르솜이라 불렀으니 이는 그가 말하기를 내가 낯선 땅에서 나그네가 되었도다 하였음이라'),
(1578, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 23, 'OT', '그 많은 날 후에 애굽 왕이 죽었고 이스라엘 자손들이 그 일로 인하여 탄식하며 부르짖으니 그들의 부르짖음이 그 일로 인하여 하나님께 올라갔더라'),
(1579, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 24, 'OT', '하나님이 그들의 신음을 들으시고 하나님이 아브라함과 이삭과 야곱과의 언약을 기억하셨다.'),
(1580, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 2, 25, 'OT', '하나님이 이스라엘 자손을 보시고 하나님이 아셨더라'),
(1581, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 1, 'OT', '모세가 그의 장인 미디안 제사장 이드로의 양떼를 치고 있었는데, 그가 그 양떼를 광야 뒤쪽으로 인도하여 하나님의 산 호렙에 이르렀더라.'),
(1582, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 2, 'OT', '여호와의 천사가 떨기나무 불꽃 중간에서 그에게 나타나니라 그가 보니 떨기나무가 불에 타고 있는데 그 떨기나무는 사라지지 아니하니라'),
(1583, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 3, 'OT', '모세가 이르되 내가 돌이켜 가서 이 큰 모습을 보리라 떨기나무가 어찌하여 타지 아니하는고 하니'),
(1584, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 4, 'OT', '여호와께서 그가 보려고 돌이켜 오는 것을 보시고, 하나님이 떨기나무 중간에서 그를 불러 이르시되 모세야, 모세야 하시매 그가 이르되 내가 여기 있나이다'),
(1585, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 5, 'OT', '그가 말하되, 이리로 가까이 오지 말라. 네 발에서 신을 벗으라. 네가 서 있는 그 장소는 거룩한 땅이니라.'),
(1586, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 6, 'OT', '또 그가 이르시되 나는 네 아버지의 하나님이요 아브라함의 하나님이요 이삭의 하나님이요 야곱의 하나님이니라 하시니 모세가 하나님을 바라보기를 두려워하여 얼굴을 가리매'),
(1587, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 7, 'OT', '여호와께서 말씀하시되, 내가 애굽에 있는 내 백성의 고난을 분명히 보았고, 그들의 압제자들로 인한 그들의 부르짖음을 들었나니, 이는 내가 그들의 고통을 앎이라.'),
(1588, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 8, 'OT', '내가 내려와서 그를 애굽 사람의 손에서 구원하고 그 땅에서 그를 인도하여 아름답고 넓은 땅, 젖과 꿀이 흐르는 땅, 곧 가나안 사람과 히타이트와 아모리와 브리스 사람과 히위와 여부스 사람의 장소로 데려가려 하노라.'),
(1589, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 9, 'OT', '이제 보라, 이스라엘 자손의 부르짖음이 내게 이르렀고, 애굽 사람이 그들을 압제하는 그 압제도 내가 보았노라.'),
(1590, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 10, 'OT', '이제 너는 가라, 내가 너를 파라오에게 보내리니, 내 백성 이스라엘의 아들들을 애굽에서 인도하여 내라.'),
(1591, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 11, 'OT', '모세가 하나님께 말하되, 내가 누구이기에 파라오에게 가며 이스라엘의 아들들을 애굽에서 인도하여 내리이까?'),
(1592, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 12, 'OT', '그가 말씀하시기를 내가 반드시 너와 함께 있으리라, 이것이 네게 표적이니 내가 너를 보낸 것이라, 네가 백성을 애굽에서 인도하여 낸 후에 너희가 이 산에서 하나님을 섬기리라.'),
(1593, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 13, 'OT', '모세가 하나님께 말씀드리되, 보소서, 내가 이스라엘 자손에게 가서 그들에게 말하기를 너희 아버지들의 하나님이 나를 너희에게 보내셨다 하면, 그들이 내게 말하기를 그의 이름이 무엇이냐 하리니, 내가 그들에게 무엇이라고 말하리이까?'),
(1594, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 14, 'OT', '하나님이 모세에게 이르시되 나는 스스로 있는 자니라 또 이르시되 너는 이스라엘 자손에게 이같이 이르기를 스스로 있는 자가 나를 너희에게 보내셨다 하라'),
(1595, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 15, 'OT', '하나님이 또 모세에게 말씀하시되 이스라엘 자손에게 이같이 말하라 너희 조상의 하나님 여호와, 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이 나를 너희에게 보내셨느니라 이것이 나의 영원한 이름이요 이것이 대대로 나의 기념이니라'),
(1596, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 16, 'OT', '가서 이스라엘 장로들을 모으고 그들에게 말하라. 너희 조상의 하나님 여호와, 곧 아브라함과 이삭과 야곱의 하나님이 내게 나타나 이르시되, 내가 반드시 너희를 돌보았고 애굽에서 너희에게 행해진 일을 보았노라.'),
(1597, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 17, 'OT', '내가 말하였노니 내가 너희를 애굽의 고난에서 인도하여 올라가게 하여 가나안 사람과 히타이트와 아모리와 브리스 사람과 히위와 여부스 사람의 땅으로, 젖과 꿀이 흐르는 땅으로 가게 하리라.'),
(1598, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 18, 'OT', '그들이 네 소리를 들을 것이며, 너는 이스라엘 장로들과 함께 애굽 왕에게 갈지니, 너희는 그에게 말하기를 히브리인의 하나님 여호와께서 우리에게 나타나셨나니 이제 우리가 우리 하나님 여호와께 제사드리려고 광야로 사흘 길을 가겠나이다 하라'),
(1599, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 19, 'OT', '내가 알았노니 애굽 왕이 너희를 가게 하지 아니하리라, 강한 손으로도 아니하리라.'),
(1600, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 20, 'OT', '내가 내 손을 펴서 애굽 사람을 그 속에서 내가 행할 모든 이적으로 치리니 그 후에 그가 너희를 보내리라'),
(1601, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 21, 'OT', '내가 이 백성에게 애굽 사람의 눈에 은혜를 주리니 너희가 갈 때에 빈 손으로 가지 아니하리라'),
(1602, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 3, 22, 'OT', '여자가 그 이웃에게와 자기 집에 거류하는 자에게 은 그릇과 금 그릇과 옷을 구하되 너희는 그것을 너희 아들들과 너희 딸들에게 입히고 애굽 사람의 것을 빼앗으리라'),
(1603, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 1, 'OT', '모세가 대답하여 이르되, 보라 그들이 나를 믿지 아니하며 내 소리를 듣지 아니하리니 이는 그들이 말하기를 여호와께서 네게 나타나지 아니하셨다 할 것임이니이다'),
(1604, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 2, 'OT', '여호와께서 그에게 이르시되 네 손에 있는 것이 무엇이냐? 그가 이르되 막대기니이다.'),
(1605, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 3, 'OT', '그가 말하되 그것을 땅에 던지라 하니 그가 그것을 땅에 던지매 그것이 뱀이 된지라 모세가 그 얼굴 앞에서 피하니라'),
(1606, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 4, 'OT', '여호와께서 모세에게 말씀하시되 네 손을 내밀어 그 꼬리를 잡으라 하시니 그가 손을 내밀어 그것을 붙잡으매 그것이 그의 손바닥에서 막대기가 되었더라'),
(1607, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 5, 'OT', '그들이 그들의 조상의 하나님 여호와, 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이 네게 나타나신 것을 믿게 하려 함이라.'),
(1608, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 6, 'OT', '여호와께서 또 그에게 이르시되 네 손을 네 품에 넣으라 하시매 그가 그의 손을 그의 품에 넣었다가 내어니 그의 손이 눈 같이 문둥병이 들었더라'),
(1609, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 7, 'OT', '그가 이르되 네 손을 네 품에 다시 넣으라 하시매 그가 그의 손을 그의 품에 다시 넣었다가 그의 품에서 그것을 꺼내니, 보라 그것이 그의 살과 같이 회복되었더라.'),
(1610, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 8, 'OT', '그들이 네 말을 믿지 아니하며 처음 표적의 소리를 듣지 아니할지라도, 그들은 나중 표적의 소리를 믿으리라.'),
(1611, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 9, 'OT', '그들이 이 두 표적도 믿지 아니하고 네 소리를 듣지 아니하거든, 너는 나일강의 물을 가져다가 마른 땅에 부으라. 네가 나일강에서 취한 물은 마른 땅에서 피가 되리라.'),
(1612, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 10, 'OT', '모세가 여호와께 말하여 이르되, 오 주님, 나는 말씀에 능한 사람이 아니오며, 어제도 그렇고 그제도 그렇고 주께서 주의 종에게 말씀하신 때부터도 그러하오니, 이는 내가 입이 무겁고 혀가 무거운 자임이니이다.'),
(1613, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 11, 'OT', '여호와께서 그에게 이르시되 누가 사람의 입을 지었느냐, 누가 벙어리나 귀머거리나 눈 밝은 자나 소경이 되게 하였느냐, 나 여호와가 아니냐?'),
(1614, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 12, 'OT', '이제 가라, 내가 네 입과 함께 있겠고 네가 말할 것을 가르치리라.'),
(1615, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 13, 'OT', '그가 이르되, 오 나의 주님, 청하건대 주께서 보내실 자의 손으로 보내소서.'),
(1616, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 14, 'OT', '여호와의 진노가 모세에게 불붙었고 그가 말씀하시되 네 형 레위인 아론이 있지 아니하냐? 그가 말을 잘할 줄을 내가 아노라 또한 보라 그가 너를 만나러 나오고 있으며 너를 볼 때에 그의 마음에 기뻐하리라'),
(1617, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 15, 'OT', '너는 그에게 말하고 그 말씀을 그의 입에 두라 내가 네 입과 그의 입에 함께 있어서 너희가 행할 것을 가르치리라'),
(1618, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 16, 'OT', '그가 너를 대신하여 백성에게 말할 것이며, 그는 네게 입이 될 것이요, 너는 그에게 하나님이 될 것이니라.'),
(1619, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 17, 'OT', '너는 이 막대기를 네 손에 잡으라, 네가 그것으로 표적을 행할 막대기니라.'),
(1620, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 18, 'OT', '모세가 장인 이드로에게로 돌아가서 그에게 이르되 `내가 애굽에 있는 내 형제들에게로 돌아가서 그들이 아직 살아 있는지 보리이다'' 하매 이드로가 모세에게 이르되 `평안히 가라'' 하니라'),
(1621, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 19, 'OT', '여호와께서 미디안에서 모세에게 이르시되 애굽으로 돌아가라 네 영혼을 찾던 모든 사람이 죽었느니라'),
(1622, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 20, 'OT', '모세가 그의 아내와 그의 아들들을 데려다가 나귀에 태우고 애굽 땅으로 돌아갔으며, 모세가 하나님의 막대기를 그의 손에 잡았더라.'),
(1623, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 21, 'OT', '여호와께서 모세에게 이르시되 네가 애굽으로 돌아가려고 갈 때에 내가 네 손에 둔 모든 기적을 바로의 얼굴 앞에서 행하라 그러나 내가 그의 마음을 강하게 하리니 그가 백성을 놓지 아니하리라'),
(1624, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 22, 'OT', '너는 파라오에게 말하라: 여호와께서 이같이 말씀하시되, 내 아들, 내 장자는 이스라엘이라.'),
(1625, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 23, 'OT', '내가 네게 말하기를 내 아들을 보내어 나를 섬기게 하라 하였으나 네가 그를 보내기를 거절하였으니 보라 내가 네 아들, 네 장자를 죽이리라.'),
(1626, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 24, 'OT', '길에서 여관에 이르렀을 때, 여호와께서 그를 만나 그를 죽이려 하셨더라.'),
(1627, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 25, 'OT', '십보라가 부싯돌을 취하여 그 아들의 포경을 베어 그의 발에 대며 말하되, “참으로 당신은 내게 피 사위로다” 하니라'),
(1628, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 26, 'OT', '그가 그를 놓으매 그 때에 그녀가 말하되, “피 사위여, 할례 때문에” 하였더라.'),
(1629, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 27, 'OT', '여호와께서 아론에게 말씀하시되 광야로 가서 모세를 맞으라 하시매 그가 가서 하나님의 산에서 그를 만나 그에게 입맞추니라'),
(1630, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 28, 'OT', '모세가 아론에게 여호와께서 그를 보내신 모든 말씀과 그에게 명하신 모든 표적을 고하니라'),
(1631, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 29, 'OT', '모세와 아론이 가서 이스라엘 아들들의 모든 장로들을 모았더라'),
(1632, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 30, 'OT', '아론이 여호와께서 모세에게 말씀하신 모든 말씀을 전하고 백성의 눈앞에서 표적을 행하니라'),
(1633, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 4, 31, 'OT', '백성이 믿으며 여호와께서 이스라엘 자손을 돌아보시고 그들의 고난을 보셨다는 말을 듣고 그들이 머리 숙여 경배하였더라'),
(1634, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 1, 'OT', '그 후에 모세와 아론이 들어가서 파라오에게 말하여 이르되, 이스라엘의 하나님 여호와께서 이같이 말씀하시기를, 내 백성을 보내라, 그들이 광야에서 내게 절기를 지킬 것이니라 하셨나이다.'),
(1635, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 2, 'OT', '파라오가 말하되, 여호와가 누구이기에 내가 그의 소리를 듣고 이스라엘을 보내겠느냐? 나는 여호와를 알지 못하노라, 그리고 이스라엘도 내가 보내지 아니하리라.'),
(1636, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 3, 'OT', '그들이 말하되 히브리인의 하나님이 우리에게 나타나셨으니 우리가 사흘 길을 광야로 가서 우리 하나님 여호와께 희생을 드리려 하오니 그가 역병이나 칼로 우리를 치실까 두렵나이다'),
(1637, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 4, 'OT', '애굽 왕이 그들에게 이르되, 너희 모세와 아론아, 어찌하여 백성을 그들의 행위에서 떼어 놓느냐? 가서 너희의 짐을 지라.'),
(1638, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 5, 'OT', '파라오가 말하되, 보라, 이제 땅의 백성이 많도다. 너희가 그들을 그들의 짐에서 쉬게 하는도다.'),
(1639, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 6, 'OT', '그 날에 파라오가 백성의 감독자들과 그들의 관리들에게 명령하여 이르되'),
(1640, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 7, 'OT', '너희는 다시는 백성에게 벽돌을 만들 짚을 전과 같이 주지 말지니, 그들이 가서 스스로 짚을 거두게 하라.'),
(1641, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 8, 'OT', '너희는 그들이 전에 만들던 벽돌의 정량을 그들에게 부과하고 그것에서 조금도 감하지 말라 그들이 게으르므로 이에 그들이 부르짖어 말하기를 우리가 가서 우리 하나님께 희생을 드리자 하느니라'),
(1642, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 9, 'OT', '그 일을 사람들에게 무겁게 하고 그들이 그것을 행하게 하며 그들이 거짓 말씀을 듣지 않게 하라'),
(1643, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 10, 'OT', '백성의 감독자들과 그들의 관리들이 나아가 백성에게 말하여 이르되, 파라오가 이같이 말하노라, 내가 너희에게 짚을 주지 아니하리라.'),
(1644, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 11, 'OT', '너희는 가서 너희가 찾을 수 있는 곳에서 짚을 가져오라. 너희 일에서 조금도 감하지 아니하리라.'),
(1645, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 12, 'OT', '백성이 애굽 온 땅에 흩어져서 짚 대신 검불을 거두러 갔더라'),
(1646, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 13, 'OT', '독촉하는 자들이 서둘러 말하여 이르되, 너희의 행위를 마치되, 날마다의 말씀대로, 짚이 있을 때와 같이 하라 하니라'),
(1647, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 14, 'OT', '이스라엘 자손의 패장들, 곧 파라오의 감독자들이 그들 위에 세운 자들이 매를 맞으며 이르되, "어찌하여 너희가 어제와 오늘에도 전과 같이 너희 법령의 벽돌 제조를 채우지 아니하였느냐?" 하였더라.'),
(1648, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 15, 'OT', '이스라엘 자손의 관리들이 와서 파라오에게 부르짖어 이르되, 어찌하여 당신의 종들에게 이같이 행하시나이까?'),
(1649, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 16, 'OT', '종에게 짚이 주어지지 아니하고 그들이 우리에게 벽돌을 만들라 말하나이다 보소서 종들이 매를 맞사오니 이는 왕의 백성의 허물이니이다'),
(1650, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 17, 'OT', '그가 말하되 너희가 게으르다, 게으르다 그러므로 너희가 말하기를 우리가 가서 여호와께 희생을 드리자 하는도다'),
(1651, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 18, 'OT', '그러므로 이제 가서 일하라, 짚은 너희에게 주어지지 아니할 것이며, 너희는 벽돌의 척도를 바칠지니라.'),
(1652, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 19, 'OT', '이스라엘 자손의 감독들이 그들이 곤경에 처한 것을 보고 말하기를 “너희는 너희의 매일의 벽돌 말씀에서 조금도 감하지 말라” 하니라'),
(1653, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 20, 'OT', '그들이 파라오에게서 나올 때에 모세와 아론이 그들을 맞이하려고 서 있는 것을 만났더라.'),
(1654, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 21, 'OT', '그들이 그들에게 말하되 여호와께서 너희를 감찰하시고 판단하시기를 원하노라 이는 너희가 우리의 향기를 파라오의 눈과 그의 종들의 눈에 악취가 되게 하여 그들의 손에 칼을 주어 우리를 죽이게 하였음이라'),
(1655, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 22, 'OT', '모세가 여호와께 돌아와서 말씀드리되, 주님, 어찌하여 이 백성에게 해를 끼치셨나이까? 어찌하여 나를 보내셨나이까?'),
(1656, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 5, 23, 'OT', '내가 파라오에게 와서 주의 이름으로 말한 때부터 이 백성에게 해를 끼쳤으며, 주께서는 주의 백성을 전혀 구원하지 아니하셨나이다.'),
(1657, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 1, 'OT', '여호와께서 모세에게 이르시되 이제 네가 보리라 내가 파라오에게 행할 것을 이는 강한 손으로 그가 그들을 보내리라 강한 손으로 그가 그들을 그의 땅에서 쫓아내리라'),
(1658, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 2, 'OT', '하나님이 모세에게 말씀하시고 그에게 이르시되 나는 여호와라'),
(1659, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 3, 'OT', '내가 아브라함과 이삭과 야곱에게 엘 전능자로 나타났으나, 나의 이름 여호와는 그들에게 알리지 아니하였느니라.'),
(1660, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 4, 'OT', '또한 내가 그들과 내 언약을 세웠으니 그들에게 가나안 땅, 곧 그들이 거주한 거주의 땅을 주기 위함이니라'),
(1661, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 5, 'OT', '또한 내가 이스라엘 자손이 애굽 사람에게 종이 되어 신음하는 소리를 들었고, 내 언약을 기억하노라.'),
(1662, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 6, 'OT', '그러므로 이스라엘 자손에게 말하라 나는 여호와라 내가 너희를 애굽의 짐 밑에서 이끌어 내며 그들의 일에서 너희를 건지고 편 팔과 큰 심판들로 너희를 구속하리라'),
(1663, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 7, 'OT', '내가 너희를 내 백성으로 삼고 내가 너희의 하나님이 되리니 너희는 내가 너희 하나님 여호와로서 애굽의 짐 아래에서 너희를 인도하여 낸 자인 줄 알지라'),
(1664, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 8, 'OT', '내가 너희를 아브라함과 이삭과 야곱에게 주기로 내 손을 들어 맹세한 땅으로 인도하고, 그 땅을 너희에게 유산으로 주리니 나는 여호와니라.'),
(1665, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 9, 'OT', '모세가 이같이 이스라엘 자손에게 말하였으나 그들이 영의 고통과 심한 일 때문에 모세의 말을 듣지 아니하였더라'),
(1666, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 10, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(1667, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 11, 'OT', '들어가서 애굽 왕 파라오에게 말하여 그가 이스라엘 아들들을 그의 땅에서 보내게 하라.'),
(1668, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 12, 'OT', '모세가 여호와의 얼굴 앞에서 말하여 이르되, 보라, 이스라엘의 아들들이 내 말을 듣지 아니하였거늘, 어떻게 파라오가 내 말을 듣겠느냐? 나는 입술이 둔한 자니이다.'),
(1669, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 13, 'OT', '여호와께서 모세와 아론에게 말씀하시고 그들에게 이스라엘 자손과 애굽 왕 파라오에게 명령을 내리게 하셨으니, 이스라엘 자손을 애굽 땅에서 인도하여 내게 하려 하심이니라.'),
(1670, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 14, 'OT', '이들은 그들의 조상 집의 머리들이라 이스라엘의 장자 르우벤의 아들들인 에녹과 발루와 헤스론과 갈미니 이들은 르우벤의 가족들이니라'),
(1671, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 15, 'OT', '시므온의 아들들은 여무엘과 야민과 오핫과 야긴과 소할과 가나안 여인의 아들 사울이니 이들은 시므온의 가족들이라.'),
(1672, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 16, 'OT', '이들은 그들의 세대대로 레위의 아들들의 이름이니 게르손과 그핫과 므라리요, 레위의 살아있는 해는 백삼십칠 년이었더라.'),
(1673, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 17, 'OT', '게르손의 아들들은 그들의 가족대로 리브니와 시므이더라.'),
(1674, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 18, 'OT', '그핫의 아들들은 암람과 이스할과 헤브론과 웃시엘이요, 그핫이 살아있는 해는 백삼십삼 년이었더라.'),
(1675, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 19, 'OT', '므라리의 아들들은 말리와 무시이니, 이들은 그들의 세대대로 레위의 가족들이다.'),
(1676, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 20, 'OT', '암람이 그의 고모 욥게벳을 자기 여자로 취하였고, 그가 그에게 아론과 모세를 낳았으며, 암람의 살아있는 해는 백삼십칠 해였더라.'),
(1677, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 21, 'OT', '이스할의 아들들은 고라와 네펙과 시크리더라.'),
(1678, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 22, 'OT', '웃시엘의 아들들은 미사엘과 엘리사반과 시드리더라'),
(1679, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 23, 'OT', '아론이 엘리세바를 취하였으니 그녀는 암미나답의 딸이요 나손의 자매라 그가 그를 아내로 삼았고 그녀가 그에게 나답과 아비후와 엘르아살과 이타말을 낳았더라'),
(1680, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 24, 'OT', '고라의 아들들은 아시르와 엘가나와 아비아삽이니, 이들은 고라 사람의 가족들이다.'),
(1681, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 25, 'OT', '엘르아살은 아론의 아들로서 푸티엘의 딸들 중에서 그에게 여자를 아내로 취하였고, 그가 그에게 비느하스를 낳았으니, 이들은 레위인들의 아버지들의 머리들이 그들의 가족들에 따라 있느니라.'),
(1682, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 26, 'OT', '이 아론과 모세니라 여호와께서 그들에게 이르시되 너희는 이스라엘 자손을 그 군대대로 애굽 땅에서 인도하여 내라 하셨느니라'),
(1683, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 27, 'OT', '그들이 애굽 왕 파라오에게 말하여 이스라엘 자손을 애굽에서 인도해 내려 한 자들이니, 이는 모세와 아론이니라.'),
(1684, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 28, 'OT', '여호와께서 애굽 땅에서 모세에게 말씀하신 날에 그 일이 있었더라.'),
(1685, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 29, 'OT', '여호와께서 모세에게 말씀하여 이르시되 나는 여호와라 너는 내가 네게 말하는 모든 것을 애굽 왕 파라오에게 말하라'),
(1686, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 6, 30, 'OT', '모세가 여호와의 얼굴 앞에서 말하되, 보라 나는 입술이 둔한 자인데 어찌 파라오가 내게 들으리요'),
(1687, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 1, 'OT', '여호와께서 모세에게 말씀하시되 보라 내가 너를 파라오에게 하나님이 되게 하였고 네 형 아론은 네 예언자가 되리라'),
(1688, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 2, 'OT', '너는 내가 네게 명령하는 모든 것을 말할지니라. 네 형 아론은 파라오에게 말할 것이요, 그가 이스라엘의 아들들을 그의 땅에서 보내리라.'),
(1689, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 3, 'OT', '내가 파라오의 마음을 완악하게 하겠다. 그리고 내가 애굽 땅에서 나의 표적과 나의 기적을 많게 하겠다.'),
(1690, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 4, 'OT', '바로가 너희에게 듣지 아니할 것이며 내가 내 손을 애굽에 두리라 그리고 내가 내 군대, 내 백성 이스라엘 자손을 큰 심판들로 애굽 땅에서 인도하여 내리라'),
(1691, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 5, 'OT', '애굽 사람들이 내가 여호와인 줄 알리라 내가 내 손을 애굽 위에 펼 때에 이스라엘 자손을 그들 중간에서 인도하여 내리라'),
(1692, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 6, 'OT', '모세와 아론이 여호와께서 그들에게 명령하신 대로 그렇게 행하였더라.'),
(1693, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 7, 'OT', '모세는 팔십 해의 아들이었고, 아론은 팔십삼 해의 아들이었으며, 그들이 파라오에게 말할 때였다.'),
(1694, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 8, 'OT', '여호와께서 모세와 아론에게 말씀하여 이르시되'),
(1695, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 9, 'OT', '파라오가 너희에게 말하여 이르기를 너희를 위하여 기적을 보이라 할 때에, 너는 아론에게 말하기를 네 막대기를 가져다가 파라오의 얼굴 앞에 던지라, 그것이 용이 되리라 하라.'),
(1696, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 10, 'OT', '모세와 아론이 파라오에게 들어가서 여호와께서 명령하신 대로 행하니라. 아론이 그의 막대기를 파라오의 얼굴 앞과 그의 종들의 얼굴 앞에 던졌더니 그것이 용이 되었더라.'),
(1697, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 11, 'OT', '파라오도 현자들과 마술사들을 불렀고, 애굽의 마술사들도 그들의 불꽃으로 그와 같이 행하였더라.'),
(1698, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 12, 'OT', '그들이 각자 자기 막대기를 던지매 그것들이 용이 되었고 아론의 막대기가 그들의 막대기들을 삼켰더라'),
(1699, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 13, 'OT', '파라오의 마음이 강퍅하여 그들이 말을 듣지 아니하였으니 여호와께서 말씀하신 대로였더라.'),
(1700, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 14, 'OT', '여호와께서 모세에게 이르시되 파라오의 마음이 완고하여 백성 보내기를 거절하는도다'),
(1701, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 15, 'OT', '아침에 바로에게로 가라, 보라 그가 물로 나오리니, 너는 나일강 입술가에 서서 그를 맞이하고, 뱀으로 변한 그 막대기를 네 손에 잡을지니라.'),
(1702, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 16, 'OT', '너는 그에게 말하라 여호와 히브리인의 하나님이 나를 네게 보내어 이르시되 내 백성을 보내라 그들이 광야에서 나를 섬기게 하라 하셨느니라 그러나 보라 네가 이제까지 듣지 아니하였도다'),
(1703, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 17, 'OT', '여호와께서 이같이 말씀하시되, 네가 이것으로 내가 여호와인 줄 알리라. 보라, 내가 내 손에 있는 막대기로 나일강의 물을 치리니, 그것들이 피로 변하리라.'),
(1704, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 18, 'OT', '나일강에 있는 물고기는 죽을 것이요, 나일강은 악취가 나리니 애굽 사람들이 나일강의 물 마시기를 싫어하리라.'),
(1705, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 19, 'OT', '여호와께서 모세에게 이르시되 아론에게 말하라 네 막대기를 가지고 네 손을 애굽의 물들 위에, 그들의 강들 위에, 그들의 나일강들 위에, 그들의 늪들 위에, 그리고 그들의 모든 물 고임 위에 펴라 그것들이 피가 되리라 그리고 애굽의 모든 땅과 나무와 돌에 피가 있으리라'),
(1706, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 20, 'OT', '모세와 아론이 여호와께서 명령하신 대로 행하여 바로의 눈과 그의 종들의 눈 앞에서 막대기를 들어 나일강에 있는 물을 치니 나일강에 있는 모든 물이 피로 변하니라'),
(1707, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 21, 'OT', '나일강의 물고기가 죽었고 나일강이 악취가 났으며 애굽 사람들이 나일강의 물을 마실 수 없었고 나일강의 물이 모든 애굽 땅에 피가 되었더라'),
(1708, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 22, 'OT', '애굽의 마술사들도 그들의 은밀한 술법으로 그와 같이 행하였고, 파라오의 마음이 강퍅하여 그들의 말을 듣지 아니하였으니, 여호와께서 말씀하신 대로였더라.'),
(1709, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 23, 'OT', '파라오가 돌이켜 그의 집으로 들어갔고, 그도 이 일에 마음을 두지 아니하였더라.'),
(1710, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 24, 'OT', '모든 애굽 사람들은 나일강 주위를 파서 마실 물을 구하였으니, 이는 그들이 나일강의 물을 마실 수 없었기 때문이었더라.'),
(1711, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 7, 25, 'OT', '여호와께서 나일강을 치신 후에 칠 일이 차니라.'),
(1712, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되, 파라오에게 가서 그에게 말하라, 여호와께서 이같이 말씀하시되, 내 백성을 보내라, 그들이 나를 섬기게 하라.'),
(1713, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 2, 'OT', '만일 네가 보내기를 거절하면, 보라, 내가 네 모든 경계를 개구리로 칠 것이다.'),
(1714, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 3, 'OT', '나일강이 개구리로 가득 차게 되고 그것들이 올라와 네 집과 네 침상의 안방과 네 침상 위에 들어가며 네 종들의 집과 네 백성에게와 네 화덕들과 네 반죽 그릇들에 들어가리라'),
(1715, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 4, 'OT', '개구리들이 너와 네 백성과 네 모든 종들에게 올라오리라.'),
(1716, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 5, 'OT', '여호와께서 모세에게 이르시되 아론에게 말하라 네 손을 네 막대기로 강들과 나일강들과 늪들 위에 내밀어 개구리들을 애굽 땅 위에 올라오게 하라'),
(1717, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 6, 'OT', '아론이 그의 손을 애굽의 물들 위에 펴매 개구리가 올라와서 애굽 땅을 덮었더라'),
(1718, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 7, 'OT', '마술사들도 그들의 은밀한 술법대로 그렇게 하여 개구리들을 애굽 땅 위로 올라오게 하였더라.'),
(1719, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 8, 'OT', '바로가 모세와 아론을 불러 이르되 여호와께 간구하여 개구리를 나와 내 백성에게서 떠나게 하라 내가 그 백성을 보내리니 그들이 여호와께 희생을 드릴 것이니라'),
(1720, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 9, 'OT', '모세가 파라오에게 이르되, 내가 너를 위하여 어느 때에 간구하리이까? 너와 네 종들과 네 백성을 위하여 개구리들을 네게서와 네 집들에서 끊어서 나일강에만 남게 하리이까? 내게 영광을 돌리소서.'),
(1721, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 10, 'OT', '그가 말하되 내일이니라. 또 그가 말하되 네 말씀대로 하여 우리 하나님 여호와와 같은 이가 없는 줄을 네가 알게 하려 함이니라.'),
(1722, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 11, 'OT', '개구리들이 네게서, 네 집에서, 네 종들에게서, 네 백성에게서 떠나리니 오직 나일 강에만 남으리라'),
(1723, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 12, 'OT', '모세와 아론이 파라오에게서 나가니, 모세가 파라오에게 내리신 개구리 말씀으로 인하여 여호와께 부르짖으니라.'),
(1724, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 13, 'OT', '여호와께서 모세의 말씀대로 행하시니 개구리들이 집들과 뜰들과 들판에서 죽었더라.'),
(1725, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 14, 'OT', '그들이 그것들을 진흙 무더기, 진흙 무더기로 쌓았고, 땅에서 악취가 났더라.'),
(1726, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 15, 'OT', '파라오가 숨돌림이 있음을 보고 그의 마음을 완강하게 하여 그들을 듣지 아니하였으니 여호와께서 말씀하신 대로였더라.'),
(1727, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 16, 'OT', '여호와께서 모세에게 이르시되 아론에게 말하라 네 막대기를 내밀어 땅의 흙을 치라 그것이 애굽 온 땅에서 이가 되리라'),
(1728, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 17, 'OT', '그들이 그대로 행하니 아론이 그의 막대기로 그의 손을 내밀어 땅의 흙을 치매 이가 사람과 짐승에게 있었으며 땅의 모든 흙이 애굽 온 땅에서 이가 되었더라'),
(1729, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 18, 'OT', '마술사들이 그들의 은밀한 술법으로 이를 내려 하였으나 능히 하지 못하였고, 이는 사람과 짐승에게 있었더라.'),
(1730, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 19, 'OT', '마술사들이 파라오에게 말하되 "이것은 하나님의 손가락이니이다" 하였으나 파라오의 마음이 강퍅해져 그들이 말을 듣지 아니하였으니 여호와께서 말씀하신 대로였더라.'),
(1731, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 20, 'OT', '여호와께서 모세에게 말씀하시되 아침에 일찍 일어나 바로의 얼굴 앞에 서라, 보라 그가 물로 나오리니, 그에게 말하라 여호와께서 이같이 말씀하시되 내 백성을 보내라 그들이 나를 섬기게 하라'),
(1732, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 21, 'OT', '만일 네가 내 백성을 보내지 아니하면, 보라, 내가 너와 네 종들과 네 백성과 네 집들에 파리 떼를 보내리니, 애굽 사람의 집들이 그 파리 떼로 가득할 것이며, 그들이 그 위에 있는 땅에도 그러하리라.'),
(1733, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 22, 'OT', '그 날에 내가 내 백성이 그 위에 서 있는 고센 땅을 구별하여 그 곳에 파리 떼가 없게 하리니 이는 내가 땅 속에 있는 여호와인 줄을 네가 알게 하려 함이라'),
(1734, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 23, 'OT', '내가 내 백성과 네 백성 사이에 구속을 두리니 내일 이 표적이 있으리라.'),
(1735, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 24, 'OT', '여호와께서 그대로 행하셨으니 무거운 파리 떼가 파라오의 집과 그의 종들의 집에 들어왔고 애굽 온 땅에 이르렀으며 파리 떼의 얼굴로 인하여 땅이 망가지니라'),
(1736, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 25, 'OT', '파라오가 모세와 아론을 불러 이르되, 너희는 가서 이 땅에서 너희 하나님께 희생을 드리라.'),
(1737, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 26, 'OT', '모세가 말하되, 우리가 우리 하나님 여호와께 애굽 사람의 가증한 것을 제사로 드리는 것은 합당하지 아니하니, 보라, 우리가 그들의 눈 앞에서 애굽 사람의 가증한 것을 제사로 드리면 그들이 우리를 돌로 치지 아니하겠느냐?'),
(1738, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 27, 'OT', '우리가 사흘 길을 광야로 가서 우리 하나님 여호와께 희생을 드리되 그가 우리에게 말씀하시는 대로 하려 하나이다'),
(1739, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 28, 'OT', '파라오가 말하되, 내가 너희를 보내리니 너희가 너희 하나님 여호와께 광야에서 희생을 드릴 것이나, 너희가 가되 너무 멀리 가지 말지니라. 너희는 나를 위하여 간구하라.'),
(1740, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 29, 'OT', '모세가 말하되, 보라 내가 네게서 나가서 여호와께 간구하리니 파리 떼가 내일 파라오와 그의 종들과 그의 백성에게서 떠나리라, 오직 파라오는 다시 속임을 행하여 백성을 보내어 여호와께 희생을 드리지 못하게 하지 말지니라'),
(1741, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 30, 'OT', '모세가 파라오에게서 나가서 여호와께 간청하니라'),
(1742, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 31, 'OT', '여호와께서 모세의 말씀대로 행하사 파리 떼를 파라오와 그의 종들과 그의 백성에게서 제거하셨으니, 하나도 남지 아니하였더라.'),
(1743, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 8, 32, 'OT', '파라오가 이 때에도 그의 마음을 완강하게 하였고, 백성을 보내지 아니하였더라.'),
(1744, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 1, 'OT', '여호와께서 모세에게 말씀하시되 파라오에게 들어가서 그에게 말하라 여호와께서 이같이 말씀하시되 히브리인의 하나님이여 내 백성을 보내라 그들이 나를 섬기리라'),
(1745, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 2, 'OT', '네가 만일 그들을 보내기를 거절하고 여전히 그들을 붙잡고 있으면'),
(1746, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 3, 'OT', '보라, 여호와의 손이 들에 있는 네 가축, 곧 말과 나귀와 낙타와 소와 양떼 위에 임하리니, 심히 중한 역병이 있으리라.'),
(1747, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 4, 'OT', '여호와가 이스라엘의 가축과 애굽의 가축을 구별하리니 이스라엘 자손의 모든 가축 중에서 하나도 죽지 아니하리라'),
(1748, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 5, 'OT', '여호와께서 정한 때를 두어 이르시되, 내일 여호와께서 이 땅에서 이 말씀을 행하시리라 하셨더라.'),
(1749, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 6, 'OT', '여호와께서 이 말씀을 이튿날에 행하시니 애굽 사람의 모든 가축은 죽었으나 이스라엘 아들들의 가축은 하나도 죽지 아니하였더라'),
(1750, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 7, 'OT', '바로가 보내어 보니, 이스라엘의 가축 중 하나도 죽지 아니하였더라. 그러나 바로의 마음이 무거워져서 백성을 보내지 아니하니라.'),
(1751, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 8, 'OT', '여호와께서 모세와 아론에게 말씀하여 이르시되, 너희는 용광로의 재를 너희 주먹에 가득 채워 가지라, 모세가 파라오의 눈 앞에서 하늘을 향하여 그것을 뿌릴지니라.'),
(1752, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 9, 'OT', '그것이 애굽 온 땅에 먼지가 되고, 애굽 온 땅의 사람과 짐승에게 터지는 물집 있는 종기가 되리라.'),
(1753, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 10, 'OT', '그들이 용광로의 재를 가져다가 파라오의 얼굴 앞에 서서, 모세가 그것을 하늘을 향해 뿌리니, 사람과 짐승에게 터지는 물집이 있는 종기가 생겼더라.'),
(1754, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 11, 'OT', '마술사들이 종기로 인하여 모세의 얼굴 앞에 서지 못하였으니, 이는 종기가 마술사들과 모든 애굽 사람들에게 있었음이라.'),
(1755, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 12, 'OT', '여호와께서 파라오의 마음을 강하게 하셨으므로 그가 그들의 말을 듣지 아니하였으니 여호와께서 모세에게 말씀하신 것과 같았더라.'),
(1756, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 13, 'OT', '여호와께서 모세에게 이르시되 아침에 일찍 일어나 바로의 얼굴 앞에 서서 그에게 말하라 여호와 곧 히브리인의 하나님이 이같이 말하노라 내 백성을 보내라 그들이 나를 섬기게 하라'),
(1757, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 14, 'OT', '이번에는 내가 나의 모든 재앙을 네 마음과 네 종들과 네 백성에게 보내리니, 이는 온 땅에 나와 같은 이가 없음을 네가 알게 하려 함이라.'),
(1758, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 15, 'OT', '내가 지금 내 손을 펴서 너와 네 백성을 역병으로 쳤더라면 네가 땅에서 끊어졌을 것이니라'),
(1759, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 16, 'OT', '그러나 내가 너를 세운 것은 바로 이 까닭이니, 곧 내 힘을 네게 보이기 위함이요, 내 이름이 모든 땅에 전파되게 하기 위함이니라.'),
(1760, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 17, 'OT', '네가 여전히 내 백성 앞에서 스스로 높여 그들을 보내지 아니하려 하느냐'),
(1761, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 18, 'OT', '보라 내일 이맘때에 내가 심히 중한 우박을 내리리니 애굽에 그 같은 것이 있지 아니하였느니라 그 날이 세움으로부터 지금까지'),
(1762, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 19, 'OT', '이제 너의 가축과 들에 있는 네 모든 것을 보내어 모으라. 들에서 발견되는 모든 사람과 짐승, 집으로 모이지 않은 자에게는 우박이 그들 위에 내려 그들이 죽으리라.'),
(1763, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 20, 'OT', '여호와의 말씀을 두려워하는 파라오의 종들 중에 있는 자는 그의 종들과 그의 가축을 집들로 피하게 하였더라'),
(1764, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 21, 'OT', '여호와의 말씀에 마음을 두지 아니한 자는 그의 종들과 그의 가축을 들판에 버려 두었더라'),
(1765, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 22, 'OT', '여호와께서 모세에게 이르시되 네 손을 하늘을 향하여 내밀라 그리하면 애굽 온 땅에 우박이 있으리니 사람과 짐승과 들의 모든 풀 위에 애굽 땅에 내리리라'),
(1766, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 23, 'OT', '모세가 그의 막대기를 하늘을 향하여 내밀매 여호와께서 소리와 우박을 주시고 불이 땅으로 달려가게 하셨으며 여호와께서 우박을 애굽 땅에 내리셨더라'),
(1767, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 24, 'OT', '우박이 내리고 불이 우박 가운데서 번쩍이며 섞여 내렸는데, 심히 중하여 애굽 온 땅에 그 나라가 된 이래로 그와 같은 것이 없었더라.'),
(1768, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 25, 'OT', '우박이 애굽 온 땅에서 들판에 있는 모든 것을 사람부터 짐승까지 쳤으며, 우박이 들판의 모든 풀을 쳤고 들판의 모든 나무를 부러뜨렸더라.'),
(1769, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 26, 'OT', '오직 이스라엘 자손이 있는 고센 땅에는 우박이 없었더라'),
(1770, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 27, 'OT', '바로가 사람을 보내어 모세와 아론을 불러 그들에게 이르되 내가 이번에 범죄하였나이다 여호와는 의로우시고 나와 내 백성은 악하나이다'),
(1771, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 28, 'OT', '여호와께 간청하라, 하나님의 소리와 우박이 그치기에 충분하니, 내가 너희를 보내리라, 너희가 다시는 머물지 아니하리라.'),
(1772, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 29, 'OT', '모세가 그에게 이르되, 내가 성에서 나가자 내 손바닥을 여호와를 향하여 펴리니, 그리하면 소리들이 그치고 우박이 다시 있지 않을지라, 이는 땅이 여호와께 속한 줄을 네가 알게 하려 함이니라.'),
(1773, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 30, 'OT', '그러나 당신과 당신의 종들에 대하여는, 내가 아나이다 당신들이 아직 여호와 하나님의 얼굴을 두려워하지 아니할 줄을.'),
(1774, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 31, 'OT', '아마와 보리는 맞았으니 이는 보리는 이삭이요 아마는 볼이었음이라'),
(1775, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 32, 'OT', '밀과 쌀보리는 상하지 아니하였으니 이는 그들이 아직 자라지 아니하였음이라.'),
(1776, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 33, 'OT', '모세가 파라오에게서 나와 그 도시를 떠나 여호와를 향하여 손바닥을 펴니 소리와 우박이 그치고 비가 땅에 쏟아지지 아니하니라'),
(1777, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 34, 'OT', '파라오가 비와 우박과 소리가 그친 것을 보고 다시 죄를 범하며 그의 마음을 완악하게 하였으니 그와 그의 종들이 그리하였더라'),
(1778, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 9, 35, 'OT', '바로의 마음이 강퍅해졌고 그가 이스라엘 자손을 보내지 아니하였으니, 여호와께서 모세의 손을 통해 말씀하신 것과 같았더라.'),
(1779, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 1, 'OT', '여호와께서 모세에게 이르시되 파라오에게로 들어가라 내가 그의 마음과 그의 종들의 마음을 완강하게 하였음은 나의 이 표적들을 그 속에 두기 위함이니라'),
(1780, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 2, 'OT', '또한 내가 애굽에서 행한 일들과 그들 가운데서 내가 세운 내 표적들을 네 아들과 네 아들의 아들의 귀에 전하게 하려 함이니 너희는 내가 여호와인 줄 알리라'),
(1781, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 3, 'OT', '모세와 아론이 파라오에게 들어가서 그에게 말하되, 히브리인의 하나님 여호와께서 이렇게 말씀하시기를, 네가 언제까지 내 얼굴 앞에서 겸비하기를 거부하겠느냐? 내 백성을 보내라, 그들이 나를 섬기게 하라.'),
(1782, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 4, 'OT', '만일 네가 내 백성 보내기를 거절하면, 보라, 내일 내가 메뚜기를 네 경계 안에 들어오게 하리라.'),
(1783, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 5, 'OT', '그것이 땅의 눈을 덮어서 사람이 땅을 볼 수 없게 되리라 그것이 너희에게 우박에서 남아 있는 도피의 남은 것을 먹으며 들에서 너희를 위하여 자라는 모든 나무를 먹으리라'),
(1784, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 6, 'OT', '네 집들과 네 모든 종들의 집들과 모든 애굽 사람들의 집들에 가득하리니, 이는 네 아버지들과 네 조상들이 땅 위에 있던 날부터 오늘까지 보지 못하였던 것이니라. 그가 돌이켜 파라오에게서 나가니라.'),
(1785, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 7, 'OT', '바로의 신하들이 그에게 말하되, "이 사람이 우리에게 덫이 된 지가 언제까지이리이까? 그 사람들을 보내어 그들의 하나님 여호와를 섬기게 하소서. 왕은 아직도 애굽이 망한 줄을 알지 못하시나이까?"'),
(1786, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 8, 'OT', '모세와 아론을 파라오에게로 다시 데려오니 그가 그들에게 이르되, 가서 너희 하나님 여호와를 섬기라. 누구 누구가 갈 자들이냐?'),
(1787, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 9, 'OT', '모세가 말하되 우리 소년들과 우리 노인들과 함께 가겠나이다 우리 아들들과 우리 딸들과 우리 양떼와 우리 소들과 함께 가겠나이다 이는 우리에게 여호와의 축제가 있음이니이다'),
(1788, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 10, 'OT', '그가 그들에게 말하되, “여호와께서 너희와 함께하시기를 내가 너희와 너희 어린아이들을 보낼 때와 같이 하시리라. 보라, 너희 얼굴 앞에 악이 있느니라.”'),
(1789, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 11, 'OT', '아니라, 가라, 너희 사내들아, 여호와를 섬기라, 그것이 너희가 구하는 바이니라. 그들이 파라오의 얼굴 앞에서 쫓겨나니라.'),
(1790, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 12, 'OT', '여호와께서 모세에게 이르시되 네 손을 애굽 땅 위에 내밀어 메뚜기로 애굽 땅에 올라와서 땅의 모든 풀, 곧 우박이 남긴 모든 것을 먹게 하라'),
(1791, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 13, 'OT', '모세가 애굽 땅 위에 그의 막대기를 내밀매 여호와께서 동풍을 그 땅에 그 온 날과 온 밤에 불게 하셨고 아침이 되매 동풍이 메뚜기를 실어 왔더라'),
(1792, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 14, 'OT', '메뚜기가 애굽 온 땅에 올라와서 애굽 모든 경계에 내렸는데, 심히 중하였으니 그 얼굴 앞에는 이런 메뚜기가 없었고 그 후에도 이런 일이 있지 아니하리라.'),
(1793, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 15, 'OT', '그들이 온 땅의 눈을 덮으매 땅이 어두워졌고 우박이 남기지 아니한 땅의 모든 풀과 나무의 모든 열매를 먹었으며 애굽 온 땅에 나무와 들판의 풀에 푸성귀가 하나도 남지 아니하였더라'),
(1794, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 16, 'OT', '바로가 급히 모세와 아론을 부르고 이르되 내가 너희 하나님 여호와와 너희에게 범죄하였나이다'),
(1795, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 17, 'OT', '그러므로 이제 내 죄를 이번만이라도 용서하소서, 너희 하나님 여호와께 간구하여 이 사망만을 내게서 떠나게 하소서.'),
(1796, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 18, 'OT', '그가 파라오에게서 나가서 여호와께 간구하니라'),
(1797, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 19, 'OT', '여호와께서 강하고 매우 센 바다의 영을 돌이키사 메뚜기를 들어 올려 갈대 바다에 던지셨으니 애굽의 모든 경계에 메뚜기 하나도 남지 아니하였더라'),
(1798, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 20, 'OT', '여호와께서 파라오의 마음을 강하게 하셨고, 그가 이스라엘의 아들들을 보내지 아니하였더라.'),
(1799, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 21, 'OT', '여호와께서 모세에게 이르시되 하늘을 향하여 네 손을 내밀라 애굽 땅 위에 어둠이 있게 하리니 곧 만질 수 있는 어둠이리라'),
(1800, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 22, 'OT', '모세가 하늘을 향하여 그의 손을 내밀매 캄캄한 어둠이 애굽 온 땅에 삼 일 동안 있었더라'),
(1801, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 23, 'OT', '사람이 자기 형제를 보지 못하였고 삼 일 동안 사람이 자기 자리에서 일어나지 못하였으며 모든 이스라엘 아들들의 거주지에는 빛이 있었더라'),
(1802, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 24, 'OT', '바로가 모세를 불러 이르되, 너희는 가서 여호와를 섬기라, 다만 너희 양떼와 소는 머물러 두고, 너희 어린아이들도 너희와 함께 갈지니라.'),
(1803, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 25, 'OT', '모세가 말하되, 너도 우리 손에 제사와 번제를 주어야 하겠고, 우리가 우리 하나님 여호와께 드리리라.'),
(1804, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 26, 'OT', '또한 우리의 가축도 우리와 함께 가리니 굽 하나도 남기지 아니하리라 이는 우리가 그 중에서 취하여 우리 하나님 여호와를 섬길 것임이요 우리가 거기 이르기까지는 무엇으로 여호와를 섬길는지 알지 못함이니이다'),
(1805, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 27, 'OT', '여호와께서 파라오의 마음을 강하게 하셨고 그가 그들을 보내기를 원하지 아니하니라'),
(1806, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 28, 'OT', '바로가 그에게 이르되, 내게서 떠나가라. 스스로 삼가 내 얼굴을 다시 보지 말라. 네가 내 얼굴을 보는 날에는 네가 죽으리라.'),
(1807, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 10, 29, 'OT', '모세가 말하되, 왕이 말씀하신 대로 하겠나이다. 내가 다시는 왕의 얼굴을 보지 아니하리이다.'),
(1808, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 1, 'OT', '여호와께서 모세에게 이르시되 내가 아직 한 가지 상처를 파라오와 애굽에 내리리니 그 후에야 그가 너희를 여기서 보내리라 그가 너희를 보낼 때에는 반드시 소멸로 너희를 여기서 쫓아내리라'),
(1809, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 2, 'OT', '백성의 귀에 말하되 사람이 그의 친구에게서, 여자가 그의 동료에게서 은 그릇과 금 그릇을 구하게 하라.'),
(1810, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 3, 'OT', '여호와께서 애굽 사람들의 눈에 백성에게 은혜를 주셨고, 또한 그 사람 모세는 애굽 땅에서 바로의 종들의 눈과 백성의 눈에 심히 컸더라.'),
(1811, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 4, 'OT', '모세가 말하되 여호와께서 이같이 말씀하시기를 한밤중에 내가 애굽 중간으로 나가리라'),
(1812, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 5, 'OT', '애굽 땅에 있는 모든 장자가 죽으리니 곧 왕좌에 앉은 파라오의 장자로부터 맷돌 뒤에 있는 여종의 장자까지와 모든 짐승의 장자까지라.'),
(1813, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 6, 'OT', '애굽 온 땅에 큰 부르짖음이 있으리니, 그와 같은 것이 있은 적이 없었고, 그와 같은 것이 다시 있지 아니하리라.'),
(1814, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 7, 'OT', '그러나 모든 이스라엘 자손에게는 사람에게나 짐승에게나 개가 그 혀를 움직이지 아니하리니 여호와가 애굽과 이스라엘 사이에 구별하시는 줄을 너희가 알게 하려 함이니라'),
(1815, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 8, 'OT', '당신의 이 모든 종들이 내게 내려와 내게 절하며 이르기를, 너와 네 발 아래 있는 모든 백성은 나가라, 그 후에야 내가 나가리라 하리라. 그가 심히 노하여 파라오에게서 나오니라.'),
(1816, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 9, 'OT', '여호와께서 모세에게 이르시되, 파라오가 너희에게 듣지 아니하리니, 이는 내 기적을 애굽 땅에서 많게 하려 함이라.'),
(1817, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 11, 10, 'OT', '모세와 아론이 이 모든 기적을 파라오의 얼굴 앞에서 행하였으나 여호와께서 파라오의 마음을 강하게 하셨으므로 그가 이스라엘의 아들들을 그의 땅에서 보내지 아니하였더라'),
(1818, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 1, 'OT', '여호와께서 애굽 땅에서 모세와 아론에게 말씀하여 이르시되'),
(1819, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 2, 'OT', '이 달은 너희에게 달들의 머리가 되고, 그것은 너희에게 해의 달들의 첫째가 되느니라.'),
(1820, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 3, 'OT', '이스라엘의 모든 회중에게 말하여 이르기를, 이 달 열흘에 그들이 각자 아버지의 집을 위하여 양을, 집을 위하여 양을 취할지니라.'),
(1821, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 4, 'OT', '만일 그 집이 양 한 마리에 부족하여 적으면, 그 사람과 그의 집에서 가장 가까운 이웃이 영혼의 수대로 함께 취할 것이요, 각 사람이 먹는 분량에 따라 너희가 그 양에 대하여 계산할지니라.'),
(1822, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 5, 'OT', '너희 양은 흠 없고 수컷이며 일년 된 아들이 되리라; 어린양 중에서와 염소 중에서 취할지니라'),
(1823, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 6, 'OT', '너희를 위하여 파수가 되리니 이 달 십사일까지 간직하였다가 이스라엘의 모든 회중이 저녁 사이에 그것을 잡을지니라'),
(1824, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 7, 'OT', '그들이 그 피를 취하여 그 양을 먹을 집들의 좌우 문설주와 문지방에 바를지니라'),
(1825, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 8, 'OT', '그들이 그 밤에 그 살을 먹을지니 불에 구운 고기와 누룩 없는 빵을 쓴맛과 함께 먹을지라'),
(1826, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 9, 'OT', '그것을 날로 먹지 말고 물에 삶아서도 먹지 말고, 오직 불에 구운 고기로, 그 머리와 다리와 속을 다하여 먹을지니라.'),
(1827, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 10, 'OT', '너희는 그것을 아침까지 남겨 두지 말고, 아침까지 그것에게서 남은 것은 불로 태울지니라.'),
(1828, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 11, 'OT', '너희는 그것을 이렇게 먹을지니, 너희 허리는 띠로 동이고, 너희 신발은 너희 발에 신고, 너희 막대기는 너희 손에 들고, 너희는 그것을 히파존으로 먹을지니, 이것이 여호와의 유월절이니라.'),
(1829, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 12, 'OT', '내가 이 밤에 애굽 땅을 두루 다니며 애굽 땅에 있는 모든 장자를 사람에게서부터 짐승까지 치리니 내가 애굽의 모든 신에게 심판을 행하리라 나는 여호와라'),
(1830, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 13, 'OT', '그 피가 너희를 위하여 너희가 있는 집들 위에 표적이 될지니 내가 그 피를 보고 너희를 넘어가리라 내가 애굽 땅을 칠 때에 파멸시키는 역병이 너희에게 있지 아니하리라'),
(1831, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 14, 'OT', '이 날이 너희에게 기념이 되게 하라. 너희는 그것을 여호와의 축제로 지킬지니, 너희 세대를 위하여 영원한 규례로 그것을 지킬지니라.'),
(1832, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 15, 'OT', '너희는 칠 일 동안 누룩 없는 빵을 먹을지니, 오직 첫 날에 너희 집에서 누룩을 제할지니라. 이는 누룩을 먹는 모든 자, 그 영혼이 첫 날부터 일곱째 날까지 이스라엘에서 끊어질 것임이니라.'),
(1833, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 16, 'OT', '첫째 날에는 거룩한 집회가 있고, 일곱째 날에도 너희에게 거룩한 집회가 있을지니, 그 날들에는 모든 일을 하지 말고, 오직 모든 영혼이 먹을 것만 그것을 따로 너희를 위해 준비할지니라.'),
(1834, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 17, 'OT', '너희는 누룩 없는 빵을 지키라, 내가 바로 이 날에 너희 군대를 애굽 땅에서 인도하여 내었음이라. 그러므로 너희는 이 날을 너희 세대에 영원한 규례로 지킬지니라.'),
(1835, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 18, 'OT', '첫째 달 십사일 저녁에 너희는 누룩 없는 빵을 먹을지니, 그 달 이십일일 저녁까지니라.'),
(1836, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 19, 'OT', '칠 일 동안은 누룩이 너희 집들에서 발견되지 않을 것이니, 이는 누룩 있는 것을 먹는 모든 자는 그 영혼이 이스라엘 회중에서 끊어질 것임이라, 나그네든지 땅의 본토인이든지.'),
(1837, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 20, 'OT', '모든 누룩 있는 것은 먹지 말지니라 너희 모든 거주지에서 누룩 없는 빵을 먹을지니라'),
(1838, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 21, 'OT', '모세가 이스라엘의 모든 장로들을 불러 그들에게 이르되, 너희는 가족대로 양떼를 끌어내어 취하고 유월절 양을 잡으라.'),
(1839, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 22, 'OT', '너희는 우슬초 다발을 취하여 대접에 있는 피에 적시고, 대접에 있는 피를 문지방과 두 문설주에 바르되, 너희는 아침까지 각 사람이 자기 집 문에서 나가지 말지니라.'),
(1840, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 23, 'OT', '여호와께서 애굽을 치러 지나가실 때에 그가 문지방과 두 문설주에 있는 피를 보시리니 여호와께서 그 문을 넘으시고 썩게 하는 자가 너희 집에 들어가서 치지 못하게 하시리라'),
(1841, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 24, 'OT', '너희는 이 말씀을 지키라 너를 위한 법령으로, 너와 네 아들들에게 영원히.'),
(1842, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 25, 'OT', '너희가 여호와께서 너희에게 주시는 땅에 들어갈 때에, 그가 말씀하신 대로, 너희는 이 일을 지킬지니라.'),
(1843, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 26, 'OT', '너희 자녀가 너희에게 말할 때에 이르기를, 너희에게 이 일이 무슨 뜻이냐 하리라.'),
(1844, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 27, 'OT', '너희는 말하되 이것은 여호와의 유월절 제사라, 그가 애굽에서 이스라엘 자손의 집들을 넘으시고 애굽을 치실 때에 우리의 집을 구원하셨느니라 하라. 백성이 머리 숙여 경배하니라.'),
(1845, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 28, 'OT', '이스라엘 자손들이 가서 행하되 여호와께서 모세와 아론에게 명령하신 대로 그들이 행하였더라.'),
(1846, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 29, 'OT', '밤중에 여호와께서 애굽 땅에서 모든 장자를 치셨으니, 왕좌에 앉은 파라오의 장자로부터 우물에 있는 집의 포로의 장자까지와 모든 짐승의 장자까지였더라.'),
(1847, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 30, 'OT', '바로가 밤에 일어나니 그와 그의 모든 종들과 모든 애굽 사람들이라 애굽에 큰 부르짖음이 있었으니 이는 집마다 죽은 자가 없는 집이 하나도 없었음이라'),
(1848, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 31, 'OT', '밤에 그가 모세와 아론을 불러 이르되, 일어나 내 백성 가운데서 나가라, 너희도, 이스라엘의 아들들도, 가서 너희가 말한 대로 여호와를 섬기라.'),
(1849, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 32, 'OT', '너희 양떼와 너희 소도 가져가되 너희가 말한 대로 가고, 또한 나를 축복하라.'),
(1850, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 33, 'OT', '애굽 사람들이 백성을 재촉하여 그 땅에서 속히 보내려 하였으니 이는 그들이 말하기를 우리 모든 사람이 죽은 자가 되었다 하였음이라'),
(1851, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 34, 'OT', 'וַיִּשָּׂ֥א הָעָ֛ם אֶת בְּצֵק֖וֹ טֶ֣רֶם יֶחְמָ֑ץ מִשְׁאֲרֹתָ֛ם צְרֻרֹ֥ת בְּשִׂמְלֹתָ֖ם עַל שִׁכְמָֽם  백성이 그 반죽을 아직 발효되기 전에 들고, 그들의 반죽 그릇을 그들의 옷에 싸서 그들의 어깨에 두었더라.'),
(1852, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 35, 'OT', '이스라엘 자손이 모세의 말씀대로 행하여 애굽에게 은 그릇과 금 그릇과 옷을 구하니라'),
(1853, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 36, 'OT', '여호와께서 애굽 사람의 눈에 백성에게 은혜를 주셨고 그들이 그들에게 꾸어 주었으며 그들이 애굽 사람의 물품을 벗겼더라'),
(1854, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 37, 'OT', '이스라엘 자손들이 라암세스에서 출발하여 숙곳으로 갔는데, 보행하는 사내들이 어린아이들 외에 약 육십만 명이었더라.'),
(1855, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 38, 'OT', '또한 아라비아가 그들과 함께 올라갔고, 양떼와 소, 심히 많은 가축이 있었더라.'),
(1856, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 39, 'OT', '그들이 애굽에서 가져온 반죽으로 누룩 없는 화덕빵을 구웠으니 이는 그것이 누룩이 들지 아니하였음이라 그들이 애굽에서 쫓겨나 지체할 수 없었고 또한 그들을 위하여 식량도 준비하지 못하였음이었더라'),
(1857, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 40, 'OT', '이스라엘 자손이 애굽에 거주한 거주지는 삼십 년과 사백 년이었더라'),
(1858, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 41, 'OT', '사백삼십 년이 끝나는 바로 그 날에 여호와의 모든 군대가 애굽 땅에서 나왔더라.'),
(1859, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 42, 'OT', '이 밤은 여호와께 파수하는 밤이니 그들을 애굽 땅에서 인도하여 내심을 위한 것이며, 이 밤은 여호와께 파수하는 밤이라 모든 이스라엘 자손이 그들의 세대를 위하여 지킬 것이니라.'),
(1860, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 43, 'OT', '여호와께서 모세와 아론에게 말씀하시되 이것이 유월절의 규례라 모든 타국인의 아들은 그것을 먹지 못할 것이니라'),
(1861, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 44, 'OT', '모든 사람의 은으로 구매한 종은 네가 그에게 할례를 행한 후에 그것을 먹을지니라'),
(1862, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 45, 'OT', '나그네와 품꾼은 그것을 먹지 못할지니라'),
(1863, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 46, 'OT', '한 집에서 먹되 그 살을 집 밖으로 내지 말고 뼈도 꺾지 말지니라'),
(1864, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 47, 'OT', '모든 이스라엘 회중이 그것을 행할지니라'),
(1865, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 48, 'OT', '나그네가 너와 함께 머물러 여호와께 유월절을 지키고자 하거든 그의 모든 남자는 할례를 받아야 하며 그런 후에야 가까이하여 지킬지니 그는 땅의 본토인과 같이 될 것이나 모든 할례 받지 못한 자는 그것을 먹지 못할 것이니라'),
(1866, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 49, 'OT', '율법 하나가 본토인에게 있을 것이요, 너희 중간에 거하는 나그네에게도 그러하리라'),
(1867, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 50, 'OT', '모든 이스라엘 자손이 여호와께서 모세와 아론에게 명령하신 대로 그렇게 행하였더라.'),
(1868, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 12, 51, 'OT', '그 날 바로 그 때에 여호와께서 이스라엘 자손을 그들의 군대대로 애굽 땅에서 인도하여 내셨더라.'),
(1869, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(1870, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 2, 'OT', '내게 모든 장자를 거룩히 구별하라, 이스라엘 아들들 가운데 자궁을 여는 모든 첫새끼, 사람과 짐승 중에서, 그것은 내 것이니라.'),
(1871, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 3, 'OT', '모세가 백성에게 말하되, 너희는 애굽에서, 종의 집에서 나온 이 날을 기억하라. 여호와께서 강한 손으로 너희를 이 곳에서 인도하여 내셨음이라. 누룩 있는 것은 먹지 말지니라.'),
(1872, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 4, 'OT', '오늘 너희가 나오는 날이니 이삭의 달에 나오느니라'),
(1873, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 5, 'OT', '여호와께서 너를 가나안 사람과 히타이트 사람과 아모리 사람과 히위 사람과 여부스 사람의 땅, 곧 네 아버지들에게 주리라고 맹세하신 젖과 꿀이 흐르는 땅으로 인도하실 때에, 너는 이 달에 이 일을 지킬지니라.'),
(1874, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 6, 'OT', '칠 일 동안 누룩 없는 빵을 먹을지니, 일곱째 날에는 여호와께 축제가 있으리라.'),
(1875, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 7, 'OT', '칠 일 동안 누룩 없는 빵을 먹을 것이며, 네게 누룩이 보이지 않을 것이요, 네 모든 경계 안에서 누룩이 네게 보이지 않을 것이다.'),
(1876, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 8, 'OT', '그 날에 네 아들에게 말하여 이르기를, 여호와께서 내가 애굽에서 나올 때에 나를 위하여 행하신 일 때문에 이러하다 하라.'),
(1877, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 9, 'OT', '이것이 네 손에 표적이 되고 네 눈 사이에 기념이 되어 여호와의 율법이 네 입에 있게 하려 함이니 이는 여호와께서 강한 손으로 너를 애굽에서 인도하여 내셨음이니라'),
(1878, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 10, 'OT', '너는 이 규례를 그 정한 때에 지키되 날에서 날까지 지킬지니라'),
(1879, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 11, 'OT', '여호와께서 너를 가나안 사람의 땅으로 인도하실 때에, 그가 너와 네 아버지에게 맹세하신 대로, 그 땅을 네게 주시리라.'),
(1880, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 12, 'OT', '네 모든 자궁에서 처음 난 것은 여호와께 돌리고, 네게 있는 짐승의 모든 첫새끼 중 수컷은 여호와의 것이니라.'),
(1881, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 13, 'OT', '모든 나귀의 첫새끼는 양으로 대속할 것이요, 만일 대속하지 아니하면 그 목을 꺾을 것이며, 네 아들들 중 모든 사람의 장자는 대속할지니라.'),
(1882, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 14, 'OT', '네 아들이 내일 네게 묻기를 이것이 무엇이냐 하거든 너는 그에게 말하기를 여호와께서 강한 손으로 우리를 애굽에서, 종의 집에서 인도하여 내셨느니라'),
(1883, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 15, 'OT', '파라오가 우리를 보내기를 거절하자 여호와께서 애굽 땅에서 사람의 장자와 짐승의 장자까지 모든 처음 난 것을 죽이셨으므로 내가 여호와께 모든 자궁을 여는 수컷 첫새끼를 제사로 드리고 내 아들들의 모든 장자는 대속하나이다'),
(1884, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 16, 'OT', '이것이 네 손에 표적이 되고 네 눈 사이에 이마의 표가 되리니, 이는 여호와께서 강한 손으로 우리를 애굽에서 인도하여 내셨음이라.'),
(1885, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 17, 'OT', '바로가 백성을 보낼 때에 하나님이 그들을 블레셋 사람의 땅 길로 인도하지 아니하셨으니 이는 그 길이 가까움이라 하나님이 말씀하시기를 백성이 전쟁을 보고 뉘우쳐 애굽으로 돌아갈까 하셨음이라'),
(1886, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 18, 'OT', '하나님이 백성을 광야 길 곧 갈대 바다 길로 돌리셨고, 이스라엘 자손이 애굽 땅에서 대오를 지어 올라왔더라.'),
(1887, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 19, 'OT', '모세가 요셉의 뼈를 자기와 함께 취하였으니 이는 그가 이스라엘의 아들들을 단단히 맹세하게 하여 이르기를, 하나님이 반드시 너희를 돌보시리니 너희는 나의 뼈를 이곳에서 너희와 함께 가지고 올라가라 하였음이라'),
(1888, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 20, 'OT', '그들이 숙곳에서 출발하여 광야 끝에 있는 에담에 장막을 쳤더라.'),
(1889, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 21, 'OT', '여호와께서 그들 얼굴 앞에서 행하시며 낮에는 구름 기둥으로 그들을 길로 인도하시고 밤에는 불 기둥으로 그들에게 비추어 주야로 가게 하셨더라'),
(1890, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 13, 22, 'OT', '구름 기둥이 낮에, 불 기둥이 밤에 백성의 얼굴 앞에서 떠나지 아니하니라.'),
(1891, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(1892, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 2, 'OT', '이스라엘 자손에게 말하여 그들이 돌아서 비하히롯 앞 곧 미그돌과 바다 사이에 진을 치게 하라 바알스본 맞은편 바닷가에 너희가 그 앞에 진을 칠지니라'),
(1893, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 3, 'OT', '파라오가 이스라엘 자손에 대하여 말하리니 그들이 그 땅에서 혼란에 빠졌도다 광야가 그들을 가두었도다'),
(1894, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 4, 'OT', '내가 파라오의 마음을 강하게 하리니 그가 그들의 뒤를 따르리라. 내가 파라오와 그의 모든 군대로 말미암아 영광을 얻으리니 애굽 사람들이 내가 여호와인 줄 알리라. 그들이 그대로 행하니라.'),
(1895, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 5, 'OT', '애굽 왕에게 백성이 도망하였다고 알려지매, 파라오와 그의 종들의 마음이 백성에게서 돌이켜져 그들이 말하되 "우리가 어찌 이렇게 하여 이스라엘을 우리를 섬김에서 놓아 보내었는가?" 하였더라.'),
(1896, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 6, 'OT', '그가 자기 병거를 갖추고 자기 백성을 데리고 그와 함께 갔더라'),
(1897, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 7, 'OT', '그가 선별된 병거 육백 대와 애굽의 모든 병거를 취하고, 모든 위에 대장들을 두었더라'),
(1898, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 8, 'OT', '여호와께서 애굽 왕 파라오의 마음을 강하게 하시매 그가 이스라엘 자손의 뒤를 쫓았으며 이스라엘 자손은 높은 손으로 나가고 있었더라'),
(1899, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 9, 'OT', '애굽 사람들이 그들의 뒤를 쫓았고, 그들이 바다 곁에 진 친 곳에서 그들을 따라잡았으니, 파라오의 모든 말과 병거와 그의 기병들과 그의 군대가 비하히롯 어귀, 바알스본 맞은편에 있었더라.'),
(1900, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 10, 'OT', '파라오가 가까이 오매, 이스라엘 자손이 눈을 들어 보니, 보라, 애굽 사람들이 그들 뒤를 따라오는지라, 그들이 심히 두려워하여 이스라엘 자손이 여호와께 부르짖으니라.'),
(1901, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 11, 'OT', '그들이 모세에게 이르되, 애굽에 무덤이 없어서 우리를 광야에서 죽게 하려고 데려왔느냐? 네가 우리를 애굽에서 인도해 내어 우리에게 이같이 행한 것이 무엇이냐?'),
(1902, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 12, 'OT', '우리가 애굽에서 당신에게 말한 것이 이 말이 아니냐? 이르기를 우리를 버려 두라 우리가 애굽 사람을 섬기리라 하지 아니하였느냐? 애굽 사람을 섬기는 것이 광야에서 죽는 것보다 우리에게 더 좋았겠노라.'),
(1903, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 13, 'OT', '모세가 백성에게 이르되 너희는 두려워하지 말라, 너희는 서서 여호와께서 오늘 너희를 위하여 행하시는 구원을 보라, 너희가 오늘 본 애굽 사람을 다시는 영원히 보지 못하리라'),
(1904, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 14, 'OT', '여호와께서 너희를 위하여 싸우시리니 너희는 잠잠할지니라'),
(1905, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 15, 'OT', '여호와께서 모세에게 이르시되 네가 어찌하여 내게 부르짖느냐 이스라엘 자손에게 말하여 그들이 나아가게 하라'),
(1906, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 16, 'OT', '너는 네 막대기를 들고 네 손을 바다 위로 내밀어 그것을 갈라지게 하라 그러면 이스라엘 자손이 바다 중간의 마른 땅으로 들어가리라'),
(1907, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 17, 'OT', '나는 내가 애굽 사람들의 마음을 강하게 하리니 그들이 그들의 뒤를 따라 들어오리라 내가 파라오와 그의 모든 군대와 그의 병거와 그의 기병으로 말미암아 영광을 얻으리라'),
(1908, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 18, 'OT', '애굽 사람들은 내가 파라오와 그의 병거와 그의 기병들로 말미암아 영광을 얻을 때에 내가 여호와인 줄 알리라.'),
(1909, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 19, 'OT', '하나님의 천사가 이스라엘 진영 앞에서 행하다가 그들 뒤로 옮겨 갔고, 구름 기둥도 그들 얼굴 앞에서 옮겨 그들 뒤에 섰더라.'),
(1910, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 20, 'OT', '애굽 진영과 이스라엘 진영 사이에 이르렀는데, 그 구름과 어둠이 있었고 밤을 밝혔으며, 그들이 밤새도록 서로에게 가까이 가지 못하였더라.'),
(1911, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 21, 'OT', '모세가 바다 위로 그의 손을 내밀매 여호와께서 모든 밤 동안 강한 동풍으로 바다를 인도하시고 바다를 마른 땅이 되게 하시니 물이 갈라졌더라'),
(1912, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 22, 'OT', '이스라엘 자손들이 바다 중간 마른 땅으로 들어갔고, 물은 그들의 오른쪽과 왼쪽에 성벽이 되었더라.'),
(1913, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 23, 'OT', '애굽 사람들이 추격하여 그들 뒤를 따라 들어왔으니, 파라오의 모든 말과 그의 병거와 그의 기병들이 바다 중간으로 들어왔더라.'),
(1914, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 24, 'OT', '새벽 파수 때에 여호와께서 불과 구름 기둥 가운데서 애굽 사람의 진영을 내려다보시고 애굽 사람의 진영을 어지럽게 하셨더라'),
(1915, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 25, 'OT', '그가 그들의 병거 바퀴를 벗기시고 그들을 중하게 몰아가게 하시니 애굽이 이르되 우리가 이스라엘의 얼굴 앞에서 도망하자 여호와께서 그들을 위하여 애굽에서 싸우시느니라 하였더라'),
(1916, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 26, 'OT', '여호와께서 모세에게 이르시되 네 손을 바다 위로 내밀라 그리하면 물이 애굽과 그 병거와 그 기병들 위에 다시 돌아오리라'),
(1917, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 27, 'OT', '모세가 바다 위에 그의 손을 내밀매 바다가 아침이 되기 전에 그 세력대로 돌아갔고 애굽 사람들은 그것을 향해 도망하였으나 여호와께서 애굽 사람들을 바다 중간에서 뒤엎으시니라'),
(1918, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 28, 'OT', '물이 다시 돌아와 병거와 기병들을 덮었고, 그들의 뒤를 따라 바다로 들어온 파라오의 모든 군대를 덮었으니, 그들 중 하나도 남지 아니하였더라.'),
(1919, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 29, 'OT', '이스라엘 자손들은 바다 중간의 마른 땅으로 걸어갔고, 물이 그들의 오른쪽과 왼쪽에 성벽이 되었더라.'),
(1920, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 30, 'OT', '그 날에 여호와께서 이스라엘을 애굽의 손에서 구원하셨고, 이스라엘은 애굽 사람들이 바닷가 입술에 죽은 것을 보았더라.'),
(1921, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 14, 31, 'OT', '이스라엘이 여호와께서 애굽에서 행하신 큰 손을 보았고 백성이 여호와를 두려워하며 여호와와 그의 종 모세를 믿었더라'),
(1922, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 1, 'OT', '그 때에 모세와 이스라엘 자손이 이 노래를 여호와께 불렀고 말하여 이르되, 내가 여호와께 노래하리니 그가 높이 높임을 받으셨음이요, 말과 그 탄 자를 바다에 던지셨음이로다.'),
(1923, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 2, 'OT', '나의 힘과 노래는 야이시며, 그가 나에게 구원이 되셨도다. 이는 나의 엘이시니 내가 그를 찬송하리로다, 내 아버지의 하나님이시니 내가 그를 높이리로다.'),
(1924, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 3, 'OT', '여호와는 전쟁의 사람이시니 여호와는 그의 이름이시로다'),
(1925, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 4, 'OT', '파라오의 병거와 그의 군대를 바다에 던지셨고, 그의 선택된 대장들은 갈대 바다에 잠겼도다.'),
(1926, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 5, 'OT', '심연이 그들을 덮었으니 그들이 돌처럼 심해에 내려갔도다'),
(1927, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 6, 'OT', '여호와여, 주의 오른손이 힘으로 영광스럽도다. 여호와여, 주의 오른손이 원수를 부수시도다.'),
(1928, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 7, 'OT', '주의 교만의 많음으로 주를 대적하는 자들을 멸하시며 주의 격노를 보내시니 그것이 그들을 검불같이 사르나이다'),
(1929, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 8, 'OT', '주의 콧김에 물들이 쌓였고, 흐르는 물들이 무더기 같이 섰으며, 심연들이 바다의 마음 속에서 얼어붙었나이다.'),
(1930, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 9, 'OT', '원수가 말하기를 내가 쫓아가서 따라잡아 전리품을 나누리라 내 영혼이 그들로 가득 차리라 내가 내 칼을 빼리니 내 손이 그들을 멸하리라 하였도다'),
(1931, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 10, 'OT', '주께서 주의 영으로 부시매 바다가 그들을 덮었나이다 그들이 창대한 물에 납 같이 잠겼나이다'),
(1932, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 11, 'OT', '누가 엘들 가운데 주와 같으리이까, 여호와여! 누가 주와 같으리이까, 거룩함에 영광스럽고 찬양으로 두려우며 불가사의한 일을 행하는 이여!'),
(1933, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 12, 'OT', '주께서 오른손을 펴시매 땅이 그들을 삼켰나이다'),
(1934, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 13, 'OT', '주의 은혜로 주께서 구속하신 백성을 인도하셨고, 주의 힘으로 그들을 주의 거룩함의 거처로 이끄셨나이다.'),
(1935, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 14, 'OT', '백성들이 듣고 떨며, 진통이 블레셋 거민들을 사로잡았도다.'),
(1936, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 15, 'OT', '그 때에 에돔의 족장들이 놀라며, 모압의 숫양들이 떨림에 사로잡히고, 가나안의 모든 주민들이 녹아내렸도다.'),
(1937, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 16, 'OT', '그들 위에 공포와 두려움이 떨어지리이다 주의 팔이 크심으로 그들이 돌같이 잠잠하리이다 여호와여 주의 백성이 통과하기까지 주께서 사신 백성이 통과하기까지였나이다'),
(1938, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 17, 'OT', '그들을 인도하여 주의 유산의 산에 심으소서, 여호와여, 주의 처소를 위한 터전을 주께서 만드셨고, 주님의 성소를 주의 손이 세우셨나이다.'),
(1939, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 18, 'OT', '여호와께서 영원무궁토록 다스리시리로다'),
(1940, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 19, 'OT', '파라오의 말이 그의 병거와 그의 기병들과 함께 바다에 들어갔고, 여호와께서 그들 위에 바다의 물을 되돌리셨으나, 이스라엘 자손들은 바다 중간의 마른 땅으로 걸어갔더라.'),
(1941, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 20, 'OT', '선지자 미리암이 아론의 자매라 손에 탬버린을 잡으매 모든 여자들이 그를 따라 탬버린과 춤으로 나오니라'),
(1942, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 21, 'OT', '미리암이 그들에게 대답하여 이르되, 너희는 여호와께 노래하라, 그가 높이 들리어 영광스러우시도다, 말과 그 탄 자를 바다에 던지셨도다.'),
(1943, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 22, 'OT', '모세가 이스라엘을 갈대 바다에서 인도하여 내니 그들이 수르 광야로 나아가서 광야에서 사흘 동안 걸었으나 물을 찾지 못하니라'),
(1944, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 23, 'OT', '그들이 마라에 이르렀으나 그 물이 마라에서 나온 것이라 마시지 못하였으니 이는 그 물이 썼음이라 그러므로 그 이름을 마라라 불렀더라'),
(1945, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 24, 'OT', '백성이 모세에게 대하여 원망하여 이르되 우리가 무엇을 마실까 하니'),
(1946, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 25, 'OT', '그가 여호와께 부르짖었더니 여호와께서 그에게 나무를 보여 주시니 그가 물에 던지매 물이 달아졌더라 거기서 그가 그를 위하여 법령과 판결을 정하셨고 거기서 그를 시험하셨더라'),
(1947, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 26, 'OT', '네가 네 하나님 여호와의 소리를 청종하고 그의 눈에 옳은 것을 행하며 그의 명령에 귀를 기울이고 그의 모든 법령을 지키면 내가 애굽에 내린 모든 병을 네게 두지 아니하리니 나는 너를 치료하는 여호와임이니라'),
(1948, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 15, 27, 'OT', '그들이 엘림에 이르렀는데, 거기에 물이 열두 샘과 종려나무 일흔 그루가 있었고, 그들이 거기 물 곁에 장막을 쳤더라.'),
(1949, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 1, 'OT', '그들이 엘림에서 떠나서, 이스라엘 자손의 모든 회중이 엘림과 시내 사이에 있는 신 광야에 이르렀는데, 그들이 애굽 땅에서 나온 지 둘째 달 십오일이었다.'),
(1950, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 2, 'OT', '이스라엘 자손의 모든 회중이 광야에서 모세와 아론을 원망하니라'),
(1951, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 3, 'OT', '이스라엘 자손들이 그들에게 이르되 우리가 애굽 땅에서 고기 냄비 곁에 앉아 빵을 배불리 먹을 때에 여호와의 손에 죽었더라면 좋았을 것을 너희가 우리를 이 광야로 인도하여 내어 이 모든 회중을 기근으로 죽이려 하는도다'),
(1952, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 4, 'OT', '여호와께서 모세에게 이르시되 보라 내가 너희를 위하여 하늘에서 빵을 비 같이 내리리니 백성이 나가서 날마다 그 날의 말씀을 거둘 것이라 이는 내가 그들이 내 율법을 따라 행하는지 아니하는지 시험하려 함이니라'),
(1953, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 5, 'OT', '여섯째 날에는 그들이 가져올 것을 예비할지니 날마다 거두는 것의 둘째가 되리라'),
(1954, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 6, 'OT', '모세와 아론이 모든 이스라엘 아들들에게 말하되, 저녁에 너희는 여호와께서 너희를 애굽 땅에서 인도하여 내셨음을 알리라.'),
(1955, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 7, 'OT', '아침에 너희가 여호와의 영광을 보리니 이는 여호와께서 너희가 여호와를 향하여 불평함을 들으셨음이라 우리가 무엇이기에 너희가 우리를 향하여 불평하느냐'),
(1956, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 8, 'OT', '모세가 말하되 여호와께서 저녁에 너희에게 살을 주어 먹게 하시고 아침에 빵을 주어 배부르게 하시리니 이는 여호와께서 너희가 그를 향하여 불평하는 너희의 불평을 들으셨음이라 우리가 무엇이냐 너희의 불평은 우리를 향한 것이 아니요 여호와를 향한 것이로다'),
(1957, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 9, 'OT', '모세가 아론에게 말하여 이르되, 이스라엘 자손의 모든 회중에게 말하라, 여호와의 얼굴 앞으로 가까이 나아오라, 그가 너희의 불평을 들으셨느니라.'),
(1958, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 10, 'OT', '아론이 이스라엘 자손의 모든 회중에게 말할 때에 그들이 광야를 바라보았더니, 보라, 여호와의 영광이 구름 속에 나타났더라.'),
(1959, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 11, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(1960, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 12, 'OT', '내가 이스라엘 자손의 불평을 들었노라. 그들에게 말하여 이르기를, 너희는 저녁 사이에 살을 먹고 아침에는 빵으로 배부르리니, 내가 여호와 너희의 하나님인 줄 알리라 하라.'),
(1961, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 13, 'OT', '저녁에 메추라기가 올라와서 진영을 덮었고, 아침에는 이슬이 진영 주위에 깔려 있었더라.'),
(1962, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 14, 'OT', '이슬이 걷힌 후에, 보라 광야의 얼굴 위에 가늘고 벗겨진 것이 있으니, 땅 위의 서리 같이 가늘더라.'),
(1963, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 15, 'OT', '이스라엘 자손들이 보고 서로 말하되 이것이 무엇이냐 하니 이는 그들이 그것이 무엇인지 알지 못함이라 모세가 그들에게 이르되 이는 여호와께서 너희에게 주어 먹게 하신 빵이니라'),
(1964, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 16, 'OT', '이것은 여호와께서 명하신 말씀이니, 너희는 그것에서 각 사람이 자기 입의 음식대로 거두되, 너희 영혼의 수대로 각 사람에게 한 단씩, 각 사람이 자기 천막에 있는 자들을 위하여 취할지니라.'),
(1965, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 17, 'OT', '이스라엘 자손이 그같이 행하였더니 많이 거둔 자와 적게 거둔 자가 있었더라'),
(1966, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 18, 'OT', '그들이 오멜로 되어 보니 많이 거둔 자도 남음이 없었고 적게 거둔 자도 부족함이 없었으며 각 사람이 자기 음식대로 입에 맞게 거두었더라'),
(1967, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 19, 'OT', '모세가 그들에게 이르되, 사람은 아침까지 그것을 남겨 두지 말지니라.'),
(1968, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 20, 'OT', '그들이 모세의 말을 듣지 아니하고 어떤 사람들은 그것을 아침까지 남겨 두었더니 진홍색 벌레가 생기고 냄새가 났으며 모세가 그들에게 노하니라'),
(1969, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 21, 'OT', '그들이 그것을 아침마다 거두되 각 사람이 자기 음식 분량대로 거두었고, 해가 뜨거워지면 그것이 녹았더라.'),
(1970, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 22, 'OT', '여섯째 날에 그들이 갑절의 빵을 거두었으니, 한 사람에게 두 단씩이었더라. 회중의 모든 통치자들이 와서 모세에게 말하니라.'),
(1971, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 23, 'OT', '그가 그들에게 말하되, 이것은 여호와께서 말씀하신 것이니, 내일은 여호와께 거룩함의 안식일이요 안식이라. 너희가 구울 것은 굽고, 삶을 것은 삶고, 모든 남은 것은 아침까지 파수로 너희를 위하여 간수하라.'),
(1972, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 24, 'OT', '그들이 모세가 명령한 대로 아침까지 그것을 두었더니 냄새가 나지 아니하고 그 안에 구더기도 없었더라'),
(1973, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 25, 'OT', '모세가 말하되, 오늘 그것을 먹으라, 오늘은 여호와께 안식일이니, 오늘은 너희가 그것을 들판에서 찾지 못하리라.'),
(1974, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 26, 'OT', '엿새 동안은 너희가 그것을 거두되, 일곱째 날에는 안식일이라 그 날에는 없을지니라.'),
(1975, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 27, 'OT', '일곱째 날에 백성 중에서 거두러 나갔으나 얻지 못하였더라'),
(1976, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 28, 'OT', '여호와께서 모세에게 이르시되 어느 때까지 너희가 내 명령과 내 율법을 지키기를 거절하겠느냐'),
(1977, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 29, 'OT', '보라 여호와가 너희에게 안식일을 주었으므로 그가 여섯째 날에 너희에게 이틀 양식의 빵을 주는 것이니 너희는 각자 자기 자리에 머물고 일곱째 날에는 아무도 자기 장소에서 나오지 말지니라'),
(1978, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 30, 'OT', '그리하여 백성이 일곱째 날에 쉬었더라.'),
(1979, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 31, 'OT', '이스라엘 집이 그 이름을 만나라 불렀으며, 그것은 고수 씨 같고 희며, 그 맛은 꿀 섞은 전병 같았더라.'),
(1980, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 32, 'OT', '모세가 말하되, 이것은 여호와께서 명하신 말씀이니, 그것으로 한 오멜을 채워 너희 세대를 위하여 파수하여 두라, 이는 내가 너희를 애굽 땅에서 인도하여 낼 때에 광야에서 너희에게 먹인 빵을 그들이 보게 하려 함이니라.'),
(1981, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 33, 'OT', '모세가 아론에게 이르되, 항아리 하나를 가져다가 그 속에 만나 한 오멜의 충만한 분량을 담아 여호와의 얼굴 앞에 두어 너희 세대를 위한 파수로 간수하라'),
(1982, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 34, 'OT', '여호와께서 모세에게 명령하신 대로 아론이 그것을 증언 앞에 두어 파수하게 하였더라.'),
(1983, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 35, 'OT', '이스라엘 자손들이 사람이 사는 땅에 이르기까지 사십 년 동안 만나를 먹었으며, 그들이 가나안 땅의 끝에 이르기까지 만나를 먹었더라.'),
(1984, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 16, 36, 'OT', '단은 에바의 십분의 일이니라'),
(1985, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 1, 'OT', '모든 이스라엘 자손의 회중이 여호와의 입의 명령대로 신 광야에서 그들의 여정대로 떠나 르피딤에 장막을 쳤으나 백성이 마실 물이 없었더라.'),
(1986, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 2, 'OT', '백성이 모세와 다투며 말하여 이르되 우리에게 물을 주어 마시게 하라 하니 모세가 그들에게 이르되 너희가 어찌하여 나와 다투느냐 너희가 어찌하여 여호와를 시험하느냐'),
(1987, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 3, 'OT', '그 곳에서 백성이 물로 인하여 목이 말랐고, 백성이 모세에게 원망하며 말하되 어찌하여 우리를 애굽에서 인도하여 내어 나와 내 아들들과 내 가축을 갈증으로 죽게 하느냐 하였더라'),
(1988, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 4, 'OT', '모세가 여호와께 부르짖어 이르되, 내가 이 백성에게 무엇을 하리이까? 그들이 조금만 더하면 나를 돌로 칠 것이니이다.'),
(1989, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 5, 'OT', '여호와께서 모세에게 말씀하시되 백성의 얼굴 앞으로 지나가고 이스라엘 장로들 중에서 몇을 데리고, 네가 나일강을 치던 네 막대기를 손에 잡고 가라'),
(1990, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 6, 'OT', '보라 내가 거기서 호렙의 바위 위에서 네 얼굴 앞에 서리니 너는 그 바위를 치라 그러면 그에게서 물이 나와서 백성이 마시리라 모세가 이스라엘 장로들의 눈 앞에서 그대로 행하니라'),
(1991, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 7, 'OT', '그가 그 장소의 이름을 맛사와 므리바라 불렀으니, 이는 이스라엘 자손의 분쟁 때문이요, 그들이 여호와를 시험하여 이르기를 "여호와께서 우리 속에 계신가, 아니면 없는가" 하였음이더라.'),
(1992, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 8, 'OT', '아말렉이 이르러 르피딤에서 이스라엘과 싸우니라'),
(1993, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 9, 'OT', '모세가 여호수아에게 말하되 우리를 위하여 사람들을 택하여 나가서 아말렉과 싸우라 내일 내가 언덕 머리에 서리니 하나님의 막대기가 내 손에 있느니라'),
(1994, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 10, 'OT', '여호수아가 모세가 그에게 말한 대로 아말렉과 싸우려고 행하였고, 모세와 아론과 후르는 언덕 머리에 올라갔더라.'),
(1995, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 11, 'OT', '모세가 그의 손을 들면 이스라엘이 이기고, 그의 손을 내리면 아말렉이 이기더라.'),
(1996, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 12, 'OT', '모세의 손이 무거웠고, 그들이 돌을 가져다가 그 아래에 놓으매 그가 그 위에 앉았으며, 아론과 후르가 그의 손을 붙들었는데, 이쪽에서 하나, 저쪽에서 하나였고, 그의 손이 해가 질 때까지 믿음으로 굳게 있었더라.'),
(1997, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 13, 'OT', '여호수아가 칼의 입으로 아말렉과 그의 백성을 쳐서 파하니라'),
(1998, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 14, 'OT', '여호와께서 모세에게 이르시되 이것을 책에 기록하여 기념이 되게 하고 여호수아의 귀에 두라 내가 아말렉의 기념을 하늘 아래에서 완전히 지워버리리라'),
(1999, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 15, 'OT', '모세가 제단을 쌓고 그 이름을 여호와 닛시라 하였더라'),
(2000, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 17, 16, 'OT', '그가 말하기를 손이 야의 맹세 위에 있도다 여호와가 아말렉과 전쟁을 대대로 하리라 하였더라'),
(2001, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 1, 'OT', '미디안 제사장 이드로가 모세의 장인으로서, 하나님이 모세와 그의 백성 이스라엘에게 행하신 모든 일, 곧 여호와께서 이스라엘을 애굽에서 인도하여 내신 것을 들으니라'),
(2002, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 2, 'OT', '모세의 장인 이드로가 모세의 아내 십보라를 그가 돌려보낸 후에 데려갔더라'),
(2003, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 3, 'OT', '그리고 그의 두 아들들, 그중 하나의 이름은 게르솜이니, 이는 그가 말하기를 내가 낯선 땅에서 나그네가 되었도다 하였음이라.'),
(2004, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 4, 'OT', '하나의 이름은 엘리에셀이니 이는 내 아버지의 하나님이 나의 도움이 되사 나를 파라오의 칼에서 구원하셨음이라'),
(2005, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 5, 'OT', '모세의 장인 이드로가 모세의 아들들과 그의 아내와 함께 모세에게 왔으니, 그가 하나님의 산 곁에 진을 친 광야로 왔더라.'),
(2006, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 6, 'OT', '그가 모세에게 말하되, 나는 네 장인 이드로라, 네게 왔노라, 네 아내와 그와 함께한 그 두 아들이 그녀와 함께 있느니라.'),
(2007, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 7, 'OT', '모세가 그의 장인을 맞으러 나가서 절하고 그에게 입맞추며 그들이 서로 친구에게 평화를 묻고 천막으로 들어왔더라'),
(2008, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 8, 'OT', '모세가 그의 장인에게 여호와께서 파라오와 애굽에게 이스라엘의 까닭으로 행하신 모든 일과 길에서 그들이 당한 모든 고생과 여호와께서 그들을 구원하신 것을 말하니라'),
(2009, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 9, 'OT', '이드로가 여호와께서 이스라엘에게 행하신 모든 선하심, 곧 그들을 애굽의 손에서 구원하신 것 때문에 기뻐하니라.'),
(2010, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 10, 'OT', '이드로가 말하되, 여호와를 찬송하리로다. 그가 너희를 애굽의 손에서와 파라오의 손에서 건지셨고, 그가 백성을 애굽의 손 아래에서 건지셨도다.'),
(2011, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 11, 'OT', '이제 내가 알았도다 여호와께서 모든 하나님보다 크시다는 것을, 그들이 그들에게 교만히 행한 그 말씀으로 말미암아.'),
(2012, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 12, 'OT', '모세의 장인 이드로가 번제와 제사를 하나님께 드렸고, 아론과 이스라엘의 모든 장로들이 모세의 장인과 함께 하나님 앞에서 빵을 먹으러 왔더라.'),
(2013, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 13, 'OT', '이튿날에 모세가 백성을 재판하라고 앉았고 백성은 아침부터 저녁까지 모세 곁에 섰더라'),
(2014, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 14, 'OT', '모세의 장인이 그가 백성에게 행하는 모든 일을 보고 말하되, 그대가 백성에게 행하는 이 말씀이 무엇이뇨? 어찌하여 그대는 따로 앉아 있고 모든 백성은 아침부터 저녁까지 그대 곁에 서 있느뇨?'),
(2015, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 15, 'OT', '모세가 그의 장인에게 말하되, 백성이 하나님께 묻기 위해 내게로 오나이다'),
(2016, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 16, 'OT', '그들이 말씀이 있을 때 내게로 오나니 내가 사람과 그의 친구 사이를 판단하고, 내가 그들에게 하나님의 법령과 그의 율법을 알게 하리라.'),
(2017, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 17, 'OT', '모세의 장인이 그에게 이르되, 네가 행하는 이 말씀은 좋지 아니하니라.'),
(2018, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 18, 'OT', '네가 반드시 쇠하리니, 너와 너와 함께한 이 백성도 그러하리라. 이 말씀이 너에게 너무 무거워서 네가 그것을 혼자서 따로 감당할 수 없음이라.'),
(2019, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 19, 'OT', '이제 내 소리를 들으라, 내가 네게 조언하리니 하나님이 너와 함께 하시리라. 너는 백성을 위하여 하나님 앞에 있어서 그 말씀들을 하나님께로 가져오라.'),
(2020, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 20, 'OT', '그들에게 법령과 율법을 경고하고, 그들이 걸어갈 길과 행할 행위를 그들에게 알게 하라.'),
(2021, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 21, 'OT', '너는 모든 백성 가운데서 능력 있는 사람들, 곧 하나님을 두려워하는 자들, 진리를 따르는 사람들, 부당이득을 미워하는 자들을 살피고, 그들 위에 천 명의 통치자들과 백 명의 통치자들, 오십 명의 통치자들, 십 명의 통치자들을 세울지니라.'),
(2022, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 22, 'OT', '그들이 모든 때에 백성을 재판하게 하라 모든 큰 말씀은 네게로 가져올 것이요 모든 작은 말씀은 그들이 스스로 재판할 것이라 그리하면 네게서 가벼워지리니 그들이 너와 함께 담당하리라'),
(2023, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 23, 'OT', '네가 이 말씀을 행하고 하나님이 네게 명령하시면 네가 능히 서 있을 수 있을 것이요, 또한 이 모든 백성도 각자 자기 장소로 평화히 돌아가리라.'),
(2024, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 24, 'OT', '모세가 그의 장인의 소리를 듣고 그가 말한 모든 것을 행하였더라.'),
(2025, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 25, 'OT', '모세가 모든 이스라엘에서 군대 사람들을 택하여 그들을 백성의 머리로 삼았으니 곧 천 명의 통치자, 백 명의 통치자, 오십 명의 통치자, 십 명의 통치자로 삼았더라.'),
(2026, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 26, 'OT', '그들이 모든 때에 백성을 재판하되 어려운 말씀은 모세에게로 가져왔고 모든 작은 말씀은 그들이 직접 재판하니라'),
(2027, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 18, 27, 'OT', '모세가 그의 장인을 보내니 그가 자기 땅으로 갔더라.'),
(2028, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 1, 'OT', '이스라엘 자손이 애굽 땅에서 나온 지 삼 개월이 되는 그 날에 그들이 시내 광야에 이르렀더라.'),
(2029, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 2, 'OT', '그들이 르피딤에서 출발하여 시내 광야에 이르러 그 광야에 진을 쳤고, 거기서 이스라엘이 산 앞에 진을 쳤더라.'),
(2030, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 3, 'OT', '모세가 하나님께로 올라가니 여호와께서 산에서 그를 불러 이르시되 너는 야곱의 집에게 이같이 말하고 이스라엘의 아들들에게 고하라'),
(2031, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 4, 'OT', '너희는 내가 애굽에게 행한 것과 내가 어떻게 독수리 날개로 너희를 업어 내게로 인도하였음을 보았느니라'),
(2032, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 5, 'OT', '그러므로 이제 너희가 내 소리를 정말로 듣고 내 언약을 지키면, 너희는 모든 백성 가운데서 나의 보물이 되리니, 이는 온 땅이 다 내 것임이라.'),
(2033, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 6, 'OT', '너희는 내게 제사장의 왕국이 되며 거룩한 이방인이 되리라. 이것이 네가 이스라엘의 아들들에게 말할 말씀이니라.'),
(2034, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 7, 'OT', '모세가 와서 백성의 장로들을 부르고 여호와께서 그에게 명령하신 이 모든 말씀을 그들의 얼굴 앞에 두니라'),
(2035, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 8, 'OT', '모든 백성이 일제히 응답하여 이르되, 여호와께서 말씀하신 모든 것을 우리가 행하리이다 하매, 모세가 백성의 말을 여호와께 회보하니라.'),
(2036, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 9, 'OT', '여호와께서 모세에게 이르시되 보라 내가 빽빽한 구름 가운데서 네게 오리니 이는 내가 너와 말할 때에 백성으로 듣게 하여 또한 그들이 너를 영원히 믿게 하려 함이라 모세가 백성의 말씀을 여호와께 고하니라'),
(2037, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 10, 'OT', '여호와께서 모세에게 이르시되 백성에게로 가서 오늘과 내일 그들을 성결케 하며 그들로 옷을 빨게 하라'),
(2038, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 11, 'OT', '그들이 셋째 날을 위하여 준비되어 있을지니 이는 셋째 날에 여호와께서 모든 백성의 눈앞에 시내 산 위에 내려오실 것임이니라'),
(2039, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 12, 'OT', '너는 백성을 그 주위에 경계를 정하여 이르기를, 너희는 스스로 삼가 산에 오르지 말고 그 끝을 만지지 말지니, 산을 만지는 모든 자는 반드시 죽임을 당하리라.'),
(2040, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 13, 'OT', '손을 그에게 대지 말지니, 반드시 돌에 맞아 죽임을 당하거나 화살에 쏘여 죽임을 당할 것이라. 짐승이든 사람이든 살지 못하리라. 희년의 나팔을 길게 불 때 그들이 산에 오르리라.'),
(2041, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 14, 'OT', '모세가 산에서 내려와 백성에게 이르러 백성을 성결하게 하니 그들이 자기 옷을 빨았더라'),
(2042, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 15, 'OT', '그가 백성에게 이르되, 너희는 사흘 동안 준비하고 여자에게 가까이 가지 말라.'),
(2043, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 16, 'OT', '셋째 날 아침이 되었을 때에, 산 위에 천둥소리와 번개와 짙은 구름이 있었고, 매우 강한 나팔소리가 났으며, 진영에 있던 모든 백성이 떨었더라.'),
(2044, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 17, 'OT', '모세가 백성을 진영에서 이끌어 내어 하나님을 맞이하게 하니 그들이 산 아래에 섰더라'),
(2045, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 18, 'OT', '시내 산은 여호와께서 불 가운데서 그 위에 내려오셨기 때문에 온통 연기에 싸였더라. 그 연기가 용광로의 연기 같이 올라가고, 온 산이 심히 진동하니라.'),
(2046, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 19, 'OT', '나팔 소리가 점점 더 크게 울려 퍼질 때, 모세가 말하자 하나님이 음성으로 그에게 응답하셨다.'),
(2047, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 20, 'OT', '여호와께서 시내 산 위, 그 산 머리로 내려오시고 여호와께서 모세를 그 산 머리로 부르시니 모세가 올라가니라.'),
(2048, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 21, 'OT', '여호와께서 모세에게 이르시되 내려가서 백성에게 경고하라 그들이 여호와께로 돌파하여 보려고 하다가 그들 중 많은 자가 죽을까 하노라'),
(2049, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 22, 'OT', '또한 여호와께 가까이 나아가는 제사장들은 자신을 성결하게 할지니, 여호와가 그들 가운데 돌진하지 못하게 하려 함이라.'),
(2050, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 23, 'OT', '모세가 여호와께 말하되 백성이 시내 산에 오르지 못하리니 이는 주께서 우리에게 증거하사 이르시기를 산에 지경을 세우고 그것을 거룩하게 하라 하셨음이니이다'),
(2051, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 24, 'OT', '여호와께서 그에게 이르시되 가라, 내려가라, 너는 아론과 함께 올라오라, 그러나 제사장들과 백성은 여호와께로 올라오려고 돌파하지 못하게 하라, 그가 그들을 침노할까 염려하노라.'),
(2052, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 19, 25, 'OT', '모세가 백성에게 내려가서 그들에게 말하니라'),
(2053, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 1, 'OT', '하나님이 이 모든 말씀을 말씀하시며 이르시되'),
(2054, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 2, 'OT', '나는 너를 애굽 땅, 종의 집에서 인도하여 낸 너의 하나님 여호와라.'),
(2055, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 3, 'OT', '너는 내 얼굴 앞에 다른 신들을 두지 말지니라.'),
(2056, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 4, 'OT', '너는 너를 위하여 조각한 우상과 모든 형상을 만들지 말지니 위로 하늘에 있는 것이나 아래로 땅에 있는 것이나 땅 아래 물 속에 있는 것의 형상이니라.'),
(2057, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 5, 'OT', '그들에게 절하지 말고 그들을 섬기지 말라. 나 여호와 너의 하나님은 질투하는 엘인즉, 나를 미워하는 자들의 죄악을 아버지에게서 아들에게로, 삼대와 넷째까지 갚느니라.'),
(2058, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 6, 'OT', '은혜를 천대까지 베푸시되 나를 사랑하고 내 명령을 지키는 자들에게 베푸시느니라'),
(2059, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 7, 'OT', '너는 네 하나님 여호와의 이름을 헛되이 취하지 말라. 여호와는 그의 이름을 헛되이 취하는 자를 결코 깨끗하게 하지 아니하리라.'),
(2060, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 8, 'OT', '안식일을 기억하여 거룩히 지키라'),
(2061, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 9, 'OT', '엿새 동안은 네가 일하고 네 모든 일을 행할지니라'),
(2062, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 10, 'OT', '일곱째 날은 네 하나님 여호와의 안식일이니 너는 아무 일도 하지 말지니 너와 네 아들과 네 딸과 네 종과 네 여종과 네 짐승과 네 문 안에 있는 나그네도 하지 말지니라'),
(2063, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 11, 'OT', '이는 엿새 동안에 여호와가 하늘과 땅과 바다와 그 가운데 모든 것을 만들고 일곱째 날에 쉬었으므로, 여호와가 안식일을 복되게 하여 그 날을 거룩하게 하였느니라.'),
(2064, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 12, 'OT', '네 아버지와 네 어머니를 공경하라, 그리하면 네 날이 네 하나님 여호와께서 네게 주시는 땅에서 길리라.'),
(2065, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 13, 'OT', '살인하지 말지니라.'),
(2066, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 14, 'OT', '간음하지 말지니라.'),
(2067, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 15, 'OT', '도적질하지 말지니라.'),
(2068, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 16, 'OT', '네 친구에 대하여 거짓 증인이 되지 말지니라'),
(2069, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 17, 'OT', '네 친구의 집을 탐내지 말지니라. 네 친구의 여자와 그의 종과 그의 여종과 그의 소와 그의 나귀와 네 친구에게 있는 모든 것을 탐내지 말지니라.'),
(2070, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 18, 'OT', '모든 백성이 그 소리들과 횃불들과 나팔 소리와 연기 나는 산을 보았더라. 백성이 보고 떨며 멀리 서 있더라.'),
(2071, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 19, 'OT', '그들이 모세에게 말하되, 당신이 우리에게 말씀하소서 우리가 들으리이다. 하나님이 우리에게 말씀하시지 말게 하소서 우리가 죽을까 하나이다.'),
(2072, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 20, 'OT', '모세가 백성에게 이르되, 두려워하지 말라, 하나님께서 너희를 시험하시려고 오셨고, 그의 두려움이 너희 얼굴 위에 있게 하여 너희가 범죄하지 않게 하려 하심이니라.'),
(2073, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 21, 'OT', '백성은 멀리 서 있었고, 모세는 하나님이 계신 짙은 어둠에게 가까이 나아갔더라.'),
(2074, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 22, 'OT', '여호와께서 모세에게 이르시되 너는 이스라엘 자손에게 이같이 말하라 너희가 보았으니 내가 하늘에서부터 너희와 말하였느니라'),
(2075, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 23, 'OT', '너희는 나와 함께 은으로 만든 신상이나 금으로 만든 신상을 너희를 위하여 만들지 말지니라'),
(2076, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 24, 'OT', '내게 흙으로 제단을 만들고 그 위에 네 번제와 화목제, 네 양떼와 네 소를 드릴지니라 내가 내 이름을 기념하게 하는 모든 장소에서 내가 네게 이르러 네게 복을 주리라'),
(2077, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 25, 'OT', '네가 내게 돌로 제단을 만들려거든 다듬은 돌로 그것들을 쌓지 말라, 네가 네 칼을 그것 위에 휘두르면 그것을 더럽혔음이니라.'),
(2078, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 20, 26, 'OT', '너는 층계로 내 제단에 오르지 말지니, 이는 네 벌거벗음이 그 위에서 드러나지 않게 하려 함이라.'),
(2079, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 1, 'OT', '이것들이 네가 그들의 얼굴 앞에 세울 판결들이니라'),
(2080, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 2, 'OT', '네가 히브리인 종을 사면 그가 여섯 해 동안 섬길 것이요, 일곱째 해에는 값 없이 자유로 나갈 것이니라.'),
(2081, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 3, 'OT', '만일 그가 꼭대기로 왔으면 꼭대기로 나갈 것이요, 만일 그가 여자의 주인이라면 그의 여자도 그와 함께 나가리라.'),
(2082, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 4, 'OT', '만일 그의 주인이 그에게 여자를 주어 그 여자가 그에게 아들들이나 딸들을 낳았으면, 그 여자와 그 아이들은 그의 주인의 것이 될 것이요, 그는 꼭대기로 나갈 것이니라.'),
(2083, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 5, 'OT', '만일 종이 분명히 말하기를 내가 내 주인과 내 여자와 내 아들들을 사랑하니 내가 자유롭게 나가지 아니하겠다 하면'),
(2084, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 6, 'OT', '주인이 그를 하나님 앞으로 데려가고, 또 그를 문이나 문설주 앞으로 데려가서, 주인이 맞뚫개로 그의 귀를 뚫을 것이며, 그가 영원히 그를 섬기리라.'),
(2085, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 7, 'OT', '사람이 자기 딸을 여종으로 팔았으면, 그녀는 종들이 나오는 것처럼 나오지 못할 것이다.'),
(2086, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 8, 'OT', '만일 그녀가 그녀의 주인의 눈에 들지 아니하여 그가 그녀를 약혼시키지 아니하고 그녀를 속량하게 하면, 그가 그녀를 속였으므로 그녀를 다른 백성에게 팔 권한이 없느니라.'),
(2087, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 9, 'OT', '만일 그가 그녀를 자기 아들에게 정혼하였으면, 딸들의 판결대로 그녀에게 행할지니라.'),
(2088, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 10, 'OT', '만일 그가 다른 아내를 취할지라도 그녀의 살과 덮개와 혼인 의무는 감하지 못할지니라'),
(2089, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 11, 'OT', '만일 그가 그 세 가지를 그녀에게 행하지 아니하면, 그녀는 돈 없이 거저 나가게 될 것이니라.'),
(2090, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 12, 'OT', '사람을 쳐서 죽게 한 자는 반드시 죽임을 당할 것이다.'),
(2091, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 13, 'OT', '그러나 그가 계획하여 죽인 것이 아니라 하나님이 그의 손에 넘기신 것이라면, 내가 너를 위하여 그가 도망할 장소를 정하리라.'),
(2092, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 14, 'OT', '만일 사람이 그의 친구를 교활함으로 죽이려고 교만하게 범하면, 내 제단에서라도 그를 잡아내어 죽일지니라.'),
(2093, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 15, 'OT', '아버지나 어머니를 치는 자는 반드시 죽임을 당할지니라'),
(2094, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 16, 'OT', '사람을 훔쳐서 그를 팔거나 그가 그의 손에 발견되면 반드시 죽임을 당할 것이다.'),
(2095, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 17, 'OT', '아버지와 어머니를 저주하는 자는 반드시 죽임을 당할지니라'),
(2096, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 18, 'OT', '사람들이 서로 싸우다가 어떤 사람이 그의 친구를 돌이나 주먹으로 쳤으나 그가 죽지 않고 침상에 눕게 되면'),
(2097, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 19, 'OT', '만일 그가 일어나서 지팡이를 짚고 밖으로 걸어다니면 그를 친 자는 형벌을 면하되, 다만 그의 쉼에 대한 값을 지불하고 그를 온전히 치료하게 할지니라.'),
(2098, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 20, 'OT', '만일 어떤 사람이 막대기로 자기 종이나 여종을 쳐서 그가 그의 손 아래에서 죽으면 반드시 복수할지니라.'),
(2099, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 21, 'OT', '그러나 만일 그가 하루나 이틀을 서 있으면, 그는 벌을 받지 않을지니, 이는 그것이 그의 은이기 때문이다.'),
(2100, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 22, 'OT', '사람들이 서로 싸우다가 아이 밴 여자를 쳐서 그 아이가 나오게 하였으나 해가 없으면, 그 여자의 주인이 그에게 부과하는 대로 반드시 벌금을 내되, 재판관들 앞에서 지불할지니라.'),
(2101, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 23, 'OT', '만일 해가 있으면, 영혼 대신 영혼을 갚을지니라.'),
(2102, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 24, 'OT', '눈은 눈으로, 이빨은 이빨로, 손은 손으로, 발은 발로'),
(2103, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 25, 'OT', '화상은 화상으로, 상처는 상처로, 멍은 멍으로.'),
(2104, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 26, 'OT', '사람이 자기 종의 눈이나 자기 여종의 눈을 쳐서 그것을 상하게 하면, 그 눈 때문에 그를 자유롭게 놓아줄지니라.'),
(2105, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 27, 'OT', '만일 그의 종의 이빨이나 그의 여종의 이빨을 빠뜨리면, 그는 그 이빨 때문에 그를 자유롭게 놓아줄지니라.'),
(2106, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 28, 'OT', '만일 소가 사람이나 여자를 받아서 죽이면, 그 소는 반드시 돌에 맞아 죽을 것이요, 그 살은 먹지 말 것이며, 그 소의 주인은 무죄하니라.'),
(2107, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 29, 'OT', '만일 소가 본래 받는 버릇이 있어서 전에도 그랬고 오늘도 그랬으며, 그 주인에게 경고를 받았어도 그가 그것을 지키지 아니하여 그것이 사람이나 여자를 죽였으면, 그 소는 돌로 쳐 죽일 것이요, 그 주인도 죽일 것이니라.'),
(2108, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 30, 'OT', '만일 그에게 몸값이 부과되면, 그는 그의 영혼의 몸값을 그에게 부과된 모든 대로 낼 것이니라.'),
(2109, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 31, 'OT', '혹은 아들이나 혹은 딸을 받았으면 이 판결대로 그에게 행할지니라'),
(2110, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 32, 'OT', '만일 소가 남종이나 여종을 받으면, 그가 그 주인에게 은 삼십 세겔을 줄 것이요, 그 소는 돌에 맞아 죽을지니라.'),
(2111, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 33, 'OT', '사람이 우물을 열어 두거나 사람이 우물을 파고 그것을 덮지 아니하면 소나 나귀가 거기에 빠질 것이요'),
(2112, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 34, 'OT', '우물의 주인이 배상할지니, 은을 그 주인에게 돌려줄 것이요, 죽은 것은 그의 것이 되리라.'),
(2113, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 35, 'OT', '만일 어떤 사람의 소가 그의 친구의 소를 받아 죽이면, 그들은 살아 있는 소를 팔아 그 은을 반으로 나누고, 죽은 소도 또한 반으로 나눌지니라.'),
(2114, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 21, 36, 'OT', '혹시 그 소가 전부터 받는 버릇이 있는 줄 알려졌는데도 그 주인이 그것을 지키지 아니하였으면 그는 소로 소를 갚을 것이요, 죽은 것은 그의 것이 되리라'),
(2115, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 1, 'OT', '사람이 소나 양을 도적질하여 그것을 잡거나 팔면, 그는 그 소 대신에 소 다섯을 갚고, 그 양 대신에 양떼 넷을 갚을지니라.'),
(2116, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 2, 'OT', '도둑이 굴을 뚫는 중에 발견되어 맞아 죽으면 그에게 피 흘린 죄가 없느니라.'),
(2117, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 3, 'OT', '해가 그 위에 돋았으면 그에게 피 값이 있으니 반드시 배상할 것이요, 그에게 없는 경우에는 그의 도둑질로 인해 팔릴 것이니라.'),
(2118, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 4, 'OT', '만일 그 도둑질한 것이 살아서 그의 손에 있으면, 소에서부터 나귀까지, 양까지, 둘을 갚을지니라.'),
(2119, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 5, 'OT', '만일 사람이 들판이나 포도원에서 불을 놓아 가축을 보내어 다른 사람의 들판을 먹게 하면, 자기 들판의 최상과 자기 포도원의 최상으로 배상할지니라.'),
(2120, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 6, 'OT', '불이 나서 가시에 옮겨 붙어 곡식단이나 곡식이나 들판이 불타면, 그 불을 놓은 자가 반드시 배상할지니라.'),
(2121, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 7, 'OT', '사람이 친구에게 은이나 그릇을 맡겨 지키게 하였는데 그 사람의 집에서 도둑을 맞았으면, 그 도둑이 발견되면 그는 갑절을 배상할지니라.'),
(2122, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 8, 'OT', '만일 도둑이 발견되지 아니하면 그 집 주인이 하나님 앞에 나아갈 것이며, 그가 자기 친구의 일에 손을 대지 아니하였는지를 알게 될 것이니라.'),
(2123, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 9, 'OT', '모든 반역의 말씀에 대하여, 소에 대하여, 나귀에 대하여, 양에 대하여, 옷에 대하여, 모든 잃어버린 것에 대하여, 그가 말하기를 이것이 그것이라 하면, 두 사람의 말씀이 하나님 앞에 나아갈 것이요, 하나님이 죄 있다고 하시는 자가 그의 친구에게 갑절을 배상할지니라.'),
(2124, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 10, 'OT', '사람이 친구에게 나귀나 소나 양이나 모든 짐승을 맡겨 지키게 하였는데 그것이 죽거나 상하거나 끌려가도 그것을 본 사람이 없으면'),
(2125, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 11, 'OT', '여호와의 맹세가 그들 둘 사이에 있을 것이니 그가 그의 친구의 일에 손을 대지 아니하였다는 것이라 그 주인이 그것을 받을 것이요 그는 배상하지 아니하리라'),
(2126, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 12, 'OT', '만일 그것이 그에게서 도둑맞으면, 그는 그것의 주인에게 배상할 것이다.'),
(2127, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 13, 'OT', '만일 찢겨 죽임을 당하면 그것을 증인에게 가져올 것이요, 그 찢긴 것은 배상하지 아니하리라.'),
(2128, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 14, 'OT', '만일 어떤 사람이 친구에게서 빌렸는데 그것이 부러지거나 죽으면, 그 주인이 그와 함께 있지 아니할 때에는 반드시 배상할지니라.'),
(2129, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 15, 'OT', '그 주인이 그것과 함께 있으면 배상하지 않을 것이요, 만일 삯꾼이면 그는 삯으로 왔느니라.'),
(2130, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 16, 'OT', '사람이 약혼하지 아니한 처녀를 꾀어 그와 동침하였으면 반드시 그에게 빙폐를 드려 그를 여자로 삼을 것이니라'),
(2131, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 17, 'OT', '만일 그 아버지가 그를 그에게 주기를 거절하면 그는 처녀의 지참금대로 은을 달아 줄지니라'),
(2132, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 18, 'OT', '무당을 살려 두지 말지니라.'),
(2133, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 19, 'OT', '모든 짐승과 함께 눕는 자는 반드시 죽임을 당할 것이다.'),
(2134, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 20, 'OT', '다른 신에게 제사를 드리는 자는 진멸될지니라, 오직 여호와께만 따로 드릴지니라.'),
(2135, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 21, 'OT', '너는 나그네를 속이지 말며 그를 압제하지 말라 너희가 애굽 땅에서 나그네였음이라'),
(2136, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 22, 'OT', '모든 과부와 고아를 학대하지 말지니라'),
(2137, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 23, 'OT', '네가 그를 괴롭히되 반드시 괴롭게 하면, 그가 내게 부르짖되 반드시 부르짖을 때에 내가 반드시 그의 부르짖음을 들으리라.'),
(2138, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 24, 'OT', '내 분노가 타오르리니 내가 칼로 너희를 죽이리라. 너희 여자들은 과부가 되고 너희 아들들은 고아가 되리라.'),
(2139, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 25, 'OT', '네가 내 백성, 곧 너와 함께 있는 가난한 자에게 은을 꾸어 주거든 그에게 채주처럼 되지 말며, 그에게 고리대금을 부과하지 말지니라.'),
(2140, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 26, 'OT', '네가 만일 친구의 옷을 전당잡거든 해가 지기 전에 그에게 돌려보내라'),
(2141, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 27, 'OT', '그것은 그의 덮개요 그에게 따로 있는 것뿐이라 그것은 그의 가죽을 위한 그의 옷이니 그가 무엇을 입고 자겠느냐 그가 내게 부르짖을 때에 내가 들으리니 나는 자비로운 자임이라'),
(2142, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 28, 'OT', '하나님을 저주하지 말며 네 백성의 통치자를 욕하지 말지니라.'),
(2143, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 29, 'OT', '네 성숙한 열매와 눈물을 지체하지 말고 드리되, 네 아들들의 장자를 내게 줄지니라.'),
(2144, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 30, 'OT', '네 소와 양떼에게도 그와 같이 하되, 칠 일 동안 그것이 어미와 함께 있을 것이요, 여덟째 날에 그것을 내게 줄지니라.'),
(2145, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 22, 31, 'OT', '너희는 내게 거룩한 사람이 될지니 들판에서 찢긴 살은 먹지 말고 그것을 개에게 던질지니라'),
(2146, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 1, 'OT', '너는 헛된 소문을 퍼뜨리지 말며 악인과 함께 손을 얹어 폭력적인 증인이 되지 말지니라'),
(2147, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 2, 'OT', '다수를 따라 악을 행하지 말며 분쟁에 응하여 다수를 따라 판결을 굽히지 말지니라'),
(2148, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 3, 'OT', '가난한 자를 그의 분쟁에서 존중하지 말지니라.'),
(2149, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 4, 'OT', '네가 네 원수의 소나 그의 나귀가 길을 잃은 것을 만나거든 반드시 그것을 그에게로 돌려보낼지니라.'),
(2150, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 5, 'OT', '네가 너를 미워하는 자의 나귀가 그 짐 아래에 엎드려 있는 것을 보거든, 그것을 버려두지 말고 반드시 그와 함께 도와줄지니라.'),
(2151, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 6, 'OT', '가난한 자의 판결을 그의 분쟁에서 굽게 하지 말지니라'),
(2152, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 7, 'OT', '거짓 말씀에게서 멀리하라, 무죄한 자와 의로운 자를 죽이지 말라, 내가 악인을 의롭다 하지 아니할 것임이라.'),
(2153, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 8, 'OT', '너는 뇌물을 받지 말라, 뇌물은 밝은 자의 눈을 어둡게 하고 의로운 자의 말씀을 굽게 하느니라.'),
(2154, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 9, 'OT', '너는 나그네를 압제하지 말지니라. 너희가 애굽 땅에서 나그네였었으므로 나그네의 영혼을 아느니라.'),
(2155, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 10, 'OT', '네가 육 년 동안 네 땅에 씨를 뿌리고 그 수확을 거둘지니라.'),
(2156, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 11, 'OT', '일곱째 해에는 그것을 쉬게 하고 버려 두어서 네 백성의 가난한 자들이 먹게 하라, 그 남은 것은 들판의 살아있는 짐승이 먹으리라. 네 포도원과 네 올리브에도 그렇게 할지니라.'),
(2157, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 12, 'OT', '육일 동안에 네 행위를 할 것이요, 일곱째 날에는 쉴지니 이는 네 소와 네 나귀가 쉬게 하며 네 여종의 아들과 나그네가 숨을 돌리게 하려 함이라'),
(2158, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 13, 'OT', '내가 너희에게 말한 모든 것에 삼가 지키고, 다른 신들의 이름은 기억하지 말며, 네 입에서 들리지 않게 하라.'),
(2159, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 14, 'OT', '너는 해에 세 번 내게 절기를 지킬지니라.'),
(2160, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 15, 'OT', '누룩 없는 빵의 축제를 지키라. 내가 네게 명령한 대로 이삭의 달의 정한 때에 칠 일 동안 누룩 없는 빵을 먹을지니, 이는 그 달에 네가 애굽에서 나왔음이라. 그리고 내 얼굴이 빈손으로 나타나지 않게 하라.'),
(2161, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 16, 'OT', '추수의 축제, 네가 들판에 뿌린 네 행위의 첫 열매를 지키고, 해의 끝에 네가 들판에서 네 행위를 거둘 때의 추수의 축제를 지키라.'),
(2162, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 17, 'OT', '해마다 세 번, 네 모든 남자아이들이 주인 여호와의 얼굴 앞에 나타날지니라.'),
(2163, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 18, 'OT', '내 제사의 피를 누룩과 함께 드리지 말며 내 축제의 기름을 아침까지 남겨 두지 말지니라'),
(2164, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 19, 'OT', '네 땅의 첫 열매의 처음 것을 네 하나님 여호와의 집으로 가져올지니라. 너는 염소 새끼를 그 어미의 젖으로 삶지 말지니라.'),
(2165, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 20, 'OT', '보라, 내가 천사를 네 얼굴 앞에 보내어 길에서 너를 지키고, 내가 예비한 장소로 너를 인도하게 하리라.'),
(2166, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 21, 'OT', '그의 얼굴을 삼가고 그의 소리를 들으며 그를 거역하지 말라 그가 너희 반역을 용서하지 아니할 것임이라 이는 내 이름이 그의 속에 있음이니라'),
(2167, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 22, 'OT', '네가 참으로 그의 소리를 청종하고 내가 말하는 모든 것을 행하면, 내가 네 원수들을 원수로 삼고 네 대적들을 대적하리라.'),
(2168, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 23, 'OT', '내 천사가 네 얼굴 앞에 가서 너를 아모리 사람과 히타이트 사람과 브리스 사람과 가나안 사람과 히위 사람과 여부스 사람에게로 인도하리니 내가 그를 끊으리라.'),
(2169, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 24, 'OT', '너는 그들의 하나님께 경배하지 말며 그들을 섬기지 말며 그들의 행위대로 행하지 말지니라 오직 너는 그들을 완전히 헐어버리고 그들의 기둥을 부수어 깨뜨릴지니라'),
(2170, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 25, 'OT', '너희는 너희 하나님 여호와를 섬기라 그가 네 빵과 네 물에 복을 내리리라 내가 네 속에서 병을 제하리라'),
(2171, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 26, 'OT', '네 땅에서 유산하는 자가 없고 잉태하지 못하는 자가 없을 것이며, 내가 네 날의 수를 채우리라.'),
(2172, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 27, 'OT', '내가 내 공포를 네 얼굴 앞에 보내어 네가 그들에게 이를 모든 백성을 멸하고, 네 모든 원수들이 네게 목을 돌리게 하리라.'),
(2173, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 28, 'OT', '내가 말벌을 네 얼굴 앞에 보내리니 그것이 히위 사람과 가나안 사람과 히타이트 사람을 네 얼굴 앞에서 쫓아내리라.'),
(2174, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 29, 'OT', '내가 그들을 일 년 안에 네 얼굴 앞에서 쫓아내지 아니하리니, 그리하여 땅이 황폐하게 되고 들판의 살아있는 짐승들이 네게 많아질까 함이라.'),
(2175, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 30, 'OT', '조금 조금 내가 그들을 네 얼굴 앞에서 쫓아내리니, 네가 번성하여 그 땅을 기업으로 얻을 때까지니라.'),
(2176, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 31, 'OT', '내가 네 경계를 갈대 바다에서부터 블레셋 사람의 바다까지, 광야에서부터 강까지 정하리니, 이는 내가 그 땅의 거주민들을 너희 손에 넘겨주고 그들을 네 얼굴 앞에서 쫓아낼 것임이라.'),
(2177, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 32, 'OT', '그들과 그들의 하나님과 언약을 맺지 말라'),
(2178, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 23, 33, 'OT', '그들이 네 땅에 거주하지 못하리니, 그들이 너로 하여금 나에게 범죄하게 하지 못하게 하려 함이라. 네가 그들의 하나님을 섬기면 그것이 네게 덫이 될 것임이니라.'),
(2179, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 1, 'OT', '그리고 모세에게 말씀하시되 여호와께로 올라오라, 너와 아론, 나답과 아비후, 그리고 이스라엘 장로 칠십 인과 함께, 너희는 멀리서 경배할지니라.'),
(2180, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 2, 'OT', '모세는 따로 여호와께 가까이 나아갈 것이요 그들은 가까이 나아가지 못할 것이며 백성은 그와 함께 올라가지 못할지니라'),
(2181, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 3, 'OT', '모세가 와서 여호와의 모든 말씀과 모든 판결을 백성에게 전하매 모든 백성이 한 소리로 응답하여 이르되 여호와께서 말씀하신 모든 말씀을 우리가 행하리이다'),
(2182, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 4, 'OT', '모세가 여호와의 모든 말씀을 기록하고 아침에 일찍 일어나 산 아래에 제단을 쌓고 이스라엘의 열두 막대기대로 열두 기둥을 세우니라'),
(2183, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 5, 'OT', '그가 이스라엘 자손의 소년들을 보내어 번제를 드리게 하고 여호와께 수송아지로 화목제 제사를 드리게 하니라'),
(2184, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 6, 'OT', '모세가 피의 반을 취하여 대접에 두고, 피의 반은 제단에 뿌리니라'),
(2185, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 7, 'OT', '그가 언약의 책을 가져다가 백성의 귀에 낭독하매 그들이 말하되 여호와께서 말씀하신 모든 것을 우리가 행하고 듣겠나이다'),
(2186, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 8, 'OT', '모세가 그 피를 취하여 백성에게 뿌리고 말하되, 보라 이는 여호와께서 이 모든 말씀에 대하여 너희와 맺으신 언약의 피니라'),
(2187, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 9, 'OT', '모세와 아론과 나답과 아비후와 이스라엘 장로 칠십 인이 올라가니라'),
(2188, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 10, 'OT', '그들이 이스라엘의 하나님을 보았고 그의 발 아래에는 사파이어 리브나의 행위 같은 것이 있었으며, 광채에 있어서 하늘의 뼈와 같았더라.'),
(2189, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 11, 'OT', '그러나 이스라엘 아들들의 귀족들에게는 그의 손을 대지 아니하셨고 그들은 하나님을 보고 먹고 마셨더라'),
(2190, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 12, 'OT', '여호와께서 모세에게 이르시되, 너는 산에 올라 내게로 와서 거기 있으라. 내가 너에게 돌판과 율법과 명령, 곧 내가 그들을 가르치기 위해 기록한 것을 주리라.'),
(2191, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 13, 'OT', '모세가 일어나고 그의 시종 여호수아도 일어나니, 모세가 하나님의 산으로 올라가니라.'),
(2192, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 14, 'OT', '그가 장로들에게 이르되, 너희는 여기서 우리가 너희에게로 돌아올 때까지 기다리라. 보라, 아론과 후르가 너희와 함께 있으니, 말씀의 주인이 있는 자는 그들에게로 나아갈지니라.'),
(2193, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 15, 'OT', '모세가 산에 오르매 구름이 산을 가리니라'),
(2194, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 16, 'OT', '여호와의 영광이 시내 산 위에 머물렀고 구름이 육 일 동안 그것을 덮었으며, 일곱째 날에 그가 구름 중간에서 모세를 부르셨더라.'),
(2195, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 17, 'OT', '여호와의 영광의 모습이 산의 머리 위에서 이스라엘 자손의 눈에 삼키는 불 같았더라'),
(2196, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 24, 18, 'OT', '모세가 구름 중간으로 들어가서 산에 올랐으며, 모세가 산에 사십 일과 사십 밤을 있었더라.'),
(2197, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2198, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 2, 'OT', '이스라엘 자손에게 말하라 그들이 내게 제사를 가져올지니 모든 사람이 그 마음이 자원하여 내는 자에게서 너희는 내 제사를 받을지니라'),
(2199, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 3, 'OT', '이것이 그들에게서 너희가 취할 제사이니 금과 은과 놋쇠라'),
(2200, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 4, 'OT', '청색과 자주색과 진홍색과 가는 베실과 염소털'),
(2201, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 5, 'OT', '붉은 물들인 숫양의 가죽과 오소리의 가죽과 싯딤나무'),
(2202, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 6, 'OT', '빛을 위한 기름과 기름부음의 기름을 위한 향기와 향료의 향을 위한 향기'),
(2203, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 7, 'OT', '마노 돌과 위임식 돌들, 에봇과 흉패를 위한 것이라.'),
(2204, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 8, 'OT', '그들이 나를 위하여 성소를 짓고, 내가 그들 중간에 거하리라.'),
(2205, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 9, 'OT', '내가 네게 보이는 모든 대로 장막의 모형과 그 모든 그릇의 모형을 따라 너희가 그렇게 행할지니라'),
(2206, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 10, 'OT', '그들이 싯딤나무로 궤를 만들되 그 길이는 두 규빗 반, 그 너비는 한 규빗 반, 그 키는 한 규빗 반이 되게 할지니라'),
(2207, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 11, 'OT', '너는 그것을 순금으로 입히되 안과 밖을 입히고, 그 위에 금으로 만든 왕관을 주위에 두를지니라.'),
(2208, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 12, 'OT', '금고리 넷을 부어 만들고, 그것의 네 때에 달되, 그 한 옆에 두 고리요, 그 둘째 옆에 두 고리라.'),
(2209, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 13, 'OT', '너는 싯딤나무로 따로를 만들고 그것들을 금으로 입힐지니라'),
(2210, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 14, 'OT', '그 채를 반지들에 꿰어 궤의 옆에 두어 그것들로 궤를 메게 하라'),
(2211, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 15, 'OT', '채는 궤의 반지들에 있을 것이며 그것들에게서 빼내지 말지니라'),
(2212, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 16, 'OT', '너는 내가 네게 줄 증언을 궤 안에 두라.'),
(2213, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 17, 'OT', '너는 순금으로 속죄소를 만들되, 그 길이는 두 규빗 반, 그 너비는 한 규빗 반이 되게 할지니라.'),
(2214, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 18, 'OT', '네가 두 그룹을 금으로 만들되, 두들겨 만든 것으로 그것들을 만들지니, 속죄소의 두 끝에서 할지니라.'),
(2215, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 19, 'OT', '네 쪽 끝에 그룹 하나를 만들고, 다른 쪽 끝에 그룹 하나를 만들되, 속죄소의 두 끝에 그룹들을 속죄소와 한 덩이로 만들지니라.'),
(2216, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 20, 'OT', '그룹들은 날개를 위로 펴서 그들의 날개로 속죄소를 덮으며 그들의 얼굴은 서로 마주보되, 그룹들의 얼굴은 속죄소를 향하게 될지니라.'),
(2217, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 21, 'OT', '너는 속죄소를 궤 위에 얹고, 내가 네게 줄 증언을 궤 안에 넣을지니라.'),
(2218, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 22, 'OT', '내가 거기서 너와 만나고 속죄소 위에서, 곧 증언궤 위에 있는 두 그룹 사이에서, 내가 이스라엘 자손에게 네게 명할 모든 것을 네게 말하리라.'),
(2219, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 23, 'OT', '너는 싯딤나무로 상을 만들되, 그 길이는 두 규빗, 너비는 한 규빗, 그 키는 한 규빗 반이 되게 할지니라.'),
(2220, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 24, 'OT', '너는 그것을 순금으로 입히고, 그것을 위하여 금 왕관을 그 주위에 만들지니라.'),
(2221, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 25, 'OT', '너는 그것에게 한 뼘 너비의 가장자리를 그 주위에 만들고, 그 가장자리 주위에 금으로 왕관을 만들지니라.'),
(2222, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 26, 'OT', '그것을 위하여 금반지 넷을 만들고, 그 반지들을 네 발에 있는 네 모퉁이에 달지니라.'),
(2223, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 27, 'OT', '턱 곁에 반지들이 있으리니, 상을 메는 채를 꿸 집들을 위하여 따로 있으리라.'),
(2224, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 28, 'OT', '또한 싯딤나무로 그 채들을 만들고 그것들을 금으로 입히며, 그것들로 그 상을 멜 것이니라.'),
(2225, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 29, 'OT', '너는 그 쟁반들과 그 손바닥들과 그 덮개들과 그 사발들을 만들되, 그것들로 부어 붓는 것들을 만들지니, 정금으로 그것들을 만들지어다.'),
(2226, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 30, 'OT', '상 위에 얼굴의 빵을 내 얼굴 앞에 항상 두라.'),
(2227, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 31, 'OT', '너는 정금으로 촛대를 만들되, 두들겨 만든 것으로 촛대를 만들지니, 그 넓적다리와 갈대, 그 잔들과 손잡이들과 꽃들이 그것에서 나올지니라.'),
(2228, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 32, 'OT', '여섯 갈대가 그 곁에서 나오되, 촛대의 세 갈대는 그 한쪽 곁에서, 촛대의 세 갈대는 그 둘째 곁에서 나오며'),
(2229, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 33, 'OT', '한 갈대에 살구꽃 형상의 잔 셋과 손잡이와 꽃이 있고, 다른 갈대에도 살구꽃 형상의 잔 셋과 손잡이와 꽃이 있으니, 촛대에서 나온 여섯 갈대가 다 그러하며'),
(2230, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 34, 'OT', '촛대에는 네 개의 잔이 있으며, 살구꽃 모양으로, 그 손잡이들과 그 꽃들이 있게 하라.'),
(2231, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 35, 'OT', '손잡이 하나는 그 갈대 둘 아래에 있고, 손잡이 하나는 그 갈대 둘 아래에 있고, 손잡이 하나는 그 갈대 둘 아래에 있으니, 촛대에서 나온 여섯 갈대를 위함이니라.'),
(2232, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 36, 'OT', '그들의 손잡이와 갈대는 그것에서 나올 것이며, 그것의 모든 것은 두들겨 만든 한 덩어리, 순금이 될지니라.'),
(2233, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 37, 'OT', '네가 그것의 등불 일곱을 만들고, 그것의 등불들을 올려 그것의 얼굴 건너편을 비추게 할지니라.'),
(2234, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 38, 'OT', '그 집게들과 불집게들은 순금으로 만들지니'),
(2235, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 39, 'OT', '정금 한 덩어리로 그것을 만들되, 이 모든 그릇을 만들지니라.'),
(2236, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 25, 40, 'OT', '너는 보고 그들의 모형대로 행하되, 네가 그 산에서 보인 대로 하라.'),
(2237, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 1, 'OT', '너는 장막을 만들되 열 폭의 휘장을 만들지니 가늘게 꼰 베실과 청색과 자색과 진홍색 실로 그룹들을 공교한 행위로 만들어 그것들을 만들지니라'),
(2238, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 2, 'OT', '한 휘장의 길이는 스물여덟 규빗, 한 휘장의 너비는 네 규빗이며, 모든 휘장은 한 치수로 같게 하라.'),
(2239, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 3, 'OT', '다섯 휘장은 서로 연결되되 여자가 그 자매에게 연결되며, 또 다섯 휘장은 서로 연결되되 여자가 그 자매에게 연결될지니라.'),
(2240, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 4, 'OT', '청색 고리를 한 휘장의 입술 끝, 이음매에 만들고, 둘째 이음매에 있는 바깥 휘장의 입술에도 그와 같이 할지니라.'),
(2241, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 5, 'OT', '휘장 하나에 고리 오십 개를 만들고, 둘째 이음매에 있는 휘장의 끝에도 고리 오십 개를 만들어 그 고리들이 서로 마주보게 하되, 하나가 그 자매를 향하게 할지니라.'),
(2242, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 6, 'OT', '금 갈고리 오십 개를 만들고, 그 갈고리들로 휘장들을 여자가 그 자매에게 연결하라. 그리하면 장막이 하나가 될지니라.'),
(2243, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 7, 'OT', '염소 휘장들로 장막 위에 덮는 천막을 만들되, 열한 폭 휘장을 만들지니라.'),
(2244, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 8, 'OT', '한 휘장의 길이는 삼십 규빗, 한 휘장의 너비는 사 규빗이며, 열한 휘장의 옷은 하나의 척도로 하라.'),
(2245, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 9, 'OT', '다섯 휘장을 따로 잇고, 여섯 휘장을 따로 잇되, 여섯째 휘장은 천막 얼굴 앞쪽으로 접어 드리우라.'),
(2246, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 10, 'OT', '너는 이음매에 있는 첫째 휘장의 가장자리 입술에 고리 오십 개를 만들고, 둘째 이음매에 있는 휘장의 입술에도 고리 오십 개를 만들지니라.'),
(2247, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 11, 'OT', '놋쇠 갈고리 오십 개를 만들고, 그 갈고리들을 고리에 끼워 천막을 연결하라, 그러면 그것이 하나가 되리라.'),
(2248, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 12, 'OT', '남은 자는 천막의 휘장 중에서 남은 반 휘장을 장막 뒤에 드리울지니라'),
(2249, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 13, 'OT', '한 규빗은 이쪽에, 한 규빗은 저쪽에, 천막 휘장의 길이에서 남은 것이 장막의 곁들 이쪽과 저쪽에 덮어 드리우리라.'),
(2250, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 14, 'OT', '너는 천막을 위한 덮개를 붉게 물들인 숫양의 가죽으로 만들고, 그 위에 오소리 가죽으로 덮개를 만들지니라.'),
(2251, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 15, 'OT', '너는 장막을 위하여 널빤지를 만들되 싯딤나무로 세워서 만들지니라'),
(2252, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 16, 'OT', '널빤지의 길이는 열 규빗이요, 그 한 널빤지의 너비는 한 규빗 반이니라.'),
(2253, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 17, 'OT', '각 널빤지에 두 손이 있어 서로 여자처럼 자매에게 맞물리게 하되, 너는 장막의 모든 널빤지에 그와 같이 할지니라.'),
(2254, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 18, 'OT', '너는 장막을 위하여 널빤지들을 만들되, 남쪽 모퉁이 쪽을 위하여 널빤지 스무 개를 만들지니라.'),
(2255, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 19, 'OT', '은 받침대 마흔 개를 스무 널빤지 아래에 만들되, 한 널빤지 아래에 그 두 손을 위하여 받침대 두 개를, 또 한 널빤지 아래에 그 두 손을 위하여 받침대 두 개를 만들지니라.'),
(2256, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 20, 'OT', '장막의 둘째 옆, 곧 북쪽 모퉁이를 위하여 널빤지 스물 개로 하라.'),
(2257, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 21, 'OT', '그들의 받침대는 은으로 마흔 개이니, 한 널빤지 아래에 두 받침대, 또 한 널빤지 아래에 두 받침대라.'),
(2258, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 22, 'OT', '장막의 변두리, 곧 바다 쪽을 위하여는 널빤지 여섯을 만들지니라.'),
(2259, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 23, 'OT', '장막의 변두리 모퉁이를 위하여 널빤지 둘을 만들지니'),
(2260, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 24, 'OT', '그들이 아래에서 쌍둥이로 되고, 함께 그 머리 위에서 하나의 반지에 이르기까지 온전하게 되며, 그와 같이 그들 둘에게 있게 되고, 두 모퉁이에게 있게 될 것이다.'),
(2261, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 25, 'OT', '널빤지는 여덟 개가 될 것이며, 그 받침대들은 은으로 열여섯 받침대이니, 한 널빤지 아래에 두 받침대, 또 한 널빤지 아래에 두 받침대이니라.'),
(2262, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 26, 'OT', '너는 싯딤나무로 빗장들을 만들지니, 장막의 한쪽 옆의 널빤지들을 위하여 다섯이요.'),
(2263, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 27, 'OT', '또한 장막의 둘째 옆 널빤지를 위하여 빗장 다섯 개요, 장막의 옆 널빤지를 위하여 바다 쪽 변두리로 빗장 다섯 개요,'),
(2264, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 28, 'OT', '중간 빗장은 널빤지 중간에 있어, 이 끝에서 저 끝까지 미치게 하라.'),
(2265, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 29, 'OT', '널빤지들을 금으로 입히고 그들의 반지들을 금으로 만들되 빗장들을 위한 집들을 만들고, 그 빗장들을 금으로 입힐지니라.'),
(2266, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 30, 'OT', '너는 산에서 보인 판결대로 장막을 세울지니라.'),
(2267, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 31, 'OT', '너는 청색과 자주색과 진홍색과 가늘게 꼰 베실로 휘장을 만들되, 공교한 행위로 그룹들을 그 위에 수놓아 만들지니라.'),
(2268, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 32, 'OT', '그것을 싯딤나무 기둥 네 개 위에 두되, 금으로 입힌 기둥들과 그 갈고리들은 금이며, 은 받침대 네 개 위에 두라.'),
(2269, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 33, 'OT', '너는 휘장을 갈고리 아래에 달고, 그 휘장 안으로 증언궤를 가져다 놓아라. 그 휘장이 너희를 위하여 거룩한 곳과 지성소 사이를 구별할 것이다.'),
(2270, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 34, 'OT', '너는 속죄소를 증언의 궤 위에 거룩함의 거룩함 안에 두라.'),
(2271, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 35, 'OT', '너는 휘장 바깥에 상을 두고, 등대는 상 맞은편에 두되 장막의 남쪽 옆에 두며, 상은 북쪽 옆에 둘지니라.'),
(2272, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 36, 'OT', '청색과 자주색과 진홍색 실과 가늘게 꼰 베실로 수 놓아 짠 휘장을 천막 문에 만들지니, 그것은 수 놓는 행위로 만든 것이니라.'),
(2273, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 26, 37, 'OT', '너는 휘장을 위하여 싯딤나무 기둥 다섯을 만들고 그것들을 금으로 입히며 그 갈고리들도 금으로 하고 그것들을 위하여 놋쇠 받침대 다섯을 부어 만들지니라'),
(2274, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 1, 'OT', '너는 싯딤나무로 제단을 만들되 길이가 다섯 규빗, 너비가 다섯 규빗이라 제단은 네모 반듯하게 하며, 그 키는 세 규빗으로 할지니라.'),
(2275, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 2, 'OT', '네가 그것의 네 모퉁이 위에 그것의 뿔들을 만들되, 그것의 뿔들은 그것에서 나오게 할지니라. 그리고 너는 그것을 놋쇠로 입힐지니라.'),
(2276, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 3, 'OT', '너는 그것의 재를 담는 냄비들과 그것의 삽들과 그것의 대접들과 그것의 고기갈고리들과 그것의 불집게들을 만들고, 그것의 모든 그릇을 놋쇠로 만들지니라.'),
(2277, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 4, 'OT', '너는 그것을 위하여 놋쇠로 그물 모양의 석쇠를 만들고, 그 그물 위에 그 네 끝에 놋쇠 반지 넷을 만들지니라.'),
(2278, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 5, 'OT', '그것을 제단 가장자리 아래에 두되 그물이 제단의 반까지 이르게 할지니라'),
(2279, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 6, 'OT', '너는 제단을 위하여 따로를 만들되 싯딤나무로 따로를 만들고 그것들을 놋쇠로 입힐지니라'),
(2280, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 7, 'OT', '그의 채들을 반지들에 꿰고, 그 채들이 제단의 두 옆에 있게 하여 그것을 멜 때에 이르게 하라.'),
(2281, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 8, 'OT', '네가 그것을 널판으로 비게 만들되, 산에서 네게 보인 대로 그들이 만들지니라.'),
(2282, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 9, 'OT', '너는 장막의 뜰을 만들지니 남쪽 모퉁이를 향하여 남쪽에 뜰을 위한 매달린 휘장을 세마포로 짠 백 규빗 길이로 그 한 모퉁이에 만들지니라.'),
(2283, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 10, 'OT', '그 기둥들은 스물이며 그 받침대들도 스물인데 놋쇠로 하고, 그 기둥들의 갈고리와 그 가름대들은 은으로 하며'),
(2284, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 11, 'OT', '북쪽 모퉁이에도 길이를 따라 매달린 휘장이 백 길이요, 그 기둥은 스물이며 그들의 받침대는 스물로 놋쇠요, 기둥들의 갈고리와 그들의 가름대는 은이니라.'),
(2285, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 12, 'OT', '뜰의 너비는 바다 모퉁이 쪽에 매달린 휘장 오십 규빗이요, 그 기둥이 열이요, 그 받침대가 열이니라.'),
(2286, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 13, 'OT', '뜰의 너비는 동쪽 모퉁이, 곧 동쪽을 향한 쪽이 오십 규빗이라.'),
(2287, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 14, 'OT', '어깨를 위한 매달린 휘장은 열다섯 규빗이며, 그 기둥은 셋이요, 그 받침대는 셋이니라.'),
(2288, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 15, 'OT', '다른 쪽 어깨를 위하여도 매달린 휘장이 열다섯이며, 그 기둥이 셋이요, 그 받침대가 셋이며'),
(2289, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 16, 'OT', '뜰 문을 위하여는 청색, 자주색, 진홍색과 가늘게 꼰 베실로 수 놓아 짠 이십 규빗의 휘장이 있게 할지니 그 기둥이 넷이요, 그 받침대가 넷이며'),
(2290, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 17, 'OT', '뜰 주위의 모든 기둥은 은으로 입혀졌고, 그 갈고리들은 은이며, 그 받침대들은 놋쇠로 되었느니라.'),
(2291, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 18, 'OT', '뜰의 길이는 백 규빗이요, 너비는 오십 규빗이며, 키는 다섯 규빗인데 가늘게 꼰 베요, 그 받침대들은 놋쇠니라.'),
(2292, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 19, 'OT', '장막의 모든 그릇과 그 모든 일에 쓰는 모든 기구와 그 모든 말뚝과 뜰의 모든 말뚝은 놋쇠로 할지니라'),
(2293, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 20, 'OT', '너는 이스라엘 자손에게 명령하여 그들이 너에게 빛을 위한 순결한 올리브 기름을 찧어낸 것으로 가져오게 하여 항상 등불을 켜게 하라'),
(2294, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 27, 21, 'OT', '정한 때의 천막 안, 증언 위에 있는 휘장 밖에서 아론과 그의 아들들이 그것을 저녁부터 아침까지 여호와 앞에 정돈할지니, 이는 이스라엘 자손에게서 온 그들의 세대를 위한 영원한 규례니라.'),
(2295, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 1, 'OT', '너는 이스라엘 자손 중에서 네 형 아론과 그와 함께 있는 그의 아들들을 네게로 가까이 데려오되, 그들이 나를 위하여 제사장 직분을 행하게 하라. 아론과 나답과 아비후와 엘르아살과 이다말, 곧 아론의 아들들이다.'),
(2296, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 2, 'OT', '너는 네 형 아론을 위하여 거룩한 옷을 지어서 영광과 아름다움을 위하게 할지니라'),
(2297, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 3, 'OT', '너는 모든 마음이 지혜로운 자, 곧 내가 지혜의 영으로 채운 자에게 말하여 아론의 옷을 만들어 그를 거룩하게 하여 내게 제사장으로 섬기게 하라'),
(2298, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 4, 'OT', '이것들은 그들이 만들 옷들이니 곧 흉패와 에봇과 겉옷과 수놓은 속옷과 터번과 띠라 그들이 네 형 아론과 그의 아들들을 위하여 거룩한 옷을 만들어 그들이 내게 제사장으로 섬기게 할지니라'),
(2299, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 5, 'OT', '그들이 금과 청색과 자주색과 진홍색과 가는 실을 가져올 것이며'),
(2300, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 6, 'OT', '그들이 금과 청색과 자주색과 진홍색과 가늘게 꼰 베실로 공교한 행위로 에봇을 만들지니'),
(2301, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 7, 'OT', '그것에게 두 어깨가 있어서 그것의 두 끝에 연결될 것이며, 그것이 함께 연결될 것이다.'),
(2302, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 8, 'OT', '에봇 위에 있는 그 띠는 에봇과 같은 행위로 만들되, 그 자체에서 나온 것이어야 하며, 금과 청색, 자주색, 진홍색 실과 가늘게 꼰 베실로 할지니라.'),
(2303, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 9, 'OT', '너는 마노 두 돌을 취하고 그 위에 이스라엘 아들들의 이름을 새기라'),
(2304, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 10, 'OT', '그들의 이름 중 여섯은 한 돌 위에, 나머지 여섯 이름은 둘째 돌 위에 그들의 세대대로 있게 하라'),
(2305, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 11, 'OT', '돌 장인의 행위로, 인장의 새김들로 너는 그 두 돌을 이스라엘 아들들의 이름 위에 새기되, 금 보석 테두리들로 그것들을 둘러 만들지니라.'),
(2306, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 12, 'OT', '너는 그 두 돌을 에봇의 어깨에 두되 이스라엘 아들들의 기념 돌로 삼을지니라. 아론이 그들의 이름을 여호와 앞에서 그의 두 어깨에 메어 기념이 되게 할지니라.'),
(2307, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 13, 'OT', '너는 금으로 보석 테두리를 만들지니라'),
(2308, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 14, 'OT', '정금으로 두 사슬을 끝에서 만들되 밧줄 모양의 행위로 그것들을 만들고, 그 밧줄 사슬들을 보석 테두리 위에 달지니라'),
(2309, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 15, 'OT', '너는 판결 흉패를 공교한 행위로 만들되 에봇의 행위와 같이 그것을 만들지니 금과 청색과 자주색과 진홍색과 가늘게 꼰 베실로 그것을 만들지니라'),
(2310, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 16, 'OT', '네모 반듯하게 하되 두 겹으로 하고, 한 뼘 길이, 한 뼘 너비로 할지니라.'),
(2311, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 17, 'OT', '그것에 보석받침으로 네 줄의 돌을 채우되 첫 줄은 홍보석, 황옥, 홍옥이니 그 첫 줄이라.'),
(2312, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 18, 'OT', '둘째 줄은 에메랄드, 사파이어, 다이아몬드요.'),
(2313, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 19, 'OT', '세째 줄은 리슘, 마노, 자수정이요'),
(2314, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 20, 'OT', '넷째 줄은 감람석과 마노와 벽옥이니, 그들이 보석받침에 금으로 물려 있을지니라.'),
(2315, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 21, 'OT', '돌들은 이스라엘 아들들의 이름 위에 있을 것이니, 그들의 이름대로 열둘이라, 인장의 새김처럼 각 사람이 자기 이름 위에 있을 것이며, 열두 막대기에게로 있을 것이다.'),
(2316, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 22, 'OT', '너는 흉패 위에 순금으로 밧줄 모양의 행위로 만든 끝 사슬들을 만들지니라.'),
(2317, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 23, 'OT', '흉패 위에 금 반지 둘을 만들고, 그 두 반지를 흉패의 두 끝에 달라.'),
(2318, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 24, 'OT', '너는 금으로 만든 두 밧줄을 흉패의 두 끝에 있는 두 반지에 달되,'),
(2319, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 25, 'OT', '그리고 두 밧줄의 두 끝을 두 보석 테두리에 달고, 그것을 에봇의 어깨 앞쪽, 그 얼굴 맞은편에 두라.'),
(2320, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 26, 'OT', '네가 금 반지 둘을 만들고 그것들을 흉패의 두 끝에 달되, 에봇의 건너편을 향한 입술 위, 집 쪽에 달지니라.'),
(2321, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 27, 'OT', '또한 금반지 둘을 만들어 에봇의 두 어깨 위, 그 얼굴 맞은편 아래 곧 그 이음매 곁, 에봇의 띠 위에 달라.'),
(2322, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 28, 'OT', '그들이 청색 꼰 끈으로 흉패의 반지들을 에봇의 반지들에 연결하여 흉패가 에봇의 띠 위에 있게 하고, 흉패가 에봇에서 떨어지지 않게 할지니라.'),
(2323, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 29, 'OT', '아론이 판결 흉패에 이스라엘 아들들의 이름을 그의 마음 위에 지고 거룩한 곳에 들어갈 때에 여호와 앞에서 항상 기념이 되게 할지니라'),
(2324, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 30, 'OT', '너는 판결 흉패 안에 우림과 훔밈을 넣으라. 그것들이 아론의 마음 위에 있게 하라, 그가 여호와 앞에 들어갈 때에. 아론은 이스라엘 아들들의 판결을 그의 마음 위에 지니고 여호와 앞에서 항상 있게 하라.'),
(2325, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 31, 'OT', '에봇의 겉옷을 전부 청색으로 만들지니라'),
(2326, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 32, 'OT', '그 머리 입구가 그 중간에 있게 하고, 그 입 주위에 주위로 짠 행위의 입술이 있게 하되, 가죽 갑옷의 입과 같이 그것에게 있게 하여 찢어지지 않게 할지니라.'),
(2327, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 33, 'OT', '그것의 자락 위에 청색과 자주색과 진홍색 석류를 그 자락 주위에 만들고, 그 중간에 금 방울들을 주위에 달라.'),
(2328, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 34, 'OT', '금 방울과 석류, 금 방울과 석류가 겉옷 자락 주위에 있게 하라'),
(2329, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 35, 'OT', '그것이 아론에게 있어 섬기기 위한 것이 되리니, 그가 여호와의 얼굴 앞 거룩함에 들어갈 때와 나올 때에 그의 소리가 들리리라, 그리하면 그가 죽지 아니하리라.'),
(2330, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 36, 'OT', '너는 또 순금으로 꽃을 만들고 그 위에 인장의 새김으로 새기되 여호와께 거룩함이라 하라'),
(2331, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 37, 'OT', '그것을 청색 꼰 끈에 달아 터번 위에 두되, 터번 얼굴 앞쪽에 있게 하라.'),
(2332, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 38, 'OT', '그것이 아론의 이마에 있게 될 것이며, 아론이 이스라엘 자손이 그들의 모든 거룩한 선물로 거룩하게 하는 거룩함의 죄악을 담당할 것이며, 그것이 그의 이마에 항상 있어 그들이 여호와 앞에서 기쁨이 되게 할 것이다.'),
(2333, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 39, 'OT', '네가 속옷을 가는 베실로 짜고, 가는 베실로 터번을 만들며, 수 놓은 행위로 띠를 만들지니라.'),
(2334, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 40, 'OT', '아론의 아들들을 위하여 너는 속옷을 만들고, 그들을 위하여 띠를 만들며, 그들을 위하여 두건을 만들어 영광과 아름다움을 위하게 할지니라.'),
(2335, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 41, 'OT', '너는 그것들을 네 형 아론과 그와 함께한 그의 아들들에게 입히고, 그들에게 기름을 부어 그들의 손을 위임하고 그들을 거룩하게 하여 그들이 나를 위해 제사장 직분을 행하게 할지니라.'),
(2336, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 42, 'OT', '그들을 위하여 베로 속바지를 만들어 벌거벗은 살을 가리게 하되 허리에서부터 넓적다리까지 이르게 할지니라'),
(2337, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 28, 43, 'OT', '그들이 아론과 그의 아들들에게 있을 것이니 그들이 정한 때의 천막에 들어갈 때나 제단에 가까이 나아가 거룩함에서 섬길 때에 그들이 죄악을 지지 아니하고 죽지 아니하리라. 그것은 그와 그의 뒤를 따르는 그의 씨에게 영원한 규례니라.'),
(2338, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 1, 'OT', '네가 그들에게 행할 일은 이러하니 그들을 거룩하게 하여 내게 제사장으로 섬기게 하려 함이라: 흠 없는 수송아지 하나와 숫양 둘을 취할지니라'),
(2339, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 2, 'OT', '누룩 없는 빵과 기름에 섞은 누룩 없는 화병과 기름 바른 누룩 없는 얇은 떡을 고운 밀가루로 만들지니라'),
(2340, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 3, 'OT', '그것들을 한 바구니에 두고, 그 바구니에 그것들을 가져오되, 수송아지와 두 숫양과 함께 가져올지니라.'),
(2341, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 4, 'OT', '아론과 그의 아들들을 정한 때의 천막 문 앞으로 데려오고 물로 그들을 씻을지니라'),
(2342, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 5, 'OT', '너는 그 옷들을 가져다가 아론에게 속옷과 에봇 받침 겉옷과 에봇과 흉패를 입히고, 에봇의 띠로 그에게 띠우라.'),
(2343, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 6, 'OT', '너는 그 터번을 그의 머리에 두르고, 거룩함의 왕관을 그 터번 위에 얹을지니라.'),
(2344, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 7, 'OT', '네가 기름부음의 기름을 가져다가 그의 머리에 붓고 그에게 기름을 부을지니라'),
(2345, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 8, 'OT', '네 아들들을 데려와서 그들에게 속옷을 입힐지니라'),
(2346, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 9, 'OT', '너는 그들에게 띠를 띠우되 아론과 그의 아들들에게 띠우고 그들에게 두건을 씌우라. 그리하면 그들에게 제사장의 직분이 영원한 규례가 되리라. 너는 아론의 손과 그의 아들들의 손을 위임하라.'),
(2347, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 10, 'OT', '너는 그 수송아지를 정한 때의 천막 얼굴 앞으로 가져오고, 아론과 그의 아들들은 그들의 손을 그 수송아지의 머리에 얹을지니라.'),
(2348, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 11, 'OT', '네가 그 수송아지를 여호와의 얼굴 앞, 정한 때의 천막 문에서 잡을지니라.'),
(2349, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 12, 'OT', '너는 수송아지의 피를 취하여 네 손가락으로 제단의 뿔들에 바르고, 그 모든 피를 제단의 기초에 쏟을지니라.'),
(2350, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 13, 'OT', '네가 모든 속을 덮는 기름과 간에 덮인 꺼풀과 두 콩팥과 그 위에 있는 기름을 취하여 제단 위에 불사르라'),
(2351, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 14, 'OT', '그 수송아지의 살과 그 가죽과 그 똥을 진영 밖에서 불로 사르되, 그것은 죄제니라.'),
(2352, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 15, 'OT', '또한 너는 숫양 하나를 취하고 아론과 그의 아들들은 그들의 손을 그 숫양의 머리 위에 얹을지니라'),
(2353, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 16, 'OT', '네가 그 숫양을 잡고 그 피를 취하여 제단 위에 주위에 뿌릴지니라'),
(2354, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 17, 'OT', '숫양을 그 조각으로 자르고 그 속과 다리를 씻어 그 조각들과 그 머리 위에 두라'),
(2355, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 18, 'OT', '네가 그 숫양 전체를 제단 위에서 불사르되 그것은 여호와께 드리는 번제이며 여호와께 드리는 향기로운 냄새의 불제물이니라'),
(2356, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 19, 'OT', '네가 둘째 숫양을 취하고 아론과 그의 아들들이 그들의 손을 그 숫양의 머리 위에 얹을지니라'),
(2357, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 20, 'OT', '너는 그 숫양을 잡고 그 피를 취하여 아론의 오른 귀 끝과 그의 아들들의 오른 귀 끝에 바르고, 그들의 오른손 엄지와 그들의 오른발 엄지에 바르고, 그 피를 제단 주위에 뿌릴지니라.'),
(2358, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 21, 'OT', '너는 제단 위에 있는 피와 기름부음의 기름을 취하여 아론과 그의 옷과 그의 아들들과 그와 함께한 그의 아들들의 옷에 뿌리라. 그와 그의 옷과 그의 아들들과 그와 함께한 그의 아들들의 옷이 거룩하리라.'),
(2359, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 22, 'OT', '또한 너는 숫양에서 기름과 궁둥이와 속을 덮는 기름과 간의 꺼풀과 두 콩팥과 그것들 위에 있는 기름과 오른쪽 넓적다리를 취하라, 이는 위임식의 숫양이기 때문이다.'),
(2360, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 23, 'OT', '또 여호와 앞에 있는 누룩 없는 빵 바구니에서 빵 한 덩어리와 기름 섞인 빵 화병 하나와 얇은 떡 하나를 취할지니라'),
(2361, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 24, 'OT', '너는 그 모든 것을 아론의 손바닥과 그의 아들들의 손바닥에 두고, 그것을 여호와의 얼굴 앞에서 흔들어 바침으로 흔들어 바칠지니라.'),
(2362, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 25, 'OT', '너는 그것들을 그들의 손에서 취하여 제단 위에서 번제 위에 불사르라. 여호와 앞에 향기로운 냄새를 위하여, 그것은 여호와께 드리는 불제물이니라.'),
(2363, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 26, 'OT', '너는 위임식 숫양의 가슴을 취하여 아론의 것으로 삼고, 그것을 여호와의 얼굴 앞에서 흔들어 바침으로 흔들어 바침을 드릴지니, 그것이 네 몫이 될지니라.'),
(2364, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 27, 'OT', '너는 흔들어 바침의 가슴과 제사의 넓적다리를 거룩하게 하라, 그것은 흔들린 것이요 들어 올려진 것이라, 위임식의 숫양에서, 아론의 것과 그의 아들들의 것에서.'),
(2365, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 28, 'OT', '이것은 아론과 그의 아들들에게 영원한 법령으로 이스라엘 자손에게서 주어질 것이니, 그것은 제사이기 때문이다. 그리고 그것은 이스라엘 자손이 그들의 화목제 제사 중에서 드리는 제사가 될 것이니, 그들의 제사는 여호와께 드리는 것이다.'),
(2366, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 29, 'OT', '아론의 거룩한 옷은 그 후에 그의 아들들이 가질 것이니, 그들이 그것으로 기름부음을 받고 그것으로 그들의 손을 위임할 것이다.'),
(2367, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 30, 'OT', '그의 아들 중에서 그를 이어 제사장이 되는 자는 칠 일 동안 그것들을 입을지니, 그가 정한 때의 천막에 들어가 거룩함에서 섬기려 할 때에니라.'),
(2368, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 31, 'OT', '너는 위임식 숫양을 취하여 거룩한 장소에서 그 살을 삶을지니라.'),
(2369, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 32, 'OT', '아론과 그의 아들들은 숫양의 살과 바구니에 있는 빵을 정한 때의 천막 문에서 먹을지니라'),
(2370, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 33, 'OT', '그들이 속죄를 위해 그들을 위임하고 거룩하게 하기 위해 그들의 손을 채우는 그들을 먹을 것이나, 타인은 먹지 못할지니 이는 그들이 거룩함이기 때문이다.'),
(2371, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 34, 'OT', '만일 위임식의 살과 빵 중에 아침까지 남은 것이 있으면, 그 남은 것을 불로 사를지니, 그것은 먹지 못할지니 이는 그것이 거룩함이니라.'),
(2372, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 35, 'OT', '너는 아론과 그의 아들들에게 이와 같이 행하되 내가 네게 명령한 모든 대로 하여 칠 일 동안 그들의 손을 위임할지니라'),
(2373, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 36, 'OT', '매일 속죄를 위하여 수송아지 하나를 죄 제물로 드릴지니, 네가 그것을 위하여 속죄할 때에 제단을 정결케 하고, 그것에 기름을 부어 거룩하게 할지니라.'),
(2374, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 37, 'OT', '칠 일 동안 제단을 위하여 속죄하고 그것을 거룩하게 하라 그리하면 제단이 지극히 거룩한 거룩함이 되리니 모든 제단에 접촉하는 자는 거룩하리라'),
(2375, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 38, 'OT', '네가 제단 위에 드릴 것은 이러하니라 해가 한 해 된 어린 양 두 마리를 날마다 항상 드릴지니'),
(2376, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 39, 'OT', '아침에 한 어린양을 드리고, 저녁 때에 다른 어린양을 드릴지니라.'),
(2377, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 40, 'OT', '한 어린 양에 고운 밀가루 십분의 일을 찧은 기름 힌의 사분의 일과 섞고, 또 전제로 포도주 힌의 사분의 일을 더할지니라'),
(2378, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 41, 'OT', '네가 두 번째 어린양은 저녁 사이에 드리되 아침의 제물과 그것의 제사대로 그것에게 행할지니 여호와께 불제물로 향기로운 향기가 되게 할지니라'),
(2379, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 42, 'OT', '항상 드릴 번제는 너희 세대를 위하여 회막 문 앞, 곧 정한 때의 천막 문 앞에서 여호와의 얼굴 앞에 드릴지니, 내가 거기서 너희와 만나고 거기서 네게 말하리라.'),
(2380, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 43, 'OT', '내가 거기서 이스라엘 자손과 만나리니 내 영광으로 거룩하게 되리라'),
(2381, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 44, 'OT', '내가 정한 때의 천막과 제단을 거룩하게 하며, 아론과 그의 아들들도 거룩하게 하여 나를 위해 제사장으로 섬기게 하리라.'),
(2382, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 45, 'OT', '내가 이스라엘 자손 중간에 거하리니 그들에게 하나님이 되리라'),
(2383, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 29, 46, 'OT', '그들이 내가 그들의 하나님 여호와인 줄 알리니 내가 그들을 애굽 땅에서 인도하여 내어 그들 중간에 거하려 함이라 나는 그들의 하나님 여호와니라'),
(2384, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 1, 'OT', '너는 분향할 제단을 만들되 싯딤나무로 그것을 만들지니라.'),
(2385, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 2, 'OT', '한 규빗이 그 길이, 한 규빗이 그 너비로 네모 반듯하게 될 것이며, 두 규빗이 그 키이며, 그것에서 그 뿔들이 나오느니라.'),
(2386, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 3, 'OT', '너는 그것을 순금으로 입히되, 그 지붕과 그 벽들을 주위에, 그리고 그 뿔들을 입히고, 너는 그것을 위하여 금으로 만든 왕관을 주위에 만들지니라.'),
(2387, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 4, 'OT', '금고리 둘을 그것을 위하여 만들되 그 왕관 아래, 그것의 두 옆에 만들고, 그것의 두 곁에 만들지니, 그것들이 따로 집들이 되어 그것을 그것들로 메는 데 쓰일지니라.'),
(2388, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 5, 'OT', '너는 그 채를 싯딤나무로 만들고 그것들을 금으로 입힐지니라.'),
(2389, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 6, 'OT', '너는 그것을 증언궤 위에 있는 휘장 앞, 곧 증언 위에 있는 속죄소 앞에 두라. 내가 거기서 너와 만날 것이다.'),
(2390, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 7, 'OT', '아론이 그 위에 향료 향을 사르되 아침마다 아침마다 등불을 정리할 때에 그것을 사를지니라'),
(2391, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 8, 'OT', '아론이 저녁 사이에 등불을 켤 때에 그 위에 향을 사를지니 여호와 앞에 항상 드리는 향으로 너희 세대에 이를지니라'),
(2392, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 9, 'OT', '너희는 그 위에 다른 향을 사르지 말며 번제나 제물을 드리지 말며 제사를 붓지 말지니라'),
(2393, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 10, 'OT', '아론이 그 뿔들을 위하여 일 년에 한 번 속죄하되, 속죄의 죄 제사 피로 일 년에 한 번 그것을 위하여 속죄할지니, 너희 대대로 거룩함 중의 거룩함이라, 그것은 여호와께 거룩하니라.'),
(2394, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 11, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2395, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 12, 'OT', '네가 이스라엘 자손의 머리를 그들의 계수에 따라 셀 때에, 그들이 각 사람이 자기 영혼의 몸값을 여호와께 드릴지니, 그들을 계수할 때에 그들 중에 역병이 없게 하려 함이라.'),
(2396, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 13, 'OT', '이것이 그들이 낼 것이니, 계수된 자들 가운데 지나가는 모든 자는 거룩함의 세겔대로 절반 세겔을 낼지니, 한 세겔은 이십 게라라, 그 절반 세겔은 여호와께 드리는 제사니라.'),
(2397, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 14, 'OT', '모든 계수된 자들 가운데 통과하는 자, 곧 스무 해 이상 된 아들마다 여호와께 제사를 드릴지니라.'),
(2398, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 15, 'OT', '부자는 반 세겔에서 더 내지 말고, 가난한 자는 덜 내지 말지니, 여호와께 제사를 드려 너희 영혼을 속죄하기 위함이니라.'),
(2399, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 16, 'OT', '너는 이스라엘 자손에게서 속죄의 은을 취하여 정한 때의 천막의 일에 그것을 바치라 그것이 여호와 앞에서 이스라엘 자손에게 기념이 되어 너희 영혼을 속죄하리라'),
(2400, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 17, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2401, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 18, 'OT', '너는 놋쇠로 화로를 만들고 그 받침대도 놋쇠로 만들어 씻게 하되, 그것을 정한 때의 천막과 제단 사이에 두고 거기에 물을 담을지니라.'),
(2402, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 19, 'OT', '아론과 그의 아들들은 그것에서 자기들의 손과 자기들의 발을 씻을지니라'),
(2403, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 20, 'OT', '그들이 정한 때의 천막에 들어갈 때에 물로 씻어 죽지 아니할 것이요, 제단에 가까이 가서 섬기며 여호와께 불제물을 사를 때에도 그리할지니라'),
(2404, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 21, 'OT', '그들이 그들의 손과 발을 씻어야 죽지 아니할 것이며, 그것이 그와 그의 씨에게 대대에 걸쳐 영원한 법령이 될지니라.'),
(2405, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 22, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2406, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 23, 'OT', '너는 또 너를 위하여 으뜸 향품을 취하되 자유 몰약 오백과, 그 절반인 향기로운 계피 이백 오십과, 향기로운 갈대 이백 오십을 취할지니라'),
(2407, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 24, 'OT', '계피 오백 세겔을 성소의 세겔대로 하고 올리브 기름 한 힌을 취할지니라'),
(2408, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 25, 'OT', '네가 그것으로 거룩한 기름부음의 기름을 만들되 향유 제조자의 행위로 만든 연고, 거룩한 기름부음의 기름이 될지니라.'),
(2409, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 26, 'OT', '그것으로 정한 때의 천막과 증언의 궤에 기름을 바르라.'),
(2410, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 27, 'OT', '상과 그 모든 그릇들과 촛대와 그 그릇들과 향 제단을 두라'),
(2411, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 28, 'OT', '번제단과 그 모든 그릇들과 화로와 그 받침대를'),
(2412, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 29, 'OT', '너는 그것들을 거룩하게 구별하라, 그리하면 그것들이 거룩함 중의 거룩함이 되리라. 모든 그것들에 접촉하는 자는 거룩하리라.'),
(2413, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 30, 'OT', '너는 아론과 그의 아들들에게 기름을 바르고 그들을 거룩하게 하여 그들이 내게 제사장으로 섬기게 할지니라'),
(2414, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 31, 'OT', '너는 이스라엘 자손에게 말하여 이르기를, 이것은 너희 세대 동안 나에게 거룩한 기름부음의 기름이 될지니라.'),
(2415, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 32, 'OT', '사람의 살에는 그것을 붓지 말 것이며, 그 정량대로 너희는 그것과 같은 것을 만들지 말지니라. 그것은 거룩함이요, 그것은 너희에게 거룩함이 될 것이니라.'),
(2416, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 33, 'OT', '그것과 같이 만드는 사람이나 그것을 타인에게 붓는 사람은 그 백성 중에서 끊쳐지리라.'),
(2417, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 34, 'OT', '여호와께서 모세에게 이르시되 너는 향료를 취하되 나타프와 오닉사와 갈바눔을 취하고 향료와 순수한 유향을 따로 따로 두라'),
(2418, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 35, 'OT', '네가 그것을 향으로 만들되, 향유 만드는 자의 행위로 만든 향, 소금을 친 정결한 거룩함으로 만들지니라.'),
(2419, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 36, 'OT', '네가 그것을 곱게 빻아 그 중에서 증언 앞, 곧 정한 때의 천막 안에서 내가 너와 만날 그 곳에 두라. 그것은 너희에게 지극히 거룩한 거룩함이 되리라.'),
(2420, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 37, 'OT', '네가 만들 향은 그 정량대로 너희를 위하여 만들지 말지니 그것은 너에게 여호와를 위한 거룩함이 될 것이니라.'),
(2421, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 30, 38, 'OT', '그 향기를 맡으려고 그것과 같은 것을 만드는 사람은 그의 백성 중에서 끊쳐지리라'),
(2422, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2423, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 2, 'OT', '보라, 내가 이름으로 브살렐을 불렀으니, 그는 우리의 아들, 후르의 아들, 유다 지파의 막대기에서 난 자니라.'),
(2424, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 3, 'OT', '내가 그를 하나님의 영으로 채웠으니 지혜와 지혜와 지식과 모든 일로'),
(2425, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 4, 'OT', '교묘한 일들을 고안하며 금과 은과 놋쇠로 일하기 위함이니'),
(2426, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 5, 'OT', '돌 조각하여 채우는 일과 나무 조각하여 모든 일을 하는 일에'),
(2427, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 6, 'OT', '내가 보라, 내가 그와 함께 아홀리압을 주었으니 그는 아히사막의 아들이요 단 막대기에게 속한 자라, 내가 모든 지혜로운 마음의 마음에 지혜를 주었으니 그들이 내가 네게 명령한 모든 것을 만들리라.'),
(2428, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 7, 'OT', '회막 곧 정한 때의 천막과 증언의 궤와 그 위의 속죄소와 천막의 모든 그릇을'),
(2429, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 8, 'OT', '상과 그 그릇들과 정결한 촛대와 그 모든 그릇들과 향 제단을 두라'),
(2430, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 9, 'OT', '번제단과 그 모든 그릇들과 화로와 그 받침대를'),
(2431, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 10, 'OT', '봉사하는 옷들과 제사장 아론의 거룩한 옷들과 그의 아들들의 옷을 제사장 직분을 행하기 위하여'),
(2432, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 11, 'OT', '기름부음의 기름과 거룩함을 위한 향료의 향을 모든 내가 네게 명령한 대로 그들이 만들지니라'),
(2433, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 12, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2434, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 13, 'OT', '너는 이스라엘 자손에게 말하여 이르기를, 너희는 반드시 나의 안식일들을 지킬지니라. 이는 그것이 나와 너희 사이에 너희 세대들을 위한 표적이 됨이라, 나 여호와가 너희를 거룩하게 하는 자인 줄 알게 하려 함이니라.'),
(2435, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 14, 'OT', '너희는 안식일을 지킬지니 이는 그것이 너희에게 거룩함이 됨이라 그것을 더럽히는 자는 반드시 죽임을 당할 것이니 모든 그 안에서 일하는 자는 그 영혼이 그 백성 속에서 끊쳐지리라'),
(2436, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 15, 'OT', '엿새 동안은 일을 할 것이나, 일곱째 날은 여호와께 거룩한 안식의 안식일이라. 안식일에 일을 하는 모든 자는 반드시 죽임을 당할지니라.'),
(2437, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 16, 'OT', '이스라엘 자손이 안식일을 지켜서 그 안식일을 그들의 세대들에게 영원한 언약으로 삼을지니라'),
(2438, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 17, 'OT', '이것은 나와 이스라엘 자손 사이에 영원한 표적이니, 이는 여호와께서 엿새 동안에 하늘과 땅을 만드시고 일곱째 날에 쉬셨으며 평안하셨음이니라.'),
(2439, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 31, 18, 'OT', '여호와께서 시내 산에서 모세와 말씀을 마치신 때에 증거판 둘을 모세에게 주셨으니, 이는 돌판이요 하나님의 손가락으로 쓰신 것이라.'),
(2440, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 1, 'OT', '백성이 모세가 산에서 내려오기를 더디게 함을 보고, 백성이 아론에게 모여 그에게 이르되, "일어나 우리를 위하여 우리 앞에서 갈 하나님을 만들라. 이 모세, 곧 우리를 애굽 땅에서 인도하여 낸 그 사람은 우리가 그에게 무슨 일이 생겼는지 알지 못함이라."'),
(2441, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 2, 'OT', '아론이 그들에게 말하되, 너희 아내들과 아들들과 딸들의 귀에 있는 금 귀고리를 빼어 내게로 가져오라.'),
(2442, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 3, 'OT', '모든 백성이 그들의 귀에 있는 금 귀고리를 떼어 아론에게로 가져왔더라'),
(2443, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 4, 'OT', '그들의 손에서 그것을 받아 조각칼로 새겨 덮개를 씌운 송아지 형상을 만들었더라. 그들이 말하되 “이스라엘아, 이는 너를 애굽 땅에서 인도하여 올린 너의 하나님이로다” 하였더라.'),
(2444, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 5, 'OT', '아론이 보고 그 앞에 제단을 쌓고 아론이 외쳐 말하되 내일은 여호와의 축제라 하니'),
(2445, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 6, 'OT', '이튿날 그들이 일찍 일어나 번제를 드리고 화목제를 가져왔으며 백성이 앉아서 먹고 마시고 일어나서 뛰놀았더라'),
(2446, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 7, 'OT', '여호와께서 모세에게 말씀하여 이르시되, 내려가라, 네가 애굽 땅에서 인도하여 낸 네 백성이 부패하였도다.'),
(2447, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 8, 'OT', '그들이 내가 명령한 길에서 급히 떠나 자기들을 위하여 덮개를 씌운 송아지를 만들어 그것에게 절하고 그것에게 제사를 드리며 말하기를 “이스라엘아, 이것이 너를 애굽 땅에서 인도하여 올린 너희 하나님이라” 하였도다'),
(2448, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 9, 'OT', '여호와께서 모세에게 이르시되 내가 이 백성을 보았노니 보라 이는 목이 곧은 백성이로다'),
(2449, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 10, 'OT', '그러므로 이제 나를 내버려 두라, 내 분노가 그들에게 타오르게 하여 그들을 소멸하리라, 내가 너를 큰 이방인이 되게 하리라.'),
(2450, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 11, 'OT', '모세가 그의 하나님 여호와의 얼굴을 간청하며 이르되 여호와여 어찌하여 주의 분노가 주의 백성에게 타오르나이까 주께서 큰 힘과 강한 손으로 애굽 땅에서 그들을 인도하여 내셨나이다'),
(2451, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 12, 'OT', '애굽 사람들이 말하여 이르기를 그가 그들을 악으로 인도하여 산에서 죽이고 땅의 얼굴에서 멸하려 하였다 하지 못하게 하소서 주의 격노의 분노를 돌이키시고 주의 백성에게 내리신 악에 대하여 뜻을 돌이키소서'),
(2452, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 13, 'OT', '주의 종 아브라함과 이삭과 이스라엘을 기억하소서, 주께서 그들에게 주를 가리켜 맹세하시고 그들에게 말씀하시기를 내가 너희 씨를 하늘의 별들처럼 많게 하리라 하셨으며, 또 내가 말한 이 모든 땅을 너희 씨에게 주리니 그들이 영원히 기업으로 얻으리라 하셨나이다.'),
(2453, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 14, 'OT', '여호와께서 그가 자기 백성에게 행하리라고 말씀하신 악에 대해 뜻을 돌이키셨더라.'),
(2454, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 15, 'OT', '모세가 돌이켜 산에서 내려오는데, 증언의 두 판이 그의 손에 있었고, 그 판들은 그들의 양쪽 건너편에, 이쪽과 저쪽에 기록되어 있었더라.'),
(2455, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 16, 'OT', '그 판들은 하나님의 행위이며, 그 글은 하나님의 글이니, 판에 새겨진 것이더라.'),
(2456, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 17, 'OT', '여호수아가 백성의 소리를 그들의 소리 가운데서 듣고 모세에게 말하되 진영에서 전쟁의 소리가 있나이다'),
(2457, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 18, 'OT', '그가 말하되, 힘으로 외치는 소리가 아니요, 연약함으로 부르짖는 소리도 아니니, 내가 듣는 것은 노래하는 소리로다.'),
(2458, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 19, 'OT', '그가 진영에 가까이 이르렀을 때, 그가 송아지와 춤을 보고, 모세의 진노가 타올라, 그가 자기 손에서 그 판들을 던져 산 아래에서 그것들을 깨뜨렸더라.'),
(2459, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 20, 'OT', '그가 그들이 만든 송아지를 가져다가 불로 사르고 빻아 가루를 만들어 물 위에 뿌려 이스라엘 자손에게 마시게 하니라'),
(2460, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 21, 'OT', '모세가 아론에게 이르되, 이 백성이 네게 무엇을 하였기에 네가 그들 위에 큰 죄를 가져왔느냐?'),
(2461, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 22, 'OT', '아론이 말하되, 내 주인의 노여움이 타오르지 않게 하소서, 당신은 이 백성이 악에 있음을 아나이다.'),
(2462, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 23, 'OT', '그들이 내게 말하기를 우리를 위하여 우리 앞에서 갈 하나님을 만들라 이 모세 곧 우리를 애굽 땅에서 인도하여 낸 사람은 어떻게 되었는지 우리가 알지 못하노라 하였느니라'),
(2463, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 24, 'OT', '내가 그들에게 말하기를 금이 있는 자는 빼어내라 하였더니 그들이 그것을 내게 주었기에 내가 그것을 불에 던졌더니 이 송아지가 나왔나이다'),
(2464, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 25, 'OT', '모세가 백성을 보니 그들이 방자하였으니 이는 아론이 그들을 그들의 원수들 가운데서 수치가 되게 하였음이라'),
(2465, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 26, 'OT', '모세가 진영의 문에 서서 이르되 여호와께 속한 자는 내게로 오라 하매 레위의 모든 아들들이 그에게로 모였더라'),
(2466, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 27, 'OT', '그가 그들에게 말하되, 이스라엘의 하나님 여호와께서 이같이 말씀하시기를, 너희는 각 사람이 자기 칼을 자기 넓적다리에 차고, 진영에서 문에서 문까지 왕래하며, 각 사람이 자기 형제를, 각 사람이 자기 친구를, 각 사람이 자기 이웃을 죽이라 하셨느니라.'),
(2467, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 28, 'OT', '레위의 아들들이 모세의 말씀대로 행하니, 그 날에 백성 중에서 약 삼천 명이 죽었더라.'),
(2468, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 29, 'OT', '모세가 말하되, 오늘 너희 손을 여호와께 충만하게 채우라, 이는 각 사람이 자기 아들과 자기 형제를 대적하였음이니, 오늘 너희 위에 축복을 주시도록 하려 함이라.'),
(2469, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 30, 'OT', '이튿날 모세가 백성에게 말하되 너희가 큰 죄를 범하였도다 이제 내가 여호와께로 올라가리니 혹 내가 너희의 죄를 속할까 하노라'),
(2470, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 31, 'OT', '모세가 여호와께로 돌아와서 말하되, 슬프도소이다! 이 백성이 큰 죄를 범하였사오며, 그들이 자기들을 위하여 금으로 된 하나님을 만들었나이다.'),
(2471, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 32, 'OT', '그러나 이제 주께서 그들의 죄를 사하시려거든 사하시옵소서 그렇지 아니하시거든 원하건대 주께서 기록하신 주의 책에서 나를 지워 주옵소서'),
(2472, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 33, 'OT', '여호와께서 모세에게 이르시되 누구든지 내게 범죄한 자를 내가 내 책에서 지워버리리라'),
(2473, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 34, 'OT', '그러므로 이제 가서 내가 네게 말한 곳으로 백성을 인도하라 보라 내 천사가 네 얼굴 앞에서 가리라 그러나 내가 보응할 날에는 그들의 죄를 그들에게 보응하리라'),
(2474, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 32, 35, 'OT', '여호와께서 백성을 치셨으니 이는 그들이 아론이 만든 송아지를 만들었음이라.'),
(2475, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되 너는 이곳에서 올라가라, 너와 네가 애굽 땅에서 인도하여 낸 백성과 함께, 내가 아브라함과 이삭과 야곱에게 맹세하여 말하기를 네 씨에게 주리라 한 그 땅으로.'),
(2476, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 2, 'OT', '내가 네 얼굴 앞에 천사를 보내고, 가나안 사람과 아모리 사람과 히타이트 사람과 브리스 사람과 히위 사람과 여부스 사람을 쫓아내리라.'),
(2477, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 3, 'OT', '젖과 꿀이 흐르는 땅으로 가리라, 내가 네 속에 올라가지 아니하리니, 이는 네가 목이 곧은 백성임이라, 내가 길에서 너를 삼킬까 염려함이니라.'),
(2478, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 4, 'OT', '백성이 이 악한 말씀을 듣고 슬퍼하였으며, 아무 사람도 자기 장식을 그 위에 두지 아니하니라.'),
(2479, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 5, 'OT', '여호와께서 모세에게 이르시되, 이스라엘 자손에게 말하라, 너희는 목이 곧은 백성이니, 내가 네 속에 순간에 올라가서 너를 소멸하리라. 그런즉 이제 네 장식을 네 위에서 벗어 버리라, 그러면 내가 네게 무엇을 행할지 알리라.'),
(2480, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 6, 'OT', '이스라엘 자손들이 호렙 산에서 그들의 장식을 벗어 버렸더라.'),
(2481, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 7, 'OT', '모세가 천막을 취하여 진영 밖에 그것을 치되 진영에서 멀리 떨어뜨리고 그것을 정한 때의 천막이라 불렀으며, 여호와를 찾는 모든 자는 진영 밖에 있는 정한 때의 천막으로 나아가더라.'),
(2482, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 8, 'OT', '모세가 천막으로 나아갈 때에 모든 백성이 일어나 각자 자기 천막 문에 서서 모세가 천막에 들어갈 때까지 바라보았더라'),
(2483, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 9, 'OT', '모세가 천막에 들어갈 때에 구름 기둥이 내려와 천막 문에 서며 모세와 말씀하시니'),
(2484, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 10, 'OT', '모든 백성이 구름 기둥이 천막 문에 서 있는 것을 보았고, 모든 백성이 일어나 각 사람이 자기 천막 문에서 경배하니라.'),
(2485, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 11, 'OT', '여호와께서 모세에게 얼굴과 얼굴을 마주하여 말씀하시되, 사람이 자기 친구에게 말함 같이 하셨고, 그는 진영으로 돌아갔으나, 그의 수종자 눈의 아들 소년 여호수아는 천막 중간에서 떠나지 아니하니라.'),
(2486, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 12, 'OT', '모세가 여호와께 말하되 보소서 주께서 내게 이르시기를 이 백성을 인도하여 올라가라 하시면서 주께서 나와 함께 보낼 자를 내게 알게 하지 아니하셨나이다 주께서 말씀하시기를 내가 이름으로 너를 알고 너도 내 눈에 은혜를 찾았다 하셨나이다'),
(2487, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 13, 'OT', '그러므로 이제 내가 주의 눈앞에서 은혜를 얻었사오면 원하건대 주의 길을 내게 알게 하사 내가 주를 알게 하시고 주의 눈앞에서 은혜를 얻게 하소서 또 이 이방인이 주의 백성인 것을 생각하소서'),
(2488, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 14, 'OT', '그가 말하되, 내 얼굴이 갈 것이요, 내가 너를 쉬게 하리라.'),
(2489, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 15, 'OT', '그가 그에게 말하되, 만일 주의 얼굴이 가지 아니하시려거든 우리를 이곳에서 올려 보내지 마옵소서.'),
(2490, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 16, 'OT', '우리가 주의 눈에 은혜를 입었음을 무엇으로 알리이까? 그것은 주께서 우리와 함께 가심이 아니니이까? 그리하여 나와 주의 백성이 땅의 얼굴 위에 있는 모든 백성 중에서 구별되리이다.'),
(2491, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 17, 'OT', '여호와께서 모세에게 이르시되 네가 말한 이 말씀도 내가 행하리니 이는 네가 내 눈에 은혜를 입었고 내가 네 이름으로 너를 알기 때문이라'),
(2492, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 18, 'OT', '그가 이르되, 원하건대 주의 영광을 내게 보이소서.'),
(2493, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 19, 'OT', '그가 말하되, 내가 나의 모든 좋음을 네 얼굴 앞으로 지나가게 하고 여호와의 이름을 네 얼굴 앞에서 선포하리라. 내가 은혜를 베풀 자에게 은혜를 베풀고, 긍휼을 베풀 자에게 긍휼을 베풀리라.'),
(2494, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 20, 'OT', '그가 이르되, 너는 내 얼굴을 볼 수 없나니, 이는 나를 보고 살 사람이 없음이라.'),
(2495, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 21, 'OT', '여호와께서 말씀하시기를, 보라 내 곁에 장소가 있으니 너는 그 바위 위에 설지니라.'),
(2496, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 22, 'OT', '내 영광이 지나갈 때에 내가 너를 바위 틈에 두고 내가 지나갈 때까지 내 손바닥으로 너를 덮으리라'),
(2497, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 33, 23, 'OT', '내가 내 손바닥을 거두리니 네가 내 뒤를 볼 것이요 내 얼굴은 보이지 아니하리라'),
(2498, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 1, 'OT', '여호와께서 모세에게 이르시되 너는 처음 것과 같은 돌판 둘을 다듬어 만들라 내가 네가 깨뜨린 처음 판에 있던 말씀을 그 판에 쓰리라'),
(2499, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 2, 'OT', '아침에 준비하고 아침에 시내 산에 올라와 그 산 머리에서 내게 거기 서 있으라'),
(2500, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 3, 'OT', '아무도 너와 함께 오르지 말 것이며, 또한 어떤 사람도 그 모든 산에서 보이지 않게 하라. 양떼와 소도 그 산 앞에서 먹지 못하게 하라.'),
(2501, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 4, 'OT', '모세가 처음 것과 같이 돌판 둘을 깎아 만들고 아침에 일찍 일어나 여호와께서 그에게 명령하신 대로 시내 산에 올라가서, 그의 손에 돌판 둘을 가지고 갔더라.'),
(2502, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 5, 'OT', '여호와께서 구름 가운데 내려오사 그와 함께 거기 서서 여호와의 이름을 선포하셨더라'),
(2503, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 6, 'OT', '여호와께서 그의 얼굴 앞으로 지나가시며 선포하시되 여호와 여호와 엘 자비롭고 은혜롭고 분노하기를 더디하고 은혜와 진리가 많은 이시로다'),
(2504, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 7, 'OT', '은혜를 천대까지 지키시며 죄악과 반역과 죄를 용서하시나 결코 깨끗하게 하지 아니하시고 아버지의 죄악을 아들들과 손자들 위에, 삼대와 넷째까지 보응하시느니라'),
(2505, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 8, 'OT', '모세가 급히 땅에 엎드려 경배하니라'),
(2506, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 9, 'OT', '주께서 이르시되, 만일 내가 주의 눈에 은혜를 입었사오면, 원하건대 주님께서 우리 속에 행하시옵소서, 이는 목이 곧은 백성이니이다, 우리의 죄악과 우리의 죄를 사하시고 우리를 주의 기업으로 삼으소서.'),
(2507, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 10, 'OT', '보라 내가 언약을 세우나니 네 모든 백성 앞에서 내가 모든 땅과 모든 이방인 가운데서 창조되지 아니한 이적들을 행할 것이라 네가 그 속에 있는 모든 백성이 여호와의 행위를 보리니 이는 내가 너와 함께 행하는 것이 두렵기 때문이니라'),
(2508, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 11, 'OT', '내가 오늘 네게 명령하는 것을 지키라. 보라, 내가 네 얼굴 앞에서 아모리 사람과 가나안 사람과 히타이트 사람과 브리스 사람과 히위 사람과 여부스 사람을 쫓아내리라.'),
(2509, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 12, 'OT', '너는 스스로 삼가 네가 들어가는 땅의 거민과 언약을 세우지 말라 그것이 네 속에 덫이 될까 하노라'),
(2510, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 13, 'OT', '너희는 그들의 제단들을 헐고 그들의 기둥들을 부수며 그들의 아세라들을 찍을지니라'),
(2511, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 14, 'OT', '너는 다른 신에게 절하지 말지니라. 여호와는 질투라는 이름이요, 그는 질투하는 엘이심이니라.'),
(2512, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 15, 'OT', '너는 그 땅의 거주민과 언약을 맺지 말지니, 그들이 그들의 하나님들을 따라 음란하게 행하며 그들의 하나님들에게 제사를 드리고, 그가 너를 부르면 네가 그의 제사에서 먹을까 함이라.'),
(2513, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 16, 'OT', '네가 그들의 딸들을 네 아들들에게 취할 것이요, 그들의 딸들이 그들의 하나님들을 따라 음란하게 행하며 네 아들들을 그들의 하나님들을 따라 음란하게 행하게 할 것이니라.'),
(2514, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 17, 'OT', '너는 너를 위하여 덮개로 만든 신들, 곧 부어 만든 신들을 만들지 말지니라.'),
(2515, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 18, 'OT', '너는 누룩 없는 빵의 축제를 지키라. 내가 네게 명령한 대로 이삭의 달의 정한 때에 칠 일 동안 누룩 없는 빵을 먹을지니, 이는 네가 이삭의 달에 애굽에서 나왔음이라.'),
(2516, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 19, 'OT', '모든 자궁을 여는 첫새끼는 내 것이며, 네 가축의 모든 첫새끼, 소와 양의 첫새끼도 그러하니라.'),
(2517, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 20, 'OT', '나귀의 첫새끼는 양으로 대속할 것이요, 만일 대속하지 아니하려면 그 목을 꺾을 것이며, 네 아들 중 모든 장자는 대속할지니, 빈손으로 내 얼굴을 보지 말지니라.'),
(2518, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 21, 'OT', '엿새 동안 일하고 일곱째 날에는 쉴지니 쟁기질 때와 추수 때에도 쉴지니라'),
(2519, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 22, 'OT', '너는 밀 추수의 첫 열매로 칠일 축제를 지키고, 해의 순환 때에는 추수 축제를 지킬지니라.'),
(2520, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 23, 'OT', '일 년에 세 번, 네 모든 남자아이들이 주 여호와 이스라엘의 하나님의 얼굴 앞에 나타날지니라.'),
(2521, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 24, 'OT', '내가 이방인들을 네 앞에서 쫓아내고 네 경계를 넓히리니 네가 매년 세 때에 여호와 네 하나님의 얼굴을 보러 올라갈 때에 아무 사람도 네 땅을 탐내지 아니하리라.'),
(2522, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 25, 'OT', '내 제사의 피를 누룩과 함께 드리지 말며 유월절 축제의 제사를 아침까지 두지 말지니라'),
(2523, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 26, 'OT', '네 땅의 첫 열매의 처음 것을 네 하나님 여호와의 집으로 가져올지니라. 너는 염소 새끼를 그 어머니의 젖으로 삶지 말지니라.'),
(2524, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 27, 'OT', '여호와께서 모세에게 이르시되 너는 이 말씀들을 기록하라 이는 이 말씀들의 입으로 내가 너와 이스라엘과 언약을 맺었음이니라'),
(2525, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 28, 'OT', '그가 거기 여호와와 함께 사십 일과 사십 밤을 있었으며 빵도 먹지 아니하고 물도 마시지 아니하였으며 그가 언약의 말씀 곧 십계명을 그 판들에 기록하였더라.'),
(2526, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 29, 'OT', '모세가 시내 산에서 내려올 때에, 증언의 두 판을 모세의 손에 들고 그 산에서 내려오는데, 모세는 여호와께서 그와 말씀하실 때에 그의 얼굴 가죽에 광채가 났음을 알지 못하였더라.'),
(2527, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 30, 'OT', '아론과 모든 이스라엘 자손이 모세를 보았는데, 보라, 그의 얼굴 가죽에 광채가 났으며, 그들이 그에게 가까이 가기를 두려워하더라.'),
(2528, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 31, 'OT', '모세가 그들을 부르니 아론과 회중의 모든 통치자가 그에게로 돌아왔고 모세가 그들과 말하니라'),
(2529, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 32, 'OT', '그 후에 모든 이스라엘 아들들이 가까이 나아오니 그가 여호와께서 시내 산에서 자기와 함께 말씀하신 모든 것을 그들에게 명령하니라'),
(2530, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 33, 'OT', '모세가 그들과 말하기를 마치고 자기 얼굴에 면사포를 썼더라'),
(2531, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 34, 'OT', '모세가 여호와의 얼굴 앞에 들어가 그와 말하려 할 때에는 나올 때까지 면사포를 벗지 아니하고, 나와서는 이스라엘의 아들들에게 명령하신 모든 것을 말하니라.'),
(2532, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 34, 35, 'OT', '이스라엘 자손이 모세의 얼굴을 보았으니 모세의 얼굴 가죽이 광채가 났음이라 모세가 그와 말하러 들어갈 때까지 자기 얼굴에 면사포를 다시 씌웠더라'),
(2533, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 1, 'OT', '모세가 이스라엘 자손의 모든 회중을 모으고 그들에게 이르되, 여호와께서 행하라고 명령하신 말씀들이 이러하니라.'),
(2534, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 2, 'OT', '엿새 동안은 일을 할 것이나, 일곱째 날에는 너희에게 거룩함이 있으리니 여호와께 안식일의 안식이라. 그 날에 일을 하는 모든 자는 죽임을 당하리라.'),
(2535, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 3, 'OT', '너희 모든 거주지에서 불을 피우지 말지니라, 안식일 날에.'),
(2536, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 4, 'OT', '모세가 이스라엘 자손의 모든 회중에게 말하여 이르되, 여호와께서 명령하신 말씀이 이러하니라 이르시기를'),
(2537, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 5, 'OT', '너희 중에서 여호와께 제사를 드리되 모든 마음이 원하는 자는 그것을 가져다가 여호와의 제사로 드릴지니 곧 금과 은과 놋쇠로 할지니라'),
(2538, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 6, 'OT', '청색과 자주색과 진홍색과 가는 베실과 염소털'),
(2539, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 7, 'OT', '붉은 물들인 숫양의 가죽과 오소리의 가죽과 싯딤나무'),
(2540, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 8, 'OT', '빛을 위한 기름과 기름부음의 기름을 위한 향기와 향료의 향을 위한 향기'),
(2541, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 9, 'OT', '호마노 돌들과 위임식 돌들, 에봇과 흉패를 위한 것들이니라.'),
(2542, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 10, 'OT', '너희 중 모든 마음이 지혜로운 자는 와서 여호와께서 명령하신 모든 것을 만들지니라'),
(2543, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 11, 'OT', '장막과 그 천막과 그 덮개, 그 갈고리들과 그 널빤지들, 그 빗장들, 그 기둥들과 그 받침대들'),
(2544, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 12, 'OT', '궤와 그 채들과 속죄소와 가리는 휘장을'),
(2545, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 13, 'OT', '상과 그 따로와 그 모든 그릇과 얼굴의 빵을 두라.'),
(2546, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 14, 'OT', '빛의 촛대와 그 그릇들과 그 등불들과 빛의 기름을'),
(2547, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 15, 'OT', '또한 분향제단과 그 채들과 관유와 향료 향과 장막 문의 문 휘장을 두라.'),
(2548, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 16, 'OT', '번제단과 그 놋쇠 석쇠와 그 따로와 그 모든 그릇과 화로와 그 받침대를'),
(2549, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 17, 'OT', '뜰의 매달린 휘장과 그 기둥들과 그 받침대들과 뜰 문의 휘장을'),
(2550, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 18, 'OT', '장막의 말뚝들과 뜰의 말뚝들과 그들의 밧줄들'),
(2551, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 19, 'OT', '봉사하는 옷은 거룩함에서 섬기기 위한 것이며, 제사장 아론을 위한 거룩한 옷과 그의 아들들의 옷은 제사장 직분을 행하기 위한 것이니라.'),
(2552, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 20, 'OT', '모든 이스라엘 자손의 회중이 모세의 얼굴 앞에서 나아갔더라'),
(2553, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 21, 'OT', '마음이 그를 움직인 모든 사람과 영이 그를 자원하게 한 모든 사람이 와서 여호와의 제사를 정한 때의 천막의 일과 그 모든 일과 거룩함의 옷을 위하여 가져왔더라'),
(2554, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 22, 'OT', '사람들이 여자들에게 나아왔으니 모든 마음이 너그러운 자는 고리와 귀고리와 반지와 장식판, 모든 금 그릇을 가져왔고, 모든 사람이 여호와께 금을 흔들어 바치는 예물을 드렸더라'),
(2555, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 23, 'OT', '모든 사람 중에 청색과 자주색과 진홍색과 가는 베실과 염소 털과 붉은 물들인 숫양의 가죽과 오소리의 가죽이 있는 자는 그것들을 가져왔더라'),
(2556, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 24, 'OT', '모든 은과 놋쇠의 제사를 드리는 자는 여호와의 제사를 가져왔고, 모든 싯딤나무가 자기에게 있는 자는 섬기는 일의 모든 일을 위하여 가져왔더라'),
(2557, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 25, 'OT', '모든 마음이 슬기로운 여인은 손수 실을 낳고 그 낳은 청색, 자색, 홍색실과 가는 베실을 가져왔으며'),
(2558, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 26, 'OT', '모든 마음에 지혜로 감동을 받은 여자들은 염소 털을 실을 낳았으며'),
(2559, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 27, 'OT', '통치자들은 마노 돌과 위임식 돌을 에봇과 흉패를 위해 가져왔습니다.'),
(2560, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 28, 'OT', '향기와 기름을 가져오되 빛을 위한 기름과 기름부음의 기름과 향료의 향을 위하여'),
(2561, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 29, 'OT', '마음에 원하는 모든 사람과 여자, 곧 그들의 마음이 그들을 기쁘게 하여 여호와께서 모세의 손으로 명하신 모든 일을 위하여 가져오려 한 자들, 이스라엘 자손이 여호와께 자원제사를 드렸더라.'),
(2562, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 30, 'OT', '모세가 이스라엘 자손에게 이르되 보라 여호와께서 이름으로 브살렐을 부르셨으니 그는 우리의 아들이요 후르의 아들인 유다 지파의 막대기라'),
(2563, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 31, 'OT', '하나님이 그를 하나님의 영으로 채우시되 지혜와 지혜와 지식과 모든 일로 채우셨다.'),
(2564, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 32, 'OT', '금과 은과 놋으로 일하게 하기 위하여 생각을 연구하며'),
(2565, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 33, 'OT', '돌 조각하여 채우는 일과 나무 조각하여 모든 생각하는 일을 하게 하려 함이니라'),
(2566, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 34, 'OT', '또 그가 가르치도록 그의 마음에 주었으니, 그와 단 지파 아히사막의 아들 아홀리압에게니라.'),
(2567, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 35, 35, 'OT', '그들을 마음의 지혜로 채우사 모든 장인의 일과 공교로운 일과 청색과 자주색과 진홍색 실과 가는 실로 수 놓는 일과 짜는 일을 하게 하시며 모든 일을 하는 자들과 생각을 연구하는 자들을 채우셨느니라'),
(2568, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 1, 'OT', '브살렐과 아홀리압과 모든 마음이 지혜로운 사람, 곧 여호와께서 그들에게 지혜와 총명을 주사 거룩한 일을 위한 모든 일을 알게 하신 자들은 여호와께서 명령하신 모든 대로 하였더라.'),
(2569, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 2, 'OT', '모세가 브살렐과 아홀리압과 및 마음이 지혜로운 모든 사람을 불렀으니 곧 여호와께서 그 마음에 지혜를 주신 자요, 그 마음이 그를 이끌어 그 일을 하려고 나아온 모든 자더라'),
(2570, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 3, 'OT', '그들이 모세의 얼굴 앞에서 이스라엘 자손이 거룩한 일의 일을 위하여 가져온 모든 제사를 받았으니 그것을 만들기 위함이었더라 그들이 아침마다 아침마다 그에게 또 자원제사를 가져왔더라'),
(2571, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 4, 'OT', '모든 지혜로운 자들이 거룩함의 모든 일을 하는 자들이 왔으니, 각 사람이 자기 일에서 그들이 하는 일에서 왔더라.'),
(2572, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 5, 'OT', '그들이 모세에게 말하여 이르되, 백성이 여호와께서 명령하신 일을 행하기에 충분한 일보다 더 많이 가져오나이다.'),
(2573, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 6, 'OT', '모세가 명령하여 진영에 소리를 전하게 하여 이르되, 사람이나 여자나 거룩함의 제사를 위한 일을 다시 하지 말라 하매, 백성이 가져오기를 그치니라'),
(2574, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 7, 'OT', '있었던 일이 모든 일을 하기에 충분하여 남음이 있었더라'),
(2575, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 8, 'OT', '마음이 지혜로운 모든 사람이 일을 하는 자들 중에서 장막을 열 폭 휘장으로 지었으니 곧 가늘게 꼰 베실과 청색과 자주색과 진홍색 실로 그룹들을 정교한 행위로 만들었더라'),
(2576, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 9, 'OT', '한 휘장의 길이는 스물여덟 규빗, 한 휘장의 너비는 네 규빗이며, 모든 휘장은 한 치수로 같게 하라.'),
(2577, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 10, 'OT', '그가 다섯 휘장을 하나와 다른 하나에 서로 연결하고, 또 다섯 휘장을 하나와 다른 하나에 서로 연결하니라.'),
(2578, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 11, 'OT', '그가 청색 고리를 만들었는데, 첫 휘장의 입술 끝, 이음매에서 만들었고, 둘째 이음매의 바깥 휘장 입술에도 그와 같이 만들었더라.'),
(2579, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 12, 'OT', '휘장 하나에 고리 오십 개를 만들고, 둘째 이음매에 있는 휘장의 끝에도 고리 오십 개를 만들어, 그 고리들이 서로 마주보게 하였더라.'),
(2580, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 13, 'OT', '그가 금 갈고리 오십 개를 만들고, 그 갈고리들로 휘장들을 서로 연결하여 장막이 하나가 되었더라.'),
(2581, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 14, 'OT', '그가 장막 위에 덮을 천막을 위하여 염소 휘장들을 만들었으니, 열한 폭 휘장을 만들었더라.'),
(2582, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 15, 'OT', '한 휘장의 길이는 삼십 규빗, 한 휘장의 너비는 사 규빗이며, 열한 휘장의 옷은 하나의 크기로 하라.'),
(2583, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 16, 'OT', '그가 다섯 휘장을 따로 연결하고, 여섯 휘장을 따로 연결하니라.'),
(2584, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 17, 'OT', '그가 이음매에 있는 끝 휘장의 입술에 고리 오십 개를 만들고, 둘째 이음매 휘장의 입술에도 고리 오십 개를 만들었더라.'),
(2585, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 18, 'OT', '놋쇠 갈고리 오십을 만들어 천막을 연합하여 하나가 되게 하였더라'),
(2586, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 19, 'OT', '그가 천막의 덮개를 붉게 물들인 숫양의 가죽으로 만들고, 그 위에 오소리의 가죽으로 덮개를 만들었더라.'),
(2587, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 20, 'OT', '그가 장막을 위해 싯딤나무로 널빤지들을 만들어 세웠더라.'),
(2588, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 21, 'OT', '각 널빤지의 길이는 열 규빗이요, 각 널빤지의 너비는 한 규빗 반이며'),
(2589, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 22, 'OT', '각 널빤지에 두 손이 있어 서로 연결되었으니, 그가 장막의 모든 널빤지에 이와 같이 만들었더라.'),
(2590, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 23, 'OT', '그가 장막을 위하여 널빤지를 만들었으되, 남쪽 모퉁이 남쪽으로 널빤지가 이십이더라.'),
(2591, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 24, 'OT', '은받침대 마흔 개를 스무 널빤지 아래에 만들었으니, 한 널빤지 아래에 두 받침대가 그 두 손을 받고, 또 한 널빤지 아래에 두 받침대가 그 두 손을 받게 하였더라.'),
(2592, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 25, 'OT', '장막의 둘째 옆, 곧 북쪽 모퉁이를 위하여 널빤지 이십 개를 만들었더라.'),
(2593, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 26, 'OT', '그들의 받침대는 은으로 마흔 개이니, 한 널빤지 아래에 받침대 둘, 또 한 널빤지 아래에 받침대 둘이라.'),
(2594, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 27, 'OT', '장막의 변두리, 곧 바다 쪽을 위하여 널빤지 여섯을 만들었더라.'),
(2595, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 28, 'OT', '그가 장막의 모퉁이를 위하여 널빤지 둘을 만들었으니, 변두리에 있게 하였더라.'),
(2596, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 29, 'OT', '그들이 아래에서 쌍둥이가 되고, 함께 그 머리 위로, 하나의 반지에 이르기까지 온전하게 되며, 그가 두 모퉁이, 곧 두 모퉁이 편에 그렇게 행하였더라.'),
(2597, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 30, 'OT', '널빤지는 여덟 개였고, 그 받침대는 은 받침대 열여섯 개였으니, 각 널빤지 아래에 받침대 둘씩이었더라.'),
(2598, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 31, 'OT', '그가 싯딤나무로 빗장을 만들었으니, 장막의 한쪽 옆 널빤지를 위하여 다섯이더라.'),
(2599, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 32, 'OT', '또한 장막의 둘째 옆 널빤지를 위하여 빗장 다섯 개, 장막의 뒤 곧 바다 쪽 변두리 널빤지를 위하여 빗장 다섯 개며'),
(2600, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 33, 'OT', '그가 중간 빗장을 만들어 널빤지 중간을 이 끝에서 저 끝까지 통과하게 하였더라.'),
(2601, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 34, 'OT', '그 널빤지들을 금으로 입히고 그들의 반지를 금으로 만들어 빗장들의 집을 삼았으며, 그 빗장들을 금으로 입혔더라.'),
(2602, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 35, 'OT', '그가 휘장을 만들었는데 청색과 자주색과 진홍색과 가늘게 꼰 베실로, 공교한 행위로 그룹들을 그 위에 수 놓아 만들었더라.'),
(2603, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 36, 'OT', '그가 그것을 위하여 싯딤나무로 네 기둥을 만들고 금으로 입혔으며, 그 갈고리는 금이었고, 그들을 위하여 은 받침대 네 개를 부어 만들었다.'),
(2604, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 37, 'OT', '그가 천막 문을 위하여 청색과 자주색과 진홍색과 가늘게 꼰 베실로 수 놓은 행위의 휘장을 만들었더라.'),
(2605, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 36, 38, 'OT', '그 기둥 다섯과 그 갈고리들, 그리고 그 머리들과 그 가름대들을 금으로 입혔고, 그 받침대 다섯은 놋쇠였더라.'),
(2606, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 1, 'OT', '브살렐이 싯딤나무로 궤를 만들었으니, 그 길이가 두 규빗 반, 그 너비가 한 규빗 반, 그 키가 한 규빗 반이었더라.'),
(2607, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 2, 'OT', '그것을 순금으로 안과 밖에 입히고, 그것을 위해 금으로 만든 왕관을 주위에 만들었다.'),
(2608, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 3, 'OT', '그것을 위하여 금 반지 넷을 부어 만들어 그 네 때에 달았으니, 곧 그 한 옆에 두 반지요, 그 둘째 옆에 두 반지더라'),
(2609, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 4, 'OT', '그가 싯딤나무로 따를 만들어 금으로 입혔더라'),
(2610, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 5, 'OT', '그가 막대기들을 궤의 옆에 있는 반지들에 끼워 궤를 메게 하였더라.'),
(2611, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 6, 'OT', '그가 순금으로 속죄소를 만들었으니, 그 길이가 두 규빗 반이요, 그 너비가 한 규빗 반이었더라.'),
(2612, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 7, 'OT', '그가 금으로 그룹 둘을 만들었으니, 두들겨 만든 것으로 그것들을 만들었으며, 속죄소의 두 끝에서였더라.'),
(2613, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 8, 'OT', '이쪽 끝에 그룹 하나가, 저쪽 끝에 그룹 하나가 있게 하되, 속죄소에서 그룹들을 그 양쪽 끝에 만들었더라.'),
(2614, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 9, 'OT', '그룹들은 날개를 위로 펴서 그들의 날개로 속죄소를 덮었고 그들의 얼굴은 서로 마주 보았으며 그룹들의 얼굴은 속죄소를 향하고 있었더라'),
(2615, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 10, 'OT', '그가 싯딤나무로 상을 만들었으니, 그 길이가 두 규빗, 그 너비가 한 규빗, 그 키가 한 규빗 반이었더라.'),
(2616, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 11, 'OT', '그것을 순금으로 입히고 그 주위에 금 왕관을 만들었다.'),
(2617, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 12, 'OT', '그가 그것을 위하여 한 뼘 너비의 가장자리를 주위에 만들고, 그 가장자리 주위에 금으로 왕관을 만들었더라.'),
(2618, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 13, 'OT', '그것을 위하여 금 반지 넷을 부어 만들고, 그 반지들을 그것의 네 발에 있는 네 모퉁이에 달았더라.'),
(2619, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 14, 'OT', '턱 곁에 반지들이 있었으니, 상을 메는 채를 꿰는 집들이라.'),
(2620, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 15, 'OT', '그가 싯딤나무로 따로를 만들고 그것들을 금으로 입혀 상을 메게 하였더라'),
(2621, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 16, 'OT', '그가 상 위에 있을 그릇들, 곧 그 쟁반들과 그 손바닥들과 그 사발들과 그 덮개들, 그것들로 부을 덮개들을 정금으로 만들었더라.'),
(2622, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 17, 'OT', '그가 정금으로 촛대를 만들되 두들겨 만든 것으로 촛대를 만들었으니 그 넓적다리와 갈대, 그 잔들과 손잡이들과 꽃들이 그것에서 나왔더라'),
(2623, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 18, 'OT', '여섯 갈대가 그 곁에서 나오되, 촛대의 세 갈대는 한쪽 곁에서, 촛대의 세 갈대는 둘째 곁에서 나왔더라.'),
(2624, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 19, 'OT', '한 가지에 살구꽃 모양의 잔 셋과 손잡이와 꽃이 있고, 다른 가지에 살구꽃 모양의 잔 셋과 손잡이와 꽃이 있으니, 촛대에서 나온 여섯 갈대가 다 그러하니라.'),
(2625, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 20, 'OT', '촛대에는 잔 넷이 있으며, 그 손잡이와 꽃이 살구꽃 모양으로 만들어졌느니라.'),
(2626, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 21, 'OT', '그 손잡이 하나는 그 갈대 둘 아래에 있고, 또 손잡이 하나는 그 갈대 둘 아래에 있고, 또 손잡이 하나는 그 갈대 둘 아래에 있으니, 등대에서 나온 여섯 갈대를 위함이니라.'),
(2627, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 22, 'OT', '그들의 손잡이와 그들의 갈대는 그것에서 나왔으며, 그것의 모든 것은 두들겨 만든 하나의 순금이었다.'),
(2628, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 23, 'OT', '그가 그 등불 일곱 개와 그 집게들과 그 불집게들을 순금으로 만들었더라.'),
(2629, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 24, 'OT', '정금 한 덩어리로 그것을 만들었고, 그것의 모든 그릇도 만들었더라.'),
(2630, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 25, 'OT', '그가 싯딤나무로 향 제단을 만들었으니, 그 길이가 한 규빗, 너비가 한 규빗이라 네모 반듯하고, 그 키가 두 규빗이며, 그 뿔들이 그것에서 나왔더라.'),
(2631, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 26, 'OT', '그가 그것을 순금으로 입혔으니 그 지붕과 그 주위의 벽들과 그 뿔들을 입히고, 그것을 위하여 주위에 금 왕관을 만들었더라.'),
(2632, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 27, 'OT', '그 아래 왕관 밑에 금 반지 둘을 만들었으되, 그 두 옆과 두 곁에 만들어, 따로 막대기들을 꿸 집들로 삼아 그것을 그것들로 메게 하였더라.'),
(2633, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 28, 'OT', '그가 싯딤나무로 그 채들을 만들고 그것들을 금으로 입혔더라'),
(2634, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 37, 29, 'OT', '그가 거룩한 기름부음의 기름과 정결한 향료의 향을 만들었으니, 향을 만드는 자의 행위로 만들었더라.'),
(2635, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 1, 'OT', '그가 싯딤나무로 번제단을 만들었으니, 그 길이가 다섯 규빗, 그 너비가 다섯 규빗이라 네모 반듯하고, 그 키가 세 규빗이었더라.'),
(2636, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 2, 'OT', '그의 뿔들을 그 네 모퉁이 위에 만들었는데 그의 뿔들이 그것에서 나왔고, 그 제단을 놋쇠로 입혔더라.'),
(2637, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 3, 'OT', '그가 제단의 모든 그릇을 만들었으니 곧 냄비들과 삽들과 대접들과 고기갈고리들과 불집게들이라, 그 모든 그릇을 놋쇠로 만들었더라.'),
(2638, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 4, 'OT', '그가 제단을 위하여 놋쇠 그물로 만든 석쇠를 만들었으니, 그 가장자리 아래로부터 반까지 이르게 하였더라.'),
(2639, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 5, 'OT', '그가 놋쇠 석쇠의 네 일부에 반지 넷을 부어 만들었으니, 따로 막대기들을 꿸 집들로 삼았더라.'),
(2640, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 6, 'OT', '그가 싯딤나무로 따로를 만들고, 그것들을 놋쇠로 입혔더라.'),
(2641, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 7, 'OT', '그가 제단 옆에 있는 반지들에 따로를 꿰어 그것을 그것들로 메게 하였으며, 제단을 판들로 속이 비게 만들었더라.'),
(2642, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 8, 'OT', '그가 놋쇠로 화로를 만들고 그 받침대도 놋쇠로 만들었으니, 정한 때의 천막 문에서 모였던 군대들의 거울로 만들었더라.'),
(2643, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 9, 'OT', '그가 뜰을 만들었으니 남쪽 모퉁이 남쪽으로 뜰의 매달린 휘장은 가늘게 꼰 베 실로 백 규빗이었더라.'),
(2644, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 10, 'OT', '그들의 기둥은 스물이며, 그들의 받침대는 스물인데 놋쇠요, 기둥들의 갈고리와 그들의 가름대는 은이더라.'),
(2645, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 11, 'OT', '북쪽 모퉁이에는 백 규빗이라, 그 기둥이 스물이며, 그 받침대가 스물이니 놋쇠요, 기둥의 갈고리와 그 가름대는 은이더라.'),
(2646, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 12, 'OT', '바다 쪽 모퉁이에는 매달린 휘장이 오십 규빗이며, 그 기둥이 열이요, 그 받침대가 열이며, 기둥의 갈고리들과 그 가름대는 은이니라.'),
(2647, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 13, 'OT', '동쪽 모퉁이, 동쪽으로 오십 규빗이라.'),
(2648, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 14, 'OT', '매달린 휘장은 어깨 쪽으로 열다섯 규빗이요, 그 기둥은 셋이며 그 받침대는 셋이더라.'),
(2649, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 15, 'OT', '뜰 문의 다른 어깨 쪽, 이편과 저편에는 매달린 휘장이 열다섯 규빗이며, 그 기둥이 셋, 그 받침대가 셋이더라.'),
(2650, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 16, 'OT', '뜰 주위의 모든 매달린 휘장은 가늘게 꼰 베 실로 되었더라.'),
(2651, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 17, 'OT', '뜰의 모든 기둥은 은으로 가름대를 꿰었으며, 기둥 받침대는 놋쇠요, 기둥의 갈고리와 그 가름대는 은이요, 그 머리 덮개는 은이며, 뜰의 모든 기둥은 은으로 가름대를 꿰었더라.'),
(2652, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 18, 'OT', '뜰의 문 휘장은 수놓은 행위로 청색과 자주색과 진홍색과 가늘게 꼰 베실로 만들었으며, 길이는 이십 규빗이요, 너비에 따른 키는 오 규빗으로 뜰의 매달린 휘장 곁과 같았더라.'),
(2653, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 19, 'OT', '그들의 기둥은 넷이요, 그들의 받침대는 넷으로 놋쇠이며, 그들의 갈고리는 은이요, 그들의 머리 덮개와 가름대도 은이더라.'),
(2654, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 20, 'OT', '모든 장막의 말뚝과 뜰 주위의 말뚝은 놋쇠였더라'),
(2655, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 21, 'OT', '이것은 증거의 장막인 장막의 계수된 수효로서 모세의 입의 명령대로 레위인의 일을 제사장 아론의 아들 이다말의 손으로 계수하였더라'),
(2656, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 22, 'OT', '브살렐은 우리의 아들, 후르의 아들, 유다 지파의 막대기로, 여호와께서 모세에게 명하신 모든 것을 만들었더라.'),
(2657, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 23, 'OT', '그와 함께 아히사막의 아들 아홀리압이 있었으니 그는 단 막대기의 장인이며 청색과 자주색과 진홍색과 가는 실로 수 놓는 자더라'),
(2658, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 24, 'OT', '모든 일을 위해 거룩한 일에 쓰인 모든 금, 곧 흔들어 바침의 금은 거룩한 세겔대로 이십구 덩어리와 칠백삼십 세겔이었더라.'),
(2659, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 25, 'OT', '회중의 계수된 자의 은은 거룩함의 세겔대로 백 덩어리와 일천 칠백 칠십 오 세겔이니라'),
(2660, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 26, 'OT', '반 세겔을 해골마다, 거룩함의 세겔로 절반 세겔, 조사받는 모든 자에게, 스무 해 이상의 아들들로부터, 육십만 삼천 오백 오십 명에게.'),
(2661, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 27, 'OT', '은 일백 덩어리로 거룩함의 받침대들과 휘장의 받침대들을 부어 만들었으니, 일백 받침대가 일백 덩어리로 되었고, 각 받침대에 덩어리 하나씩이었더라.'),
(2662, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 28, 'OT', '또한 그 일천칠백칠십오 세겔로 기둥 갈고리를 만들고 그들의 머리를 입히고 그것들을 띠로 묶었더라'),
(2663, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 29, 'OT', '놋쇠 흔들어 바침은 칠십 덩어리와 이천 사백 세겔이었더라.'),
(2664, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 30, 'OT', '그것으로 정한 때의 천막 문 받침대와 놋쇠 제단과 그것의 놋쇠 석쇠와 제단의 모든 그릇을 만들었더라'),
(2665, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 38, 31, 'OT', '뜰 주위의 받침대들과 뜰 문의 받침대들과 장막의 모든 말뚝들과 뜰 주위의 모든 말뚝들을 만들었더라'),
(2666, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 1, 'OT', '청색과 자주색과 진홍색 실로 성소에서 섬기기 위한 봉사 옷을 만들었고, 여호와께서 모세에게 명하신 대로 아론을 위한 거룩한 옷을 만들었더라.'),
(2667, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 2, 'OT', '그가 에봇을 만들었으니 금과 청색과 자주색과 진홍색과 가늘게 꼰 베실로 하였더라'),
(2668, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 3, 'OT', '그들이 금판을 얇게 두드려 꼰 끈을 잘라 청색과 자주색과 진홍색과 가는 실의 중간에 넣어 공교한 행위로 만들었더라'),
(2669, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 4, 'OT', '그것을 위하여 어깨들을 만들되 서로 잇게 하여, 그 두 끝으로 그것을 잇게 하였더라.'),
(2670, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 5, 'OT', '그의 에봇 위에 있는 에봇의 띠는 그 행위와 같이 금과 청색과 자주색과 진홍색과 가늘게 꼰 베실로 만들었으니, 여호와께서 모세에게 명령하신 대로 하였더라.'),
(2671, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 6, 'OT', '그들이 마노 돌들을 금 보석 테두리에 둘러싸게 하고, 인장 새김으로 이스라엘 아들들의 이름을 새겼더라.'),
(2672, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 7, 'OT', '그들을 에봇의 어깨에 두어 이스라엘 자손의 기념 돌이 되게 하였으니 여호와께서 모세에게 명령하신 대로 하였더라'),
(2673, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 8, 'OT', '그가 또 흉패를 공교한 행위로 만들되 에봇의 행위와 같이 금과 청색과 자주색과 진홍색과 가늘게 꼰 베실로 하였더라'),
(2674, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 9, 'OT', '네모 반듯하였고, 두 겹으로 흉패를 만들었으니, 한 뼘 길이, 한 뼘 너비로 두 겹이더라.'),
(2675, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 10, 'OT', '그것에 네 줄의 돌을 채웠으니, 홍보석과 황옥과 홍옥이 첫 줄이더라.'),
(2676, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 11, 'OT', '둘째 줄은 에메랄드, 사파이어, 다이아몬드요'),
(2677, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 12, 'OT', '세째 줄은 리슘, 마노, 자수정이요'),
(2678, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 13, 'OT', '넷째 줄은 감람석과 마노와 벽옥이라, 그 보석받침에 금 보석 테두리로 둘렸더라'),
(2679, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 14, 'OT', '돌들은 이스라엘 아들들의 이름에 따라 열둘이니 그들의 이름대로, 인장의 새김 같이 각 사람이 자기 이름으로, 열두 막대기에 따라 있느니라.'),
(2680, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 15, 'OT', '그들이 흉패 위에 끝이 사슬을 밧줄 행위로 만드니 순금으로 하였더라'),
(2681, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 16, 'OT', '그들이 금 보석 테두리 둘과 금 반지 둘을 만들고, 그 두 반지를 흉패의 두 끝에 달았다.'),
(2682, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 17, 'OT', '그들이 금으로 만든 두 밧줄을 흉패 끝에 있는 두 반지에 달았더라'),
(2683, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 18, 'OT', '그 땋은 두 밧줄의 두 끝을 두 보석 테두리에 달고, 에봇 어깨 앞쪽 얼굴 맞은편에 두었더라.'),
(2684, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 19, 'OT', '그들이 금 반지 둘을 만들어 흉패의 두 끝에 달았으니, 곧 에봇의 건너편 안쪽 입술에 달았더라.'),
(2685, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 20, 'OT', '그들이 금반지 둘을 만들어 에봇의 두 어깨 아래, 그 얼굴 맞은편 곁, 그 이음매 곁, 에봇 띠 위에 달았더라.'),
(2686, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 21, 'OT', '그들이 흉패를 그 반지들로 에봇의 반지들에 청색 꼰 끈으로 연결하여 에봇의 띠 위에 있게 하였고, 흉패가 에봇 위에서 떨어지지 않게 하였으니, 여호와께서 모세에게 명령하신 대로 하였더라.'),
(2687, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 22, 'OT', '그가 에봇의 겉옷을 짜는 행위로 만들었으니 전부 청색이더라.'),
(2688, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 23, 'OT', '겉옷의 입은 중간에 가죽 갑옷의 입과 같고, 그 입 주위에 입술이 있어 찢어지지 아니하느니라.'),
(2689, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 24, 'OT', '그들이 겉옷 자락에 청색과 자주색과 진홍색 실로 석류를 만들었으니 가늘게 꼰 것이더라'),
(2690, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 25, 'OT', '그들이 순금으로 방울들을 만들고 그 방울들을 겉옷 자락의 주위에 있는 석류들 중간, 석류들 중간에 달았다.'),
(2691, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 26, 'OT', '방울과 석류, 방울과 석류를 겉옷 자락 주위에 두르고 섬기게 하였으니, 여호와께서 모세에게 명령하신 대로 하였더라.'),
(2692, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 27, 'OT', '그들이 아론과 그의 아들들을 위하여 짠 행위로 가는 베 속옷을 만들었더라.'),
(2693, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 28, 'OT', '세마포로 터번을 만들고, 세마포로 두건들의 아름다움을 만들고, 가는 베로 속바지들을 만들되, 가늘게 꼰 세마포로 만들지니라.'),
(2694, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 29, 'OT', '가는 베실로 꼰 띠와 청색, 자주색, 진홍색 실로 수 놓은 행위로 만든 띠를 여호와께서 모세에게 명하신 대로 하였더라.'),
(2695, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 30, 'OT', '그들이 거룩한 왕관의 꽃을 순금으로 만들고, 그 위에 인장의 새김 글을 새겨 여호와께 거룩함이라 하였더라.'),
(2696, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 31, 'OT', '그들이 그것 위에 청색 꼰 끈을 두어 터번 위 높은 곳에 달게 하였으니 여호와께서 모세에게 명령하신 대로 하였더라'),
(2697, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 32, 'OT', '모든 장막 곧 정한 때의 천막의 일이 다 끝나매 이스라엘의 아들들이 여호와께서 모세에게 명하신 모든 대로 행하였더라'),
(2698, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 33, 'OT', '그들이 장막을 모세에게로 가져왔으니 곧 천막과 그 모든 그릇과, 그 갈고리들과, 그 널빤지들과, 그 빗장들과, 그 기둥들과, 그 받침대들로다.'),
(2699, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 34, 'OT', '붉은 물들인 숫양의 가죽 덮개와 오소리의 가죽 덮개와 휘장의 덮개를 두되,'),
(2700, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 35, 'OT', '증언의 궤와 그 따로와 속죄소를'),
(2701, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 36, 'OT', '상과 그 모든 그릇들과 얼굴의 빵을'),
(2702, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 37, 'OT', '정금 촛대와 그 등불들, 곧 벌여 놓은 등불들과 그 모든 그릇들과 빛을 위한 기름과'),
(2703, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 38, 'OT', '금 제단과 기름부음의 기름과 향료의 향과 천막 문의 휘장을'),
(2704, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 39, 'OT', '놋쇠 제단과 그 놋쇠 석쇠와 그 따로와 그 모든 그릇과 화로와 그 받침대를'),
(2705, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 40, 'OT', '뜰의 매달린 휘장들과 그것의 기둥들과 그것의 받침대들과 뜰 문의 휘장과 그것의 밧줄들과 그것의 말뚝들과, 정한 때의 천막 곧 장막의 일을 위한 모든 그릇들을'),
(2706, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 41, 'OT', '성소에서 섬기기 위한 봉사의 옷과 제사장 아론의 거룩한 옷과 그의 아들들의 옷을 제사장 직분을 행하기 위한 옷으로 삼을지니라'),
(2707, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 42, 'OT', '여호와께서 모세에게 명령하신 모든 것과 같이, 이스라엘 자손이 모든 일을 그렇게 행하였더라.'),
(2708, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 39, 43, 'OT', '모세가 모든 일을 보고, 보라 그들이 여호와께서 명령하신 대로 그렇게 행하였더라. 모세가 그들을 축복하였더라.'),
(2709, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2710, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 2, 'OT', '첫째 달 초하루에 너는 정한 때의 천막인 장막을 세울지니라.'),
(2711, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 3, 'OT', '너는 거기에 증언의 궤를 두고, 그 궤 위에 휘장으로 덮을지니라.'),
(2712, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 4, 'OT', '상을 가져다가 그 위에 평가를 베풀고, 촛대를 가져다가 그 등불을 켜라.'),
(2713, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 5, 'OT', '너는 금 향단을 증언궤 앞에 두고 장막 문의 휘장을 달지니라.'),
(2714, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 6, 'OT', '번제단을 회막의 장막 문 앞, 곧 정한 때의 천막 앞에 두라.'),
(2715, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 7, 'OT', '너는 물두멍을 정한 때의 천막과 제단 사이에 두고, 거기에 물을 담을지니라.'),
(2716, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 8, 'OT', '응당 뜰 주위에 두르고 뜰 문의 휘장을 달지니라'),
(2717, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 9, 'OT', '너는 기름부음의 기름을 취하여 장막과 그 안에 있는 모든 것에 바르고, 그것과 그 모든 그릇을 거룩하게 하라. 그것이 거룩함이 되리라.'),
(2718, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 10, 'OT', '너는 번제단과 그 모든 그릇에 기름을 바르고 그 제단을 거룩하게 하라. 그 제단은 지극히 거룩함이 되리라.'),
(2719, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 11, 'OT', '너는 물두멍과 그 받침대에 기름을 바르고 그것을 거룩하게 할지니라'),
(2720, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 12, 'OT', '아론과 그의 아들들을 정한 때의 천막 문으로 데려오고 물로 그들을 씻을지니라'),
(2721, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 13, 'OT', '아론에게 거룩한 옷을 입히고 그에게 기름을 부어 그를 거룩하게 하여 그가 내게 제사장으로 섬기게 할지니라'),
(2722, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 14, 'OT', '그의 아들들을 데려다가 그들에게 속옷을 입힐지니라'),
(2723, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 15, 'OT', '너는 그들의 아버지에게 기름을 부은 것 같이 그들에게도 기름을 부어 그들이 내게 제사장 직분을 행하게 하라 그들의 기름부음이 그들의 세대에 걸쳐 영원한 제사장 직분이 되리라'),
(2724, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 16, 'OT', '모세가 행하되 여호와께서 그에게 명하신 모든 대로 그렇게 행하였더라'),
(2725, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 17, 'OT', '둘째 해 첫째 달, 그 달 초하루에 장막이 세워졌더라.'),
(2726, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 18, 'OT', '모세가 장막을 세우고 그 받침대들을 놓고 그 널빤지들을 세우고 그 빗장들을 끼우고 그 기둥들을 세웠더라'),
(2727, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 19, 'OT', '그가 장막 위에 천막을 펴고 그 위에 천막의 덮개를 위에서 덮었으니 여호와께서 모세에게 명령하신 대로였더라.'),
(2728, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 20, 'OT', '그가 증언을 궤에 넣고 따로를 궤에 두고 속죄소를 궤 위에 얹었더라'),
(2729, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 21, 'OT', '그가 궤를 장막 안으로 들여놓고 가리는 휘장을 두어 증언의 궤를 덮었으니, 여호와께서 모세에게 명령하신 대로였더라.'),
(2730, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 22, 'OT', '그가 정한 때의 천막 안, 장막의 북쪽 넓적다리 쪽, 휘장 밖에 상을 두었더라.'),
(2731, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 23, 'OT', '그 위에 빵의 평가를 여호와의 얼굴 앞에 진설하되, 여호와께서 모세에게 명령하신 대로 하였더라.'),
(2732, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 24, 'OT', '그가 촛대를 정한 때의 천막 안에 두되 상 맞은편에 두고 장막의 넓적다리 쪽 곧 남쪽에 두었더라'),
(2733, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 25, 'OT', '등불을 여호와의 얼굴 앞에 올렸으니 여호와께서 모세에게 명령하신 대로였더라.'),
(2734, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 26, 'OT', '그가 금 제단을 정한 때의 천막 안에 두되 휘장 앞에 두니라'),
(2735, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 27, 'OT', '그 위에 향료 향을 사르되 여호와께서 모세에게 명하신 대로 하였더라'),
(2736, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 28, 'OT', '그가 장막 문에 휘장을 달았다.'),
(2737, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 29, 'OT', '번제단을 회막 곧 증거의 천막 문 앞에 두고 그 위에 번제와 소제를 올렸으니 여호와께서 모세에게 명령하신 대로였더라.'),
(2738, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 30, 'OT', '그가 물두멍을 회막과 제단 사이에 두고 거기에 씻을 물을 담았더라'),
(2739, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 31, 'OT', '모세와 아론과 그의 아들들이 그것으로 그들의 손과 그들의 발을 씻었더라'),
(2740, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 32, 'OT', '그들이 정한 때의 천막에 들어갈 때와 제단에 가까이 갈 때에 씻었으니, 여호와께서 모세에게 명령하신 대로 되니라.'),
(2741, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 33, 'OT', '그가 뜰을 장막과 제단 주위에 세우고 뜰 문의 휘장을 달았으며, 모세가 그 일을 마치니라.'),
(2742, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 34, 'OT', '구름이 정한 때의 천막을 덮었고, 여호와의 영광이 장막에 가득하였다.'),
(2743, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 35, 'OT', '모세가 정한 때의 천막으로 들어갈 수 없었으니 이는 구름이 그 위에 머물렀고 여호와의 영광이 장막에 가득 찼음이었더라.'),
(2744, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 36, 'OT', '구름이 장막 위에서 떠오를 때에 이스라엘 자손이 그들의 모든 여정에서 출발하였더라.'),
(2745, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 37, 'OT', '구름이 떠오르지 않으면 그들이 떠오르는 날까지 행진하지 아니하였으며'),
(2746, 2, 'GOI_Ko', 'GOI_Ko', 'ko', 'EXO', 40, 38, 'OT', '여호와의 구름이 장막 위에 낮에 있고 불이 밤에 그 안에 있으니 모든 이스라엘 집의 눈 앞에서 그들의 모든 여정 가운데 있었더라'),
(2747, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 1, 'OT', '여호와께서 모세를 부르시고 정한 때의 천막에서 그에게 말씀하여 이르시되'),
(2748, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 2, 'OT', '이스라엘 자손에게 말하여 그들에게 이르라, 너희 중에 어떤 사람이 여호와께 제물을 드리려거든, 짐승 중에서 소와 양떼 중에서 너희 제물을 드릴지니라.'),
(2749, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 3, 'OT', '그의 제물이 소의 번제이면 흠 없는 수컷으로 드릴지니, 정한 때의 천막 문에서 여호와의 얼굴 앞에 그 기쁨을 위하여 그것을 드릴지니라.'),
(2750, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 4, 'OT', '그가 번제물의 머리에 손을 얹을지니 그것이 그를 위하여 받아들여져 그를 위하여 속죄가 되리라'),
(2751, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 5, 'OT', '그가 그 소 아들을 여호와 앞에서 잡을 것이요, 아론의 아들들인 제사장들이 그 피를 가져다가 정한 때의 천막 문 앞에 있는 제단 주위에 그 피를 뿌릴 것이며'),
(2752, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 6, 'OT', '그가 번제의 가죽을 벗기고 그것을 그 조각들로 쪼갤지니라.'),
(2753, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 7, 'OT', '제사장 아론의 아들들은 제단 위에 불을 두고 그 불 위에 나무를 벌여 놓을지니라'),
(2754, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 8, 'OT', '아론의 아들 제사장들은 그 조각들과 머리와 기름을 제단 위에 있는 불 위의 나무 위에 벌여 놓을 것이며'),
(2755, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 9, 'OT', '그의 속과 그의 다리를 물로 씻을 것이요, 제사장은 그 모든 것을 제단 위에 불살라 번제, 곧 여호와께 향기로운 냄새의 불제물로 삼을지니라.'),
(2756, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 10, 'OT', '만일 그의 제물이 양떼에서, 곧 어린양이나 염소에서 번제로 드리려면, 흠 없는 수컷으로 그것을 드릴지니라.'),
(2757, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 11, 'OT', '그가 그것을 제단의 넓적다리 곁, 북쪽에서 여호와의 얼굴 앞에서 잡을 것이요, 아론의 아들 제사장들은 그 피를 제단 주위에 뿌릴 것이니라.'),
(2758, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 12, 'OT', '그것을 조각으로 나누고 그 머리와 그 기름을 두되, 제사장은 그것들을 제단 위에 있는 불 위의 나무 위에 벌여 놓을지니라.'),
(2759, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 13, 'OT', '그 속과 다리를 물로 씻을 것이요, 제사장은 그 모든 것을 가져다가 제단 위에서 불살라 번제로 삼을지니, 그것은 여호와께 향기로운 냄새의 불제물이니라.'),
(2760, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 14, 'OT', '만일 여호와께 드리는 그의 제물이 새의 번제이면, 그는 비둘기나 비둘기의 아들 중에서 그의 제물을 드릴지니라.'),
(2761, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 15, 'OT', '제사장은 그것을 제단으로 가져와서 그 머리를 비틀어 끊고 제단 위에서 불사르고 그 피는 제단의 벽에 흘릴지니라'),
(2762, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 16, 'OT', '그가 그 모이주머니를 깃털과 함께 제거하고, 그것을 제단 동쪽, 재 버리는 장소 곁에 던질지니라.'),
(2763, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 1, 17, 'OT', '그것을 날개와 함께 찢되 아주 나누지 말고 제사장이 그것을 제단 위, 불 위에 있는 나무 위에서 불사르리니 그것은 번제이자 여호와께 향기로운 냄새의 불제물이니라.'),
(2764, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 1, 'OT', '영혼이 여호와께 소제의 제물을 드리려거든 고운 밀가루가 그의 제물이 될 것이며 그 위에 기름을 붓고 그 위에 유향을 둘지니라'),
(2765, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 2, 'OT', '그것을 아론의 아들들인 제사장들에게로 가져올 것이요, 제사장은 그곳에서 그 고운 밀가루와 그 기름에서 한 줌 가득한 것과 그 모든 유향을 취하여, 그 기념물을 제단 위에서 불사르되, 여호와께 향기로운 냄새의 불제물로 삼을지니라.'),
(2766, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 3, 'OT', '제물 중에 남은 것은 아론과 그의 아들들의 것이니, 여호와의 불제물 중에서 지극히 거룩한 거룩함이니라.'),
(2767, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 4, 'OT', '네가 화덕에 구운 것으로 제물의 제물을 드리려거든, 고운 밀가루로 만든 누룩 없는 빵 화병들을 기름에 섞고, 누룩 없는 빵 얇은 떡들을 기름에 바른 것으로 드릴지니라.'),
(2768, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 5, 'OT', '네 제물이 번철에 부친 소제물이거든 고운 밀가루에 기름을 섞어 누룩 없는 빵이 되게 할지니라'),
(2769, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 6, 'OT', '그것을 조각으로 나누고 그 위에 기름을 부을지니 이는 제물이니라'),
(2770, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 7, 'OT', '만일 네 제물이 프라이팬에 만든 제물이면, 고운 밀가루를 기름으로 만들지니라.'),
(2771, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 8, 'OT', '너는 이것들로 만든 소제물을 여호와께로 가져올 것이요, 그것을 제사장에게 드리고, 제사장은 그것을 제단으로 가져갈 것이니라.'),
(2772, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 9, 'OT', '제사장은 그 제물에서 기념할 것을 취하여 제단 위에서 불사를지니 이는 여호와께 향기로운 냄새의 불제물이니라.'),
(2773, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 10, 'OT', '그리고 제물 중에 남은 것은 아론과 그의 아들들의 것이니, 여호와의 불제물 중에서 지극히 거룩한 거룩함이니라.'),
(2774, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 11, 'OT', '모든 제물은 너희가 여호와께 드리는 것이니 누룩으로 만들지 말지니라 이는 너희가 모든 누룩과 모든 꿀을 여호와께 불제물로 드려 사르지 못할 것임이니라'),
(2775, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 12, 'OT', '처음 익은 제물은 그것들을 여호와께 드릴지니라 그러나 제단에 올리지 말지니 향기로운 향기를 위하여는 아니니라'),
(2776, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 13, 'OT', '모든 소제물은 소금으로 간을 할지니 네 하나님의 언약의 소금을 네 제물에서 빼지 말지니라 네 모든 제물에 소금을 드릴지니라'),
(2777, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 14, 'OT', '네가 첫 열매의 소제를 여호와께 드리려거든 불에 볶은 이삭, 으깬 갈멜 곡식을 네 첫 열매의 소제로 드릴지니라.'),
(2778, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 15, 'OT', '그 위에 기름을 붓고 그 위에 유향을 얹을지니 이는 제물이니라'),
(2779, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 2, 16, 'OT', '제사장은 그 기념을 으깬 곡식과 기름과 모든 유향 위에서 불사르되, 여호와께 드리는 불제물로 삼을지니라.'),
(2780, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 1, 'OT', '만일 그의 제물이 화목제의 제사이면, 그가 소 떼에서 드리되 수컷이든 암컷이든 흠 없는 것으로 여호와의 얼굴 앞에 드릴지니라.'),
(2781, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 2, 'OT', '그가 그 제물의 머리에 손을 얹고, 정한 때의 천막 문에서 그것을 잡을 것이요, 제사장 아론의 아들들은 그 피를 제단 주위에 뿌릴지니라.'),
(2782, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 3, 'OT', '그는 화목제의 제사 중에서 여호와께 불제물을 드릴지니, 곧 속을 덮는 기름과 속에 있는 모든 기름을 드릴지니라.'),
(2783, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 4, 'OT', '두 콩팥과 그 위에 있는 기름, 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 제거할지니라.'),
(2784, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 5, 'OT', '아론의 아들들은 그것을 제단 위에, 불 위에 있는 나무 위에 있는 번제 위에 태울지니 이는 여호와께 향기로운 냄새의 불제물이니라'),
(2785, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 6, 'OT', '만일 그의 제물이 여호와께 드리는 화목제의 제사로 양떼에서 가져온 것이면 수컷이나 암컷이나 흠 없는 것으로 그것을 드릴지니라'),
(2786, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 7, 'OT', '만일 그가 어린양을 제물로 드리면, 그것을 여호와의 얼굴 앞에 드릴지니라.'),
(2787, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 8, 'OT', '그는 자기 손을 그 제물의 머리에 얹고, 정한 때의 천막 앞에서 그것을 잡을 것이며, 아론의 아들들은 그 피를 제단 주위에 뿌릴 것이다.'),
(2788, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 9, 'OT', '그는 화목제의 제사 중에서 여호와께 불제물을 드릴지니, 그 기름 곧 등뼈 곁에서 떼어낸 온전한 궁둥이와, 속을 덮는 기름과, 속에 있는 모든 기름을 드릴지니라.'),
(2789, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 10, 'OT', '두 콩팥과 그것들 위에 있는 기름, 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 제거할지니라.'),
(2790, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 11, 'OT', '제사장은 그것을 제단 위에서 불사르되 여호와께 드리는 불제물의 빵이니라'),
(2791, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 12, 'OT', '만일 그의 제물이 염소면, 그는 그것을 여호와의 얼굴 앞에 드릴지니라.'),
(2792, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 13, 'OT', '그가 자기 손을 그 머리 위에 얹고 회막 앞에서 그것을 잡을 것이요, 아론의 아들들은 그 피를 제단 주위에 뿌릴지니라.'),
(2793, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 14, 'OT', '그 중에서 그의 제물을 여호와께 불제물로 드릴지니, 곧 속을 덮는 기름과 속 위에 있는 모든 기름을 드릴지니라.'),
(2794, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 15, 'OT', '두 콩팥과 그것들 위에 있는 기름, 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 제거할지니라.'),
(2795, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 16, 'OT', '제사장은 그것을 제단 위에서 불사르되, 불제물의 빵이요 향기로운 향기로 여호와께 드리는 것이니, 모든 기름은 여호와의 것이니라.'),
(2796, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 3, 17, 'OT', '너희 모든 거주지에서 너희 세대에게 영원한 규례가 되리니 모든 기름과 모든 피를 먹지 말지니라'),
(2797, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2798, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 2, 'OT', '이스라엘 자손에게 말하여 이르라, 누구든지 여호와의 모든 명령 중 하나라도 행하지 말아야 할 것을 과실로 범하였으면, 그 중 하나를 행하였으면'),
(2799, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 3, 'OT', '만일 기름 부음을 받은 제사장이 백성의 죄로 말미암아 죄를 범하면, 그가 범한 자기 죄를 위하여 흠 없는 수송아지 곧 소의 아들을 여호와께 죄 제물로 드릴지니라.'),
(2800, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 4, 'OT', '그가 수송아지를 정한 때의 천막 문 앞, 여호와의 얼굴 앞으로 끌어오고, 그 수송아지 머리에 그의 손을 얹고, 그 수송아지를 여호와의 얼굴 앞에서 잡을 것이며'),
(2801, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 5, 'OT', '기름 부음을 받은 제사장은 그 수송아지의 피를 취하여 정한 때의 천막으로 가져갈 것이며'),
(2802, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 6, 'OT', '제사장이 그의 손가락을 피에 담그고, 그 피를 여호와 앞 곧 거룩한 휘장 앞에 일곱 번 뿌릴 것이며'),
(2803, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 7, 'OT', '제사장은 그 피를 여호와 앞 곧 정한 때의 천막 안에 있는 향료 향 제단의 뿔들에 바르고, 그 수송아지의 모든 피를 정한 때의 천막 문 앞에 있는 번제 제단의 기초에 쏟을 것이며'),
(2804, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 8, 'OT', '그리고 그 죄 제물 수송아지의 모든 기름을 그것에서 취할지니, 곧 내장을 덮는 기름과 내장 위에 있는 모든 기름을 취할지니라.'),
(2805, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 9, 'OT', '두 콩팥과 그 위에 있는 기름, 곧 허리 근방에 있는 것과, 간 위에 있는 꺼풀을 콩팥과 함께 제거할지니라'),
(2806, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 10, 'OT', '화목제 희생의 소에게서 취함 같이 할 것이요, 제사장은 그것을 번제단 위에 불사를 것이며'),
(2807, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 11, 'OT', '수송아지의 가죽과 그 모든 살을 그 머리와 그 다리와 그 속과 그 똥과 함께'),
(2808, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 12, 'OT', '그가 그 수송아지 전체를 진영 밖 청결한 장소, 곧 재를 쏟아내는 곳으로 가져가서 나무 위에서 불로 사르되, 재를 쏟아내는 곳에서 사를지니라.'),
(2809, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 13, 'OT', '만일 이스라엘의 모든 회중이 그릇 범하여 그 일이 회중의 눈에 숨겨지고, 그들이 여호와의 모든 명령 중 하나를 행하였으나 행해서는 안 될 것이라서 허물이 있게 되면'),
(2810, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 14, 'OT', '그들이 그 죄를 범한 그 죄가 알려지면, 회중은 소의 아들인 수송아지를 죄를 위한 제물로 드릴 것이며, 그를 정한 때의 천막 앞으로 가져올지니라.'),
(2811, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 15, 'OT', '회중의 장로들이 여호와 앞에서 그들의 손을 수송아지의 머리에 얹을 것이요, 그 수송아지를 여호와 앞에서 잡을 것이니라.'),
(2812, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 16, 'OT', '기름 부음을 받은 제사장은 그 수송아지의 피를 정한 때의 천막으로 가져올지니라.'),
(2813, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 17, 'OT', '제사장이 그의 손가락을 그 피에 찍어 여호와 앞 곧 휘장 앞에 일곱 번 뿌릴 것이며'),
(2814, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 18, 'OT', '그 피를 여호와 앞에 있는 회막 안의 제단 뿔들에 바르고, 그 모든 피는 회막 문 앞에 있는 번제단의 기초에 쏟을지니라.'),
(2815, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 19, 'OT', '그의 모든 기름을 그것에서 떼어내어 제단 위에서 불사르게 할지니라'),
(2816, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 20, 'OT', '그 수송아지에게 행하기를 죄를 위한 수송아지에게 행한 것 같이 그에게 행할 것이며, 제사장이 그들을 위하여 속죄하리니 그들이 사함을 얻으리라.'),
(2817, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 21, 'OT', '그는 그 수송아지를 진영 밖으로 가져가서 첫 번째 수송아지를 태운 것 같이 그것을 태울지니, 이는 회중의 죄 제사니라.'),
(2818, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 22, 'OT', '통치자가 범죄하여 그의 하나님 여호와의 모든 명령 중 하나를 과실로 행하여서는 안 될 일을 행하고 허물이 있게 되면'),
(2819, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 23, 'OT', '혹시 그가 범한 그 죄를 알게 되거든, 그는 자기 제물로 흠 없는 수염소를 가져올지니라.'),
(2820, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 24, 'OT', '그가 그 염소의 머리에 손을 얹고 여호와 앞에서 번제를 잡는 장소에서 그것을 잡을지니 이는 죄제라.'),
(2821, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 25, 'OT', '제사장은 그 죄 희생의 피를 손가락으로 취하여 번제 제단의 뿔들에 바르고, 그 피는 번제 제단의 기초에 쏟을지니라.'),
(2822, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 26, 'OT', '그의 모든 기름을 제단 위에서 불사를지니 화목제사의 기름 같이 할 것이며 제사장이 그의 죄를 위하여 그를 속죄하리니 그가 사함을 얻으리라'),
(2823, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 27, 'OT', '만일 땅의 백성 중 한 영혼이 여호와의 명령 중 하나를 행하지 말아야 할 것을 과실로 범하여 허물이 있으면'),
(2824, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 28, 'OT', '혹시 그가 지은 죄를 알게 되거든, 그는 자기 제물로 흠 없는 암컷 염소 새끼를 그가 지은 죄를 위하여 가져올지니라.'),
(2825, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 29, 'OT', '그는 그 죄의 머리에 그의 손을 얹고, 그 죄를 번제의 장소에서 잡을 것이다.'),
(2826, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 30, 'OT', '제사장은 그의 손가락으로 그 피를 취하여 번제단의 뿔들에 바르고, 그 피의 모든 것을 제단의 기초에 쏟을지니라.'),
(2827, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 31, 'OT', '그리고 그 모든 기름을 제거할지니 화목제 제사의 기름이 제단 위에서 제거된 것 같이 하여, 제사장이 그것을 제단 위에서 여호와께 향기로운 향기로 불사를지니, 제사장이 그를 위하여 속죄할 것이요 그가 사함을 얻으리라.'),
(2828, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 32, 'OT', '만일 그가 어린양을 제물로 가져와 죄를 위하여 바치려면, 흠 없는 암컷을 가져올지니라.'),
(2829, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 33, 'OT', '그는 그 죄 희생의 머리에 그의 손을 얹고, 번제를 잡는 장소에서 그것을 죄 희생으로 잡을 것이다.'),
(2830, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 34, 'OT', '제사장은 그 죄의 피를 손가락으로 취하여 번제 제단의 뿔들에 바르고, 그 모든 피를 제단의 기초에 쏟을지니라'),
(2831, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 4, 35, 'OT', '그 모든 기름을 제거할지니 어린양의 기름이 화목제 제사에서 제거됨 같이 하여, 제사장이 그것들을 제단 위에서 여호와의 불제물 위에 불사를지며, 제사장이 그가 범한 죄에 대하여 그를 위하여 속죄하리니 그가 사함을 얻으리라.'),
(2832, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 1, 'OT', '만일 어떤 영혼이 범죄하고 저주의 소리를 들었을 때, 그가 증인이라서 보았거나 알았어도 진술하지 아니하면, 그는 자기 죄악을 담당할 것이니라.'),
(2833, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 2, 'OT', '혹시 어떤 영혼이 모든 더러운 말씀을 만지면, 곧 더러운 살아있는 동물의 시체나 더러운 짐승의 시체나 더러운 번식하는 작은 동물의 시체를 만지면, 그것이 그에게 숨겨져 있어도 그는 더러운 자가 되어 허물이 있을지니라.'),
(2834, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 3, 'OT', '혹시 그가 사람의 더러움을 만졌는데, 그가 그 더러움으로 더러워질 모든 더러움에 대하여 그것이 그에게 숨겨졌다가, 그가 알고 죄책을 지게 되면,'),
(2835, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 4, 'OT', '혹은 어떤 영혼이 입술로 맹세를 발하여 악을 행하리라 하든지 선을 행하리라 하여, 사람이 맹세로 발하는 모든 것에 대하여 그것이 그에게 숨겨졌다가, 그가 그것을 알고 그 중 하나에 허물이 있을 때에는'),
(2836, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 5, 'OT', '그가 이 중 하나에 대하여 허물이 있을 때에는, 그가 그것에 대하여 범죄하였음을 자복할지니라'),
(2837, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 6, 'OT', '그가 그의 속건제를 여호와께 가져올지니 곧 그가 범한 죄로 말미암아 양떼에서 암컷 어린 양이나 염소 새끼를 죄를 위한 속죄제로 가져올 것이요, 제사장이 그의 죄를 위하여 그를 위하여 속죄할지니라.'),
(2838, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 7, 'OT', '그의 손이 양에게 충분히 미치지 못하면, 그는 자기가 범한 속건제를 위하여 두 마리 비둘기나 두 마리 집비둘기 새끼를 여호와께로 가져올지니, 하나는 죄를 위한 것이요 하나는 번제를 위한 것일지니라.'),
(2839, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 8, 'OT', '그들을 제사장에게로 가져올 것이요, 제사장은 그 죄를 위한 제물을 먼저 드리되, 그 머리를 목 앞에서 비틀되 갈라지게 하지 말지니라'),
(2840, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 9, 'OT', '그는 죄 제물의 피를 제단의 벽에 뿌리고, 그 피의 남은 것은 제단의 기초에 쏟을지니, 그것은 죄니라.'),
(2841, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 10, 'OT', '그 둘째는 판결대로 번제를 드릴 것이며, 제사장이 그가 범한 그의 죄에 대하여 그를 위하여 속죄할 것이요, 그가 사함을 얻으리라.'),
(2842, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 11, 'OT', '만일 그의 손이 두 마리 비둘기나 두 마리 집비둘기 새끼에게까지 미치지 못하면, 그가 범죄한 자는 자기 제물을 가져올지니 에바 십분의 일의 고운 밀가루를 죄 제물로 삼을 것이요, 그 위에 기름을 두지 말며 그 위에 유향을 놓지 말지니 이는 그것이 죄 제물임이라.'),
(2843, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 12, 'OT', '그것을 제사장에게로 가져갈 것이요, 제사장은 그것에서 한 줌의 충만한 기념물을 취하여 여호와의 불제물 위에 있는 제단에서 불사를지니, 이는 죄니라.'),
(2844, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 13, 'OT', '제사장이 그가 이 중에 하나를 범한 그의 죄에 대하여 그를 위하여 속죄할지니 그가 사함을 얻으리라 그리고 그것은 제사장에게 소제물같이 되리라'),
(2845, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 14, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2846, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 15, 'OT', '영혼이 만일 여호와의 거룩함에 대하여 배신하고 과실로 죄를 범하였으면, 그 속건제를 여호와께 가져올지니 양떼 중에서 흠 없는 숫양을 네 평가대로 거룩한 세겔로 은 세겔에 해당하는 것으로 속건제를 삼아 드릴지니라.'),
(2847, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 16, 'OT', '그가 거룩함에 대해 범한 것을 갚되 그것에 다섯째를 더하여 제사장에게 줄 것이요 제사장은 그 속건제의 숫양으로 그를 위하여 속죄할지니 그가 사함을 얻으리라'),
(2848, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 17, 'OT', '만일 어떤 영혼이 여호와의 모든 명령 중 하나를 범하여 행하지 말아야 할 것을 행하였으나 알지 못하고 허물이 있어 죄악을 담당할 것이면'),
(2849, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 18, 'OT', '그가 양떼에서 흠 없는 숫양을 네 평가대로 속건제물로 제사장에게로 가져올 것이요, 제사장은 그가 알지 못하고 범한 과실을 위하여 그를 위하여 속죄할 것이라, 그가 사함을 얻으리라.'),
(2850, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 5, 19, 'OT', '그것은 속건제니 그가 실로 여호와께 범과하였느니라'),
(2851, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2852, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 2, 'OT', '영혼이 만일 범죄하여 여호와께 배신하고 동료에게 맡긴 물건이나 손에 친교하거나 강탈하거나 동료를 속여서'),
(2853, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 3, 'OT', '혹은 잃어버린 것을 찾고도 그것에 대하여 거짓말하며 거짓으로 맹세하는 것, 사람이 그 가운데 하나라도 행하여 범죄하는 모든 일에 대하여'),
(2854, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 4, 'OT', '그가 죄를 짓고 죄가 있어서, 그가 약탈한 약탈물이나 그가 착취한 착취나 그에게 맡겨진 맡긴 물건이나 그가 찾은 잃어버린 것을 돌려주어야 할 때에,'),
(2855, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 5, 'OT', '또는 그가 거짓으로 맹세한 모든 것에 대하여, 그는 그것을 머리로 갚고 그 위에 오분의 일을 더할 것이며, 그 죄가 드러나는 날에 그것이 속한 자에게 줄지니라.'),
(2856, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 6, 'OT', '그는 그의 속건제를 여호와께로 가져올지니, 양떼 중에서 흠 없는 숫양을 네 평가대로 속건제를 위하여 제사장에게로 가져올 것이며'),
(2857, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 7, 'OT', '제사장이 여호와의 얼굴 앞에서 그를 위하여 속죄할 것이요, 그리하면 그가 모든 죄 중에서 그가 죄로 말미암아 행한 모든 일에 대하여 사함을 얻으리라.'),
(2858, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 8, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2859, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 9, 'OT', '아론과 그의 아들들에게 명령하여 이르기를, 이것이 번제의 율법이니라. 그것은 제단 위의 불타는 곳 위에 있는 번제라. 밤새도록 아침까지 두고, 제단의 불은 그 위에서 꺼지지 않게 하라.'),
(2860, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 10, 'OT', '제사장은 베 옷을 입고 베 속바지를 그의 살 위에 입을 것이며, 불이 제단 위의 번제를 태운 재를 가져다가 제단 곁에 둘 것이다.'),
(2861, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 11, 'OT', '그의 옷을 벗고 다른 옷을 입고, 그 재를 진영 밖 정결한 장소로 가져갈 것이며'),
(2862, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 12, 'OT', '제단 위에 있는 불은 그 위에서 계속 타오르게 하여 꺼지지 않게 할지니, 제사장이 아침마다 그 위에 나무를 태우고 그 위에 번제를 벌여 놓으며 그 위에 화목제의 기름을 사를지니라.'),
(2863, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 13, 'OT', '제단 위에 항상 불을 피워 두고 꺼지지 않게 할지니라'),
(2864, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 14, 'OT', '이것은 제물의 율법이니 아론의 아들들이 그것을 여호와의 얼굴 앞, 제단의 얼굴 앞에 드릴지니라'),
(2865, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 15, 'OT', '그가 그 제물의 고운 밀가루와 그 기름에서 한 줌을 취하고 제물 위에 있는 모든 유향을 취하여 제단 위에서 불살라 여호와 앞에 향기로운 냄새의 기념이 되게 할지니라'),
(2866, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 16, 'OT', '그 나머지는 아론과 그의 아들들이 먹을 것이요, 누룩 없는 빵으로 거룩한 장소, 곧 정한 때의 천막의 뜰에서 먹을지니라.'),
(2867, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 17, 'OT', '누룩을 넣어 굽지 말지니, 내가 불제물 중에서 그 몫으로 그것을 주었느니라. 그것은 지극히 거룩함이라, 죄제와 속건제와 같으니라.'),
(2868, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 18, 'OT', '아론의 아들들 중 모든 남자는 그것을 먹을지니, 그것은 여호와의 불제물 중에서 너희 세대에게 영원한 법령이 될지니라. 그것들을 만지는 모든 자는 거룩하리라.'),
(2869, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 19, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2870, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 20, 'OT', '이것은 아론과 그의 아들들이 기름 부음을 받는 날에 여호와께 드릴 제물이니, 고운 밀가루 에바 십분의 일을 항상 드리는 소제물로 삼아, 그 절반은 아침에, 그 절반은 저녁에 드릴지니라.'),
(2871, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 21, 'OT', '번철에 기름으로 만들되 곱게 섞어 가져올지니 구운 조각들의 소제물을 조각으로 나누어 여호와께 향기로운 향기로 드릴지니라'),
(2872, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 22, 'OT', '그의 아들들 중에서 그를 대신하여 기름 부음을 받은 제사장이 그것을 드릴 것이니, 여호와께 영원한 법령으로 온전히 불사를지니라.'),
(2873, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 23, 'OT', '모든 제사장의 제물은 온전히 불사르게 될 것이며 먹지 못할 것이니라'),
(2874, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 24, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2875, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 25, 'OT', '아론과 그의 아들들에게 말하여 이르라, 이것이 죄 제사의 율법이니라, 번제를 잡는 장소에서 죄 제사를 여호와 앞에서 잡을지니, 그것은 지극히 거룩하니라.'),
(2876, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 26, 'OT', '제사장이 그것을 정결케 한 자가 그것을 먹을 것이니 거룩한 장소에서 먹을 것이며 정한 때의 천막의 뜰에서 먹을지니라'),
(2877, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 27, 'OT', '그 살에 닿는 모든 것은 거룩할 것이며, 그 피가 옷에 뿌려지면 그것이 뿌려진 옷은 거룩한 장소에서 빨아야 할지니라.'),
(2878, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 28, 'OT', '질그릇에 삶았으면 그것을 깨뜨릴 것이요, 놋쇠 그릇에 삶았으면 물로 닦고 씻을 것이며'),
(2879, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 29, 'OT', '제사장 중 모든 남자는 그것을 먹을지니 그것은 지극히 거룩함이니라'),
(2880, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 6, 30, 'OT', '모든 죄 제사는 그 피가 정한 때의 천막 안으로 가져와 거룩함에서 속죄하기 위한 것은 먹지 못할지니 불로 태울지니라'),
(2881, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 1, 'OT', '이것이 속건제의 율법이니 그것은 지극히 거룩한 거룩함이니라'),
(2882, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 2, 'OT', '번제를 잡는 장소에서 속건제를 잡을 것이며, 그 피를 제단 주위에 뿌릴지니라.'),
(2883, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 3, 'OT', '그 모든 기름을 그것에서 드리되, 궁둥이와 속을 덮는 기름을 드릴지니라.'),
(2884, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 4, 'OT', '두 콩팥과 그것들 위에 있는 기름, 곧 허리 근방에 있는 것과, 간에 덮인 꺼풀을 콩팥과 함께 제거할지니라.'),
(2885, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 5, 'OT', '제사장은 그것들을 제단 위에서 여호와께 불제물로 불사를지니 그것은 속건제라'),
(2886, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 6, 'OT', '제사장 중 모든 남자는 그것을 먹을지니 거룩한 장소에서 먹을지라 그것은 지극히 거룩함이니라'),
(2887, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 7, 'OT', '속죄제와 같이 속건제도 그들에게 한 율법이니 그것으로 속죄하는 제사장에게 그것이 돌아갈 것이니라'),
(2888, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 8, 'OT', '어떤 사람의 번제를 드리는 제사장은 자기가 드린 번제의 가죽을 가질지니라.'),
(2889, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 9, 'OT', '모든 화덕에서 구운 제물과 모든 프라이팬과 번철 위에서 만든 것은 그것을 드리는 제사장의 것이 될지니라.'),
(2890, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 10, 'OT', '모든 기름에 섞은 제물과 마른 제물은 아론의 모든 아들들에게 있으리니, 각 사람이 형제와 같이 하리라.'),
(2891, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 11, 'OT', '이것은 여호와께 드릴 화목제 제사의 율법이니라.'),
(2892, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 12, 'OT', '만일 그가 그것을 감사제사로 드리면, 그 감사제사의 제사와 함께 누룩 없는 빵 화병들을 기름에 섞어 드리고, 기름 바른 누룩 없는 빵 얇은 떡들과, 기름에 섞인 화병들로 된 고운 밀가루를 드릴지니라.'),
(2893, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 13, 'OT', '누룩 있는 빵 화병 위에 그의 제물을 드릴지니 그의 화목제의 감사제사 제사와 함께 할지니라'),
(2894, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 14, 'OT', '그 중에서 모든 제물 중 하나를 여호와께 제사로 드리고, 화목제의 피를 뿌린 제사장에게 그것이 그의 것이 되리라.'),
(2895, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 15, 'OT', '그의 화목제 감사제사의 제사 고기는 그 제물을 드리는 날에 먹을 것이요, 아침까지 그것을 남겨 두지 말지니라'),
(2896, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 16, 'OT', '그러나 그의 제물이 서원이나 자원제사이면, 그가 그 제사를 드리는 날에 먹을 것이요, 이튿날에도 그 남은 것을 먹을 수 있느니라.'),
(2897, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 17, 'OT', '제사 희생의 살 중에 남은 것은 제삼일에 불로 사를지니라'),
(2898, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 18, 'OT', '만일 그의 화목제 제사의 고기가 셋째 날에 조금이라도 먹히면 그것은 열납되지 않을 것이며, 그것을 드리는 자에게는 인정되지 않을 것이요, 그것은 가증한 것이 될 것이며, 그것을 먹는 영혼은 자기 죄악을 담당하리라.'),
(2899, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 19, 'OT', '모든 부정한 것에 접촉된 살은 먹지 말고 불에 사를지니라, 그러나 모든 깨끗한 자는 그 살을 먹을지니라.'),
(2900, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 20, 'OT', '그러나 여호와께 속한 화목제사의 고기를 먹는 영혼이 그 더러움이 자기 위에 있을 때에는, 그 영혼은 자기 백성 중에서 끊쳐질 것이라.'),
(2901, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 21, 'OT', '영혼이 모든 더러운 것, 곧 사람의 더러움이나 더러운 짐승이나 모든 더럽고 가증한 것에 접촉하고 여호와께 속한 화목제 제사의 살을 먹으면 그 영혼은 자기 백성 중에서 끊쳐지리라.'),
(2902, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 22, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2903, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 23, 'OT', '이스라엘 자손에게 말하여 이르기를, 모든 소와 어린양과 염소의 기름은 너희가 먹지 말지니라.'),
(2904, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 24, 'OT', '시체의 기름과 웃긴 것의 기름은 모든 일에 쓰일 것이나, 그것을 먹지는 말지니라.'),
(2905, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 25, 'OT', '모든 짐승 중에서 여호와께 불제물로 드리는 그 기름을 먹는 자는, 그 먹는 영혼이 그 백성 중에서 끊쳐지리라.'),
(2906, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 26, 'OT', '너희 모든 거주지에서 모든 피를 먹지 말지니, 새와 짐승의 피를 먹지 말라.'),
(2907, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 27, 'OT', '모든 영혼이 모든 피를 먹으면 그 영혼은 그 백성 중에서 끊쳐지리라.'),
(2908, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 28, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2909, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 29, 'OT', '이스라엘 자손에게 말하여 이르라, 자기의 화목제 제사를 여호와께 드리는 자는 그의 화목제 제사 중에서 그의 제물을 여호와께 가져올지니라.'),
(2910, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 30, 'OT', '그의 손이 여호와의 불제물을 가져올지니 곧 기름을 가슴과 함께 가져올 것이요 그 가슴을 여호와의 얼굴 앞에 흔들어 바침으로 흔들어 바칠지니라'),
(2911, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 31, 'OT', '제사장은 그 기름을 제단 위에서 불사를 것이며, 그 가슴은 아론과 그의 아들들의 것이 될 것이다.'),
(2912, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 32, 'OT', '너희는 화목제의 제사들 중에서 오른쪽 넓적다리를 제사장에게 제사로 드릴지니라.'),
(2913, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 33, 'OT', '아론의 아들 중에서 화목제의 피와 기름을 드리는 자에게는 오른쪽 넓적다리가 그의 몫이 될지니라.'),
(2914, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 34, 'OT', '내가 이스라엘 자손의 화목제 제사 중에서 흔들어 바침의 가슴과 제사의 넓적다리를 취하여 제사장 아론과 그의 아들들에게 주었나니 이는 이스라엘 자손에게서 받을 영원한 법령이니라'),
(2915, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 35, 'OT', '이것은 여호와의 불제물 중에서 아론의 기름부음과 그의 아들들의 기름부음이니, 그들을 여호와께 제사장으로 섬기도록 제사드린 날에 대한 것이니라.'),
(2916, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 36, 'OT', '여호와께서 그들에게 주라고 명령하신 것은 그들에게 기름 부은 날에 이스라엘 자손에게서 받은 것이니, 그들의 세대를 위한 영원한 규례라.'),
(2917, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 37, 'OT', '이것은 번제와 제물과 죄와 속건제와 위임식과 화목제의 제사에 관한 율법이라'),
(2918, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 7, 38, 'OT', '여호와께서 시내 산에서 모세에게 명하신 대로, 그가 이스라엘 자손에게 그들의 제물을 여호와께 드리라고 명하신 날에, 시내 광야에서 그리하였더라.'),
(2919, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(2920, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 2, 'OT', '아론과 그의 아들들과 그와 함께 있는 옷들과 기름부음의 기름과 죄를 위한 수송아지와 숫양 둘과 누룩 없는 빵 한 바구니를 취하라.'),
(2921, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 3, 'OT', '그리고 모든 회중을 정한 때의 천막 문 앞에 모으라'),
(2922, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 4, 'OT', '모세가 여호와께서 그에게 명령하신 대로 행하니 회중이 정한 때의 천막 문에 모였더라.'),
(2923, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 5, 'OT', '모세가 회중에게 말하되, 이것이 여호와께서 행하라고 명하신 말씀이니라'),
(2924, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 6, 'OT', '모세가 아론과 그의 아들들을 데려다가 물로 그들을 씻기니라'),
(2925, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 7, 'OT', '그가 그에게 속옷을 입히고 띠로 그를 띠고 겉옷을 그에게 입히고 에봇을 그 위에 두고 에봇의 띠로 그를 띠고 그것으로 그에게 에봇을 매었더라'),
(2926, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 8, 'OT', '그가 그 위에 흉패를 두르고 흉패 안에 우림과 훔밈을 넣었더라'),
(2927, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 9, 'OT', '그가 터번을 그의 머리에 두르고, 터번 위 그의 얼굴 앞쪽에 금 꽃, 곧 거룩함의 왕관을 두었으니, 여호와께서 모세에게 명령하신 대로였더라.'),
(2928, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 10, 'OT', '모세가 기름부음의 기름을 취하여 장막과 그 안에 있는 모든 것에 바르고 그것들을 거룩하게 하니라'),
(2929, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 11, 'OT', '그것을 제단 위에 일곱 번 뿌리고, 제단과 그 모든 그릇들과 화로와 그 받침대에 발라 그들을 거룩하게 하였더라.'),
(2930, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 12, 'OT', '그가 기름부음의 기름을 아론의 머리에 붓고 그를 거룩하게 하려고 기름을 발랐더라'),
(2931, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 13, 'OT', '모세가 아론의 아들들을 데려다가 그들에게 속옷을 입히고 띠로 그들을 띠우며 그들에게 두건을 씌웠으니 여호와께서 모세에게 명하신 대로였더라'),
(2932, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 14, 'OT', '그가 죄를 위한 수송아지를 가져오니, 아론과 그의 아들들이 그 죄를 위한 수송아지의 머리에 그들의 손을 얹으니라.'),
(2933, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 15, 'OT', '그가 잡았고, 모세가 그 피를 취하여 그의 손가락으로 제단의 뿔들 주위에 바르고, 제단을 정결하게 하였으며, 그 피는 제단의 기초에 쏟아 부어, 그것을 거룩하게 하여 그 위에 속죄를 이루었더라.'),
(2934, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 16, 'OT', '그가 속에 있는 모든 기름과 간의 꺼풀과 두 콩팥과 그 기름을 취하여 모세가 제단 위에서 불살랐더라.'),
(2935, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 17, 'OT', '그 수송아지와 그 가죽과 그 살과 그 똥을 진영 밖에서 불로 태웠으니, 여호와께서 모세에게 명령하신 대로였더라.'),
(2936, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 18, 'OT', '그가 번제의 숫양을 가져오매 아론과 그의 아들들이 그 숫양의 머리에 그들의 손을 얹으니라'),
(2937, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 19, 'OT', '그가 잡고 모세가 그 피를 제단 주위에 뿌리니라'),
(2938, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 20, 'OT', '그 숫양을 조각으로 쪼개고, 모세가 그 머리와 조각들과 기름을 불살랐더라.'),
(2939, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 21, 'OT', '그가 그 속과 다리들을 물로 씻고 모세가 그 숫양의 모든 것을 제단 위에 불사르니 그것은 향기로운 냄새를 위한 번제요 여호와께 드리는 불제물이라 여호와께서 모세에게 명령하신 대로였더라'),
(2940, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 22, 'OT', '또 그가 두 번째 숫양, 곧 위임식의 숫양을 가까이 가져오니, 아론과 그의 아들들이 그 숫양의 머리에 그들의 손을 얹으니라.'),
(2941, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 23, 'OT', '그가 잡아 도살하고 모세가 그 피를 취하여 아론의 오른쪽 귀 끝과 그의 오른손 엄지와 그의 오른발 엄지에 바르니라'),
(2942, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 24, 'OT', '아론의 아들들을 데려오고 모세가 그 피를 그들의 오른쪽 귀 끝과 그들의 오른손 엄지와 그들의 오른발 엄지에 바르고 모세가 그 피를 제단 주위에 뿌렸더라'),
(2943, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 25, 'OT', '그가 기름과 궁둥이와 속에 있는 모든 기름과 간의 꺼풀과 두 콩팥과 그 기름과 오른쪽 넓적다리를 취하고'),
(2944, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 26, 'OT', '여호와 앞에 있는 누룩 없는 빵 바구니에서 누룩 없는 빵 화병 하나와 기름 섞인 빵 화병 하나와 얇은 떡 하나를 취하여 그 기름들과 오른쪽 넓적다리 위에 놓았더라'),
(2945, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 27, 'OT', '그가 모든 것을 아론의 손바닥과 그의 아들들의 손바닥에 두고 여호와의 얼굴 앞에서 흔들어 바침으로 그들을 흔들었더라.'),
(2946, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 28, 'OT', '모세가 그들의 손바닥에서 그것들을 취하여 제단 위 번제물 위에 불사르니 이는 위임식으로 향기로운 향기, 곧 여호와께 드리는 불제물이라.'),
(2947, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 29, 'OT', '모세가 그 가슴을 취하여 여호와의 얼굴 앞에 흔들어 바침으로 흔들어 바침을 삼았으니 이는 위임식 숫양에서 모세에게 몫이 되었음이라 여호와께서 모세에게 명령하신 대로였더라'),
(2948, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 30, 'OT', '모세가 기름부음의 기름과 제단 위에 있는 피를 취하여 아론과 그의 옷과 그의 아들들과 그의 아들들의 옷에 그와 함께 뿌리고, 아론과 그의 옷과 그의 아들들과 그의 아들들의 옷을 그와 함께 거룩하게 하였더라.'),
(2949, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 31, 'OT', '모세가 아론과 그의 아들들에게 말하되, 너희는 정한 때의 천막 문에서 그 살을 삶고, 거기서 그것과 위임식 바구니 안에 있는 빵을 먹을지니, 내가 명령하여 이르기를 아론과 그의 아들들이 그것을 먹으리라 하였느니라.'),
(2950, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 32, 'OT', '고기와 빵에 남은 것은 불로 태울지니라'),
(2951, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 33, 'OT', '너희는 정한 때의 천막 문에서 칠 일 동안 나가지 말고, 너희 위임식의 날들이 차는 날까지 있으라. 이는 칠 일 동안 그가 너희 손을 위임할 것임이라.'),
(2952, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 34, 'OT', '그가 오늘 행한 대로 여호와께서 너희를 위하여 속죄하도록 명하셨느니라'),
(2953, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 35, 'OT', '너희는 정한 때의 천막 문에 칠 주야를 앉아 있을지니, 여호와의 파수를 지켜 죽지 않게 하라, 이는 내가 이같이 명령을 받았음이니라.'),
(2954, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 8, 36, 'OT', '아론과 그의 아들들이 여호와께서 모세의 손으로 명령하신 모든 말씀을 행하였더라'),
(2955, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 1, 'OT', '여덟째 날에 모세가 아론과 그의 아들들과 이스라엘의 장로들을 불렀더라.'),
(2956, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 2, 'OT', '그가 아론에게 말하되, 너를 위하여 죄를 위한 소의 아들인 송아지를 취하고, 흠 없는 숫양을 번제를 위하여 취하여 여호와의 얼굴 앞에 드리라.'),
(2957, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 3, 'OT', '이스라엘 자손에게 말하여 이르기를 너희는 염소 새끼를 속죄제물로 취하고, 일 년 된 흠 없는 송아지와 어린양을 번제물로 취할지니라.'),
(2958, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 4, 'OT', '소와 숫양을 화목제로 여호와 앞에 희생하여 드리고, 기름에 섞은 제물을 드릴지니, 오늘 여호와께서 너희에게 나타나실 것임이니라.'),
(2959, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 5, 'OT', '그들이 모세가 명령한 것을 정한 때의 천막 얼굴 앞으로 가져왔고, 모든 회중이 가까이 나아와 여호와의 얼굴 앞에 섰더라.'),
(2960, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 6, 'OT', '모세가 말하되, 이것은 여호와께서 명하신 말씀이니 너희는 행할지니라. 그리하면 여호와의 영광이 너희에게 나타나리라.'),
(2961, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 7, 'OT', '모세가 아론에게 말하되, 제단에 가까이 나아가 네 죄와 네 번제를 드려서 너를 위하여와 백성을 위하여 속죄하고, 백성의 제물을 드려서 그들을 위하여 속죄하되, 여호와께서 명령하신 대로 하라.'),
(2962, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 8, 'OT', '아론이 제단에 가까이 나아가서 자기 죄를 위한 송아지를 잡으니라'),
(2963, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 9, 'OT', '아론의 아들들이 그 피를 그에게 가져왔고, 그가 자기 손가락을 피에 찍어 제단의 뿔들에 바르고, 그 피는 제단의 기초에 쏟았더라.'),
(2964, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 10, 'OT', '그리고 그 죄제물의 기름과 콩팥과 간의 꺼풀을 제단 위에서 불살랐으니, 여호와께서 모세에게 명령하신 대로였더라.'),
(2965, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 11, 'OT', '그 살과 가죽을 불로 태워 진영 밖에서 불사르니라'),
(2966, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 12, 'OT', '그가 번제를 잡고, 아론의 아들들이 그 피를 그에게로 가져오매 그가 그것을 제단 주위에 뿌리니라.'),
(2967, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 13, 'OT', '그들이 번제를 그의 앞에 가져오되 그것의 조각들과 머리를 가져오매 그가 제단 위에 불사르니라'),
(2968, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 14, 'OT', '그가 그 속과 다리를 씻고 번제 위 제단에서 불살랐더라'),
(2969, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 15, 'OT', '그가 백성의 제물을 가까이 가져왔고, 백성을 위한 죄의 염소를 취하여 그것을 잡아 처음과 같이 그것을 죄를 위하여 드렸더라.'),
(2970, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 16, 'OT', '그가 번제를 가까이 가져와서 판결대로 그것을 드렸다.'),
(2971, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 17, 'OT', '그가 그 제물을 가져오고 그 중에서 손바닥에 가득 채워 제단 위에 불사르되 아침 번제와 따로 하였더라'),
(2972, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 18, 'OT', '또한 그가 백성을 위한 화목제 희생의 소와 숫양을 잡으매, 아론의 아들들이 그 피를 그에게로 가져오니 그가 제단 주위에 뿌리니라.'),
(2973, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 19, 'OT', '소의 기름과 숫양의 기름, 궁둥이와 덮개와 콩팥과 간의 꺼풀을'),
(2974, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 20, 'OT', '그들이 그 기름을 가슴들 위에 두고, 그가 그 기름을 제단 위에서 불사르니라.'),
(2975, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 21, 'OT', '아론이 그 가슴들과 오른쪽 넓적다리를 여호와 앞에 흔들어 바침으로 흔들어 바쳤으니, 모세가 명령한 대로였더라.'),
(2976, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 22, 'OT', '아론이 백성을 향하여 그의 손을 들어 그들을 축복하고, 죄제와 번제와 화목제를 드리기를 마치고 내려오니라.'),
(2977, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 23, 'OT', '모세와 아론이 정한 때의 천막에 들어가고 나와서 백성을 축복하매 여호와의 영광이 모든 백성에게 나타나니라'),
(2978, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 9, 24, 'OT', '여호와 앞에서 불이 나와 제단 위의 번제와 기름을 삼켰고, 모든 백성이 그것을 보고 소리 지르며 그들의 얼굴에 엎드렸더라.'),
(2979, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 1, 'OT', '아론의 아들 나답과 아비후가 각각 자기 불집게를 가져다가 그 안에 불을 담고 그 위에 향을 두고 여호와의 얼굴 앞에 다른 불을 드렸으니 이는 그들이 명령받지 않은 것이었더라'),
(2980, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 2, 'OT', '여호와의 얼굴 앞에서 불이 나와 그들을 삼켰고 그들이 여호와의 얼굴 앞에서 죽었더라.'),
(2981, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 3, 'OT', '모세가 아론에게 말하되, 이는 여호와께서 말씀하신 것이라, 이르시기를 나는 내게 가까이 하는 자들 가운데서 거룩함을 얻겠고 모든 백성의 얼굴 앞에서 영광을 얻으리라 하셨느니라. 아론이 잠잠하니라.'),
(2982, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 4, 'OT', '모세가 미사엘과 엘리사반을 불렀으니, 그들은 아론의 사랑하는 자 웃시엘의 아들들이라. 그가 그들에게 이르되, "가까이 나아와, 너희 형제들을 거룩함의 얼굴 앞에서 진영 밖으로 옮겨 가라."'),
(2983, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 5, 'OT', '그들이 가까이 나아가 그들의 속옷을 입은 채로 그들을 들어 진영 밖으로 메어내니, 모세가 말한 대로였더라.'),
(2984, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 6, 'OT', '모세가 아론과 그의 아들 엘르아살과 이다말에게 말하되 너희는 머리를 풀지 말며 옷을 찢지 말라 그리하여 너희가 죽지 말고 모든 회중에게 진노가 미치지 않게 하라 오직 너희 형제 이스라엘 온 집이 여호와께서 불태우신 그 불태움을 슬퍼할지니라'),
(2985, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 7, 'OT', '회막 문에서 나가지 말라 죽을까 하노니 여호와의 기름부음 기름이 너희 위에 있음이라 그들이 모세의 말씀대로 행하였더라'),
(2986, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 8, 'OT', '여호와께서 아론에게 말씀하여 이르시되'),
(2987, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 9, 'OT', '너와 네 아들들이 너와 함께 정한 때의 천막에 들어갈 때에는 포도주와 독주를 마시지 말라, 그리하여 너희가 죽지 않게 하라. 이는 너희 세대에게 영원한 규례니라.'),
(2988, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 10, 'OT', '거룩함과 속된 것 사이를 구별하게 하며, 부정한 것과 정한 것 사이를 구별하게 하려 함이니라.'),
(2989, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 11, 'OT', '또한 여호와께서 모세의 손으로 그들에게 말씀하신 모든 법령을 이스라엘 자손에게 가르치게 하려 함이니라'),
(2990, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 12, 'OT', '모세가 아론과 그의 남은 아들 엘르아살과 이다말에게 말하여 이르되, 여호와의 불제물 중에서 남은 제물을 취하여 누룩 없는 빵으로 제단 곁에서 먹으라, 그것은 지극히 거룩함이니라.'),
(2991, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 13, 'OT', '너희는 그것을 거룩한 장소에서 먹을지니, 이는 그것이 여호와의 불제물 중에서 너의 법령과 네 아들들의 법령이기 때문이니라. 내가 이같이 명령을 받았느니라.'),
(2992, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 14, 'OT', '너는 흔들어 바침의 가슴과 제사의 넓적다리를 정결한 장소에서 먹을지니, 너와 네 아들들과 네 딸들이 너와 함께 할지니라. 이는 네 법령과 네 아들들의 법령이 이스라엘 자손의 화목제 제사들 중에서 주어졌음이니라.'),
(2993, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 15, 'OT', '넓적다리의 제사와 가슴의 흔들어 바침을 기름의 불제물과 함께 가져다가 여호와의 얼굴 앞에서 흔들어 바침으로 흔들어 바칠지니 그것이 여호와께서 명령하신 대로 너와 너와 함께한 네 아들들의 영원한 법령이 될지니라'),
(2994, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 16, 'OT', '모세가 속죄제의 염소를 부지런히 찾았으나 보라 그것이 불탔더라. 그가 아론의 남은 아들 엘르아살과 이다말에게 노하여 이르되'),
(2995, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 17, 'OT', '어찌하여 너희가 그 속죄제를 거룩한 장소에서 먹지 아니하였느냐? 그것은 지극히 거룩하니라. 그가 그것을 너희에게 주어 회중의 죄악을 담당하게 하여 그들을 위하여 여호와 앞에서 속죄하게 하셨느니라.'),
(2996, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 18, 'OT', '보라, 그 피를 안으로 거룩함 안에 들여오지 아니하였으니 너희는 내가 명령한 대로 거룩함 안에서 그것을 반드시 먹었어야 하느니라.'),
(2997, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 19, 'OT', '아론이 모세에게 말하여 이르되, 보라, 오늘 그들이 그들의 죄와 그들의 번제를 여호와 앞에 드렸는데, 이런 일들이 내게 임하였도다. 내가 오늘 죄를 먹었더라면 여호와의 눈에 좋게 여겨지겠느냐?'),
(2998, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 10, 20, 'OT', '모세가 듣고 그것이 그의 눈에 좋게 여겼더라'),
(2999, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 1, 'OT', '여호와께서 모세와 아론에게 말씀하여 그들에게 이르시되'),
(3000, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 2, 'OT', '이스라엘 자손에게 말하여 이르되, 땅 위에 있는 모든 짐승 중에서 너희가 먹을 살아있는 것은 이러하니'),
(3001, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 3, 'OT', '모든 굽이 갈라지고 발굽이 갈라진 짐승 중에서 되새김질하는 것은 너희가 먹을지니라'),
(3002, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 4, 'OT', '오직 이것은 너희가 먹지 못할지니, 되새김질하는 것과 굽이 갈라진 것 중에서도 낙타는 되새김질을 하나 굽이 갈라지지 아니하였으므로 그것이 너희에게 부정하니라.'),
(3003, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 5, 'OT', '산토끼는 되새김질을 하나 굽을 갈라지게 하지 아니하므로 그것은 너희에게 부정하니라.'),
(3004, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 6, 'OT', '토끼는 되새김질을 하나 굽을 갈라지게 하지 아니하였으므로 그것은 너희에게 부정하니라'),
(3005, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 7, 'OT', '멧돼지는 굽을 갈라지게 하여 발굽이 갈라진 쪽발이지만, 그것은 되새김질을 하지 아니하나니 그것은 너희에게 부정하니라.'),
(3006, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 8, 'OT', '너희는 그들의 살을 먹지 말고 그들의 시체를 만지지 말라 그들은 너희에게 부정하니라'),
(3007, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 9, 'OT', '너희는 물에 있는 모든 것 중에서 이것을 먹을지니, 물과 바다와 골짜기에서 지느러미와 비늘을 가진 모든 것을 너희가 먹을지니라.'),
(3008, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 10, 'OT', '바다와 골짜기에 있는 모든 것 중에서 지느러미와 비늘이 없는 모든 것, 물에서 번식하는 모든 작은 동물과 물에 있는 모든 살아 있는 영혼은 너희에게 가증한 것이니라.'),
(3009, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 11, 'OT', '그것들은 너희에게 가증한 것이 될지니 너희는 그 살을 먹지 말고 그 시체를 가증히 여길지니라'),
(3010, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 12, 'OT', '물에 지느러미와 비늘이 없는 모든 것은 너희에게 가증한 것이니라.'),
(3011, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 13, 'OT', '너희는 새 중에서 이것들을 가증히 여길지니 그것들은 먹지 못할 것이요 그것들은 가증한 것이라: 독수리와 갈퀴와 군부엉이'),
(3012, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 14, 'OT', '독수리와 솔개를 그 종류대로 하라'),
(3013, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 15, 'OT', '모든 까마귀를 그 종류대로'),
(3014, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 16, 'OT', '타조와, 올빼미와, 뻐꾸기와, 매를 그 종류대로.'),
(3015, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 17, 'OT', '잔과 가마우지와 올빼미'),
(3016, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 18, 'OT', '두더지와 가마우지와 독수리와'),
(3017, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 19, 'OT', '황새와 왜가리를 그 종류대로, 후투티와 박쥐를'),
(3018, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 20, 'OT', '모든 새 중에서 네 발로 기어 다니는 번식하는 작은 동물은 그것이 너희에게 가증한 것이니라.'),
(3019, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 21, 'OT', '오직 모든 날개 있는 번식하는 작은 동물 중에서 네 발로 걷는 것, 그 발 위에 다리가 있어서 그것들로 땅에서 뛰는 것은 너희가 먹을지니라'),
(3020, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 22, 'OT', '이것들 중에서 너희가 먹을 수 있는 것은 메뚜기 종류와 베짱이 종류와 귀뚜라미 종류와 팟종이 종류니라.'),
(3021, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 23, 'OT', '모든 날개가 있고 네 발이 있는 번식하는 작은 동물은 그것이 너희에게 가증한 것이니라'),
(3022, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 24, 'OT', '이런 것들로 너희는 부정하게 될지니, 그 시체를 만지는 모든 자는 저녁까지 부정할 것이며'),
(3023, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 25, 'OT', '모든 그 시체를 옮기는 자는 그 옷을 빨 것이요, 저녁까지 부정하리라.'),
(3024, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 26, 'OT', '모든 짐승 중에 굽을 갈라지게 하되 쪽발이 아닌 것이나 되새김질하지 않는 것은 너희에게 부정하니, 그것을 만지는 모든 자는 부정하리라.'),
(3025, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 27, 'OT', '모든 손바닥으로 걷는 모든 살아있는 짐승 중 네 발로 걷는 것은 다 너희에게 부정하니, 그 시체를 만지는 모든 자는 저녁까지 부정하리라.'),
(3026, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 28, 'OT', '그 시체를 나르는 자는 그의 옷을 빨 것이요, 저녁까지 부정하리라. 그것들은 너희에게 부정하니라.'),
(3027, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 29, 'OT', '이것이 너희에게 부정한 것이니, 땅 위에 번식하는 작은 동물 가운데서 할레드와 쥐와 덮개를 그 종류대로 하라.'),
(3028, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 30, 'OT', '족제비와 힘과 도마뱀과 달팽이와 두더지라'),
(3029, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 31, 'OT', '이것들은 모든 번식하는 작은 동물 가운데 너희에게 부정한 것이라, 그 사망한 것을 만지는 모든 자는 저녁까지 부정하리라.'),
(3030, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 32, 'OT', '그리고 그들이 죽은 후에 그 위에 떨어지는 모든 것은 부정하리니 모든 나무 그릇이나 옷이나 가죽이나 굵은베나, 일을 하는 데 쓰이는 모든 그릇은 물에 담글 것이며 저녁까지 부정하다가 정결하리라'),
(3031, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 33, 'OT', '모든 질그릇은 그것들 중 어떤 것이 그 중간에 떨어지면, 그 중간에 있는 모든 것이 부정하여질 것이며, 너는 그것을 깨뜨릴지니라.'),
(3032, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 34, 'OT', '모든 음식 중에서 물이 그 위에 올 음식은 부정할 것이며, 모든 그릇에 담긴 마실 모든 술 맡은 자는 부정할 것이다.'),
(3033, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 35, 'OT', '그들의 시체가 그 위에 떨어지는 모든 것은 부정할지니, 화덕과 화덕은 깨뜨릴지니라. 그것들은 부정하니, 너희에게 부정한 것이 되리라.'),
(3034, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 36, 'OT', '오직 샘과 우물, 물이 고인 곳은 정결할 것이나 그 시체에 닿는 자는 부정하리라.'),
(3035, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 37, 'OT', '그들의 시체가 모든 씨뿌림의 씨 곧 심을 씨 위에 떨어질지라도 그것은 정하니라.'),
(3036, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 38, 'OT', '만일 물이 씨 위에 부어지고 그들의 시체 중 하나가 그 위에 떨어지면, 그것은 너희에게 부정하니라.'),
(3037, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 39, 'OT', '너희의 먹을 짐승 중에서 죽은 것이 있으면 그 시체를 만지는 자는 저녁까지 부정하리라'),
(3038, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 40, 'OT', '그 시체를 먹는 자는 그 옷을 빨 것이요 저녁까지 부정할 것이며, 그 시체를 옮기는 자도 그 옷을 빨 것이요 저녁까지 부정하리라.'),
(3039, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 41, 'OT', '땅 위에 번식하는 모든 번식하는 작은 동물은 가증한 것이라 그것은 먹지 못할지니라'),
(3040, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 42, 'OT', '배로 기어다니는 모든 것과 네 발로 걷는 모든 것과 땅에서 번식하는 모든 작은 동물 중에 발이 많은 모든 것, 너희는 그것들을 먹지 말지니 이는 그들이 가증한 것임이라.'),
(3041, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 43, 'OT', '너희는 모든 번식하는 작은 동물로 말미암아 너희 영혼을 가증하게 하지 말며, 또 그것들로 말미암아 스스로 더럽히지 말라, 그리하여 그것들로 말미암아 부정하게 되지 말라.'),
(3042, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 44, 'OT', '나는 여호와 너희 하나님이라 그런즉 너희는 자신을 거룩하게 하여 거룩하게 되라 이는 내가 거룩함이니라 너희는 땅 위에 기는 모든 번식하는 작은 동물로 너희 영혼을 더럽히지 말지니라'),
(3043, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 45, 'OT', '내가 너희를 애굽 땅에서 인도하여 낸 여호와라, 너희의 하나님이 되려 함이니, 너희는 거룩할지어다, 이는 내가 거룩함이니라.'),
(3044, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 46, 'OT', '이것은 짐승과 새와 물에서 움직이는 모든 살아 있는 영혼과 땅에 기는 모든 영혼에 대한 율법이니라'),
(3045, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 11, 47, 'OT', '부정한 것과 정결한 것 사이를 구별하며, 먹을 수 있는 살아있는 것과 먹지 못할 살아있는 것 사이를 구별하기 위함이니라.'),
(3046, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3047, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 2, 'OT', '이스라엘 자손에게 말하여 이르라, 여자가 임신하여 남자를 낳으면 그녀는 칠 일 동안 부정하리니, 그녀의 불결함의 날들과 같이 그녀가 부정할지니라.'),
(3048, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 3, 'OT', '여덟째 날에는 그의 포경의 살을 벨 것이니라'),
(3049, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 4, 'OT', '그리고 서른 날과 사흘 날을 그녀가 정결의 피 가운데 앉아 있으리니, 모든 거룩함을 만지지 말 것이며 성소에 들어가지도 말 것이며, 그녀의 정결의 날이 차기까지니라.'),
(3050, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 5, 'OT', '만일 그가 암컷을 낳으면 그녀는 자기 불결함과 같이 칠일 동안 부정할 것이며, 그녀는 정결의 피를 위하여 육십 육일을 앉아 있을 것이다.'),
(3051, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 6, 'OT', '그녀의 정결 기한이 아들을 위하여나 딸을 위하여 차면, 그녀는 일 년 된 어린양을 번제로, 비둘기 새끼나 산비둘기를 죄 제사로 가져올지니, 정한 때의 천막 문, 곧 제사장에게로 가져갈지니라.'),
(3052, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 7, 'OT', '그것을 여호와의 얼굴 앞에 드리고 그 여인을 위하여 속죄할지니 그리하면 그녀가 자기 피의 샘에서 깨끗하게 되리라. 이것은 남자나 암컷을 낳은 여인의 율법이니라.'),
(3053, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 12, 8, 'OT', '만일 그녀의 손이 양 한 마리에 충분하지 못하면, 그녀는 비둘기 두 마리나 비둘기 아들 둘을 가져갈 것이니, 하나는 번제로, 하나는 죄를 위한 제물로 삼을 것이요, 제사장이 그녀를 위하여 속죄할 것이며 그녀는 정결할지니라.'),
(3054, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 1, 'OT', '여호와께서 모세와 아론에게 말씀하여 이르시되'),
(3055, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 2, 'OT', '사람의 살가죽에 존귀나 딱지나 밝은 반점이 생겨서 그 살가죽에 나병의 상처가 되면, 그를 제사장 아론에게나 그의 아들들 중 한 제사장에게로 데려갈 것이요'),
(3056, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 3, 'OT', '제사장이 살 가죽에 있는 상처를 볼 것이요, 상처에 있는 털이 흰색으로 변하였고, 상처의 모습이 그의 살 가죽보다 깊으면, 그것은 나병의 상처라, 제사장이 그를 보고 그를 부정하다고 할 것이니라.'),
(3057, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 4, 'OT', '만일 그 밝은 반점이 그의 살가죽에 희고, 그 모습이 가죽보다 우묵하지 아니하며, 그 털이 희게 변하지 아니하면, 제사장은 그 상처를 칠 일 동안 가두어 둘 것이니라.'),
(3058, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 5, 'OT', '제사장이 일곱째 날에 그를 살펴보고, 보라 그 상처가 그의 눈에 그대로 서 있고 그 상처가 가죽에 퍼지지 아니하였으면, 제사장이 그를 또 칠 일 동안 금고할지니라.'),
(3059, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 6, 'OT', '제사장이 일곱째 날에 다시 그를 볼 것이요, 보라 그 상처가 흐릿하고 그 상처가 가죽에 퍼지지 아니하였으면 제사장이 그를 정하다 할지니 이는 딱지라, 그가 자기 옷을 빨 것이요 정하리라.'),
(3060, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 7, 'OT', '만일 그 딱지가 가죽에 퍼지되, 그가 정결을 위하여 제사장에게 보인 후에 다시 퍼지면, 그는 두 번째로 제사장에게 보일지니라.'),
(3061, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 8, 'OT', '제사장이 보고, 보라, 딱지가 가죽에 퍼졌으면, 제사장은 그를 부정하다 할지니, 이는 나병이라.'),
(3062, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 9, 'OT', '사람에게 나병의 상처가 있으면 그를 제사장에게로 데려갈 것이니라'),
(3063, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 10, 'OT', '제사장이 볼지니, 보라 가죽에 흰 존귀가 있고 그것이 털을 희게 하였으며, 그 존귀에 생명 유지하는 살이 있으면'),
(3064, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 11, 'OT', '그의 살가죽에 오래된 나병이 있으면 그것은 만성적인 것이니, 제사장이 그를 부정하다 할지니라. 그가 이미 부정하므로 그를 가두지 말지니라.'),
(3065, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 12, 'OT', '만일 나병이 가죽에 퍼져 번지고, 나병이 상처의 모든 가죽을 머리부터 발까지 덮어서 제사장의 눈에 보이는 모든 모습에 이르렀으면'),
(3066, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 13, 'OT', '제사장이 보고 볼지어다 나병이 그의 모든 살을 덮었으면 그가 상처를 정하다 할지니 그것이 모두 희어졌으면 그는 정하니라'),
(3067, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 14, 'OT', '그러나 살아 있는 살이 그에게 나타나는 날에는 그는 부정할지니라'),
(3068, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 15, 'OT', '제사장이 그 산 살을 보고 그를 부정하다 할지니 그 산 살은 부정한 것이니 그것은 나병이니라'),
(3069, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 16, 'OT', '혹은 그 산 살이 다시 돌아서 희게 변하면 제사장에게로 갈 것이요'),
(3070, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 17, 'OT', '제사장이 그것을 보고, 보라, 그 상처가 흰색으로 변하였으면, 제사장은 그 상처를 정하다고 선언할지니, 그는 정하니라.'),
(3071, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 18, 'OT', '살 가죽에 종기가 생겨서 나았으면'),
(3072, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 19, 'OT', '그 종기가 있던 자리에 흰 융기가 나거나 희고 불그스름한 밝은 반점이 생기면 제사장에게 보일지니'),
(3073, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 20, 'OT', '제사장이 보고 그 모습이 가죽보다 얕고 그 털이 흰색으로 변하였으면 제사장은 그를 부정하다 할지니 이는 종기에서 퍼진 나병 상처니라'),
(3074, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 21, 'OT', '그러나 제사장이 그것을 보고, 보라, 그 안에 흰 털이 없고, 가죽보다 얕지 아니하며, 그것이 엷으면, 제사장은 그를 칠일 동안 금고할지니라.'),
(3075, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 22, 'OT', '만일 그것이 가죽에 크게 퍼지면 제사장은 그것을 부정하다 할지니 이는 상처니라'),
(3076, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 23, 'OT', '그러나 그 밝은 반점이 그 자리에 서서 퍼지지 아니하였으면 그것은 종기의 화상이니 제사장은 그를 정결하다 할지니라'),
(3077, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 24, 'OT', '혹은 살에 불로 인한 화상이 있어서 그 가죽에 화상의 생명 유지가 밝은 반점이 되되 희고 불그스름하거나 흰색이면'),
(3078, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 25, 'OT', '제사장이 그것을 볼 것이요, 보라 그 밝은 반점에서 털이 희게 변하였고 그 모습이 가죽보다 깊으면, 이는 화상에서 퍼진 나병이라, 제사장은 그를 부정하다 할지니, 이는 나병의 상처니라.'),
(3079, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 26, 'OT', '그러나 제사장이 그것을 보고 밝은 반점에 흰 털이 없고 가죽보다 낮지 아니하며 그것이 엷으면 제사장은 그를 칠 일 동안 가두어 둘 것이며'),
(3080, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 27, 'OT', '제사장이 일곱째 날에 그것을 볼지니 만일 그것이 가죽에 퍼지면 제사장은 그를 부정하다 할지니 그것은 나병의 상처니라'),
(3081, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 28, 'OT', '만일 그 밝은 반점이 그 자리에 서서 가죽에 퍼지지 아니하고 그것이 흐리면, 그것은 화상의 존귀라. 제사장은 그를 정하다 할지니, 이는 그것이 화상의 흔적임이라.'),
(3082, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 29, 'OT', '사람이나 여자에게 상처가 머리나 수염에 있으면'),
(3083, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 30, 'OT', '제사장이 그 상처를 볼 것이요, 보라 그 모습이 가죽보다 깊고 그 안에 누르고 가는 털이 있으면 제사장은 그를 부정하다 할지니 이는 옴이라, 머리나 수염에 발한 나병이니라'),
(3084, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 31, 'OT', '만일 제사장이 옴의 상처를 보고, 그 모습이 가죽보다 깊지 아니하고 그 상처에 검은 털이 없으면, 제사장은 그 옴의 상처를 칠 일 동안 가두어 둘 것이며'),
(3085, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 32, 'OT', '제사장이 일곱째 날에 그 상처를 볼 것이며, 보라, 그 옴이 퍼지지 아니하고 그 안에 누런 털이 없으며, 그 옴의 모습이 가죽보다 깊지 아니하거든'),
(3086, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 33, 'OT', '그가 밀려고 하되 그 옴은 밀지 말 것이며 제사장은 그 옴을 다시 칠일 동안 가두어 둘 것이며'),
(3087, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 34, 'OT', '제사장이 일곱째 날에 그 옴을 살피되, 보라 그 옴이 가죽에 퍼지지 아니하고 그 모습이 가죽보다 깊지 아니하면, 제사장은 그를 정하다고 선언할 것이요, 그는 자기 옷을 빨지니 정하리라.'),
(3088, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 35, 'OT', '만일 그 옴이 가죽에 퍼지되 그가 정결하게 된 후에 퍼지면'),
(3089, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 36, 'OT', '제사장이 그를 볼 것이요, 보라 옴이 가죽에 퍼졌으면 제사장은 누른 털을 찾지 말지니 그는 부정하니라.'),
(3090, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 37, 'OT', '그러나 그 눈에 옴이 그대로 있고 그 자리에 검은 털이 자랐으면 그 옴은 나은 것이니 그는 정결하니라 제사장은 그를 정결하다고 선언할지니라'),
(3091, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 38, 'OT', '사람이나 여자가 그들의 살 가죽에 밝은 반점, 곧 흰 밝은 반점이 있으면'),
(3092, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 39, 'OT', '제사장이 살펴볼 것이요, 보라 그들의 살 가죽에 있는 밝은 반점이 흐릿한 흰색이면, 그것은 가죽에 퍼진 백반점이라, 그는 정결하니라.'),
(3093, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 40, 'OT', '사람이 그의 머리가 밀려서 벗겨지면 그는 대머리니 그는 정결하니라'),
(3094, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 41, 'OT', '그의 얼굴 모퉁이에서 머리가 빠지면 그는 이마 대머리니 그는 정하니라'),
(3095, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 42, 'OT', '대머리나 이마 대머리에 희고 불그스름한 상처가 있으면, 그것은 그의 대머리나 그의 이마 대머리에 퍼지는 나병이라.'),
(3096, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 43, 'OT', '제사장이 그것을 볼 것이요, 보라 그 상처의 존귀가 그의 대머리나 그의 대머리 이마에 희고 불그스름하여 살 가죽에 있는 나병의 모습과 같으면'),
(3097, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 44, 'OT', '그 사람은 나병환자라 그가 부정하니 제사장이 그를 확실히 부정하다고 선언할 것은 그의 상처가 그의 머리에 있음이니라'),
(3098, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 45, 'OT', '나병 환자 곧 그 상처가 있는 자는 그의 옷이 찢어지고 그의 머리는 풀리며 수염을 가리되, 부정하다 부정하다고 외칠지니라.'),
(3099, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 46, 'OT', '그 상처가 있는 모든 날 동안 그는 부정하리니 그는 부정하다. 그는 홀로 거주하며 진영 밖에 그의 거주지가 있으리라.'),
(3100, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 47, 'OT', '옷에 나병의 상처가 있게 되면, 양털 옷이나 아마 옷에 있든지'),
(3101, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 48, 'OT', '혹은 날실에나 혹은 아라비아에나, 아마와 양털에나, 혹은 가죽에나, 혹은 모든 가죽 일에나'),
(3102, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 49, 'OT', '그 상처가 옷이나 가죽이나 날실이나 아라비아나 모든 가죽 그릇에 푸르거나 붉으면 이는 나병의 상처라 제사장에게 보일지니라'),
(3103, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 50, 'OT', '제사장이 그 상처를 보고 그 상처를 칠 일 동안 가두어 둘 것이며'),
(3104, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 51, 'OT', '그가 일곱째 날에 그 상처를 볼 것이요, 만일 그 상처가 옷에나 날실에나 아라비아에나 가죽에나, 가죽으로 만든 모든 일에 퍼졌으면, 그 상처는 악성 나병이라 그것이 부정하니라.'),
(3105, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 52, 'OT', '그 옷이나 날실이나 아라비아나 양털이나 아마나 가죽으로 만든 모든 그릇을 불사르되, 그 상처가 있는 것은 그것이 악성 나병이니 불로 태울지니라.'),
(3106, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 53, 'OT', '만일 제사장이 보고, 보라, 그 상처가 옷이나 날실이나 아라비아나 모든 가죽 그릇에 퍼지지 아니하였으면'),
(3107, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 54, 'OT', '제사장은 명령하여 그 상처가 있는 것을 빨게 하고, 다시 칠 일 동안 간직할지니라.'),
(3108, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 55, 'OT', '제사장은 그 상처를 빤 후에 살펴볼지니, 보라, 그 상처가 그 눈빛을 바꾸지 아니하고 그 상처가 퍼지지 아니하였으면 그것은 부정하니, 너는 그것을 불로 사를지니라. 그것은 그의 대머리나 그의 대머리에 있는 부식이라.'),
(3109, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 56, 'OT', '만일 제사장이 보고 그 상처가 그것을 빤 후에 흐릿하면, 그는 그것을 옷에서나 가죽에서나 날실에서나 아라비아에서 찢어낼지니라.'),
(3110, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 57, 'OT', '만일 그 옷이나 날실이나 아라비아나 모든 가죽 그릇에 다시 그 상처가 나타나면 그것은 퍼지는 것이니, 그 상처가 있는 것을 불로 태울지니라.'),
(3111, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 58, 'OT', '그 옷이나 날실이나 아라비아나 모든 가죽 그릇을 네가 빨았는데 그 상처가 그것들에서 떠나면 다시 빨아야 정하리라'),
(3112, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 13, 59, 'OT', '이것은 양털 옷이나 아마 옷, 날실이나 아라비아, 또는 모든 가죽 그릇에 있는 나병 상처의 율법이니, 그것을 정결케 하거나 부정하게 하기 위한 것이니라.'),
(3113, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3114, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 2, 'OT', '이것은 나병환자의 율법이니 그가 정결함을 받는 날에 그를 제사장에게로 데려갈 것이요'),
(3115, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 3, 'OT', '제사장은 진영 밖으로 나가서, 제사장이 보고 보라, 나병 환자의 나병 상처가 나았는지라'),
(3116, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 4, 'OT', '제사장은 명하여 그 정결함을 받을 자를 위하여 살아 있는 정결한 새 두 마리와 향백나무와 진홍색과 우슬초를 가져오게 할 것이며'),
(3117, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 5, 'OT', '제사장은 명령하여 그 새 하나를 살아 있는 물 위 질그릇에 잡게 할 것이며'),
(3118, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 6, 'OT', '산 새를 취하고 백향목과 진홍색 실과 우슬초를 가져다가 그들과 산 새를 흐르는 물 위에서 잡은 새의 피에 잠그되'),
(3119, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 7, 'OT', '그가 나병에서 정결함을 받을 자에게 일곱 번 뿌리고 그를 정결하다 하며 그 산 새를 들판 얼굴 위로 놓을지니라'),
(3120, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 8, 'OT', '정결함을 받는 자는 그의 옷을 빨고 그의 모든 털을 밀고 물로 씻을 것이라 그리하면 정결하리라 그 후에 그는 진영에 들어올 것이나 그의 천막 밖에 칠 일을 거할 것이니라'),
(3121, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 9, 'OT', '일곱째 날에 그는 모든 털을 밀되 그의 머리와 그의 수염과 그의 눈썹을 밀고, 그의 모든 털을 밀 것이며, 그의 옷을 빨고 그의 살을 물에 씻을 것이라, 그리하면 그가 정결하리라.'),
(3122, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 10, 'OT', '여덟째 날에는 흠 없는 어린 수양 둘과 일 년 된 흠 없는 어린 암양 하나와 기름에 섞은 고운 밀가루 십분의 일 삼 분의 소제물과 기름 한 로그를 취할 것이며'),
(3123, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 11, 'OT', '제사장은 정결하게 하는 자를 그 정결함을 받을 사람과 그 물건들을 여호와의 얼굴 앞, 정한 때의 천막 문에 세울지니라'),
(3124, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 12, 'OT', '제사장은 그 어린양 하나를 취하여 속건제로 드리되 그 기름 한 로그와 함께 여호와 앞에 흔들어 바침을 삼을지니라'),
(3125, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 13, 'OT', '그가 어린양을 거룩한 장소, 곧 죄제와 번제를 잡는 장소에서 잡을 것이며, 속건제는 죄제와 같이 제사장의 것이 되나니 그것은 지극히 거룩한 것이니라.'),
(3126, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 14, 'OT', '제사장은 속건제의 피를 취하여 그 제사장이 정결함을 받을 자의 오른쪽 귀 끝과 그의 오른손 엄지와 그의 오른발 엄지에 바를 것이며'),
(3127, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 15, 'OT', '제사장은 그 로그의 기름을 취하여 자기 왼손 손바닥에 부을 것이며'),
(3128, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 16, 'OT', '제사장은 그의 오른손 손가락을 그의 왼손 손바닥에 있는 기름에 찍고, 그의 손가락으로 그 기름을 여호와 앞에 일곱 번 뿌릴지니라.'),
(3129, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 17, 'OT', '그리고 그 손바닥에 있는 남은 기름은 제사장이 정결함을 받는 자의 오른쪽 귀 끝과 그의 오른손 엄지와 그의 오른발 엄지 위에, 곧 속건제의 피 위에 바를 것이며'),
(3130, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 18, 'OT', '그리고 제사장의 손바닥에 있는 남은 기름은 제사장이 정결함을 받는 자의 머리에 바르고, 제사장은 여호와 앞에서 그를 위하여 속죄할지니라.'),
(3131, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 19, 'OT', '제사장은 죄를 드리고, 그 더러움에서 정결함을 받으려는 자를 위하여 속죄하며, 그 후에 번제를 잡을 것이요'),
(3132, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 20, 'OT', '제사장은 그 번제와 제물을 제단에 올릴 것이며, 제사장이 그를 위하여 속죄하면 그가 정결하리라.'),
(3133, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 21, 'OT', '만일 그가 가난하여 그의 손이 미치지 못하면 그는 속건제를 위하여 어린양 하나를 취하여 흔들어 바침으로 자신을 위해 속죄할 것이요, 또 제물을 위하여 기름에 섞은 고운 밀가루 십분의 일과 기름 한 로그를 취할 것이며'),
(3134, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 22, 'OT', '그의 손이 닿는 대로 산비둘기 둘 또는 집비둘기 새끼 둘을 취하되, 하나는 죄 제물로, 다른 하나는 번제로 삼을지니라.'),
(3135, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 23, 'OT', '그가 정결하게 되는 여덟째 날에 그것들을 제사장에게, 곧 정한 때의 천막 문 앞, 여호와의 얼굴 앞으로 가져올 것이며'),
(3136, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 24, 'OT', '제사장은 속건제 어린양과 기름 한 로그를 취하여 제사장이 여호와의 얼굴 앞에 흔들어 바침으로 흔들어 바침을 삼을지니라'),
(3137, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 25, 'OT', '그가 속건제의 어린양을 잡을 것이요, 제사장은 그 속건제의 피를 취하여 정결함을 받을 자의 오른쪽 귀 끝과 그의 오른손 엄지와 그의 오른발 엄지에 바를 것이니라.'),
(3138, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 26, 'OT', '제사장은 그 기름을 자기 왼손 손바닥에 따를지니라'),
(3139, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 27, 'OT', '제사장은 그의 오른손 손가락으로 그의 왼손 손바닥에 있는 기름을 여호와 앞에 일곱 번 뿌릴지니라'),
(3140, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 28, 'OT', '제사장은 그 손바닥에 있는 기름을 정결함을 받을 자의 오른쪽 귀 끝과 오른쪽 손의 엄지와 오른쪽 발의 엄지에, 곧 속건제의 피를 바른 장소에 바를 것이며'),
(3141, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 29, 'OT', '그리고 남은 기름은 제사장의 손바닥에 있는 그것을 정결함을 받는 자의 머리에 줄 것이요, 여호와 앞에서 그를 위하여 속죄하기 위함이니라.'),
(3142, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 30, 'OT', '그는 그 비둘기들 중 하나나 비둘기 아들들 중에서 그의 손이 닿는 대로 드릴지니라'),
(3143, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 31, 'OT', '그의 손이 닿는 대로 하나는 죄 제물로, 다른 하나는 제물과 함께 번제로 드릴 것이며, 제사장은 정결함을 받을 자를 위하여 여호와 앞에서 속죄할지니라.'),
(3144, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 32, 'OT', '이것은 그에게 나병의 상처가 있는 자의 율법이니, 그의 손이 그의 정결에 미치지 못하는 자의 율법이니라.'),
(3145, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 33, 'OT', '여호와께서 모세와 아론에게 말씀하여 이르시되'),
(3146, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 34, 'OT', '너희가 내가 너희에게 소유로 주는 가나안 땅에 이를 때에, 내가 너희 소유의 땅에 있는 집에 나병의 상처를 내리리라.'),
(3147, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 35, 'OT', '그 집을 가진 자가 와서 제사장에게 말하여 이르기를 집에 상처가 내게 보인다 할 것이요'),
(3148, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 36, 'OT', '제사장이 명하여 그 집을 비우게 하리니 제사장이 그 상처를 보러 들어가기 전에 그리하여 집에 있는 모든 것이 부정하게 되지 아니하게 한 후에 제사장이 들어가서 그 집을 볼지니라'),
(3149, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 37, 'OT', '그가 그 상처를 볼 때에, 보라, 그 상처가 집 벽에 있되 움푹한 곳이 푸르스름하거나 붉으스름하며, 그 모습이 벽보다 낮으면'),
(3150, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 38, 'OT', '제사장은 그 집에서 나와 집 문에 이르러 그 집을 칠 일 동안 폐쇄할지니라'),
(3151, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 39, 'OT', '제사장은 일곱째 날에 돌아와서 볼 것이요, 보라, 그 상처가 집의 벽에 퍼졌으면'),
(3152, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 40, 'OT', '제사장은 명령하여 그 상처가 있는 돌들을 빼내어 성 밖 부정한 장소에 버리게 할지니라'),
(3153, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 41, 'OT', '그 집을 안에서 주위에 긁게 하고, 그 긁은 흙을 성 밖 부정한 장소에 쏟아버릴지니라.'),
(3154, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 42, 'OT', '그들은 다른 돌들을 가져다가 그 돌들 대신에 두고, 다른 흙을 가져다가 그 집에 바를지니라.'),
(3155, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 43, 'OT', '그러나 그 상처가 다시 나서 집에 퍼지되, 그가 돌을 빼낸 후와 집을 긁은 후와 다시 바른 후에'),
(3156, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 44, 'OT', '제사장이 와서 살펴보고, 보라, 그 상처가 집에 퍼졌으면, 그것은 집에 있는 악성 나병이라, 그것은 부정하니라.'),
(3157, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 45, 'OT', '그가 그 집을 헐고 그 돌들과 그 나무들과 그 집의 모든 흙을 성 밖 부정한 장소로 내어갈 것이며'),
(3158, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 46, 'OT', '그 집에 들어가는 자는 그가 그것을 봉쇄한 모든 날 동안 저녁까지 부정할지니라'),
(3159, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 47, 'OT', '집에서 자는 자는 자기 옷을 빨 것이요, 집에서 먹는 자도 자기 옷을 빨 것이니라.'),
(3160, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 48, 'OT', '만일 제사장이 들어와서 살펴보니 집을 고쳐 바른 후에 그 상처가 집에 퍼지지 아니하였으면, 제사장은 그 집을 정하다 할지니 이는 그 상처가 나았음이라.'),
(3161, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 49, 'OT', '그가 그 집을 정결케 하기 위하여 새 두 마리와 향백나무와 진홍색과 우슬초를 취할 것이며'),
(3162, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 50, 'OT', '그가 그 새 하나를 질그릇 안에서 흐르는 물 위에 잡을지니라'),
(3163, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 51, 'OT', '그가 향백나무와 우슬초와 진홍색 실과 살아 있는 새를 가져다가 그들을 잡은 새의 피와 흐르는 물에 적셔서 그 집에 일곱 번 뿌릴 것이며'),
(3164, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 52, 'OT', '그가 새의 피와 흐르는 물과 산 새와 향백나무와 우슬초와 진홍색 실로 그 집을 정결케 할 것이며'),
(3165, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 53, 'OT', '그 살아 있는 새를 성 밖 들판 앞으로 보내고, 그 집을 위하여 속죄할지니 그리하면 정결하리라.'),
(3166, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 54, 'OT', '이것은 모든 나병 상처와 옴에 대한 율법이니라'),
(3167, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 55, 'OT', '옷의 나병과 집의 나병에 대하여'),
(3168, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 56, 'OT', '존귀와 딱지와 밝은 반점에 대하여'),
(3169, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 14, 57, 'OT', '더러운 날과 정한 날을 가르치기 위한 것이니, 이것이 나병의 율법이니라.'),
(3170, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 1, 'OT', '여호와께서 모세와 아론에게 말씀하여 이르시되'),
(3171, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 2, 'OT', '이스라엘 자손에게 말하고 그들에게 이르라, 어떤 사람이든지 그의 살에서 유출이 있으면 그의 유출로 인하여 그가 부정하니라.'),
(3172, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 3, 'OT', '그의 유출로 말미암은 그의 더러움은 이러하니, 그의 살이 그의 유출로 흐르든지, 그의 살이 그의 유출로 말미암아 멎든지, 그것이 그의 더러움이니라.'),
(3173, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 4, 'OT', '모든 침상 곧 유출병 있는 자가 그 위에 누울 것은 부정하고, 모든 그릇 곧 그가 그 위에 앉을 것도 부정하니라.'),
(3174, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 5, 'OT', '그 사람의 침상을 만지는 자는 그의 옷을 빨고 물로 씻을 것이며 저녁까지 부정하리라'),
(3175, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 6, 'OT', '그릇 위에 앉는 자, 곧 유출병 있는 자가 앉았던 그릇 위에 앉는 자는 그의 옷을 빨고 물로 씻을 것이며 저녁까지 부정하리라'),
(3176, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 7, 'OT', '그 유출병 있는 자의 살에 접촉하는 자는 그의 옷을 빨고 물로 씻을 것이며 저녁까지 부정하리라'),
(3177, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 8, 'OT', '유출병 있는 자가 정한 자에게 침을 뱉으면 그는 옷을 빨고 물로 씻을 것이며 저녁까지 부정하리라'),
(3178, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 9, 'OT', '모든 병거는 유출병 있는 자가 그 위에 탈 것이라면 부정하리라'),
(3179, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 10, 'OT', '그 아래에 있는 모든 것을 만지는 자는 모두 저녁까지 부정할 것이며, 그것들을 옮기는 자는 옷을 빨고 물로 씻을 것이며 저녁까지 부정하리라'),
(3180, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 11, 'OT', '모든 유출병 있는 자가 그를 만지는 자는, 그의 손을 물로 씻지 아니하였으면, 그는 옷을 빨고 물로 몸을 씻을 것이며, 저녁까지 부정하리라.'),
(3181, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 12, 'OT', '질그릇은 유출병 있는 자가 그것에 닿으면 깨뜨릴 것이요, 모든 나무 그릇은 물로 씻을지니라'),
(3182, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 13, 'OT', '유출병 있는 자가 그의 유출에서 깨끗해지면, 그는 자신을 위하여 정결하게 되는 칠 일을 계산할 것이요, 그의 옷을 빨 것이며, 그의 살을 흐르는 물에 씻을 것이라, 그리하면 그가 정결하리라.'),
(3183, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 14, 'OT', '여덟째 날에 그는 자기를 위하여 산비둘기 둘 또는 집비둘기 새끼 둘을 취하고, 여호와의 얼굴 앞, 곧 정한 때의 천막 문으로 와서 그것들을 제사장에게 줄 것이며'),
(3184, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 15, 'OT', '제사장은 그 하나는 죄로, 하나는 번제로 드릴 것이며, 제사장은 그의 유출로 말미암아 여호와의 얼굴 앞에서 그를 위하여 속죄할지니라.'),
(3185, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 16, 'OT', '사람이 만일 그에게서 동침의 씨가 나가면, 그는 물로 모든 살을 씻을 것이며 저녁까지 부정하리라.'),
(3186, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 17, 'OT', '모든 옷과 모든 가죽, 그 위에 동침의 씨가 있을 것은 물에 빨 것이며 저녁까지 부정하리라'),
(3187, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 18, 'OT', '여자와 사람이 씨의 동침으로 그녀와 함께 누웠으면, 그들은 물로 몸을 씻을 것이며 저녁까지 부정하리라.'),
(3188, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 19, 'OT', '여자가 유출을 하되 그 유출이 살에 피면 그녀는 칠 일 동안 불결함에 있게 되고 그녀를 만지는 모든 자는 저녁까지 부정하리라'),
(3189, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 20, 'OT', '그녀가 불결함 중에 누웠던 모든 것은 부정할 것이요, 그녀가 앉았던 모든 것도 부정할 것이니라.'),
(3190, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 21, 'OT', '그리고 그녀의 침상을 만지는 모든 자는 그의 옷을 빨고 물로 씻을 것이며 저녁까지 부정할 것이다.'),
(3191, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 22, 'OT', '모든 그가 앉았던 모든 그릇을 만지는 자는 그의 옷을 빨고 물에 씻을 것이며 저녁까지 부정하리라'),
(3192, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 23, 'OT', '만일 그가 침상 위에 있거나 그가 앉아 있는 그릇 위에 있을 때, 그것을 만지는 자는 저녁까지 부정하리라.'),
(3193, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 24, 'OT', '만일 어떤 사람이 그 여자와 동침하여 그 불결함이 그에게 있으면 그는 칠 일 동안 부정할 것이요, 그가 눕는 모든 침상도 부정하리라'),
(3194, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 25, 'OT', '여자가 그 불결함의 때가 아닌데도 여러 날 피의 유출이 있거나, 그 유출이 그 불결함 위에 있으면, 그 더러운 유출의 모든 날 동안은 그 불결함의 날들과 같이 그녀는 부정할지니라.'),
(3195, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 26, 'OT', '그녀가 유출이 있는 모든 날 동안에 눕는 모든 침상은 그녀에게 그녀의 불결함의 침상과 같을 것이며, 그녀가 앉는 모든 그릇도 그녀의 불결함의 더러움과 같이 부정할 것이다.'),
(3196, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 27, 'OT', '모든 그들을 만지는 자는 부정할 것이며, 그의 옷을 빨고 물로 씻을 것이며, 저녁까지 부정할 것이니라.'),
(3197, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 28, 'OT', '그러나 그녀가 자신의 유출에서 깨끗해지면, 그녀는 자신을 위하여 이레 날을 세고, 그 후에 그녀는 깨끗해질 것이다.'),
(3198, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 29, 'OT', '여덟째 날에 그녀가 자기를 위하여 비둘기 두 마리나 비둘기 아들 둘을 취하여 제사장에게, 곧 정한 때의 천막 문으로 그것들을 가져올지니라'),
(3199, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 30, 'OT', '제사장은 그 하나를 죄제로, 그 하나를 번제로 드릴 것이며, 제사장이 그 여호와의 얼굴 앞에서 그녀의 더러움의 유출로 말미암아 그녀를 위해 속죄할지니라.'),
(3200, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 31, 'OT', '너희는 이스라엘 자손을 그들의 더러움에서 떠나게 하라 그들이 그들의 더러움 가운데서 죽지 않도록, 그들 가운데 있는 내 장막을 더럽힐 때에 죽지 않도록 하라.'),
(3201, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 32, 'OT', '이것은 유출병이 있는 자의 율법이요, 그에게서 동침의 씨가 나와 그것으로 부정하게 되는 자의 율법이니라.'),
(3202, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 15, 33, 'OT', '여인의 불결함과 유출이 있는 남자와 암컷, 그리고 불결한 여인과 동침한 사람에게 관한 것이니라'),
(3203, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 1, 'OT', '여호와께서 모세에게 말씀하시되, 아론의 두 아들이 여호와 앞에 나아가다가 죽은 후에 이르시기를'),
(3204, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 2, 'OT', '여호와께서 모세에게 말씀하여 이르시되, 네 형 아론에게 말하라, 그가 모든 때에 휘장 안에서 궤 위에 있는 속죄소 앞의 거룩함에 들어오지 말지니, 그가 죽지 않도록 하라, 이는 내가 구름 가운데서 속죄소 위에 나타날 것임이니라.'),
(3205, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 3, 'OT', '이것으로 아론이 거룩함에 들어올지니, 수송아지 아들 소로 죄를 위하여, 그리고 숫양으로 번제를 위하여.'),
(3206, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 4, 'OT', '거룩한 베 속옷을 입고, 베 속바지가 그의 살 위에 있게 하며, 베 띠로 띠고, 베 터번으로 쓰되, 이것들은 거룩한 옷이라, 그가 물로 자기 살을 씻고 그것들을 입을지니라.'),
(3207, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 5, 'OT', '이스라엘 자손의 회중에게서 죄를 위한 염소 두 마리와 번제를 위한 숫양 하나를 취할지니라'),
(3208, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 6, 'OT', '아론은 자기 죄를 위한 수송아지를 드리되 자기와 자기 집을 위하여 속죄할지니라'),
(3209, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 7, 'OT', '그가 두 염소를 취하여 회막 문 여호와 앞에 세울지니라'),
(3210, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 8, 'OT', '아론이 두 염소 위에 제비를 던지되, 한 제비는 여호와를 위하고 한 제비는 아사셀을 위할지니라.'),
(3211, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 9, 'OT', '아론은 여호와를 위하여 제비가 올린 염소를 끌어다가 그것을 죄로 드릴지니라'),
(3212, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 10, 'OT', '그 제비가 아사셀에게 오른 염소는 여호와 앞에 산 채로 서서 그것을 위하여 속죄하고 아사셀에게 광야로 보낼지니라'),
(3213, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 11, 'OT', '아론은 자기를 위한 죄의 수송아지를 드리되 자기와 자기 집을 위하여 속죄하고 자기를 위한 그 죄의 수송아지를 잡을지니라'),
(3214, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 12, 'OT', '그가 불집게에 가득한 숯불을 여호와 앞 제단 위에서 가져가고, 그의 두 주먹에 가득한 곱게 간 향료 향을 가져다가 휘장 안으로 들어갈지니라.'),
(3215, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 13, 'OT', '그가 여호와 앞에서 불 위에 향을 두고, 향의 구름이 증언 위에 있는 속죄소를 덮게 할지니, 그가 죽지 아니하리라.'),
(3216, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 14, 'OT', '그가 수송아지의 피를 취하여 그의 손가락으로 속죄소의 얼굴 동쪽에 뿌리고 속죄소의 얼굴 앞에서 그의 손가락으로 그 피를 일곱 때 뿌릴 것이며'),
(3217, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 15, 'OT', '그가 백성을 위한 속죄제 염소를 잡아 그 피를 휘장 안으로 가져가서, 그 피를 수송아지의 피에 행한 것 같이 행하여 그것을 속죄소 위와 속죄소 앞에 뿌릴지니라.'),
(3218, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 16, 'OT', '그가 이스라엘 자손의 더러움과 그들의 모든 죄에 대한 반역으로 거룩함을 위해 속죄할 것이며, 그들의 더러움 가운데 그들과 함께 머무는 정한 때의 천막을 위해서도 그와 같이 행할 것이다.'),
(3219, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 17, 'OT', '모든 사람은 그가 거룩함에서 속죄하기 위해 들어갈 때부터 나올 때까지 정한 때의 천막에 있지 못할 것이며, 그가 자신과 그의 집과 모든 이스라엘 회중을 위하여 속죄할지니라.'),
(3220, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 18, 'OT', '그가 여호와 앞에 있는 제단으로 나아가서 그것을 위하여 속죄하고, 수송아지의 피와 염소의 피를 취하여 제단의 뿔들 주위에 바를지니라'),
(3221, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 19, 'OT', '그가 손가락으로 그 피를 그 위에 일곱 번 뿌리고, 이스라엘 자손의 더러움에서 그것을 정결하게 하며 거룩하게 할지니라.'),
(3222, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 20, 'OT', '그가 거룩함과 정한 때의 천막과 제단을 위하여 속죄하기를 마치고 나서, 그 산 염소를 드릴지니라.'),
(3223, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 21, 'OT', '아론은 두 손을 살아 있는 염소의 머리에 얹고 그 위에 이스라엘 자손의 모든 죄악과 그들의 모든 반역을 그들의 모든 죄에 대해 자복하며 그것들을 염소의 머리에 두고 정한 때의 사람의 손으로 광야로 보낼지니라'),
(3224, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 22, 'OT', '염소가 그 위에 그들의 모든 죄악을 지고 무인지경의 땅으로 갈 것이며, 그가 그 염소를 광야에 놓을지니라.'),
(3225, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 23, 'OT', '아론이 정한 때의 천막에 들어가서 거룩함에 들어갈 때에 입었던 베 옷을 벗어 거기 두고'),
(3226, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 24, 'OT', '거룩한 곳에서 물로 자기 살을 씻고 자기 옷을 입고 나와서 자기 번제와 백성의 번제를 드려 자기와 백성을 위하여 속죄할지니라'),
(3227, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 25, 'OT', '그리고 죄의 기름을 제단에서 불사를지니라'),
(3228, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 26, 'OT', '아사셀에게 염소를 보내는 자는 그의 옷을 빨고 물로 그의 살을 씻을 것이며, 그 후에 진영으로 들어올 것이다.'),
(3229, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 27, 'OT', '죄 제물인 수송아지와 죄 제물인 염소, 그 피를 거룩한 곳에서 속죄하기 위해 가져온 것을 진영 밖으로 내어가서 그 가죽과 그 살과 그 똥을 불로 태울지니라.'),
(3230, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 28, 'OT', '그들을 불사르는 자는 자기 옷을 빨고 물로 자기 살을 씻은 후에 진영에 들어올지니라.'),
(3231, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 29, 'OT', '너희에게 영원한 규례가 될지니라 일곱째 달 그 달 십일에 너희는 너희 영혼을 괴롭게 하고 모든 일을 하지 말지니 본토인이든지 너희 중에 거하는 나그네든지 그리할지니라'),
(3232, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 30, 'OT', '이 날에 그가 너희를 위하여 속죄하여 너희를 정결하게 하리니 너희 모든 죄에서 여호와 앞에서 너희가 정결하리라'),
(3233, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 31, 'OT', '너희에게 안식일의 안식이 되리니 너희는 너희 영혼을 괴롭게 할지니라 이는 영원한 규례니라'),
(3234, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 32, 'OT', '제사장이 그를 기름 부으며 그의 아버지를 대신하여 제사장의 직분을 행하도록 그의 손을 위임할 자는 속죄하며 베 옷 곧 거룩한 옷을 입을지니라'),
(3235, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 33, 'OT', '그가 거룩한 성소를 위하여 속죄하며, 정한 때의 천막과 제단을 위하여 속죄하고, 제사장들과 회중의 모든 백성을 위하여 속죄할지니라.'),
(3236, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 16, 34, 'OT', '이것이 너희에게 영원한 규례가 되어 이스라엘 자손의 모든 죄를 위하여 일 년에 한 번 속죄할 것이니라. 그가 여호와께서 모세에게 명령하신 대로 행하였더라.'),
(3237, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3238, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 2, 'OT', '아론에게 말하고 그의 아들들과 이스라엘의 모든 아들들에게 말하며 그들에게 이르기를, 이것이 여호와께서 명령하신 말씀이라 하라.'),
(3239, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 3, 'OT', '이스라엘 집의 어떤 사람이든지 소나 어린 양이나 염소를 진영 안에서 잡거나 진영 밖에서 잡거나'),
(3240, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 4, 'OT', '그리고 정한 때의 천막 문으로 그것을 가져오지 아니하고 여호와 앞, 여호와의 장막 얼굴 앞에서 여호와께 제물로 드리지 아니한 사람은, 그 사람에게 피로 여겨지리니 그가 피를 흘렸음이라, 그 사람은 자기 백성 속에서 끊어지리라.'),
(3241, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 5, 'OT', '이스라엘 자손이 그들의 제사를, 곧 그들이 들판 얼굴 위에서 잡는 제사를 여호와께로, 정한 때의 천막 문으로, 제사장에게로 가져오게 하려 함이며, 그들이 그것들을 여호와께 화목제 제사로 드릴지니라.'),
(3242, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 6, 'OT', '제사장은 그 피를 여호와의 제단에 뿌리되 정한 때의 천막 문에서 하고, 그 기름을 여호와께 향기로운 향기로 불살를지니라.'),
(3243, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 7, 'OT', '그들이 다시는 그들의 제사를 그들이 음란히 따르던 염소들에게 드리지 말 것이며, 이것이 그들에게 대대로 영원한 규례가 될지니라.'),
(3244, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 8, 'OT', '너는 그들에게 말하라, 이스라엘 집 사람이나 그들 중에 거주하는 나그네 중에서 어떤 사람이든 번제나 제사를 드리려고 올리면'),
(3245, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 9, 'OT', '그것을 회막 문으로 가져다가 여호와께 드리지 아니하면 그 사람은 그의 백성 중에서 끊쳐지리라.'),
(3246, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 10, 'OT', '이스라엘 집 사람이나 그들 중에 거하는 나그네 중에 어떤 사람이든지 모든 피를 먹으면, 내가 그 피를 먹는 영혼에게 내 얼굴을 돌리고 그를 그 백성의 속에서 끊으리라.'),
(3247, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 11, 'OT', '육체의 영혼이 피에 있나니 내가 그것을 너희에게 주어 제단 위에서 너희 영혼을 위해 속죄하게 하였나니 피가 영혼 안에서 속죄함이니라'),
(3248, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 12, 'OT', '그러므로 내가 이스라엘의 아들들에게 말하기를 너희 중의 모든 영혼은 피를 먹지 말 것이며, 너희 중간에 거하는 나그네도 피를 먹지 말 것이라 하였노라'),
(3249, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 13, 'OT', '이스라엘 자손 중의 어떤 사람이나 그들 중에 거하는 나그네가 먹을 수 있는 살아있는 짐승이나 새를 사냥하여 잡거든 그 피를 흘리고 흙으로 덮을지니라'),
(3250, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 14, 'OT', '모든 살의 영혼은 그 피가 그 영혼 안에 있느니라 그러므로 내가 이스라엘 자손에게 말하기를 모든 살의 피는 먹지 말라 하였나니 모든 살의 영혼은 그 피니라 그것을 먹는 모든 자는 끊쳐지리라'),
(3251, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 15, 'OT', '모든 영혼이 본토인이나 나그네 중에서 시체나 웃긴 것을 먹으면 그 옷을 빨고 물로 씻을 것이며 저녁까지 부정하고 정할지니라'),
(3252, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 17, 16, 'OT', '만일 그가 빨지 아니하고 그의 살을 씻지 아니하면 그는 자기 죄악을 담당하리라'),
(3253, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3254, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 2, 'OT', '이스라엘 자손에게 말하여 그들에게 이르라 나는 여호와 너희 하나님이라'),
(3255, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 3, 'OT', '너희가 거주하던 애굽 땅의 행위를 따라 행하지 말며, 내가 너희를 그리로 인도하는 가나안 땅의 행위도 따라 행하지 말고, 그들의 규례를 따라 걷지 말지니라.'),
(3256, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 4, 'OT', '너희는 나의 판결을 행하며 나의 규례를 지켜 그 가운데서 행하라 나는 너희의 하나님 여호와니라'),
(3257, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 5, 'OT', '너희는 나의 규례와 판결을 지킬지니, 사람이 그것을 행하면 그것으로 살리라. 나는 여호와니라.'),
(3258, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 6, 'OT', '너희 각 사람은 자기 육체의 살과 가까운 모든 친족에게 가까이하여 벌거벗음을 드러내지 말라 나는 여호와니라'),
(3259, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 7, 'OT', '네 아버지의 벌거벗음과 네 어머니의 벌거벗음은 네가 드러내지 말지니라 그녀는 네 어머니이니 너는 그녀의 벌거벗음을 드러내지 말지니라'),
(3260, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 8, 'OT', '네 아버지의 아내의 벌거벗음을 드러내지 말라 그것은 네 아버지의 벌거벗음이니라'),
(3261, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 9, 'OT', '네 자매의 벌거벗음, 곧 네 아버지의 딸이나 네 어머니의 딸, 집에서 난 친족이나 밖에서 난 친족의 벌거벗음을 너는 드러내지 말지니라.'),
(3262, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 10, 'OT', '네 아들의 딸이나 네 딸의 딸의 벌거벗음을 네가 드러내지 말지니, 그들의 벌거벗음은 곧 네 벌거벗음이기 때문이라.'),
(3263, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 11, 'OT', '네 아버지의 아내의 딸, 곧 네 아버지의 친족인 그녀는 네 자매이니, 너는 그녀의 벌거벗음을 드러내지 말지니라.'),
(3264, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 12, 'OT', '네 아버지의 자매의 벌거벗음을 드러내지 말라; 그녀는 네 아버지의 살이니라.'),
(3265, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 13, 'OT', '네 어머니의 자매의 벌거벗음을 드러내지 말라, 그녀는 네 어머니의 살이니라.'),
(3266, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 14, 'OT', '네 아버지의 형제의 벌거벗음은 드러내지 말며 그의 여자에게 가까이하지 말라 그녀는 네 고모니라'),
(3267, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 15, 'OT', '네 며느리의 벌거벗음을 드러내지 말라, 그녀는 네 아들의 여자이니, 그녀의 벌거벗음을 드러내지 말지니라.'),
(3268, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 16, 'OT', '네 형제의 아내의 벌거벗음을 드러내지 말라 그것은 네 형제의 벌거벗음이니라'),
(3269, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 17, 'OT', '여자의 벌거벗음과 그 딸의 벌거벗음을 드러내지 말며, 그 아들의 딸과 그 딸의 딸을 취하여 그 벌거벗음을 드러내지 말라 그들은 친척 여자들이니 이는 음란한 행위라'),
(3270, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 18, 'OT', '여자는 그 자매를 취하지 말지니, 그 자매가 살아있는 동안에 그 위에 그 벌거벗음을 드러내어 괴롭게 하지 말지니라.'),
(3271, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 19, 'OT', '또한 여자가 그 불결함의 더러움 중에 있을 때에는 그에게 가까이하여 그 벌거벗음을 드러내지 말지니라'),
(3272, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 20, 'OT', '네 동료의 여자에게는 네 잠자리를 씨로 주어 그로 말미암아 더럽히지 말지니라'),
(3273, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 21, 'OT', '네 씨 중에서 몰렉에게 건네주어 통과시키지 말며, 네 하나님의 이름을 욕되게 하지 말라 나는 여호와니라.'),
(3274, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 22, 'OT', '네가 여자와의 침상에 눕듯이 남자와 눕지 말라 그것은 가증한 것이니라'),
(3275, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 23, 'OT', '모든 짐승에게 네 잠자리를 주어 더럽히지 말며, 여자는 짐승 앞에 서서 그것과 교접하지 말라, 그것은 혼란이라.'),
(3276, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 24, 'OT', '이 모든 것으로 너희는 스스로 더럽히지 말라 이는 내가 너희 얼굴 앞에서 쫓아내는 이방인들이 이 모든 것으로 더러워졌음이라'),
(3277, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 25, 'OT', '그 땅이 더러워졌고 내가 그 죄악을 그 위에 벌하였으며 그 땅이 그 거주민들을 토해 내었느니라'),
(3278, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 26, 'OT', '너희는 나의 규례와 나의 판결을 지키고 이 모든 가증한 것 중에 하나도 행하지 말지니 본토인과 너희 중간에 거하는 나그네도 그러하니라'),
(3279, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 27, 'OT', '이는 그 땅의 사람들이 너희 앞에서 이 모든 가증한 것들을 행하였고 그 땅이 더러워졌음이라'),
(3280, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 28, 'OT', '땅이 너희가 그것을 더럽힘으로 너희를 토하여 내지 않게 하라, 그것이 너희 얼굴 앞에 있던 이방인을 토하여 낸 것 같이.'),
(3281, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 29, 'OT', '무릇 이 모든 가증한 일 중에서 하나라도 행하는 자는 그 영혼들이 그 백성 중에서 끊어지리라'),
(3282, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 18, 30, 'OT', '너희는 나의 파수를 지켜 너희 얼굴 앞에서 행해진 가증한 것들의 규례를 행하지 말며 그것들로 스스로 더럽히지 말지니라 나는 너희 하나님 여호와니라'),
(3283, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3284, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 2, 'OT', '모든 이스라엘 자손의 회중에게 말하여 그들에게 이르라 너희는 거룩할지니 이는 나 여호와 너희 하나님이 거룩함이니라'),
(3285, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 3, 'OT', '너희 각 사람은 자기 어머니와 아버지를 경외하고 나의 안식일들을 지키라. 나는 너희 하나님 여호와니라.'),
(3286, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 4, 'OT', '너희는 우상에게로 돌이키지 말며 너희를 위하여 덮개로 만든 신상들을 만들지 말라 나는 너희 하나님 여호와니라'),
(3287, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 5, 'OT', '너희가 화목제 제사를 여호와께 드릴 때에 너희 기쁨을 위하여 그것을 드릴지니라'),
(3288, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 6, 'OT', '너희 제사를 드리는 날에 먹을 것이요 이튿날에도 먹을 것이며, 셋째 날까지 남은 것은 불에 사를지니라.'),
(3289, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 7, 'OT', '만일 셋째 날에 그것이 조금이라도 먹히면, 그것은 가증한 것이니, 그것은 열납되지 아니하리라.'),
(3290, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 8, 'OT', '그것을 먹는 자는 그의 죄악을 담당하리니 이는 그가 여호와의 거룩함을 더럽혔음이라 그 영혼은 그 백성 중에서 끊어지리라'),
(3291, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 9, 'OT', '너희 땅의 추수를 거둘 때에 너는 네 들판의 모퉁이를 다 거두지 말고, 네 추수의 이삭줍기도 줍지 말지니라.'),
(3292, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 10, 'OT', '네 포도원을 다듬지 말며 네 포도원에 떨어진 포도도 줍지 말고 가난한 사람과 나그네를 위하여 그것들을 버려 두라 나는 너희 하나님 여호와니라'),
(3293, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 11, 'OT', '너희는 도적질하지 말며 속이지 말며 각각 동료에게 거짓말하지 말지니라'),
(3294, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 12, 'OT', '너희는 내 이름으로 거짓 맹세하지 말라. 네가 네 하나님의 이름을 욕되게 하였느니라. 나는 여호와니라.'),
(3295, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 13, 'OT', '네 친구를 압제하지 말며 도둑질하지 말지니라 품꾼의 보수를 아침까지 네게 머물게 하지 말지니라'),
(3296, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 14, 'OT', '귀먹은 자를 저주하지 말며 소경의 얼굴 앞에 걸림돌을 놓지 말고 네 하나님을 경외하라 나는 여호와니라'),
(3297, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 15, 'OT', '너희는 판결에 불의를 행하지 말며 가난한 자의 얼굴을 받들지 말고 큰 자의 얼굴을 존중하지 말며 공의로 네 동료를 재판할지니라'),
(3298, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 16, 'OT', '네 백성 가운데 중상하는 자로 다니지 말며 네 친구의 피를 대적하여 서지 말라 나는 여호와니라'),
(3299, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 17, 'OT', '네 형제를 네 마음으로 미워하지 말고, 네 동료를 반드시 책망하라, 그리하여 그 위에 죄를 지지 말라.'),
(3300, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 18, 'OT', '너는 갚지 말며 네 백성의 아들들을 미워하지 말고 네 친구를 네 자신 같이 사랑하라. 나는 여호와니라.'),
(3301, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 19, 'OT', '너희는 내 규례를 지킬지어다. 네 짐승을 두 가지 섞음으로 교합시키지 말며, 네 들판에 두 가지 섞음으로 뿌리지 말며, 두 가지 섞음으로 된 혼합직물 옷이 네게 입혀지지 말지어다.'),
(3302, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 20, 'OT', '사람이 여자와 씨의 동침으로 동침하되 그 여자가 사람에게 정혼한 여종이며 아직 속량되지도 못하고 자유도 주어지지 아니하였으면 그 여자는 매맞음을 당할 것이요 그들은 죽임을 당하지 아니하리니 이는 그 여자가 자유롭지 못하였음이라'),
(3303, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 21, 'OT', '그가 그의 속건제를 여호와께, 정한 때의 천막 문으로 가져올 것이니, 곧 속건제 숫양이라.'),
(3304, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 22, 'OT', '제사장이 그의 범한 죄에 대하여 여호와 앞에서 속건제의 숫양으로 그를 위하여 속죄할 것이요, 그가 범한 죄에서 사함을 받으리라.'),
(3305, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 23, 'OT', '너희가 그 땅에 들어가 모든 음식 나무를 심을 때에는 그 열매의 포경을 포경하되, 삼 년 동안 그것이 너희에게 포경이 될지니 먹지 말지니라.'),
(3306, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 24, 'OT', '넷째 해에는 그 모든 열매가 여호와께 드리는 거룩한 축제의 찬양이 될 것이며'),
(3307, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 25, 'OT', '다섯째 해에는 너희가 그 열매를 먹을지니, 그것이 너희에게 그 수확을 더하게 하려 함이라. 나는 너희 하나님 여호와니라.'),
(3308, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 26, 'OT', '너희는 피와 함께 먹지 말며 점치지 말며 술수를 행하지 말지니라'),
(3309, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 27, 'OT', '너희 머리 모퉁이를 둥글게 깎지 말며 네 수염 모퉁이를 손상시키지 말지니라'),
(3310, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 28, 'OT', '너희는 죽은 자를 위하여 너희 살에 새김을 내지 말며 너희 몸에 새김의 무늬를 새기지 말라 나는 여호와니라'),
(3311, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 29, 'OT', '네 딸을 더럽혀 음행하게 하지 말라, 그리하여 땅이 음행하지 않게 하라, 땅이 음란한 행위로 가득 차지 않게 하라.'),
(3312, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 30, 'OT', '내 안식일을 지키고 내 성소를 공경하라. 나는 여호와니라.'),
(3313, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 31, 'OT', '신접한 자와 무당에게로 향하지 말며 그들을 따라 스스로 더럽히지 말라 나는 너희 하나님 여호와니라'),
(3314, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 32, 'OT', '백발 앞에서 일어서고 노인의 얼굴을 공경하며 네 하나님을 경외하라 나는 여호와니라'),
(3315, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 33, 'OT', '너희 땅에 나그네가 너와 함께 거주하거든 너희는 그를 학대하지 말지니라'),
(3316, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 34, 'OT', '너희와 함께 있는 나그네는 너희 중에서 본토인 같이 되리니 너는 그를 너 자신 같이 사랑하라 너희도 애굽 땅에서 나그네였었느니라 나는 너희 하나님 여호와니라'),
(3317, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 35, 'OT', '너희는 판결에 불의를 행하지 말며, 옷과 무게와 척도에 있어서도 불의를 행하지 말지니라.'),
(3318, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 36, 'OT', '공의로운 저울과 공의로운 돌과 공의로운 에바와 공의로운 힌이 너희에게 있을지니라. 나는 너희를 애굽 땅에서 인도해 낸 너희 하나님 여호와니라.'),
(3319, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 19, 37, 'OT', '너희는 나의 모든 규례와 나의 모든 판결을 지키고 그것들을 행하라. 나는 여호와니라.'),
(3320, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3321, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 2, 'OT', '또한 너는 이스라엘 자손에게 말할지니, 이스라엘 자손 중에서든지 이스라엘 가운데 거하는 나그네 중에서든지 누구든지 자기 씨를 몰렉에게 주는 자는 반드시 죽임을 당할 것이요, 그 땅의 백성이 그를 돌로 칠지니라.'),
(3322, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 3, 'OT', '나도 그 사람에게 내 얼굴을 향하고 그를 그의 백성 속에서 끊으리니 이는 그가 그의 씨를 몰렉에게 주어 내 성소를 더럽히고 내 거룩한 이름을 욕되게 하였음이라'),
(3323, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 4, 'OT', '만일 그 땅의 백성이 그 사람이 자기 씨를 몰렉에게 줄 때에 그에게서 눈을 숨겨서 그를 죽이지 아니하면'),
(3324, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 5, 'OT', '내가 나의 얼굴을 그 사람과 그의 가족에게 두리라, 그리고 그와 그를 따라 몰렉을 음란히 섬기며 음행하는 모든 자를 그들의 백성 속에서 끊으리라.'),
(3325, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 6, 'OT', '영혼이 영적 매체와 무당에게로 돌이켜 그들을 따라 음란하게 행하면, 내가 그 영혼에게 내 얼굴을 돌리고 그를 그의 백성 속에서 끊으리라.'),
(3326, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 7, 'OT', '너희는 스스로 거룩하게 하여 거룩할지니, 이는 나 여호와 너희 하나님이니라.'),
(3327, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 8, 'OT', '너희는 내 규례를 지키고 그것들을 행하라. 나는 너희를 거룩하게 하는 여호와니라.'),
(3328, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 9, 'OT', '누구든지 자기 아버지나 어머니를 저주하는 사람은 반드시 죽임을 당할지니, 그가 자기 아버지와 어머니를 저주하였은즉 그의 피가 그에게로 돌아가리라.'),
(3329, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 10, 'OT', '사람이 다른 사람의 여자와 간음하되 그의 친구의 여자와 간음하는 자는, 그 간음한 남자와 간음한 여자를 반드시 죽일지니라.'),
(3330, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 11, 'OT', '사람이 그 아버지의 여자와 동침하면 그의 아버지의 벌거벗음을 드러낸 것이니 그들 둘 다 반드시 죽일지니 그들의 피가 그들 위에 있으리라'),
(3331, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 12, 'OT', '사람이 그의 신부와 동침하면 둘 다 반드시 죽임을 당할지니 그들이 혼란을 행하였음이라 그들의 피가 그들 위에 있으리라'),
(3332, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 13, 'OT', '사람이 여자와 같이 남자와 침상에 눕는 자는 둘 다 가증한 일을 행한 것이라 그들이 반드시 죽임을 당할지니 그들의 피가 그들 위에 있으리라'),
(3333, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 14, 'OT', '사람이 여자와 그 어머니를 함께 취하면 그것은 음란한 행위라 그와 그들을 불로 태울지니 너희 중간에 음란한 행위가 없게 하려 함이니라'),
(3334, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 15, 'OT', '사람이 그 잠자리를 짐승에게 주면 반드시 죽임을 당할 것이요, 너희는 그 짐승도 죽일지니라.'),
(3335, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 16, 'OT', '여자가 모든 짐승에게 가까이하여 그것과 교합하려 하면 너는 그 여자와 그 짐승을 죽일지니 그들은 반드시 죽임을 당할 것이라 그들의 피가 그들 위에 있으리라'),
(3336, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 17, 'OT', '사람이 그의 자매 곧 아버지의 딸이나 어머니의 딸을 취하여 그녀의 벌거벗음을 보고 그녀도 그의 벌거벗음을 보면 그것은 은혜로운 일이 아니요, 그들은 그들의 백성의 아들들의 눈 앞에서 끊어질 것이며, 그가 그의 자매의 벌거벗음을 드러냈으니 그의 죄악을 담당할 것이라.'),
(3337, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 18, 'OT', '사람이 월경하는 여자와 동침하여 그 벌거벗음을 드러내되 그 샘을 드러내었고 그 여자도 자기 피의 샘을 드러내었으면 그들 둘 다 그들의 백성 속에서 끊어지리라'),
(3338, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 19, 'OT', '네 어머니의 자매와 아버지의 자매의 벌거벗음을 드러내지 말지니 이는 그가 그의 살을 드러냈음이라 그들이 그들의 죄악을 담당하리라'),
(3339, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 20, 'OT', '사람이 그의 고모와 동침하면 그의 사랑하는 자의 벌거벗음을 드러낸 것이니 그들이 그 죄를 담당하고 자식 없이 죽으리라'),
(3340, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 21, 'OT', '사람이 그의 형제의 아내를 취하면 그것은 불결함이니 그가 그의 형제의 벌거벗음을 드러낸 것이라 그들은 자식이 없으리라'),
(3341, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 22, 'OT', '너희는 나의 모든 규례와 모든 판결을 지키고 그것들을 행할지니, 그리하면 내가 너희를 인도하여 거기 거하게 하는 땅이 너희를 토하지 아니하리라.'),
(3342, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 23, 'OT', '너희는 내가 너희 얼굴 앞에서 쫓아내는 이방인의 규례를 따르지 말라, 그들이 이 모든 일을 행하였으므로 내가 그들을 가증히 여겼느니라.'),
(3343, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 24, 'OT', '내가 너희에게 말하였노니 너희가 그들의 땅을 차지할 것이요 내가 그것을 너희에게 주어 그것을 소유하게 하리니 젖과 꿀이 흐르는 땅이라 나는 너희를 백성들 가운데서 구별한 너희의 하나님 여호와니라'),
(3344, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 25, 'OT', '너희는 정한 짐승과 부정한 짐승 사이를, 부정한 새와 정한 새 사이를 구별할지니라. 너희는 내가 너희를 위하여 부정한 것으로 구별한 짐승이나 새나 땅에 기는 모든 것으로 인하여 너희 영혼을 더럽히지 말지니라.'),
(3345, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 26, 'OT', '너희는 내게 거룩할지니 이는 나 여호와가 거룩함이라 내가 너희를 백성 중에서 구별하여 내게 속하게 하였느니라'),
(3346, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 20, 27, 'OT', '사람이나 여자가 그들 가운데 영적 매체나 무당이 되거든 반드시 죽일지니 돌로 그들을 치라 그들의 피가 그들 위에 있으리라'),
(3347, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 1, 'OT', '여호와께서 모세에게 이르시되 아론의 아들들인 제사장들에게 말하여 그들에게 이르라 그가 그의 백성 중에서 영혼으로 인하여 스스로 더럽히지 말지니라'),
(3348, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 2, 'OT', '오직 자기에게 가까운 살붙이, 곧 그의 어머니와 그의 아버지와 그의 아들과 그의 딸과 그의 형제를 위해서만'),
(3349, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 3, 'OT', '그의 처녀인 자매, 곧 그에게 가까운 자로서 아직 사람에게 시집가지 아니한 자를 위하여는 그가 몸을 더럽힐 수 있느니라'),
(3350, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 4, 'OT', '그는 자기 백성 가운데 주인으로서 스스로 더럽혀 욕되게 하지 말지니라'),
(3351, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 5, 'OT', '그들은 머리에 대머리를 내지 말며 수염의 모퉁이를 깎지 말고 살에 새김을 긋지 말지니라'),
(3352, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 6, 'OT', '그들은 그들의 하나님께 거룩할 것이며 그들의 하나님의 이름을 욕되게 하지 않을 것이라, 이는 그들이 여호와의 불제물, 곧 그들의 하나님의 빵을 드리는 자들이므로 거룩함이 될 것임이라.'),
(3353, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 7, 'OT', '여자 매춘한 자와 부정한 여자를 그들이 취하지 말 것이며 그 남편에게서 이혼 당한 여자도 취하지 말지니 이는 그가 자기 하나님께 거룩함이니라'),
(3354, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 8, 'OT', '너는 그를 거룩하게 할지니 이는 그가 네 하나님의 빵을 드림이라 그가 네게 거룩하리니 이는 나 여호와가 너희를 거룩하게 하는 자가 거룩함이니라'),
(3355, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 9, 'OT', '제사장의 딸이 행음하여 자신을 더럽히면 그녀가 자기 아버지를 욕되게 하는 것이니, 그녀는 불에 태워질지니라.'),
(3356, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 10, 'OT', '그의 형제들 중에서 관유를 머리에 부음 받고 손을 채워 옷을 입는 직분을 맡은 대제사장은 그의 머리를 풀지 말며 그의 옷을 찢지 말지니라'),
(3357, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 11, 'OT', '또한 모든 죽은 자의 영혼에게도 들어가지 말 것이며, 그의 아버지와 그의 어머니로 인하여도 더럽히지 말지니라.'),
(3358, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 12, 'OT', '그리고 그는 성소에서 나오지 말 것이며, 그의 하나님의 성소를 더럽히지 말지니, 이는 그의 하나님의 기름부음의 기름 왕관이 그 위에 있음이라. 나는 여호와니라.'),
(3359, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 13, 'OT', '그는 처녀성에 있는 여자를 취할지니라'),
(3360, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 14, 'OT', '과부나 이혼된 여인이나 더럽혀진 매춘하는 여인은 그들을 취하지 말 것이며, 오직 자기 백성 중에서 처녀를 아내로 취할 것이니라.'),
(3361, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 15, 'OT', '그가 자기 씨를 자기 백성 가운데서 더럽히지 말지니 이는 나 여호와가 그를 거룩하게 함이니라'),
(3362, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 16, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3363, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 17, 'OT', '아론에게 말하여 이르기를, 네 씨 중에서 그들의 세대들 가운데 흠이 있는 사람은 그의 하나님의 빵을 드리려고 가까이 오지 못할 것이라.'),
(3364, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 18, 'OT', '흠이 있는 사람은 누구든지 가까이 오지 못할지니, 눈먼 사람이나 절뚝발이나 코가 불완전한 사람이나 지체가 더한 사람이나'),
(3365, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 19, 'OT', '혹은 발에 파괴가 있거나 손에 파괴가 있는 사람'),
(3366, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 20, 'OT', '곱사등이나, 난장이나, 눈에 흠이 있는 자나, 딱지나 옴이 있는 자나, 돌이 상한 자나'),
(3367, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 21, 'OT', '아론 제사장의 씨 중에 흠이 있는 모든 사람은 여호와의 불제물을 드리러 가까이 나아가지 못할지니, 그에게 흠이 있은즉 그의 하나님의 빵을 드리러 가까이 나아가지 못할지니라.'),
(3368, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 22, 'OT', '그의 하나님의 빵을 지극히 거룩한 것들 중에서와 거룩한 것들 중에서 먹을지니라'),
(3369, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 23, 'OT', '오직 휘장 안에는 들어가지 못할 것이요 제단에도 가까이 가지 못할지니 이는 그에게 흠이 있음이라 그가 나의 성소를 더럽히지 못하게 하라 나는 그들을 거룩하게 하는 여호와임이니라'),
(3370, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 21, 24, 'OT', '모세가 아론과 그의 아들들과 이스라엘의 모든 아들들에게 말하였더라.'),
(3371, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3372, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 2, 'OT', '아론과 그의 아들들에게 말하여 그들이 이스라엘 자손의 거룩한 것들에서 스스로 분리하게 하고 내 거룩한 이름을 욕되게 하지 말게 하라 그들이 내게 거룩하게 하는 것들에 대하여 나는 여호와니라'),
(3373, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 3, 'OT', '그들에게 말하라 너희 대대에 걸쳐 너희 모든 씨 중에서 누구든지 이스라엘 아들들이 여호와께 거룩하게 구별하는 거룩함에 가까이 나아가되 그 더러움이 그 위에 있으면 그 영혼은 내 얼굴 앞에서 끊어지리라 나는 여호와니라'),
(3374, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 4, 'OT', '아론의 씨 중에서 어떤 사람이든 그가 나병환자이거나 유출병이 있는 자는 그가 정결하게 되기까지 거룩함을 먹지 말 것이며, 모든 부정한 영혼을 만지는 자나 그에게서 동침의 씨가 나가는 사람은'),
(3375, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 5, 'OT', '혹은 모든 번식하는 작은 동물을 만져서 그에게 더러움이 되는 사람이나, 그에게 더러움이 되는 사람을 만져서 모든 더러움에 이른 자도'),
(3376, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 6, 'OT', '영혼이 그것에 접촉하면 저녁까지 부정할 것이요, 그가 자기 살을 물로 씻지 아니하면 거룩함에서 먹지 못할지니라.'),
(3377, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 7, 'OT', '해가 지면 그가 정결하게 될 것이요, 그 후에 거룩함에서 먹을지니 이는 그의 빵이 됨이라.'),
(3378, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 8, 'OT', '죽은 시체나 웃긴 것을 먹지 말아서 그것으로 자신을 더럽히지 말지니, 나는 여호와니라.'),
(3379, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 9, 'OT', '그들이 나의 파수를 지키고 그것으로 말미암아 죄를 지지 아니하며 그것으로 죽지 아니하게 하라 그들이 그것을 욕되게 하면 죽을 것이라 나는 그들을 거룩하게 하는 여호와니라'),
(3380, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 10, 'OT', '모든 나그네는 거룩함을 먹지 못할 것이며, 제사장의 나그네와 품꾼은 거룩함을 먹지 못할 것이다.'),
(3381, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 11, 'OT', '제사장이 그의 은으로 영혼을 사면 그는 그것을 먹을 것이요, 그의 집에서 태생한 자들도 그들이 그의 빵을 먹을 것이니라'),
(3382, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 12, 'OT', '제사장의 딸이 타인에게 시집가면, 그녀는 거룩한 제사의 제물을 먹지 못할지니라.'),
(3383, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 13, 'OT', '제사장의 딸이 과부나 이혼을 당하고 씨가 없어서 아버지의 집으로 돌아가 소년기와 같이 되면 그녀는 아버지의 빵을 먹을 것이나, 모든 외인은 그것을 먹지 못할 것이니라.'),
(3384, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 14, 'OT', '사람이 만일 과실로 거룩함을 먹으면 그 다섯째를 그것에 더하고 제사장에게 그 거룩함을 줄지니라'),
(3385, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 15, 'OT', '그들이 이스라엘 자손이 여호와께 드리는 거룩함을 더럽히지 말지니'),
(3386, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 16, 'OT', '그들이 그들의 거룩한 것을 먹을 때에 그들이 죄악의 죄를 담당하게 하라, 이는 나 여호와가 그들을 거룩하게 함이니라.'),
(3387, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 17, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3388, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 18, 'OT', '아론과 그의 아들들과 이스라엘의 모든 아들들에게 말하고 그들에게 이르라 이스라엘 집의 사람이나 이스라엘 중에 있는 나그네가 그들의 모든 서원과 그들의 모든 자원제사를 위하여 여호와께 번제로 제물을 드리려거든'),
(3389, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 19, 'OT', '너희 기쁨을 위하여 흠 없는 수컷을 소와 어린양과 염소 중에서 드릴지니라'),
(3390, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 20, 'OT', '모든 흠 있는 것을 너희는 드리지 말지니 이는 그것이 너희에게 기쁨이 되지 못할 것임이라'),
(3391, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 21, 'OT', '사람이 여호와께 화목제 제사를 드리되 서원을 갚으려거나 자원제사로 드리려거든 소나 양떼 중에서 흠 없는 온전한 것으로 드릴지니 그것이 기쁨이 되리라 모든 흠이 그것에 있지 아니할지니라'),
(3392, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 22, 'OT', '눈먼 것이나 부러진 것이나 짓눌린 것이나 샘이 있는 것이나 딱지 있는 것이나 옴 있는 것을 너희는 여호와께 드리지 말며, 불제물로 그것들 중에서 제단 위에 여호와께 드리지 말라.'),
(3393, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 23, 'OT', '소나 양의 지체가 더하거나 덜한 것은 자원제사로 드릴 수 있으나 서원으로는 열납되지 못하리라'),
(3394, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 24, 'OT', '짓눌린 것과 부서진 것과 찢긴 것과 베인 것은 여호와께 드리지 말며 너희 땅에서는 행하지 말지니라'),
(3395, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 25, 'OT', '타국인의 손에서도 너희는 이 모든 것으로 너희 하나님의 빵을 드리지 말지니 이는 그들의 훼손이 그들 안에 있고 흠이 그들 안에 있음이라 그들이 너희를 위하여 열납되지 아니하리라'),
(3396, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 26, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3397, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 27, 'OT', '소나 어린양이나 염소가 태어나면 그 어미 아래에 칠 일을 있으리니, 여덟째 날부터 그 후에는 여호와께 불제물로 드리는 제물이 되어 열납되리라.'),
(3398, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 28, 'OT', '소나 양을 그 아들과 함께 하루에 잡지 말지니라.'),
(3399, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 29, 'OT', '너희가 여호와께 감사제사 제사를 드릴 때에는 너희 기쁨으로 드릴지니라'),
(3400, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 30, 'OT', '그 날에 그것을 먹을 것이요 아침까지 그것을 남겨 두지 말지니라 나는 여호와니라'),
(3401, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 31, 'OT', '너희는 나의 명령을 지키며 그것들을 행할지니라 나는 여호와니라'),
(3402, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 32, 'OT', '너희는 내 거룩한 이름을 욕되게 하지 말지니라 내가 이스라엘 자손 중간에서 거룩하게 되리라 나는 너희를 거룩하게 하는 여호와니라'),
(3403, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 22, 33, 'OT', '너희를 애굽 땅에서 인도하여 낸 자, 너희의 하나님이 되려 함이니 나는 여호와니라.'),
(3404, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3405, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 2, 'OT', '이스라엘 자손에게 말하여 그들에게 이르라 여호와의 정한 때 곧 너희가 거룩한 집회로 부를 것들, 이것들이 나의 정한 때니라'),
(3406, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 3, 'OT', '엿새 동안은 일을 할 것이요, 일곱째 날은 거룩한 집회인 안식일의 안식이니, 너희는 모든 일을 하지 말지니라. 그것은 너희 모든 거주지에서 여호와의 안식일이니라.'),
(3407, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 4, 'OT', '이것들은 여호와의 정한 때들이니 너희가 그 정한 때에 선포할 거룩한 집회들이라'),
(3408, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 5, 'OT', '첫째 달 십사일 저녁 사이에 여호와의 유월절이니라'),
(3409, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 6, 'OT', '이 달 열닷새 날은 여호와의 누룩 없는 빵 축제이니, 너희는 이레 날 동안 누룩 없는 빵을 먹을지니라.'),
(3410, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 7, 'OT', '첫째 날에 너희에게 거룩한 집회가 있을 것이니, 너희는 모든 노동의 일을 하지 말지어다.'),
(3411, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 8, 'OT', '너희는 칠 일 동안 여호와께 불제물을 드릴지니라 일곱째 날에는 거룩한 집회가 있으리니 모든 일하는 일을 하지 말지니라'),
(3412, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 9, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3413, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 10, 'OT', '이스라엘 자손에게 말하여 그들에게 이르라 너희가 내가 너희에게 주는 땅에 들어가서 그 추수를 거둘 때에 너희 추수의 처음 단을 제사장에게로 가져갈 것이요'),
(3414, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 11, 'OT', '제사장은 안식일 이튿날에 그 단을 여호와의 얼굴 앞에서 너희를 위하여 기쁨으로 흔들지니라.'),
(3415, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 12, 'OT', '너희가 그 단을 흔드는 날에 일 년 된 흠 없는 어린양을 번제로 여호와께 드릴지니라'),
(3416, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 13, 'OT', '그 소제물은 고운 밀가루 십분의 이 에바를 기름에 섞어 여호와께 드리는 불제물로 삼아 향기로운 냄새가 되게 하고, 그 제사로는 포도주 힌 사분의 일을 쓸 것이며'),
(3417, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 14, 'OT', '너희는 너희 하나님이신 여호와께 제물을 가져오는 바로 그 날까지 빵과 볶은 곡식과 갈멜을 먹지 말지니 이는 너희 모든 거주지에서 너희 세대들에게 영원한 규례니라.'),
(3418, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 15, 'OT', '너희는 안식일 이튿날, 곧 너희가 흔들어 바침의 단을 가져온 날부터 스스로 세어서 일곱 안식일이 온전하게 되게 할지니라'),
(3419, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 16, 'OT', '일곱째 안식일 이튿날까지 너희는 오십 일을 계수할지니 새 제물을 여호와께 드릴지니라'),
(3420, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 17, 'OT', '너희 거주지에서 흔들어 바치는 빵 둘을 가져오되, 그것들은 고운 밀가루 십분의 일 둘로 될 것이며, 누룩을 넣어 구울 것이니, 그것들은 여호와께 드리는 첫 열매니라.'),
(3421, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 18, 'OT', '너희는 그 빵과 함께 일 년 된 흠 없는 어린 양 일곱과 수송아지 한 마리와 숫양 둘을 여호와께 번제로 드릴지니 그것들과 그들의 곡식제물과 그들의 전제는 여호와께 불로 드리는 향기로운 냄새가 될지니라'),
(3422, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 19, 'OT', '너희는 염소 한 마리를 죄를 위한 제물로 드리고, 일 년 된 어린양 두 마리를 화목제 제사로 드릴지니라.'),
(3423, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 20, 'OT', '제사장은 첫 열매의 빵 위에서 그들을 여호와의 얼굴 앞에 흔들어 바침으로 흔들되, 두 어린양과 함께 할지니, 그것들은 여호와께 거룩함이 되어 제사장에게 돌릴지니라.'),
(3424, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 21, 'OT', '너희는 바로 이 날에 거룩한 집회를 공포하라 그것이 너희에게 있으리니 모든 노동의 일을 하지 말지어다 이는 너희 모든 거주지에서 너희 세대들에게 영원한 규례니라'),
(3425, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 22, 'OT', '너희가 너희 땅의 추수를 거둘 때에 네 들판의 모퉁이를 추수할 때에 다 베지 말며 네 추수의 이삭줍기를 줍지 말고 가난한 자와 나그네를 위하여 그것을 버려 두라 나는 너희 하나님 여호와니라'),
(3426, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 23, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3427, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 24, 'OT', '이스라엘 자손에게 말하여 이르라 일곱째 달 그 달 첫째 날에 너희에게 안식이 있으리니 나팔소리의 기념이요 거룩한 집회라'),
(3428, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 25, 'OT', '모든 일하는 일은 하지 말고 여호와께 불제물을 드릴지니라'),
(3429, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 26, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3430, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 27, 'OT', '오직 이 일곱째 달 열흘날은 속죄일이니, 너희에게 거룩한 집회가 될 것이며, 너희는 너희 영혼을 괴롭게 하고 여호와께 불제물을 드릴지니라.'),
(3431, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 28, 'OT', '모든 일을 하지 말지니 바로 이 날에, 이는 너희를 위하여 너희 하나님 여호와 앞에서 속죄할 속죄일이기 때문이니라.'),
(3432, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 29, 'OT', '모든 영혼이 이 날에 스스로 괴롭게 하지 아니하면 그 백성 중에서 끊쳐지리라'),
(3433, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 30, 'OT', '그 날에 어떤 일이든 행하는 모든 영혼은, 내가 그 영혼을 그 백성 가운데서 멸절시키리라.'),
(3434, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 31, 'OT', '너희는 아무 일도 하지 말지니 이는 너희 모든 거주지에서 너희 세대들에게 영원한 규례니라'),
(3435, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 32, 'OT', '너희에게 안식일이요 안식의 안식일이라 너희는 너희 영혼을 괴롭게 할지니라 그 달 구일 저녁, 저녁부터 저녁까지 너희 안식일을 지킬지니라'),
(3436, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 33, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3437, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 34, 'OT', '이스라엘 자손에게 말하여 이르라 이 일곱째 달 십오일은 여호와를 위한 초막절이니 칠 일 동안 지킬 것이라'),
(3438, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 35, 'OT', '첫 날에 거룩한 집회가 있으리니 너희는 모든 노동의 일을 하지 말지니라'),
(3439, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 36, 'OT', '칠 일 동안 너희는 불제물을 여호와께 드릴지니, 여덟째 날에는 거룩한 집회가 너희에게 있을 것이며, 너희는 불제물을 여호와께 드릴지니, 그것은 엄숙한 집회라, 모든 일하는 일을 하지 말지니라.'),
(3440, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 37, 'OT', '이것들은 여호와의 정한 때라 너희가 그것들을 거룩한 집회로 부를지니 여호와께 불제물을 드리되 번제와 제물과 제사와 제사를 각각 그 날에 날마다 말씀대로 드릴지니라'),
(3441, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 38, 'OT', '여호와의 안식일들 외에, 너희의 선물들 외에, 너희의 모든 서원들 외에, 너희의 모든 자원제사들 외에, 너희가 여호와께 드리는 그것들 외에.'),
(3442, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 39, 'OT', '오직 일곱째 달 열닷새 날에 너희가 땅의 수확을 거둔 후에 여호와의 축제를 칠 일 동안 지킬지니, 첫 날에는 안식이요 여덟째 날에도 안식이니라.'),
(3443, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 40, 'OT', '너희는 첫째 날에 아름다운 나무의 열매와 종려나무의 손바닥 가지와 무성한 나무의 가지와 골짜기의 버드나무를 취할지니라. 너희는 너희 하나님 여호와 앞에서 칠 일 동안 즐거워할지니라.'),
(3444, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 41, 'OT', '너희는 해마다 칠 일 동안 여호와께 축제를 지킬지니, 너희 세대들의 영원한 규례라. 일곱째 달에 너희가 그것을 지킬지니라.'),
(3445, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 42, 'OT', '너희는 칠 일 동안 초막에 거하되, 이스라엘의 모든 본토인은 초막에 거할지니라.'),
(3446, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 43, 'OT', '이는 너희 세대들이 알게 하려 함이니, 내가 이스라엘 자손을 애굽 땅에서 인도하여 낼 때에 그들을 초막에 거하게 하였음을 너희가 알게 하려 함이라. 나는 여호와 너희 하나님이니라.'),
(3447, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 23, 44, 'OT', '모세가 여호와의 정한 때를 이스라엘 자손에게 말하였더라'),
(3448, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3449, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 2, 'OT', '이스라엘 자손에게 명하여 그들이 너에게 순결한 올리브 기름을 가져오게 하되, 빛을 위해 찧어 낸 것으로, 항상 등불을 켜게 하라.'),
(3450, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 3, 'OT', '증언의 휘장 밖, 정한 때의 천막 안에서 아론이 그것을 저녁부터 아침까지 여호와의 얼굴 앞에 항상 정리할지니, 너희 세대에게 영원한 규례니라.'),
(3451, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 4, 'OT', '그가 순결한 촛대 위에 등불을 여호와의 얼굴 앞에 항상 정리할지니라'),
(3452, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 5, 'OT', '네가 고운 밀가루를 취하여 그것으로 열두 개의 화병을 굽되, 각 화병은 십분의 일 둘이 될지니라.'),
(3453, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 6, 'OT', '네가 그것들을 여호와 앞 순결한 상 위에 두 군대로 진열하되, 한 진열에 여섯씩 두 진열을 두라.'),
(3454, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 7, 'OT', '너는 진열 위에 정결한 유향을 두고, 그것이 빵 위에 있어 기념이 되게 하여 여호와께 불제물로 삼을지니라.'),
(3455, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 8, 'OT', '안식일 날마다 안식일 날에 그가 그것을 여호와의 얼굴 앞에 항상 진설할지니 이스라엘 아들들로부터 영원한 언약으로 말미암아 있느니라.'),
(3456, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 9, 'OT', '그것은 아론과 그의 아들들의 것이 되리니 그들은 그것을 거룩한 장소에서 먹을지니라 이는 여호와의 불제물 중에서 그에게 돌리는 지극히 거룩한 거룩함이요 영원한 법령이니라'),
(3457, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 10, 'OT', '이스라엘 여자의 아들이요 그는 애굽 사람의 아들인 자가 이스라엘 자손 중간에 나갔고, 그 이스라엘 여자의 아들과 이스라엘 사람이 진영에서 싸우더라.'),
(3458, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 11, 'OT', '이스라엘 여자의 아들이 그 이름을 찌르고 저주하매 그들이 그를 모세에게로 데려가니라 그의 어머니의 이름은 단 지파 디브리의 딸 슬로밋이었더라'),
(3459, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 12, 'OT', '그들이 그를 파수에 두고 여호와의 입으로 그들에게 지시하실 것을 기다리니라'),
(3460, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 13, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3461, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 14, 'OT', '저주한 자를 진영 밖으로 끌어내고, 모든 들은 자들이 그들의 손을 그의 머리에 얹을 것이며, 모든 회중이 그를 돌로 칠지니라.'),
(3462, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 15, 'OT', '너는 이스라엘 자손에게 말하여 이르기를, 어떤 사람이든지 자기 하나님을 저주하면 그의 죄를 담당할 것이라.'),
(3463, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 16, 'OT', '여호와의 이름을 훼방하는 자는 반드시 죽임을 당할지니 온 회중이 돌로 그를 칠 것이라 나그네든지 본토인이든지 그의 이름을 훼방하면 죽임을 당할지니라'),
(3464, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 17, 'OT', '사람이 모든 사람의 영혼을 치면 반드시 죽임을 당할 것이라'),
(3465, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 18, 'OT', '짐승의 영혼을 친 자는 그것을 갚을지니 영혼은 영혼으로 갚을지니라.'),
(3466, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 19, 'OT', '사람이 만일 동료에게 흠을 내게 하면, 그가 행한 대로 그에게 행해질 것이니라.'),
(3467, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 20, 'OT', '파괴는 파괴로, 눈은 눈으로, 이빨은 이빨로, 사람에게 흠을 낸 대로 그에게 그렇게 행해질 것이다.'),
(3468, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 21, 'OT', '짐승을 친 자는 그것을 갚을 것이요, 사람을 친 자는 죽임을 당할지니라.'),
(3469, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 22, 'OT', '너희에게 한 판결이 있을지니 나그네에게든지 본토인에게든지 동일하리라 이는 내가 여호와 너희 하나님이기 때문이니라'),
(3470, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 24, 23, 'OT', '모세가 이스라엘 자손에게 말하매 그들이 저주한 자를 진영 밖으로 끌어내어 돌로 그를 쳤더라 이스라엘 자손이 여호와께서 모세에게 명령하신 대로 행하였더라'),
(3471, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 1, 'OT', '여호와께서 시내 산에서 모세에게 말씀하여 이르시되'),
(3472, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 2, 'OT', '이스라엘 자손에게 말하여 그들에게 이르라 너희가 내가 너희에게 주는 땅에 들어가면 그 땅은 여호와께 안식일을 지키리라'),
(3473, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 3, 'OT', '육 년 동안 네 들판에 씨를 뿌리고 육 년 동안 네 포도원을 가지치기하며 그 수확을 거둘지니라'),
(3474, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 4, 'OT', '일곱째 해에는 땅에게 안식의 안식일이 되리니 여호와께 대한 안식일이라 너는 네 들판에 씨를 뿌리지 말고 네 포도원을 가지치기하지 말지니라'),
(3475, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 5, 'OT', '네가 네 추수의 스스로 자라는 것을 거두지 말고, 네 나실인의 포도 열매를 따지 말지니, 이는 땅에게 안식의 해가 될 것임이라.'),
(3476, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 6, 'OT', '땅의 안식일이 너희에게 먹을 것이 되리니 너와 네 종과 네 여종과 네 품꾼과 너와 함께 거하는 나그네에게니라'),
(3477, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 7, 'OT', '네 짐승과 네 땅에 있는 살아있는 모든 것에게 그 수확이 다 먹을 것이 되리라'),
(3478, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 8, 'OT', '너는 일곱 안식일의 해를 네게 계수할지니, 일곱 해를 일곱 때로 하라. 그리하면 일곱 안식일의 해의 날들이 네게 사십구 년이 되리라.'),
(3479, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 9, 'OT', '너희는 일곱째 달 초열흘 날에 속죄일의 나팔소리를 내되, 너희 모든 땅에서 나팔을 불지니라.'),
(3480, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 10, 'OT', '너희는 오십 년째 해를 거룩하게 하고 그 땅의 모든 주민에게 자유를 선포하라. 그것은 너희에게 희년이 될 것이니, 너희는 각자 자기 소유로 돌아가며 각자 자기 가족에게로 돌아갈지니라.'),
(3481, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 11, 'OT', '그것은 너희에게 희년이 될 오십 년째 해이니, 너희는 심지 말고, 그것의 스스로 자라는 것을 거두지 말며, 그것의 나실인 포도를 따지 말지어다.'),
(3482, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 12, 'OT', '그것은 희년이니 너희에게 거룩함이 될 것이며, 너희는 들판에서 그 수확을 먹을지니라.'),
(3483, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 13, 'OT', '이 희년에는 너희가 각 사람이 자기 소유로 돌아갈지니라'),
(3484, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 14, 'OT', '네가 네 동료에게 판매를 팔거나 네 동료의 손에서 사거든, 너희는 각 사람이 자기 형제를 속이지 말지니라.'),
(3485, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 15, 'OT', '희년 후의 해 수대로 네가 네 동료에게서 사되, 그가 네게 수확의 해 수대로 팔 것이다.'),
(3486, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 16, 'OT', '해의 많음을 따라 너는 그 구매를 많게 할지니, 해의 적음을 따라 너는 그 구매를 적게 할지니, 이는 그가 수확의 수를 따라 네게 팔기 때문이라.'),
(3487, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 17, 'OT', '너는 네 동료를 속이지 말고 네 하나님을 경외하라, 나는 너희 하나님 여호와이기 때문이니라.'),
(3488, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 18, 'OT', '너희는 내 규례를 행하며 내 판결을 지키고 그것들을 행할지니, 그리하면 너희가 그 땅에 안전히 거하리라.'),
(3489, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 19, 'OT', '땅이 그 열매를 내리리니 너희가 만족하도록 먹고 그 위에서 안전히 거하리라'),
(3490, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 20, 'OT', '만일 너희가 말하기를, 일곱째 해에 우리가 무엇을 먹으리요, 보라 우리가 심지도 못하고 우리의 수확을 거두지도 못하리라 하면,'),
(3491, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 21, 'OT', '내가 너희에게 내 축복을 명령하리니 여섯째 해에 그것이 수확을 삼 년 동안 내리라.'),
(3492, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 22, 'OT', '너희가 여덟째 해에 씨를 뿌리고 묵은 수확에서 먹을 것이며, 아홉째 해까지, 그 수확이 이르기까지 너희는 묵은 것을 먹을지니라.'),
(3493, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 23, 'OT', '땅은 영원함으로 팔리지 아니하리니 이는 땅이 내 것임이라 너희는 나그네와 거주하는 자로서 나와 함께 있느니라'),
(3494, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 24, 'OT', '너희 소유의 모든 땅에서 그 땅을 위하여 속량을 허락할지니라'),
(3495, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 25, 'OT', '네 형제가 가난해져서 그의 소유를 팔았으면, 그에게 가까운 그의 친족이 와서 그의 형제가 판 것을 무를 것이요'),
(3496, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 26, 'OT', '만일 어떤 사람에게 속량할 자가 없고, 그의 손이 넉넉하여 그의 속량할 만한 충분한 것을 얻으면'),
(3497, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 27, 'OT', '그는 판매한 햇수를 계산하고 그 남은 값을 그에게 판 사람에게 돌려주고 그의 소유로 돌아갈지니라'),
(3498, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 28, 'OT', '그러나 만일 그의 손이 그에게 갚을 만큼 충분하지 못하면, 그가 판 것은 그것을 산 자의 손에 희년의 해까지 있게 되고, 희년에 나가서 그의 소유로 돌아갈지니라.'),
(3499, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 29, 'OT', '사람이 성벽 있는 성읍의 거주지 집을 팔았으면 그의 속량은 판매한 해가 끝날 때까지 있으리니 그의 속량은 날들이 될지니라'),
(3500, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 30, 'OT', '만일 그가 온전한 일 년이 차기까지 구속되지 아니하면, 성벽이 없는 성읍에 있는 그 집은 그것을 산 자의 소유로 영원히 확정되어 그의 세대들에게 속할 것이요, 희년에 나가지 아니하리라.'),
(3501, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 31, 'OT', '성벽이 주위에 없는 뜰들의 집들은 땅의 들판으로 여길지니, 그것에게 속량이 있을 것이요 희년에 나가게 될 것이니라.'),
(3502, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 32, 'OT', '레위인들의 성읍들, 그들의 소유의 성읍들의 집들은 레위인들에게 영원한 속량이 될지니라.'),
(3503, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 33, 'OT', '레위인에게서 산 자는 그 판매한 집과 그 소유의 성읍이 희년에 나가리니 이는 레위인의 성읍들의 집들이 이스라엘 자손 중에서 그들의 소유임이라'),
(3504, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 34, 'OT', '그러나 그들의 성읍들의 교외 들판은 팔리지 못할지니, 이는 그것이 그들에게 영원한 소유이기 때문이라.'),
(3505, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 35, 'OT', '네 형제가 가난하게 되어 네 곁에서 그의 손이 흔들리거든 너는 그를 붙잡아 주어, 그가 나그네나 거주하는 자로서 너와 함께 살게 하라.'),
(3506, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 36, 'OT', '그에게서 이자나 증식을 취하지 말고 네 하나님을 경외하여 네 형제가 너와 함께 살게 하라'),
(3507, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 37, 'OT', '네 은을 그에게 고리대금으로 주지 말고, 네 음식을 많음으로 주지 말지니라.'),
(3508, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 38, 'OT', '나는 너희 하나님이 되기 위하여 너희에게 가나안 땅을 주기 위하여 애굽 땅에서 너희를 인도하여 낸 여호와 너희 하나님이니라'),
(3509, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 39, 'OT', '네 형제가 네 곁에서 가난하게 되어 네게 팔렸으면, 너는 그를 종의 일로 부리지 말지니라.'),
(3510, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 40, 'OT', '품꾼이나 거주하는 나그네 같이 그가 너와 함께 있게 하여 희년의 해까지 너를 섬기게 하라'),
(3511, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 41, 'OT', '그가 네게서 떠나리니 그와 그의 아들들이 그와 함께 하리라 그가 그의 가족에게로 돌아가고 그의 아버지들의 소유로 돌아가리라'),
(3512, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 42, 'OT', '그들은 내가 애굽 땅에서 인도해 낸 나의 종들이니 종으로 팔린 것처럼 팔리지 않을 것이라'),
(3513, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 43, 'OT', '그를 혹독함으로 다스리지 말고 네 하나님을 경외하라'),
(3514, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 44, 'OT', '네 종과 네 여종은 네 주위에 있는 이방인들 중에서 네게 있을 것이며, 그들 중에서 종과 여종을 사게 될 것이다.'),
(3515, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 45, 'OT', '또한 너희와 함께 거주하는 나그네의 아들들 중에서도 너희가 사되, 그들의 가족 중에서도 너희와 함께 있는 자, 곧 그들이 너희 땅에서 낳은 자들 중에서 사야 할 것이며, 그들은 너희에게 소유가 될지니라.'),
(3516, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 46, 'OT', '너희는 그들을 너희 후손에게 소유로 주어 영원히 그들 가운데서 부릴 것이며, 너희 형제 이스라엘 자손에 대해서는 사람이 그의 형제를 혹독함으로 다스리지 말지니라.'),
(3517, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 47, 'OT', '네 곁에 나그네나 거주하는 외국인의 손이 넉넉해지고 네 형제가 그와 함께 가난해져서 네 곁에 있는 나그네나 나그네 가족의 뿌리에게 팔리게 되면'),
(3518, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 48, 'OT', '팔린 후에 그에게 속량이 있을 것이니 그의 형제 중 하나가 그를 속량할지니라'),
(3519, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 49, 'OT', '혹은 그의 사랑하는 자나 그의 사랑하는 자의 아들이 그를 구속할 것이요, 혹은 그의 가족 중에서 그의 살의 가까운 자가 그를 구속할 것이요, 혹은 그의 손이 넉넉하여 그가 구속되리라.'),
(3520, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 50, 'OT', '그가 그것을 산 자와 계산하되, 그것이 그에게 팔린 해부터 희년의 해까지 이를 것이며, 그 판매의 은은 해의 수에 따라 그와 함께 있을 것이니, 품꾼의 날과 같이 될 것이다.'),
(3521, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 51, 'OT', '만일 그 해들이 아직 많으면, 그 입들대로 그의 속량 값을 그의 구매 은에서 돌려줄지니라.'),
(3522, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 52, 'OT', '만일 희년의 해까지 남은 해가 조금이면 그가 그와 계산할지니 그의 해의 입대로 그의 속량을 돌려줄지니라'),
(3523, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 53, 'OT', '해마다 삯군과 같이 그가 그와 함께 있을 것이요, 너의 눈 앞에서 그를 혹독함으로 다스리지 못할지니라'),
(3524, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 54, 'OT', '만일 그가 이들로 속량되지 않으면, 그는 희년에 나가되, 그와 그의 아들들이 그와 함께 나가리라.'),
(3525, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 25, 55, 'OT', '이스라엘 자손은 내게 종들이라 그들은 내가 애굽 땅에서 인도하여 낸 나의 종들이니 나는 너희 하나님 여호와니라'),
(3526, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 1, 'OT', '너희는 너희를 위하여 우상들을 만들지 말며, 조각한 우상과 기둥을 너희를 위하여 세우지 말고, 너희 땅에 조각상 돌을 두어 그것 위에 경배하지 말라. 나는 너희 하나님 여호와이기 때문이라.'),
(3527, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 2, 'OT', '너희는 나의 안식일들을 지키고 나의 성소를 공경할지니라. 나는 여호와니라.'),
(3528, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 3, 'OT', '너희가 나의 규례를 따라 행하며 나의 명령을 지키고 그것들을 행하면'),
(3529, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 4, 'OT', '내가 너희 비를 그 때에 주리니 땅은 그 소출을 내고 들판의 나무는 그 열매를 맺을지라'),
(3530, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 5, 'OT', '너희의 타작이 포도 수확에 미치고, 포도 수확이 씨 뿌리는 때에 미칠 것이며, 너희는 너희 빵을 만족하도록 먹고 너희 땅에서 안전히 거하리라.'),
(3531, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 6, 'OT', '내가 그 땅에 평화를 주리니 너희가 누울 것이며 두렵게 할 자가 없을 것이요 내가 살아있는 악한 짐승을 그 땅에서 제거하리니 칼이 너희 땅을 지나가지 아니하리라'),
(3532, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 7, 'OT', '너희는 너희 원수들을 쫓을 것이며 그들이 너희 얼굴 앞에서 칼에 엎드러지리라'),
(3533, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 8, 'OT', '너희 중 다섯이 백을 쫓고, 너희 중 백이 만만을 쫓으리니, 너희 원수들이 너희 얼굴 앞에서 칼에 엎드러지리라.'),
(3534, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 9, 'OT', '내가 너희를 돌아보고 너희를 번성하게 하며 너희를 많게 하리니 내가 너희와 세운 나의 언약을 세우리라'),
(3535, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 10, 'OT', '너희는 묵은 곡식을 먹되 오래된 묵은 것을 먹을 것이며, 새 것의 얼굴로 말미암아 묵은 것을 내어갈지니라.'),
(3536, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 11, 'OT', '내가 내 장막을 너희 중간에 두리니 내 영혼이 너희를 싫어하지 아니하리라'),
(3537, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 12, 'OT', '내가 너희 중간에 행하리니 너희에게 하나님이 되고 너희는 내게 백성이 되리라'),
(3538, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 13, 'OT', '나는 너희 하나님이신 여호와라. 내가 너희를 애굽 땅에서 인도하여 내어 그들의 종이 되지 않게 하였고, 너희 멍에의 빗장을 꺾고 너희를 바로 서서 걷게 하였느니라.'),
(3539, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 14, 'OT', '그러나 너희가 내게 듣지 아니하고 이 모든 명령을 행하지 아니하면'),
(3540, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 15, 'OT', '너희가 내 규례를 멸시하며 너희 영혼이 내 판결을 싫어하여 내 모든 명령을 행하지 아니하고 내 언약을 깨뜨릴진대'),
(3541, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 16, 'OT', '나도 내가 이 일을 너희에게 행하리니 내가 너희에게 두려움과 소모병과 열병을 내리리니 그것들이 눈을 쇠약하게 하고 영혼을 상하게 하리라 너희가 너희 씨를 헛됨에 뿌리리니 너희 원수들이 그것을 먹으리라'),
(3542, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 17, 'OT', '내가 내 얼굴을 너희에게 돌리리니 너희가 너희 원수들 앞에서 패할 것이요 너희를 미워하는 자들이 너희를 다스릴 것이며 너희는 쫓는 자가 없어도 도망하리라'),
(3543, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 18, 'OT', '이런 일에도 너희가 내게 듣지 아니하면 내가 너희 죄로 말미암아 너희를 일곱 배나 더 징계하리라'),
(3544, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 19, 'OT', '내가 너희 힘의 교만을 꺾고 너희 하늘을 철 같게 하며 너희 땅을 놋쇠 같게 하리라'),
(3545, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 20, 'OT', '너희 힘이 헛됨으로 소진되리니 너희 땅은 그 소출을 내지 아니하고 땅의 나무는 그 열매를 내지 아니하리라'),
(3546, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 21, 'OT', '너희가 나를 반대하여 행하며 내 말을 듣지 아니하려 하면 내가 너희 죄대로 너희에게 일곱 배나 더한 상처를 더하리라'),
(3547, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 22, 'OT', '내가 너희 중에 들판의 살아있는 짐승을 보내리니 그것이 너희 자녀를 빼앗고 너희 짐승을 끊으며 너희를 적게 하리라 너희 길들이 황폐하리라'),
(3548, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 23, 'OT', '이런 일들로도 너희가 내게 징계를 받지 아니하고, 너희가 나와 반대로 행할진대'),
(3549, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 24, 'OT', '나도 너희와 반대로 행하며 너희 죄로 말미암아 나도 너희를 일곱 배나 더 치리라'),
(3550, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 25, 'OT', '내가 너희 위에 복수하는 언약의 복수를 위한 칼을 가져오리니, 너희가 너희 성읍들로 모일지라도 내가 너희 중간에 역병을 보내고 너희가 원수의 손에 붙임을 당하리라.'),
(3551, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 26, 'OT', '내가 너희를 위하여 빵의 막대기를 꺾을 때에, 열 여자가 한 화덕에서 너희 빵을 구울 것이며, 그들이 너희 빵을 무게로 돌려줄 것이니, 너희가 먹어도 배부르지 아니하리라.'),
(3552, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 27, 'OT', '만일 너희가 이 모든 일에도 내 말을 듣지 아니하고 나와 반대로 행하면'),
(3553, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 28, 'OT', '내가 너희를 반대하여 분노 가운데 행하리니 나 곧 내가 너희 죄로 말미암아 일곱 배로 너희를 징계하리라.'),
(3554, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 29, 'OT', '너희가 너희 아들의 살을 먹을 것이요, 너희 딸의 살을 먹을지니라.'),
(3555, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 30, 'OT', '내가 너희의 높은 곳을 멸하고 너희의 우상을 끊으며 너희의 시체를 너희 우상들의 시체 위에 던지리니 내 영혼이 너희를 싫어하리라'),
(3556, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 31, 'OT', '내가 너희 성읍들을 폐허로 만들고 너희 성소들을 황폐하게 하리니 너희 향기로운 향기를 내가 맡지 아니하리라.'),
(3557, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 32, 'OT', '내가 그 땅을 황폐하게 하리니 너희 원수들, 그 땅에 거주하는 자들이 그것으로 인하여 놀라리라'),
(3558, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 33, 'OT', '내가 너희를 이방인 가운데 흩을 것이요 내가 너희 뒤로 칼을 빼어 따르게 하리니 너희 땅이 황폐하게 되고 너희 성읍들이 폐허가 되리라'),
(3559, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 34, 'OT', '그 때에 땅이 그 안식일들을 기뻐하리니, 모든 황폐한 날 동안 너희가 원수들의 땅에 있을 때에, 그 때에 땅이 쉬며 그 안식일들을 기뻐하리라.'),
(3560, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 35, 'OT', '그것이 황무한 모든 날 동안에 쉬리니, 너희가 그 땅에 거할 때에 너희 안식일에도 쉬지 못했던 그것이 쉬리라.'),
(3561, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 36, 'OT', '너희 중에 남은 자들에게는 그들의 원수들의 땅에서 내가 그들의 마음에 연약함을 가져오리니, 흔들리는 잎의 소리가 그들을 쫓을 것이요, 그들은 칼을 피하여 도피하듯 도망할 것이며, 쫓는 자가 없어도 그들은 엎드러지리라.'),
(3562, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 37, 'OT', '각 사람이 형제 앞에서 칼 앞에서 쫓는 자가 없음 같이 넘어질 것이요 너희는 너희 대적의 얼굴 앞에 일어섬이 없으리라'),
(3563, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 38, 'OT', '너희가 이방인 가운데서 멸망할 것이며 너희 원수들의 땅이 너희를 삼키리라.'),
(3564, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 39, 'OT', '너희 중에 남은 자들은 너희 원수들의 땅에서 그들의 죄악으로 말미암아 쇠잔할 것이요, 또한 그들의 아버지들의 죄악으로 말미암아 그들과 함께 쇠잔하리라.'),
(3565, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 40, 'OT', '그들이 자기 죄악과 그들의 아버지들의 죄악을 그들이 나에게 행한 배신 가운데서 자복할 것이며, 또한 그들이 나를 반대하여 행한 것도 자복할 것이다.'),
(3566, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 41, 'OT', '나도 그들을 반대하여 행하며 그들을 그들의 원수들의 땅으로 인도하리니 그 때에 그들의 할례받지 않은 마음이 낮아지고 그 때에 그들이 자기 죄악을 기꺼이 받으리라'),
(3567, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 42, 'OT', '내가 야곱과 맺은 내 언약을 기억하고, 또한 이삭과 맺은 내 언약을, 또한 아브라함과 맺은 내 언약을 기억할 것이며, 그 땅도 기억하리라.'),
(3568, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 43, 'OT', '그 땅이 그들로부터 버려져서 그들의 안식일을 누리리니 그들이 없어 황폐할 때에 그리될 것이요 그들은 자기 죄악을 담당하리니 이는 그들이 내 판결을 멸시하고 내 규례를 그들의 영혼이 싫어하였음이라'),
(3569, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 44, 'OT', '그런데도 그들이 원수의 땅에 있을 때에 내가 그들을 버리지 아니하며 싫어하지 아니하여 그들을 진멸하지 아니하고 그들과의 내 언약을 깨뜨리지 아니하리니 이는 내가 여호와 그들의 하나님이기 때문이라'),
(3570, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 45, 'OT', '내가 그들을 위하여 처음 언약을 기억하리니 곧 내가 이방인의 목전에 애굽 땅에서 그들을 인도하여 내어 그들의 하나님이 되려 한 것이라 나는 여호와니라'),
(3571, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 26, 46, 'OT', '이것은 여호와께서 시내 산에서 모세의 손을 통해 자기와 이스라엘 자손 사이에 주신 법령과 판결과 율법이니라.'),
(3572, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 1, 'OT', '여호와께서 모세에게 말씀하여 이르시되'),
(3573, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 2, 'OT', '이스라엘 자손에게 말하여 그들에게 이르라, 사람이 여호와께 영혼의 평가로 서원을 드리면'),
(3574, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 3, 'OT', '네 평가는 남자이면 스무 해 된 아들로부터 예순 해 된 아들까지이니, 네 평가는 거룩함의 세겔대로 은 오십 세겔이 될지니라.'),
(3575, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 4, 'OT', '만일 그것이 암컷이면 네 평가는 삼십 세겔이 될지니라.'),
(3576, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 5, 'OT', '만일 다섯 해에서부터 스무 해까지의 아들이면 네 평가는 남자는 스무 세겔이요, 암컷은 열 세겔이니라.'),
(3577, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 6, 'OT', '만일 한 달 된 아들부터 다섯 해 된 아들까지면, 네 평가는 남자는 은 다섯 세겔이요, 암컷에 대한 네 평가는 은 세 세겔이니라.'),
(3578, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 7, 'OT', '만일 육십 해 이상이면, 남자이면 네 평가는 열다섯 세겔이 되고, 암컷은 열 세겔이 되리라.'),
(3579, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 8, 'OT', '그러나 그가 네 평가보다 가난하면 그를 제사장 앞에 세우고 제사장이 그를 평가하되, 서원한 자의 손이 미치는 대로 제사장이 그를 평가할지니라.'),
(3580, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 9, 'OT', '만일 여호와께 제물로 드리는 짐승이면, 그 중에서 여호와께 주는 모든 것은 거룩함이 될지니라.'),
(3581, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 10, 'OT', '그것을 바꾸지 못하며 좋은 것을 나쁜 것으로, 나쁜 것을 좋은 것으로 변경하지 못할 것이요, 만일 짐승을 짐승으로 반드시 변경하면 그것과 그 변경은 거룩함이 될지니라.'),
(3582, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 11, 'OT', '그러나 여호와께 제물로 드리지 못할 모든 부정한 짐승이면, 그 짐승을 제사장 앞에 세울 것이요'),
(3583, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 12, 'OT', '제사장은 그것을 좋은 것과 나쁜 것 사이에 평가할 것이요, 제사장의 평가대로 그렇게 될지니라.'),
(3584, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 13, 'OT', '만일 그가 그것을 반드시 무르려면, 그의 다섯째를 그의 평가에 더할지니라.'),
(3585, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 14, 'OT', '사람이 자기 집을 여호와께 거룩함으로 드리려면 제사장이 그것을 좋은 것과 나쁜 것 사이에서 평가할 것이며, 제사장이 그것을 평가한 대로 그대로 서 있을 것이다.'),
(3586, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 15, 'OT', '만일 그가 자기 집을 성별한 자가 되려면 그 집을 무르려 할 때, 네 평가한 은에 그 오분의 일을 더할지니 그리하면 그의 소유가 되리라.'),
(3587, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 16, 'OT', '만일 사람이 자기 소유의 들판에서 여호와께 구별하여 드리면, 그 평가는 그 씨에 따라 하되, 보리 한 호멜의 씨는 은 오십 세겔로 할지니라.'),
(3588, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 17, 'OT', '만일 그가 자기 들판을 희년부터 구별하여 드리면 네 평가대로 그것이 설 것이니라.'),
(3589, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 18, 'OT', '만일 그가 희년 후에 자기 들판을 구별하여 드리면 제사장이 그에게 은을 계산하되 희년의 해까지 남은 해들의 입을 따라 계산하고 네 평가에서 감할지니라'),
(3590, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 19, 'OT', '만일 그가 그 들판을 거룩하게 구별한 자가 그것을 다시 사려면, 그가 네 평가의 은에 그 오분의 일을 더할 것이요, 그것이 그에게 확정되리라.'),
(3591, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 20, 'OT', '만일 그가 그 들판을 되사지 아니하거나 그 들판을 다른 사람에게 팔았으면 다시는 되사지 못할지니라'),
(3592, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 21, 'OT', '희년에 그 들판이 나올 때에는 여호와께 거룩함이 되리니 저주받은 것의 들판과 같이 제사장에게 그의 소유가 되리라'),
(3593, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 22, 'OT', '만일 그가 자기 소유의 들판이 아닌 구매한 들판을 여호와께 구별하여 드리면'),
(3594, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 23, 'OT', '제사장이 그를 위하여 네 평가의 값을 희년의 해까지 계산하고, 그 날에 네 평가를 여호와께 거룩함으로 드릴지니라.'),
(3595, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 24, 'OT', '희년에 그 들판은 그것을 산 사람에게서 돌아가되, 그 땅의 소유가 있는 자에게로 돌아갈지니라.'),
(3596, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 25, 'OT', '네 모든 평가는 거룩한 세겔로 하되 이십 게라가 한 세겔이 될지니라'),
(3597, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 26, 'OT', '오직 짐승의 장자 곧 여호와께 돌릴 장자는 사람이 그것을 구별하여 드리지 못할지니 소든 양이든 여호와의 것이니라'),
(3598, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 27, 'OT', '부정한 짐승이면 너의 평가대로 속량하고 그 다섯째를 더할 것이요, 만일 속량되지 아니하면 너의 평가대로 팔릴지니라.'),
(3599, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 28, 'OT', '오직 모든 저주받은 것은 사람이 여호와께 바친 모든 것 중에서 사람이나 짐승이나 그의 소유의 들판에서든지 팔지도 못하고 속하지도 못하나니 모든 저주받은 것은 여호와께 지극히 거룩한 거룩함이니라'),
(3600, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 29, 'OT', '모든 저주받은 것은 사람에게서 저주받은 것으로 구속되지 못하리니 반드시 죽임을 당하리라'),
(3601, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 30, 'OT', '땅의 모든 십일조는 땅의 씨나 나무의 열매에서 난 것이니 여호와의 것이며, 그것은 여호와께 거룩함이니라.'),
(3602, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 31, 'OT', '만일 어떤 사람이 자기 십일조를 반드시 속량하려면 그것에 다섯째를 더할지니라'),
(3603, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 32, 'OT', '소와 양떼의 모든 십일조는 막대기 아래로 지나가는 모든 것의 열째 것이 여호와께 거룩함이 될지니라'),
(3604, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 33, 'OT', '그가 좋은 것과 나쁜 것 사이를 살피지 아니하며 그것을 바꾸지도 아니할 것이요, 만일 그것을 바꾸면 그것과 그 변경이 거룩함이 되리니 속량되지 못하리라.'),
(3605, 3, 'GOI_Ko', 'GOI_Ko', 'ko', 'LEV', 27, 34, 'OT', '이것들은 여호와께서 시내 산에서 이스라엘 자손에게 모세에게 명령하신 명령들이니라.'),
(3606, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 1, 'OT', '여호와께서 시내 광야에서 모세에게 말씀하시되, 정한 때의 천막에서, 그들이 애굽 땅에서 나온 지 둘째 해 둘째 달 첫째 날에 이르시되,'),
(3607, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 2, 'OT', '너희는 이스라엘 자손의 모든 회중의 머리를 들어 올리되 그들의 가족과 그들의 아버지의 집을 따라, 모든 남자를 그들의 해골 수대로 이름의 수로 계수할지니라.'),
(3608, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 3, 'OT', '이십 세 이상의 모든 이스라엘 군대에 나갈 자를 너와 아론은 그들의 군대대로 계수하라.'),
(3609, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 4, 'OT', '너희와 함께 할 사람은 각 막대기에서 한 사람씩이니, 각 사람은 자기 아버지 집의 머리라.'),
(3610, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 5, 'OT', '이러하니 너희와 함께 설 사람들의 이름은 르우벤에게서 스데우르의 아들 엘리술이니라'),
(3611, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 6, 'OT', '시므온에게는 수리삿대의 아들 슬루미엘이요'),
(3612, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 7, 'OT', '유다에게는 암미나답의 아들 나손이요'),
(3613, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 8, 'OT', '잇사갈에게는 수아르의 아들 느다넬이요'),
(3614, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 9, 'OT', '스불론에게는 헬론의 아들 엘리압이요'),
(3615, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 10, 'OT', '요셉의 아들들 중에서 에브라임에게는 암미훗의 아들 엘리사마요, 므낫세에게는 브다술의 아들 가말리엘이더라'),
(3616, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 11, 'OT', '베냐민에게는 기드오니의 아들 아비단이요'),
(3617, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 12, 'OT', '단에게서는 암미샤대의 아들 아히에셀이요'),
(3618, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 13, 'OT', '아셀에게는 오크란의 아들 브그이엘이라'),
(3619, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 14, 'OT', '갓에게는 드우엘의 아들 엘리아삽이요'),
(3620, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 15, 'OT', '납달리에게는 에난의 아들 아히라더라.'),
(3621, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 16, 'OT', '이들은 회중의 통치자들이요, 그들 아버지의 막대기들의 통치자들이며, 이스라엘의 천 명의 머리들이다.'),
(3622, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 17, 'OT', '모세와 아론이 그 이름으로 지명된 이 사람들을 데리고'),
(3623, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 18, 'OT', '그들이 모든 회중을 둘째 달 초하루에 모았고, 그들이 그들의 가족과 그들의 아버지의 집을 따라 그들의 계보를 기록하였으니, 스무 해 이상 된 아들들의 이름의 수대로 그들의 해골에 따라 기록하였더라.'),
(3624, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 19, 'OT', '여호와께서 모세에게 명령하신 대로 그가 시내 광야에서 그들을 계수하였더라.'),
(3625, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 20, 'OT', '르우벤의 아들들, 이스라엘의 장자의 세대와 그들의 가족과 그들의 아버지의 집에 따라, 이름의 수대로, 그들의 해골에 따라, 모든 남자, 스무 해 이상의 모든 자, 군대에 나가는 모든 자.'),
(3626, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 21, 'OT', '그들의 계수함을 받은 자가 르우벤의 막대기 지파로 사만 육천 오백 명이었더라'),
(3627, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 22, 'OT', '시므온의 아들들에게 그들의 세대와 그들의 가족과 그들의 아버지의 집에 따라 그들의 수는 이름의 수대로 그들의 해골에 따라 모든 남자, 스무 해 이상의 아들로부터 모든 군대에 나가는 자를 계수하니'),
(3628, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 23, 'OT', '그들의 계수함을 받은 자가 시므온 막대기로는 오만 구천 삼백 명이었더라'),
(3629, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 24, 'OT', '갓의 아들들에게서 그들의 세대대로, 그들의 가족대로, 그들의 아버지의 집대로, 이름의 수대로, 스무 해 이상의 모든 군대에 나가는 자를 계수하니'),
(3630, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 25, 'OT', '그들의 계수함을 받은 자가 갓 막대기에 따라 사만 오천 육백 오십 명이었더라'),
(3631, 4, 'GOI_Ko', 'GOI_Ko', 'ko', 'NUM', 1, 26, 'OT', '유다의 아들들에게 그들의 세대대로 그들의 가족대로 그들의 아버지의 집대로 이름의 수대로 이십 세 이상의 모든 군대에 나갈 자를 계수하니'),
